WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[26894] = { title = "Blackfathom Deeps", description = "The Twilight's Hammer mocks us with their defiance. We will drive them and their allies out of this land for good.\n\nTravel north of here to Blackfathom Deeps and speak with Je'neu Sancrea. He's already made his way inside.\n\nBe wary of Zeya, by the way. She can be a bit...temperamental at times.", objectives = "Speak with Je'neu Sancrea.", completion = "Did Commander Grimfang send you? I've asked him to find suitable recruits to aid me here." }
WordHunterWoW_QuestEN[26895] = { title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", objectives = "Talk to Doctor Dealwell in Gadgetzan.", completion = "Another proud <class>, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!" }
WordHunterWoW_QuestEN[26896] = { title = "The Thunderdrome!", description = "Hey, friend, you interested in excitement? Adventure? Money? Violence?\n\nWell, you'd better like violence, because they just reopened the Thunderdrome in Gadgetzan. It was sad to see it unused for so long, what with the injury lawsuits, and the racketeering charges, and the copyright infringement... But it's back, and just waiting for burly, savage folk like you to enter and throw down with the foulest opponents ever!\n\nHead to Gadgetzan and talk to Dr. Dealwell to sign up. And tell your friends!", objectives = "Talk to Doctor Dealwell in Gadgetzan.", completion = "Another proud <class>, lured by the promise of fame! Of wealth! Of VIOLENCE!\n\nYes, welcome, friend. Welcome... to THUNDERDROME!" }
WordHunterWoW_QuestEN[26897] = { title = "Blackfathom Deeps", description = "Although our position is exposed, we are safe compared to our friends inside Blackfathom Deeps! They stand mere feet away from the most deadly Twilight's Hammer forces in the area. Speak with Sentinel Aluwyn and give them the aid they desperately need!", objectives = "Speak with Sentinel Aluwyn.", completion = "Thank Elune you're here! We could use all the help we can get." }
WordHunterWoW_QuestEN[26898] = { title = "Blackfathom Deeps", description = "I care deeply about these forests, {class}. Things look grim here, but I would rather face the Horde alone than watch them hack and slash their way through the trees.\n\nTravel west to Blackfathom Deeps. Once you're inside, find Sentinel Aluwyn. She's a trusted friend in need of help.\n\nThe orcs in Zoram'gar Outpost threaten her position as we speak. If they take Blackfathom, they will surely cut every tree down to fuel their insanity.", objectives = "Speak with Sentinel Aluwyn.", completion = "Thank Elune you're here! We could use all the help we can get." }
WordHunterWoW_QuestEN[26899] = { title = "The Enemy of My Enemy", description = "Cultists...sacrifice...power...\n\nEnemy...awaken...\n\nOld God...imprison...me...\n\nLord...Kelris...\n\nBring head...revenge...\n\nERADICATE!!!", objectives = "Obtain the head of Twilight Lord Kelris.", progress = "Revenge...reward...", completion = "<The Flaming Eradicator appears to concentrate.>\n\nI spare your life for your help, <race>. Leave now...before I change my...mind." }
WordHunterWoW_QuestEN[26900] = { title = "Agamaggan", description = "I sense a being of immense power within these twisted thorns, <name>. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.Upon completion of this quest you will gain:", objectives = "Find the Spirit of Agamaggan.I sense a being of immense power within these twisted thorns, <name>. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[26901] = { title = "Going, Going, Guano!", description = "The bats native to Razorfen Kraul produce a very peculiar natural substance. Their guano's stench seems to send the Quilboar into a murderous frenzy - and this place reeks of it!\n\nI need you to find the bat cave, and bring me a suitable sample. If we can reverse the effects and produce an antidote, we may be able to save the Quilboar.", objectives = "Extract 1 pile of Kraul Guano.", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Well done! This is just what we need, <name>." }
WordHunterWoW_QuestEN[26902] = { title = "Get Back to Town Accepted Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[26903] = { title = "Willix the Importer", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that pig snouts were selling outrageously high in the market. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", objectives = "Escort Willix the Importer to the exit of Razorfen Kraul.", completion = "Thanks again, friend! I told you I'd make it worth your while." }
WordHunterWoW_QuestEN[26904] = { title = "Corruption", description = "Few people, especially among our allies, truly understand the nature of the power we wield. They shun us for pursuing knowledge that they are too weak to use properly.\n\nAs you become more powerful, you will begin to discover new spells, further magnifying your power.\n\nGo, get more experience, then return once you've learned a new spell. We'll see if you have it in you to truly master the dark arts.", objectives = "Reach level 3 to learn Corruption, then cast it 5 times on a Training Dummy near the entrance to Anvilmar.", completion = "As you continue to gain power, return to me and I will teach you new spells and techniques." }
WordHunterWoW_QuestEN[26905] = { title = "Agamaggan's Charge", description = "Listen closely, mortal.\n\nThe Quilboar are my children. My blood runs deep in these lands.\n\nCharlga Razorflank has steered my children into darkness, driven into insanity by the Scourge.\n\nSlay her, {name}. Slay her and open my childrens' eyes.\n\nGive the Quilboar the chance to return to their noble roots. Let them once more earn my blessing.\n\nBring me her heart!!!\n\n", objectives = "Take Charlga Razorflank's heart.", progress = "<The Spirit of Agamaggan stares at you patiently.>", completion = "Take this gift. You have earned my blessing this day." }
WordHunterWoW_QuestEN[26906] = { title = "Agamaggan", description = "I sense a being of immense power within these twisted thorns, {name}. The entire area has come alive at its presence.\n\nIt must be the Spirit of Agamaggan! He was one of the first and most powerful beings to ever live - the Quilboar worship him fervently.\n\nAll the vines you see across the land are a result of his blood; of his sacrifice to save Azeroth in the War of the Ancients.\n\nIf there's any being that could steer the Quilboar towards their noble roots, it would be him.\n\nYou must seek him out.", objectives = "Talk to the Spirit of Agamaggan.", completion = "<The Spirit of Agamaggan looks at you. An ancient voice echoes inside your head.>\n\nI've been waiting for you to come here." }
WordHunterWoW_QuestEN[26907] = { title = "Take Them Down!", description = "In order to maintain the relative safety in the Southern Barrens, we must put a stop to the current leadership of the Razorfen tribe. Although Charlga Razorflank commands her people through powerful mysticism, her true power is in the strength of the elders around her.\n\nSlay them. Hunt down Bonetusk, the pack leader. Stop Roogug, the overseer of Geomancers. Crush Ramtusk, the quilboar Warlord.\n\nReturn to me when the deed is done.", objectives = "Kill Hunter Bonetusk, Roogug, and Warlord Ramtusk.", completion = "You've done well this day. Agathelos would have taken many lives in its fury." }
WordHunterWoW_QuestEN[26908] = { title = "Feeling Thorny", description = "Mankrik's furor over his dead wife raises further concerns, {class}.\n\nThe quilboar in Razorfen Kraul are far more ruthless and full of hatred than Mankrik could ever imagine.\n\nYou should travel south there and speak with my old friend Auld Stonespire. He works to put an end to their rampage before the land suffers more in its already weak condition.", objectives = "Speak to Auld Stonespire.", completion = "Only a veteran like you could brave the dangers lurking here." }
WordHunterWoW_QuestEN[26909] = { title = "The Stone Shards", description = "Ancient stones are strewn across this land. The elements flock to them, surrounding them protectively.\n\nThese are sites of great power, and the largest is just west of Hammerfall. Not a soul trespasses, but if you go there alone, you can hear whispers from the earth itself.\n\nI have not visited there in a long while... but our grunts have told me the whispers have started again. Would you look for me? Will you see if the stones still speak?", objectives = "Investigate the Shards of Myzrael.", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp..." }
WordHunterWoW_QuestEN[26910] = { title = "Etched Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, <name>. It appears to be a letter sealed with the insignia of Ashley Blank, our local hunter trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", objectives = "Read the Etched Letter and speak to Ashley Blank in Northshire Valley.", progress = "Hello, <name>. Is there something I can do for you?", completion = "So you received my note? Excellent. You've proven yourself quite capable in dealing with those orcs. As you continue to grow in power, I will teach you some new techniques." }
WordHunterWoW_QuestEN[26911] = { title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Zaruk of what you've done so far.", objectives = "Return to Zaruk at Hammerfall in Arathi Highlands.", completion = "I know, <name>. I should not have sent you.\n\nForgive me... the whispers of the past are sometimes too strong." }
WordHunterWoW_QuestEN[26912] = { title = "The Princess Unleashed", description = "Myzrael is a deceiver. She is an ancient force sealed long ago, and must be kept that way.\n\nYou must confront her at the Shards of Myzrael where you first spoke with her.  Summon her with this scroll, and when she has been fully brought to the surface, defeat her. Then take the Eldritch Shackles from her body and place them on the Shards to keep her fully bound once more.\n\nGood luck, {name}... may my past trouble you no more.", objectives = "Summon and defeat Myzrael at the Shards of Myzrael.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface." }
WordHunterWoW_QuestEN[26913] = { title = "Charging into Battle", description = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important.\n\nAs you get more experience, you'll be able to do new techniques you never thought of.\n\nGo, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", objectives = "Reach level 3 to learn Charge, then practice using Charge on a Training Dummy south of the entrance to Northshire Abbey.", completion = "You're a quick learner, <name>. Return to me as you grow stronger and I'll show you other combat techniques." }
WordHunterWoW_QuestEN[26914] = { title = "Corruption", description = "We must take care in how we speak around the abbey and its environs, but don't let that deter you from the path of power.\n\nAs you become more powerful, you will begin to hear the fel voices, granting you their power in the dark arts.\n\nGo, get more experience and learn a new spell. Once you have, practice it on the training dummies.", objectives = "Reach level 3 to learn the Corruption ability, then practice casting Corruption 5 times on a Training Dummy south of the entrance to Northshire Abbey.", completion = "I see you have already mastered Immolation! I look forward to instructing you in the future. Do not forget to return for further lessons as you grow in power." }
WordHunterWoW_QuestEN[26915] = { title = "The Deepest Cut", description = "By now, you know the basics of combat as rogue, but I want to teach you a new skill. As rogues, we are renowned for our ability to execute chains of combat techniques, often saving the most powerful strikes for the end.\n\nAs you get more experience, you'll learn new things - and this is one of the ones you'll learn first. Once you have, I want you to go try it on one of the training dummies south of the entrance to the abbey.", objectives = "Reach level 3 to learn Eviscerate, then find a Training Dummy south of the entrance to Northshire Abbey and practice Eviscerate 3 times.", completion = "You've caught on quickly, <name>, and a quick mind will serve you well. Return to me as you grow in power and I will show you new techniques." }
WordHunterWoW_QuestEN[26916] = { title = "Mastering the Arcane", description = "As a mage, you will learn a variety of spells as your understanding grows. All you need to do is get some more experience, and the secrets of the arcane will reveal themselves to you.\n\nYou'll see. Go develop your powers, and show me what you learn.", objectives = "Reach level 3 to learn Frost Nova, then practice casting it 2 times on a Training Dummy south of the entrance to Northshire Abbey.", completion = "Have you mastered the use of Arcane Missiles already? You are a quick study in the arcane arts and you have a promising future ahead. Don't forget to return to me for training as you grow in power." }
WordHunterWoW_QuestEN[26917] = { title = "The Hunter's Path", description = "I've heard about your help in clearing out some of the orcs. You've shown that you can handle yourself in combat.\n\nAs you get more experience in combat, you'll start learning how to do new things. I want you to go, get some more experience, then try the new abilities you learn on one of the training dummies south of the entrance to the abbey.", objectives = "Reach level 3 to learn Steady Shot, then find a Training Dummy south of the entrance to Northshire Abbey and practice using Steady Shot 5 times.", completion = "I knew you would master Steady Shot quickly. I'm looking forward to showing you other techniques as you get more experienced in the ways of the <class>." }
WordHunterWoW_QuestEN[26918] = { title = "The Power of the Light", description = "As you continue in your journey as a Paladin, you'll become closer to the light, learning new abilities.\n\nGo, get more experience, and learn a new ability. Demonstrate it for me, and we will continue your training.", objectives = "Reach level 3 to learn Seal of Command. Cast Seal of Command on yourself and then hit a Training Dummy south of the entrance to Northshire Abbey.", completion = "You're a quick learner, <name>. Return to me as you grow stronger and I'll teach you more about using the Light to vanquish your enemies and strengthen your allies." }
WordHunterWoW_QuestEN[26919] = { title = "Learning the Word", description = "One of your responsibilities as a priest is caring for the wounded. Another is to go out into the world and be more... proactive about defending them.\n\nAs you do so, you'll grow in power and learn all sorts of new things.\n\nWhy don't you go out, get more experience, and then return to demonstrate what you've learned?", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on training dummies near Northshire Abbey.", completion = "You're a quick learner, <name>, and the wounded are fortunate to have your aid. Return to me as you grow stronger and I'll teach you other spells." }
WordHunterWoW_QuestEN[26920] = { title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  Lady Sylvanas has sent one of her best death knights to lead the charge for her cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the perfect time for the Forsaken to take Andorhal.\n\nSpeak with the bat handler, Timothy Cunningham, when you are ready, and he will put you on the first flight out there.", objectives = "Report to Koltira Deathweaver within Andorhal in Western Plaguelands.", completion = "It's about time you arrived, <class>." }
WordHunterWoW_QuestEN[26921] = { title = "Scourge First... Alliance Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Thassarian, leads the Alliance forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Thassarian well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Alliance will have to wait to taste our wrath.", objectives = "Slay 15 Desiccated Scourge within Andorhal.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, <name>, when the time is right." }
WordHunterWoW_QuestEN[26922] = { title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Jearl passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", objectives = "Use Jearl's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, <name>.", completion = "These grenades are all explosives, nothing more.  Even as a member of the Royal Apothecary Society, I recognize that some problems are not solved by throwing more plague at them." }
WordHunterWoW_QuestEN[26923] = { title = "War Machines", description = "You fools will never defeat the Scourge with those abominations running around.  Koltira blathers on about reducing their numbers, but the Scourge's best weapon here in Andorhal can be found in those lumbering brutes that are throwing my deathguards around like ragdolls.\n\nI won't have it.  {name}, enter the battlefield and destroy those monsters.", objectives = "Destroy 6 Opengut Behemoths in Andorhal.", completion = "With the behemoths out of the way, our victory against the Scourge is inevitable.\n\nOur current chances against the Alliance aren't quite as favorable... but that's no concern of yours.  Not yet, anyhow." }
WordHunterWoW_QuestEN[26924] = { title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", objectives = "Kill Darkmaster Gandling within Andorhal.", completion = "Excellently done, <name>.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time." }
WordHunterWoW_QuestEN[26925] = { title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", objectives = "Kill Araj the Summoner. You may use Jearl's Hand Grenades to destroy Stickbone Berserkers.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  The Royal Apothecary Society has done its part.  As have you, <name>." }
WordHunterWoW_QuestEN[26926] = { title = "Victory, For Now", description = "The Forsaken are victorious, and our forces are still strong.  Military strategy dictates that we attack the Alliance now, while they are recovering and unaware.  I have other plans, however...\n\nWe will wait.  We attack Thassarian and his troops when the time is right.  In the meantime, speak with Rhonda Molver and take a flight to the Bulwark, on the Plaguelands' western border.  High Executor Derrington will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", objectives = "Report to High Executor Derrington at the Bulwark in Tirisfal Glades.", completion = "Word arrived shortly before you did, <name>.  With the Scourge ejected from Andorhal, the Forsaken has cemented its foothold in Lordaeron." }
WordHunterWoW_QuestEN[26927] = { title = "Suddenly, Murlocs!", description = "So we've got troggs working for kobolds, and kobolds working for gnolls. The gnolls must've moved in from the Wetlands.\n\nHow do I know? Well, they brought friends, because what's left of the Loch is swarming with Bluegill murlocs that were never there before.\n\nPests are pests, but this coordination is worrying. I need you to talk to Cannary Caskshot. She's one of the best hunters in these parts, and she'll know how to handle murlocs, if you can pull her away from her mug long enough.", objectives = "Speak with Cannary Caskshot.", completion = "Murlocs? Sure, I've hunted murlocs.\n\nAnd every single stinkin' one of them deserved what they got! You hear me?" }
WordHunterWoW_QuestEN[26928] = { title = "Smells Like A Plan", description = "Murlocs workin' with gnolls? That's a laugh! Now, just killin' them won't get you anywhere. Too many of the buggers.\n\nBut I've got a plan, usin' the old noggin, see. Those murlocs, they have this smell, they get that smell on stuff, and when another murloc smells it, they go all crazy! Makes great bait for 'em.\n\nAnyway, they've got little glands that have that smell in 'em. You go and get me a bunch of those.", objectives = "Collect 7 Murloc Scent Glands from any Bluegill Murloc in The Loch.", progress = "Now don't you stink all to high hell! I'm assumin' that's because of the murlocs, but it's hard to tell.", completion = "Phew! Ain't that a stench.\n\nNow you prepare yourself, because I'm about to wow you with what's left of my mental faculties." }
WordHunterWoW_QuestEN[26929] = { title = "A Load of Croc", description = "Now while you're runnin' around doin' whatever the heck it is that you do, would you mind helpin' me out a bit?\n\nSee, I usually go out huntin' crocolisks down in the loch, but given certain circumstances, I'd rather sit here right now. Mighty polite of you not to give me grief over it, thanks!\n\nSo seein' as how you're such a gentleman, why don't you bring me back some crocolisk jaws and I'll give you some mostly-clean money in return.", objectives = "Collect 6 Crocolisk Jaws.", progress = "So did you get those crocolisk things or did I make that up?", completion = "Mighty kind of you to help out an ol' fool like me. Here's your reward as promised an' all." }
WordHunterWoW_QuestEN[26930] = { title = "After the Crusade", description = "Our victories are quickly piling up, {name}.  The Scarlet Crusade, which has long persecuted the Forsaken, is on its last legs.  While they still hold their monastery here in Tirisfal, they no longer occupy Hearthglen, or Tyr's Hand, far to the east.\n\nAs recently as last week, there have been reports of Scarlet Crusade activity at a small camp east of Felstone Field, but I have reason to believe that they too have been eliminated.  Travel there, and verify this information for me.", objectives = "Scout the Scarlet Crusade camp located east of Felstone Field in Western Plaguelands.", completion = "Burning bodies?  No survivors?  I guessed correctly.\n\nAll the better!  We're better off without the Scarlet taint upon Lordaeron.  They epitomized all the worst things about humans." }
WordHunterWoW_QuestEN[26931] = { title = "Foxes and Hounds", description = "These Alliance forces walk around the Plaguelands like they own the place.  Well, they don't!  This land rightfully belongs to the Dark Lady!\n\nAs the battle for Andorhal drew to a close, the Alliance forces occupying the Plaguelands scattered.  Several of them can be found just east of here, hunting foxes.  Prove to them that this is Forsaken territory.\n\nKill the hunters.  Kill their hunting dogs.  And kill the foxes they hunt, for good measure.", objectives = "Kill 4 Alliance Fox Hunters, 4 Bullmastiffs, and 4 Whitetail Foxes in Western Plaguelands.", completion = "It's a relief to have those hunters out of the way.  We're not done killing Alliance, however..." }
WordHunterWoW_QuestEN[26932] = { title = "Buzz Off", description = "When the Stonewrought Dam burst, it drained near the entire loch. Horrible ecological devastation.\n\nAnd don't you go thinking it didn't really affect us dwarves! Not only are we plumb out of fish, but there's acres of dead threshadons out there left to rot in the sun. The buzzards are after them, and they're spreading all manner of filth and disease right on the outskirts of town.\n\nI can't ask you to clean it all up, but could you deal with the buzzards? Killin' even just a few will help.", objectives = "Kill 8 Loch Buzzards.", progress = "Plenty of 'em flappin' around yet, lad.", completion = "That should help prevent disease and illness from spreading into our remaining water. Many thanks, <name>." }
WordHunterWoW_QuestEN[26933] = { title = "Foes Before Hoes", description = "The men who till Felstone Field are no farmers.  They're soldiers.\n\nThassarian's forces needed food, so he sent some of the Alliance north from Andorhal, to tend Felstone Field.  The battle for Andorhal may be over, but another battle looms... Forsaken versus human.  Killing those soldiers that work at Felstone will give the Dark Lady's forces a decided advantage.", objectives = "Kill 9 Alliance Laborers on Felstone Field.", completion = "Ha ha!  I hope that they come back as zombies." }
WordHunterWoW_QuestEN[26934] = { title = "Latent Disease", description = "I need plagued grass for an... an experiment, of sorts.  Those Argent Crusaders and those infernal Cenarion druids have done too good a job of healing the plaguelands, however... and I can't find proper reagents within a reasonable walking distance.\n\nSome of the local wildlife retain the plague's touch, however.  Kill a diseased black bear, then retrieve the grass that grows where its decaying body lies.  It's not optimal, but it'll do.", objectives = "Kill Diseased Black Bears in Western Plaguelands, then loot 20 Plague Tangles that grow near their corpses.", progress = "Animal tissue holds onto disease so much better than plant tissue, doesn't it?", completion = "Glorious!  This is the last bit I need.\n\nActually, stick around, <name>.  Let me tell you a little bit more about our plan." }
WordHunterWoW_QuestEN[26935] = { title = "Northridge Lumber Mill", description = "We are not the only Argent Crusaders here in the plaguelands.  Our headquarters, Hearthglen, lies to the north.  Even nearer to the north is a small lumber mill which we also control.\n\nNathaniel Dumah is my main contact at the lumber mill.  I encourage you to speak with him, should you find yourself in that part of the woods.", objectives = "Report to Nathaniel Dumah at the Northridge Lumber Mill in Western Plaguelands.", completion = "Welcome to Northridge, <class>." }
WordHunterWoW_QuestEN[26936] = { title = "Lower the Boom", description = "", objectives = "Felstone is cleared and the bombs are set.  I hope you're ready.  I recommend covering your ears.\n\n<Derrington looks down and places his finger on an ignition switch.>\n\nEVERYBODY, PREPARE FOR IGNITION!  IN 3...\n\n2....\n\n1..." }
WordHunterWoW_QuestEN[26937] = { title = "When Death is Not Enough", description = "Derrington and his men don't know it, but it was I who ordered the plaguing of Felstone Field.  We need this area for practice.  If we're to win this war for Andorhal, we need to use our newest, most versatile weapon:\n\nVal'kyr.\n\nTake my enthralled val'kyr with you, {name}, and kill the simpering Alliance scum that remain on Felstone.  Once they are dead, she will bring them back to this world... as one of us.\n\nThe Forsaken shall not die out!", objectives = "Kill 8 Alliance Laborers on Felstone Field so your Enthralled Val'kyr can convert them into Forsaken.", completion = "I am able to communicate with you through the Val'kyr, <name>.  You have done well.\n\nRemain on Felstone Field.  We must now teach these newly-converted Forsaken how to fight." }
WordHunterWoW_QuestEN[26938] = { title = "Combat Training", description = "A val'kyr's only purpose is to serve, and this one serves you.  I am now giving you full control over her abilities, {name}.\n\nRoaming around the farm's outskirts, you should find several of the Forsaken that you just created.  I want you to use your val'kyr to gather at least five of them.  Once you have done so, take your newly-formed band of soldiers, bring them into Felstone's barn, and kill the beast inside.  Today, they will learn what it means to fight for the Dark Lady.", objectives = "Use your Enthralled Val'kyr's Call to Arms ability to mobilize 5 Forsaken Troopers on Felstone Field. Then slay the Opengut Abomination inside Felstone's barn.", progress = "You try my patience, young <name>.", completion = "When Koltira gives his word, I will bring these val'kyr into Andorhal.  We will win.  And yet another piece of Lordaeron will fall to the might of the Forsaken." }
WordHunterWoW_QuestEN[26939] = { title = "The G-Team", description = "How did you get in here?\n\nOh, it doesn't matter. I'm Murd Doc of the G-Team. We're the best there is, and we're here to retake Gnomeregan!\n\nWhen nobody else could help him, the High Tinker found and hired us.\n\nBut we simply can't do this alone! You're an honorary G-Team Commando now, {name}.\n\nTake this parachute, jump down straight ahead into the Hall of Gears, and kill the Viscous Fallout. After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", objectives = "Kill the Viscous Fallout.", progress = "What're you doing out in the open like that, fool? Get down!", completion = "I hope that wasn't too much for you. The mission is far from over!" }
WordHunterWoW_QuestEN[26940] = { title = "Frost Nova", description = "We are the heirs to a legacy of arcane magic and your path will not be an easy one. Many still hold us responsible for the actions of our forebears, but our talents are needed.\n\nThough you must be cautious, it is important to develop your powers, as that will deepen your connection to the arcane and grant you access to new spells.\n\nGo - get more experience with your spells, and demonstrate what you learn for me.", objectives = "Reach level 3 to learn Frost Nova. Look for a Training Dummy near, and practice using it twice.", completion = "I knew you would master this lesson quickly. You are a credit to the highborn and to all our kin. Remember, as you grow in power, return to me and will instruct you further." }
WordHunterWoW_QuestEN[26941] = { title = "The G-Team", description = "That Murd Doc is crazy, {class}. Never, ever, let you find yourself in an aircraft with that gnome.\n\nStealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000.\n\nThe Electrocutioner is in charge of the aircraft...\n\n...and I hate aircraft. I'm not getting in any sort of aircraft!\n\nUse this parachute to drop down afterwards and speak with Commando Face for your next job.", objectives = "Kill the Electrocutioner 6000.", progress = "Woah! How did you see me!?", completion = "Took you long enough. Get behind the pillar with me before you blow our cover!" }
WordHunterWoW_QuestEN[26942] = { title = "The G-Team", description = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable.\n\nYou are, though, so let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg.\n\nOur leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work.\n\nProbably.", objectives = "Kill Mekgineer Thermaplugg.", completion = "I'd love for you to come aboard as a full G-Team Commando, but you have other adventures to pursue.\n\nI'm sure we'll meet again, and I hope you'll have considered joining by then. Here's something for your trouble." }
WordHunterWoW_QuestEN[26943] = { title = "Home Sweet Gnome", description = "I used t' have quite the home back in Ironforge. That is, I did until I was booted out to make way for the gnomes.\n\nThey couldn't stop a bunch of troggs with all them gizmos and machines! An' I have to pay for their weakness?\n\nNo, sir. No longer.\n\nGo to Gnomeregan and talk to Commando Murd Doc. Sure, he's a gnome, but his crew, S.A.F.E. I think they call 'em, are going to take Gnomeregan back.\n\nGo! I want my house back!", objectives = "Speak to Murd Doc.", completion = "Never thought I'd see a <race> like you down here. Any particular reason you're risking life and limb?" }
WordHunterWoW_QuestEN[26944] = { title = "Exploring Gnomeregan", description = "The gnomish capital, Gnomeregan, hasn't been under their control for some time now. I know what it feels like to lose a home.\n\nPlease, venture inside Gnomeregan and speak to Commando Murd Doc, a member of S.A.F.E. If there's anything at all that you can do to help them take their home, I urge you to do so. There are dark secrets in those halls.", objectives = "Speak to Murd Doc.", completion = "Never thought I'd see a <race> like you down here. Any particular reason you're risking life and limb?" }
WordHunterWoW_QuestEN[26945] = { title = "Learning New Techniques", description = "As you overcome the challenges before you, you'll begin to learn new techniques.\n\nGo, get more experience, and learn a new skill. Then demonstrate it for me on one of the training dummies.", objectives = "Reach level 3 to learn Charge. Look for a Training Dummy and practice using Charge.", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques." }
WordHunterWoW_QuestEN[26946] = { title = "A Rogue's Advantage", description = "I'm certain that by now, you've mastered using Sinister Strike against your enemies. But, as you learn more and advance as a rogue, you'll start to figure out new techniques. One you should figure out soon is called Eviscerate. It can be a strong way to end a combination of attacks.\n\nI want you to get some more experience, figure it out, then try it on a training dummy near the southeastern edge of Aldrassil.", objectives = "Reach Level 3 and Learn Eviscerate. Look for a Training Dummy southeast of Aldrassil and practice using Eviscerate 3 times.", completion = "You've learned quickly. If you are as sharp as you seem to be, you may prove to be one of my best students yet. Return to me when you are in need of further training." }
WordHunterWoW_QuestEN[26947] = { title = "A Woodsman's Training", description = "When most people think of the kaldorei, they conjure visions of druids and sentinels, but the way of the hunter is just as ancient and just as venerable.\n\nI've been observing you, and you've had quite a bit of experience handling that bow. As you gain more, you'll start to learn some new abilities.\n\nI want you to go out, get some more experience, and figure out how to do something new. Then go use it on a training dummy near the southeastern edge of Aldrassil.", objectives = "Reach level 3 to learn Steady Shot. Look for a Training Dummy southeast of Aldrassil, and practice using Steady Shot 5 times.", completion = "You are a quick study in our ways. I look forward to continuing your training in the future. Return to me when the time is right." }
WordHunterWoW_QuestEN[26948] = { title = "Moonfire", description = "Druids play an important role in our society, but all too often we are seen as passive dreamers in a world that is changing around us.\n\nThe truth is, though, we must actively practice and go out onto the world to develop our connection to nature.\n\nSo go, get some more experience. You will begin to feel your connection deepen, learning new skills. Demonstrate the first you learn for me.", objectives = "Reach level 3 to learn Moonfire. Use it on a training dummy in Aldrassil.", completion = "You have mastered the basics of the healing ways quickly, <name>. I have no doubt that your healing skills will often come in handy. Return to me when you need further training." }
WordHunterWoW_QuestEN[26949] = { title = "Learning the Word", description = "As you venture out into the world and develop your skills, you will begin to learn new abilities that you never knew you had within you.\n\nI'd like you to go out, get some more experience, and then show me the first new ability you learn.", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on training dummies.", completion = "You will find no lack of allies in need of healing. Return to me when you need further training." }
WordHunterWoW_QuestEN[26950] = { title = "The Dark Side of the Light", description = "The Scarlet Crusade lures in anxious young warriors with their promise to eradicate the undead. What they don't see is the dark underbelly of the entire operation.\n\nInterrogator Vishas is the cruelest man I've ever had the displeasure to meet - he 'extracted' information from my mother during the initial outbreak of the plague. The merciless Bloodmage Thalnos watches over their graveyard.\n\nThe crusaders' zealous holy rage blinds them from their own darkness. Make them regret their hypocrisy.", objectives = "Kill Interrogator Vishas and Bloodmage Thalnos.", completion = "What do you mean Thalnos was an undead? That's impossible. This is a holy place, the Scarlet Crusade would never allow...\n\nTake this as a reward, and get some rest. The crypts must have gotten the best of your nerves." }
WordHunterWoW_QuestEN[26951] = { title = "Cleanup on Isle E.", description = "The Battle to reclaim the Echo Isles was a costly one.  But well worth it, <class>.  The great spirit, Bwonsamdi, helped our warriors defeat the foul Zalazane.  He protected our warriors with spirits from the island.  But some of those spirits fell in battle.  Help put those spirits to rest.  On the Echo Isles, you will find masks laying about gather them and bring them here.", objectives = "Gather 8 Disenchanted Tiki Masks.", progress = "Have you gathered the masks, <class>?", completion = "Thanks, <class>.  The spirits can rest now.  As long as we show them respect they will bless us and our new home for a long time.  Spirits be with you, <name>." }
WordHunterWoW_QuestEN[26952] = { title = "The Menders' Stead", description = "I don't like the looks of what the Forsaken are doing here at the Bulwark.  Bombs, cauldrons, needless bloodshed... none of these embody that which the Argent Crusade stands for.  Furthermore, I don't like the fact that they employ mercenaries like yourself.\n\nNothing against you personally, {class}.  It's just that you could be doing so much more for yourself.  If you're interested in healing the plaguelands, rather than re-plaguing them, then report to Field Agent Kaartish at the Menders' Stead to the east.", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, <class>.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land." }
WordHunterWoW_QuestEN[26953] = { title = "Zen'Kiki, the Druid", description = "I am Adrine Towhide, a druid of the Cenarion Circle.  You can thank us for healing this land, where once there was only death.\n\nWe accept all who choose to follow the druidic path, regardless of race, faction, or talent.  Occasionally that means we enlist a druid who needs more help than others.\n\nI'd like you to meet Zen'Kiki.  He's pretty new, and he's still learning his craft.  Would you mind taking him out with you for a while?  You can practice combat on the plagued animals that roam nearby.", objectives = "Kill 20 plagued wildlife with Zen'Kiki by your side. You may kill Hulking Plaguebears, Diseased Wolves, Venom Mist Lurkers, or Plague Lurkers.\n\nReturn to the Menders' Stead if you become separated from Zen'Kiki.", completion = "It looks like Zen'Kiki is still having a little bit of trouble with his shapeshifting." }
WordHunterWoW_QuestEN[26954] = { title = "A Different Approach", description = "Among other things, Zen'Kiki needs to work on his spell accuracy.  I could see his wrath spells spiraling out of control even from here!  In fact, I used them as a marker to follow your progress through the woods.\n\nPerhaps we can use Zen'Kiki another way.  Take him up to the top of the hill just to our east.  The diseased hawks that circle above that hill must be destroyed.  Ask Zen'Kiki to shoot at these hawks.  Even if he can't hit them, he will distract them so you can finish them off.", objectives = "Bring Zen'Kiki to the top of the hill east of the Menders' Stead, then use him to summon and kill 7 Diseased Hawks.", progress = "Back so soon?", completion = "Now we're getting somewhere.  How many birds did Zen'Kiki end up killing?\n\nNone?  You killed them all yourself?\n\nAlright, I suppose we'll have to find another use for him then.  I will let you know when the time is right." }
WordHunterWoW_QuestEN[26955] = { title = "Zen'Kiki and the Cultists", description = "While you've been away, I've been trying a different approach on our friend Zen'Kiki.  I believe he may have a future as a healer.  This is mainly because healing spells never miss.\n\nI hear from Field Agent Kaartish that the cultist camp to the east is where the plagued animals are coming from.  I hope you don't mind escorting Zen'Kiki over there... perhaps he can help heal some of the plagued animals within the camp.", objectives = "Bring Zen'Kiki to the Malicia Outpost in Western Plaguelands, then break 4 Captive Plaguebears out of their cages and allow Zen'Kiki to heal them.", completion = "By the grace of the Earthmother, he's done it!  Thank you, <name>!\n\nI admit, I had nearly given up hope on Zen'Kiki.  It is only due to your patience and diligence that he has come into his own as a druid and member of the Cenarion Circle.  And that's without even mentioning the good you've done for nature.\n\nYou have my admiration and respect." }
WordHunterWoW_QuestEN[26956] = { title = "I Ain't Sayin' You a Gourd-Digger...", description = "{race}!  I'm glad someone's here to help me out.\n\nWe Cenarion druids have re-cultivated Dalson's Farm, immediately behind me.  The land has flourished and our crops have been successful... mostly.\n\nA few plants seem to still be infected by the plague that ran through this land.  Perhaps their roots were too deep, perhaps the seeds were weak... I cannot say.  All I can say is that I need an able {class} like you to help me remove the bad plants from the good ones.", objectives = "Remove 6 Bad Corn, 4 Rotten Apples, and 3 Unhealthy-Looking Pumpkins from Dalson's Farm in Western Plaguelands.", progress = "Have you finished killing... er, removing those plants yet?", completion = "Thank you for your help, <name>.  I know that picking vegetables isn't the most heroic task imaginable, but even the humblest tasks have their rewards." }
WordHunterWoW_QuestEN[26957] = { title = "The Long Trip Home", description = "I've been many places in my life, good {class}.  I fought the battle for Ahn'Qiraj, passed through the Dark Portal into Outland, and joined the Argent Crusade to beat down Scourge in coldest Northrend.\n\nBut before it all, I was a farmer here in Lordaeron.  Now I find myself here in Hearthglen, a scant few miles from home.  It's time I paid my respects.\n\nI'm headed to the Menders' Stead before I return home.  I wouldn't mind meeting up with you again once I get there.", objectives = "Reconvene with Del Gahrron at the Menders' Stead in Western Plaguelands.", completion = "It would appear that I arrived before you, <name>.\n\nField Agent Kaartish gave me the details about my old home.  It seems my battles with the Scourge aren't quite over yet." }
WordHunterWoW_QuestEN[26958] = { title = "Your First Lesson", description = "Let's start your training right away. As you get more experience in combat, you'll start to develop new techniques.\n\nGo, get some more experience, learn something new, and demonstrate it on the dummies to the northwest.", objectives = "Reach level 3 to learn Charge. Find a Training Dummy on the northwest side of the Crash Site and practice using Charge.", completion = "Keep that technique handy, <name>. I find myself using it all the time. Return when you're ready for further training." }
WordHunterWoW_QuestEN[26959] = { title = "Stripping Their Defenses", description = "We need to eliminate the Scarlet Monastery's defenses before a true invasion can begin. Venture deep into here, their library, and assassinate Houndmaster Loksey and Arcanist Doan. They maintain the powerful defenses that protect their comrades.\n\nMy own magic will ensure your actions go undetected by the rest of the monastery. Once they are dead, I can summon in additional reinforcements to aid in our attack.\n\nWe must be successful, <name>, the Dark Lady will not tolerate failure in the slightest.", objectives = "Eliminate Houndmaster Loksey and Arcanist Doan.", completion = "I knew I could count on you! These fools will never know what hit them." }
WordHunterWoW_QuestEN[26960] = { title = "My Son, the Prince", description = "Great burdens have been placed on my son's shoulders in his short lifetime, and I fear his responsibilities are only going to grow.\n\nHe will never learn leadership confined to the keep, but I am loath to send him forth without escort.\n\n<name>, your deeds in the wake of this cataclysm are already legendary. You would be an excellent mentor for young Prince Anduin.\n\nPlease, introduce yourself to him. There is some pressing city business that you both can attend to for me.", objectives = "Introduce yourself to Prince Anduin in Stormwind Keep. Speak with King Wrynn once you are both acquainted.", completion = "Excellent, Anduin will learn a lot by shadowing you.\n\nRemember, stay within the city's borders. Keep him out of trouble. And above all else, guard him with your life.\n\n<King Wrynn turns his attention to his son.>\n\nAnduin, no adventures! Stay close to <name> and return to the keep should you see any trouble." }
WordHunterWoW_QuestEN[26961] = { title = "Gathering Idols", description = "Recently, just before the troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the troggs chased us away from the ruins! And those idols have a strange effect on the troggs. It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of trogg hands!  You can find the idols on the troggs infesting the site.", objectives = "Bring 8 Carved Stone Idols to Magmar Fellhew at Ironband's Excavation.", progress = "Do you have those idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, <name>!\n\nAnd you don't look too worse for wear, even with those berserk troggs about.  I'm going to keep my eye on you...you show some promise." }
WordHunterWoW_QuestEN[26962] = { title = "Stripping Their Offense", description = "As you can see, <name>, our first assault on the Armory did not go as planned. We had taken the nearby courtyard until the Scarlet Champion, Herod, showed up.\n\nWe must continue our assault. The Scarlet Crusade will never be allowed to train another warrior here, let alone launch an attack on the Undercity.\n\nYour task should be obvious. Down the Scarlet Champion.", objectives = "Kill Herod.", completion = "Herod is slain! The Armory will fall!" }
WordHunterWoW_QuestEN[26963] = { title = "Steadying Your Shot", description = "Let's start your training right away. It's going to be a struggle to survive here, and you'll play an important role in making sure our people are safe and well-supplied.\n\nAs you become more experiened, you'll begin to discover new abilities. Go ahead and go out, learn something new, and try it out. Return to me when you think you've mastered it.", objectives = "Reach level 3 to learn Steady Shot. Find a Training Dummy on the northwest side of the Crash Site and practice using Steady Shot 5 times.", completion = "Keep that technique handy, <name>. I find myself using it all the time. Return when you're ready for further training." }
WordHunterWoW_QuestEN[26964] = { title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\nOnward, brother! Destiny calls!", objectives = "Report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.", completion = "Most excellent! A new recruit has arrived. There is much to do... much to do I say." }
WordHunterWoW_QuestEN[26965] = { title = "The Warchief Cometh", description = "You're just in time, {name}nub. It is {name}nub, right?\n\n<Grand Executor Mortuus looks at a sheet of paper.>\n\nYes, that's what the paperwork says: \"{name}nub.\"\n\n<Grand Executor Mortuus points to your name on the sheet of paper.>\n\nWhere was I? Oh yes, you're just in time! The Warchief should be arriving at any moment to meet with our leader and savior, the Dark Lady herself. Just stand by and be at your best behavior. I expect that when this demonstration is over we will all receive commendations!", objectives = "Stand by for Warchief Garrosh Hellscream's arrival.", progress = "Stand at attention, Zulazanjinub!", completion = "Well that was unexpected. I am not one to doubt our Warchief, but...\n\nNevermind! We have work to do. I'm sure the Dark Lady and the Warchief will get this all worked out." }
WordHunterWoW_QuestEN[26966] = { title = "The Light's Power", description = "As a paladin, you're no stranger to the Light that touches all of us. But you also have the unique power to call upon the Light to help you in battle.\n\nAs you gain more experience, you'll grow even closer to the Light and be able to call upon new powers in battle.\n\nGo, grow in experience until you have learned a new power, and then demonstrate it for me.", objectives = "Reach level 3 to learn Seal of Command. Apply Seal of Command, find a Training Dummy on the northwest side of the Crash Site and hit it with an attack.", completion = "You've proven yourself a quick learner, <name>. I look forward to training you again when the time is right." }
WordHunterWoW_QuestEN[26967] = { title = "Battle for the Scarlet Monastery", description = "Behold the might of the Forsaken! The unstoppable will of the Dark Lady flows through our bodies! \n\nThe vast majority of the crusade's remaining forces have fled. Some, however, remain defiant.\n\nYou have been instrumental in this campaign's success. Sylvanas extends the honor of slaying her last remaining enemies to you, <name>.\n\nShow no mercy.", objectives = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", completion = "Yes! The Scarlet Monastery now belongs to the Forsaken! None can escape our wrath!\n\nYou've completed your task with the precision of a true champion. Take this as a reward, courtesy of the Banshee Queen." }
WordHunterWoW_QuestEN[26968] = { title = "Frost Nova", description = "In your future as a mage, you'll want to master a wide variety of spells. To do so, you need to deepen your connection by the arcane by growing in power.\n\nGo, get more experience as a mage, and demonstrate what you learn for me.", objectives = "Reach level 3 to learn Frost Nova. Find a Training Dummy on the northwest side of the Crash Site and practice using it 2 times.", completion = "You've mastered the use of this new spell quickly, <name>. I only wish all of my students were as talented. Return to me when you find yourself in need of further training." }
WordHunterWoW_QuestEN[26969] = { title = "Primal Strike", description = "Your walk with the elemental powers will take you to many places. As you grow in power, you will begin to learn new abilities. \n\nLet us start your journey with a simple, but useful, lesson.\n\nLearn the secret of Primal Strike, and then practice your new skill using the training dummies to the northwest of the Crash Site. Return to me when you are finished.", objectives = "Learn Primal Strike by reaching Level 3, and then find a Training Dummy on the northwest side of the Crash Site and practice using Primal Strike 3 times.", completion = "It is a pleasure to teach such a capable student. As long as you continue the traditons faithfully, the shamanic arts will never be lost to our people again. Return to me when you need further training." }
WordHunterWoW_QuestEN[26970] = { title = "Learning the Word", description = "As a priest, one of your most important duties is to use the Light's power to aid the wounded.\n\nAnother is to use your power offensively, to protect them.\n\nAs you grow more experienced, you will begin to uncover new abilities that you can use in your charge. Go, gain more experience, and then demonstrate the abilities you have learned to me.", objectives = "Reach level 3 to learn Shadow Word: Pain, then use it 5 times on target dummies near the crash site.", completion = "You'll often find your skills as a healer in demand, <name>. Do not hesitate to return when you need more training." }
WordHunterWoW_QuestEN[26971] = { title = "The Binding", description = "A noise in the main chamber of the temple draws your attention. You hear a familiar laugh... Lorthuna. She's returned to interrupt the ritual - you must stop her!", objectives = "Kill High Priestess Lorthuna.", completion = "Maruut said when all dis started dat he would gladly give his life ta see our task done. He would be proud of dis success... of dis death.\n\nDa rift be closed on dis side. Deepholm should calm down a bit. It'll be takin' time for Thrall to mend da wound in Azeroth, and we'll be needin' to remain until he finishes.\n\nThank you for all ya've done. I don't tink we could have been accomplishin' dis so soon without you." }
WordHunterWoW_QuestEN[26972] = { title = "The Dark Side of the Light", description = "I joined the Scarlet Crusade as a young paladin, eager to cleanse the world of evil. Little did I know of the dark truth to these fanatics.\n\nInterrogator Vishas and Bloodmage Thalnos oversee this graveyard. They take great pleasure in torturing new recruits endlessly to ensure that they are 'pure'. It is an affront to the light, <class>!\n\nNo longer can I be a part of this corrupt organization. You're going to have to kill them both, so that others will never endure the same pain I did.", objectives = "Kill Interrogator Vishas and Bloodmage Thalnos.", completion = "What do you mean Thalnos was an undead? That's impossible. The entire mission of the Scarlet Crusade is to destroy the undead! There's just no way...\n\nYou have muddied my thoughts. Please take this reward for your achievement and leave me to rest." }
WordHunterWoW_QuestEN[26973] = { title = "The Only True Path", description = "I think that the root of the crusade's corruption can be found here. Arcanist Doan watches over the library, and teaches many young recruits to wield the arcane arts.\n\nThe Light is the only true path! You must kill him, <class>, and redeem this glorious movement!\n\n<Joseph the Awakened shifts nervously.>\n\nYou'll want to dispose of Loksey as well. His hounds seem to disapprove of our noble intent.", objectives = "Eliminate Houndmaster Loksey and Arcanist Doan.", completion = "Good work! I just know the Light shines favorably upon us for our work. Our cause is righteous!" }
WordHunterWoW_QuestEN[26974] = { title = "The False Champion", description = "We...we...we had to kill them! They were coming right for us!\n\nYou believe me, don't you <name>?\n\nHerod is not the true champion of the Scarlet Crusade. I am! He took what was rightfully mine!\n\nYou should kill him. He's...a menace! Trains the soldiers to kill anyone instead of just the undead!\n\nI'll reward you handsomely...", objectives = "Kill Herod.", completion = "So he's really dead? That means...I, Joseph, am the new Scarlet Champion!!!\n\nTake this. I don't have a need for such possessions anyways! I'm the Scarlet Champion, after all." }
WordHunterWoW_QuestEN[26975] = { title = "Rallying the Fleet", description = "I am amassing a warfleet to assault Twilight Highlands and bring an end to Deathwing's lackeys. My soldiers are ready but fleet preparations lag behind.\n\nMy men at the docks need some inspiration and motivation. A visit from the Prince here should lift their spirits and remind them of the bright future they're fighting for.\n\nTake Prince Anduin to the docks with you and speak with Supply Sergeant Graves. I want Anduin to observe how a natural leader handles the situation.", objectives = "Escort Prince Anduin to the Stormwind Docks and talk to Supply Sergeant Graves. If you get separated from the Prince, you'll find him in the Stormwind throne room.", completion = "<Graves bows respectfully to the Prince.>\n\nPlease understand your highness, the men are working double-shifts. The scale of your father's operation is enormous.\n\nBut we will endeavor to wrap things up. I give you my word." }
WordHunterWoW_QuestEN[26976] = { title = "Battle for the Scarlet Monastery", description = "Oh, it's great to see you again <name>! I'm afraid I'm going to need your help.\n\nYou see, Mograine's the Commander here along with High Inquisitor Whitemane, and they tried telling me that I wasn't really the new Scarlet Champion! 'Course, the boys and I didn't take kindly to that.\n\nWe're taking the Scarlet Monastery for our own and re-establishing the order as it always should have been - with me at the head of things! I'll take care of the Forsaken and the Scourge for good.\n\nHelp an old friend out?", objectives = "Kill Scarlet Commander Mograine and High Inquisitor Whitemane.", completion = "Yes! The Scarlet Monastery is ours! You're a real friend. Take this as a reward, and feel free to visit again once I've taken the Undercity too.\n\nIt'll be a Scarlet Paradise!" }
WordHunterWoW_QuestEN[26977] = { title = "Twilight Investigation", description = "The city is still reeling from the seditious acts of the Twilight's Hammer in recent months. They prey on peasant fears and corrupt our most important citizens. We need to find out how deep the conspiracy runs.\n\nI've tasked Major Samuelson of the Stormwind City Guard to head up an investigation. He's right here in the throne room. See if you can assist his efforts.", objectives = "Speak with Major Samuelson in Stormwind Keep.", completion = "Hmmm, yes? My investigation of the Twilight's Hammer. Of course.\n\nYour assistance will be valuable." }
WordHunterWoW_QuestEN[26978] = { title = "Who Needs Cauldrons?", description = "Have you seen the condition of Felstone Field?  The Alliance forces at Andorhal have taken the area, and they're using it to... to... to grow CROPS!\n\nI almost liked it better when the Scourge held the area.  At least they had the sense to put a giant plague cauldron in the middle of the field.\n\nWe're going to take that farm back from these humans, {name}.  Take these drums and place them at key locations around the field.  I'll be waiting here at the Bulwark.", objectives = "Place Dithers' Plague Drums near the Windmill, the Grain Silos, the Ranch House, and the Barn at Felstone Field.", completion = "<Dithers practically glimmers with excitement.>\n\nThe drums are placed?  In their positions?\n\nVery well then, I will give the word to the High Executor.  When the time is ready, he will be the one to press the ignition switch." }
WordHunterWoW_QuestEN[26979] = { title = "Strange New Faces", description = "Now that Felstone is ours, we can use its acreage - and any dead bodies we find - for our own purposes.  I've received orders from higher up that you are going to be helping out in this process.\n\nYou may have met Lindsay Ravensun on the battlefield in Andorhal.  I've never met her before, but she seems to have made some friends in high places, because she's taking over operations at Felstone.  You're to meet her at the charred Scarlet camp... the one you scouted out earlier.", objectives = "Report to Lindsay Ravensun at the Charred Outpost in Western Plaguelands.", completion = "<name>.  The Dark Lady watches over you." }
WordHunterWoW_QuestEN[26980] = { title = "Swiftgear Station", description = "You've done good work here, {name}. Askin' you to haul sandbags would be a waste, to be honest; I'd rather send you along where your skills are needed.\n\nWe've got a small outpost up north in the marsh. Swiftgear's the gnome that built it, but you'll want to talk to Shilah Slabchisel and help her with Ironforge matters.\n\nI'll admit, she's a looker... but I wouldn't make the mistake of getting fresh with her! They don't call their family Slabchisel for nothing.", objectives = "Speak with Shilah Slabchisel at Swiftgear Station, north of Menethil Harbor.", completion = "Stoutfist sent you, eh? He's a good captain, runs his men well. Just wish he'd stop starin' at my midriff.\n\nDon't let me catch you doin' it either. We've work to take care of here!" }
WordHunterWoW_QuestEN[26981] = { title = "Whelgar's Retreat", description = "Prospector Whelgar's been leading an excavation in the mountains southeast of here for quite some time. He had some raptor problems back in the day, but things were going better recently.\n\nJust the other day, we got word he had to evacuate the entire digsite again. I'm not sure what's going on there, but I can't imagine the cataclysm making a quarry any safer than it was before.\n\nThere's good dwarves working there, {name}. Would you go see what's wrong there, and maybe lend a hand?", objectives = "Speak with Prospector Whelgar at Whelgar's Retreat, southeast of Swiftgear Station.", completion = "Well met, <class>. We've got raptor problems for sure... sort of.\n\nMore like the entire dig site deciding to attack us. I've never seen rocks and fossils get so upset!" }
WordHunterWoW_QuestEN[26982] = { title = "The Scarlet Monastery", description = "The same Monastery in Tirisfal Glades that the Scarlet Crusaders now occupy used to be a major training ground for our paladins. Now the Forsaken loom over it from the Undercity and the Crusade prevents us from utilizing it to train the very soldiers we need to deal with the Forsaken!\n\nLook, I don't trust him, but Joseph the Awakened waits inside the graveyard. Go speak with him - although he is a crusader, he says he now rebels against them, providing us with an opportunity to take back what's ours.", objectives = "Visit Joseph the Awakened.", completion = "Captain Nials sent you? I haven't seen her in ages! How is she? Did she get my letter?\n\nOh, you're not here for that. Well then, let's get down to business!" }
WordHunterWoW_QuestEN[26983] = { title = "Just Close Enough", description = "Make no mistake - there is a ton of stuff to be done here! However, we also need to strike at the Forsaken where it hurts. The Scarlet Monastery in Tirisfal Glades is the perfect distance from the Undercity and Brill.\n\nReport to Joseph the Awakened in their Library. He's a rebel crusader that can hopefully help us take the Monastery as our base of operations in that region, and maybe take out Arcanist Doan, one of their most powerful mages, in the process.", objectives = "Visit Joseph the Awakened.", completion = "You came here from Southshore, eh? I bet you hunger for revenge against the vile Forsaken that trashed the place. The Scarlet Crusade can help take care of that!\n\nRight after you help me realign their misguided souls, that is." }
WordHunterWoW_QuestEN[26984] = { title = "An Old, Crazed Friend", description = "Joseph the Crazed was one of my good friends before he joined the Scarlet Crusade up in the Scarlet Monastery in Tirisfal Glades. I heard that he's in the Armory there trying some ridiculous attempt at taking over Herod's position as Scarlet Champion.\n\nIt's a death wish to challenge Herod like that! Go up there and try to talk him out of it.", objectives = "Visit Joseph the Crazed.", completion = "You look pretty tough, <class>. There are wrongs to be righted here. Let's get started." }
WordHunterWoW_QuestEN[26985] = { title = "Pitting Madness Against Madness", description = "Our renewed forces can handle the situation here for a while without you. I've received reports that Joseph the Insane, a former Scarlet Crusade officer, is in the Scarlet Monastery Cathedral and is taking his band of renegades to strike out against Scarlet Commander Mograine.\n\nThis is an excellent opportunity. Go there and help him with his insane task, and maybe we can use the Monastery as an excellent stronghold right at Sylvanas' doorstep!", objectives = "Visit Joseph the Insane.", completion = "Wait, you were sent here by THE Shandris Feathermoon? I can barely believe my ears! To know that my cause is supported by her massive army...\n\nYes, yes, you will be perfect. You're the key to my future!" }
WordHunterWoW_QuestEN[26986] = { title = "Into the Scarlet Monastery", description = "Oftentimes the best way to ensure our men sustain as few injuries as possible is to cause great harm to our enemies in their very homes and prevent battles from ever occurring!\n\nTravel to the Scarlet Monastery and speak with Dark Ranger Velonara in their graveyard. She is leading a Forsaken assault there and could benefit from a seasoned <class> such as yourself.", objectives = "Report to Dark Ranger Velonara.", completion = "It looks like Darthalia sent an able <class>, as I requested." }
WordHunterWoW_QuestEN[26987] = { title = "The Right Way", description = "My people are not generally fond of the arcane arts that so many other races abuse. Thankfully the wizards within the Scarlet Monastery library are separated from us by considerable land, but their ability to transcend the physical realm concerns me and, ultimately, my tribe's survival.\n\nTravel far to the west to the monastery's library and speak with Dark Ranger Velonara there. Her forces are already poised to strike at Arcanist Doan himself, head magi for the crusade.", objectives = "Speak to Dark Ranger Velonara.", completion = "I'm surprised to see Huntsman Markhor working with me for once. He's usually quite stubborn. He does tend to a strong hatred for magic, though.\n\nI hope you do, too, <class>, because we're going to strip the Scarlet Crusade of theirs." }
WordHunterWoW_QuestEN[26988] = { title = "Moving Things Along", description = "I'm waitin' on some very powerful reagents I ordered from the Undercity not long ago. I heard that the shipment is late because the Scarlet Monastery's crusaders are blocking its passage. Da Scarlet Champion, Herod, is likely to blame for dis annoyance.\n\nPlease go speak to Dark Ranger Velonara in the Scarlet Monastery's armory, she is goin' to 'take care' of Herod, which means my shipment will arrive safely!", objectives = "Visit Dark Ranger Velonara.", completion = "Yayo'jin is correct, you helping me here will aid her in the Hinterlands as well.\n\nAll the more reason to get started immediately." }
WordHunterWoW_QuestEN[26989] = { title = "The Gilneas Liberation Front", description = "The battle over this region still rages, {name}nub. Although we soundly beat back the Gilnean defenses and took Gilneas for the Horde, a small group of rebels managed to escape. The \"Gilneas Liberation Front\" - as they call themselves - make attacks of opportunity against our forces in the field. The rebels have had a few minor victories and now grow brazen in their assaults! The time to strike back is now, {name}nub.\n\nVenture south into the wilds of Silverpine and kill any rebel that you cross.", objectives = "Kill 10 Worgen Renegades.", progress = "What have you to report, Duridnub?", completion = "Vorelocknub has returned! And in one piece!\n\nDefender of Silverpine! Redeemer of the Horde! Vorelocknub, your bravery must be rewarded!" }
WordHunterWoW_QuestEN[26990] = { title = "Water They Up To?", description = "It appears that the Sandfury trolls are working with the Twilight's Hammer.\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell Hamuul Runetotem what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", objectives = "Slay Kai'ju Gahz'rilla and inform Hamuul Runetotem in Thunder Bluff.", completion = "Sandfury trolls and the Cult of Twilight's Hammer, you say?\n\nAnd they meant to send some giant monster into the heart of the city?!\n\nWell done! Thunder Bluff is in your debt." }
WordHunterWoW_QuestEN[26991] = { title = "Enemies Abroad", description = "Sometimes we must acknowledge the need to protect our allies so that they may protect us. This is one such occasion, <race>.\n\nTravel to the Scarlet Monastery near the Undercity in Tirisfal Glades. Once you arrive, go to the Cathedral and speak with Dark Ranger Velonara. She is leading the final assault against the crusade there, and it would benefit us all greatly to ensure our undead allies secure the monastery before the crusaders have a chance to attack their capital.", objectives = "Find Dark Ranger Velonara.", completion = "Nazeer is a strong warrior - his hatred for our enemies rivals my own. You are welcome help to my forces." }
WordHunterWoW_QuestEN[26992] = { title = "Agony Abounds", description = "You have no doubt heard about the incident that transpired at the Wrath Gate in Northrend, yes? Due to those unfortunate events we are strictly forbidden from using the strain of life-shattering blight that we finally perfected. Now we have rules and regulations and other nonsense!\n\nThey've given us some neutered version of the perfected blight and expect us to weaponize it.\n\nIf I'm to get this crap functional I'll need several bags full of ferocious doomweed. You'll find it all over Silverpine.", objectives = "Gather 8 Ferocious Doomweed.", progress = "Have you collected the ferocious doomweed I requested?", completion = "Agony abounds, friend! The land itself threatens to devour us, and yet we persist. I wonder why that is? With this doomweed and the guts and gore that T'Veen needs, we might have something suitable to send to the Forsaken front." }
WordHunterWoW_QuestEN[26993] = { title = "Compendium of the Fallen", description = "Don't fret, I serve no master, <race>. Within these halls lies a book called the Compendium of the Fallen. It holds vast amounts of research that the Scarlet Crusade has done on my kind over the years.\n\nSimply put, I'd like you to retrieve it and bring it back to me. No questions asked.", objectives = "Retrieve the Compendium of the Fallen.", progress = "I don't want to stay in a monastery packed full of undead-hating zealots for much longer. Surely you can understand why. Don't speak to me if you don't have the book with you.", completion = "Well done. How about I give you a nice reward for your work, and you don't tell a soul that you saw me here. Deal?" }
WordHunterWoW_QuestEN[26994] = { title = "Without Rhyme or Reason", description = "I heard that Joseph the Crazed wants you to kill Herod. While you're at it, how about you slaughter their top soldiers? I'll pay you well for your work.\n\nDon't worry about the why, just worry about the how.", objectives = "Kill 3 Scarlet Myrmidons, 3 Scarlet Protectors, 3 Scarlet Guardsmen, and 3 Scarlet Evokers.", completion = "Very good. Yes, very good indeed.\n\nYour reward, as promised. No questions." }
WordHunterWoW_QuestEN[26995] = { title = "Guts and Gore", description = "If we're to get this new blight up and running we'll need clean beast guts. The problem is that clean beast guts are a rare commodity in Silverpine Forest. Most of the beasts here have succumbed to disease and thus only have diseased organs.\n\nDo a sweep of the forested area east of here for worgs and grizzled bears. Kill only the non-diseased variety and rip out their entrails. Bring me all of the clean guts that you can stuff into your backpack!", objectives = "Recover 6 \"Clean\" Beast Guts.", progress = "Remember, I can only use clean beast guts for the new strain of blight we're developing.", completion = "Excellent! With these guts and the ferocious doomweed we'll be able to test out our new strain of blight. Now to select a suitable target..." }
WordHunterWoW_QuestEN[26996] = { title = "Right Under Their Noses", description = "In the right side-room of the accursed cathedral ahead there is a torch on the wall. Move it and a secret door will open. Inside is High Inquisitor Fairbanks. He is now an undead.\n\nI need him taken care of. Kill him in his own room if possible, I'd strongly prefer the crusaders not see him. You know the deal - kill him, and I'll reward you. No other words are necessary between us.", objectives = "Kill High Inquisitor Fairbanks.", completion = "<Dominic hands you your reward. No words are spoken.>" }
WordHunterWoW_QuestEN[26997] = { title = "The Usual Suspects", description = "<Samuelson scratches his chin, absently.>\n\nMy investigations reveal, ah, it's likely that there's trouble brewing among the Stormwind dock workers. Shifty lot. Don't trust 'em.\n\nYou should go there and shake the place down. Start grilling those longshoremen. That should keep you busy.\n\nGo rout out those Twilight infidels!", objectives = "Grill 6 Stormwind Dock Workers in Stormwind Harbor.", completion = "This doesn't make any sense, <name>.\n\nWhy was Samuelson sending us out here on a wild goose chase?\n\nSomething doesn't feel right. We should poke around on our own..." }
WordHunterWoW_QuestEN[26998] = { title = "Iterating Upon Success", description = "The concoction is finally ready, but before I can put my seal of approval on this strain, we'll need to run a field test.\n\nSpeak to Bat Handler Maggotbreath, here at High Command, and requisition a bat. The bat will take you to the Dawning Isles, east of here across Lordamere Lake, right into the heart of depravity itself - the Vile Fin murloc dens!\n\nUse the concoction against the murlocs and report the results back to me.\n\nThose results being that you killed them all, as commanded!", objectives = "Kill 50 Vile Fin Murlocs.", progress = "Have you exterminated the Vile Fin murlocs of the Dawning Isles?", completion = "Potent enough to exterminate a thousand murlocs! I think I'll put that on the label. You've done well, <name>, and great work around here gets rewarded." }
WordHunterWoW_QuestEN[26999] = { title = "A New Era for the Plaguelands", description = "No longer does the Scourge hold this area.  We, the living, are retaking Lordaeron.\n\nWe have taken great strides already, as you have already seen.  The earth flowers, the trees grow tall and green, and the wildlife is beginning to return.  Yet a few remnants of undeath remain.\n\nWhile the trees and grass prosper, the animals are struggling.  Something is preventing them from healing, and I intend to find out what.  Bring me samples from the plagued wildlife so that I may study them more closely.", objectives = "Obtain 4 Plague Lurker Samples, 4 Venom Mist Lurker Samples, 4 Hulking Plaguebear Samples, and 4 Diseased Wolf Samples.", progress = "Once the animals are healed, our duties here will be nearly complete.", completion = "This will be more than enough, <name>.  Now, I will need some time to perform my studies." }
WordHunterWoW_QuestEN[27000] = { title = "Learning the Ropes", description = "Ah, it's good to be back in Northridge!  I've got my mill, my beautiful wife, a bouncing baby boy... I've even put in my hat with the Argent Crusade.  We'll be supplying Tirion's forces with lumber.\n\nMy lumberjacks were being exceptionally productive, too... up until the point when the spiders came.  Now they refuse to go any deeper in the woods.\n\nMaybe you can help me out.  Hop on one of my horses and use it to frighten those spiders.  Maybe we can avoid bloodshed and just scare them away.", objectives = "Mount a Hearthglen Mustang at Northridge Lumber Mill, then use its Whinny ability to frighten 25 Northridge Spiders.", progress = "The spiders tend to be a little skittish.  One of the mustangs should be enough to scare them away.", completion = "Well, it sounds like they're certainly afraid of the mustang, but they're not leaving for good.  I can't have you running around on a horse forever.  Nor do I think you'd want to.\n\nFine.  Bloodshed it is." }
WordHunterWoW_QuestEN[27001] = { title = "This Means WAR (Wild Arachnid Roundup)", description = "The Highlord was generous enough to send some of his recruits to protect us here at the mill.  With your horsemanship skills, and their martial prowess, we can do away with this spider problem easily.\n\nHop back on that mustang and scare those spiders again, but this time, scare them all the way up here to the mill.  These Hearthglen recruits can handle things from there.", objectives = "Mount a Hearthglen Mustang near the Northridge Lumber Mill, then use its Whinny ability to send 10 Northridge Spiders to the Hearthglen Recruits at the Northridge Lumber Mill. You can round up several spiders at once.", completion = "That's much more like it!  Now my lumberjacks can get to work again.\n\nNice riding out there, <name>.  You cut a pretty impressive silhouette on that mustang." }
WordHunterWoW_QuestEN[27002] = { title = "An Audience with the Highlord", description = "Oh, before you go, {name}... I have a message for you.  There's someone in Hearthglen who'd like to meet with you.  Said he's \"heard your name pop up\" a few times already.\n\nConsider yourself lucky, {name}.  Not everybody gets a personal audience with Highlord Tirion Fordring.\n\nOh, and feel free to use one of my mustangs for the ride up there.  They're the fastest money can buy.", objectives = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", completion = "<name>.  It is truly a pleasure.\n\nI know you are young, and still training, but I've had my eye on you.  We among the Argent Crusade are always looking for promising new recruits, and you have indeed shown great promise.  I have no immediate tasks for you, but merely wished to meet you in person, and see for myself what type of <race> you really were.\n\nFor the time being, the amenities of Hearthglen are yours to enjoy.  I look forward to our next meeting, <name>.  You are dismissed." }
WordHunterWoW_QuestEN[27003] = { title = "Easy Money", description = "Well, hello there!\n\nWhatever brought you, I'm so glad that you're here! My friends will never admit to it, but we could really use a hand.\n\nThe ancient region of Uldum has been exposed! Treasures beyond your wildest dreams, free for the taking!\n\nWe just need a bit of an escort, what with the bandits and all...\n\nYou'll accompany us, won't you?\n\nYou're welcome to all the loot you can haul off!", objectives = "Accompany Adarrah's caravan into Uldum.", completion = "Smells like someone else was in this cell recently.\n\nGross!" }
WordHunterWoW_QuestEN[27004] = { title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKeep searching the cultists until you find them.", objectives = "Collect the Masters' Gate Plans.", progress = "Those plans are the key to everything.", completion = "<Mowi takes a look at the plans that you hand to her.>\n\nBut... but, this is just gibberish!\n\nWhat does this even say? What language is that?" }
WordHunterWoW_QuestEN[27005] = { title = "The Twilight Plot", description = "We came here to investigate rumors of a Titan artifact up at the Masters' Gate to the southwest.\n\nOne of those Twilight's Hammer cultists must have the plans for what they're doing up there. You're going to have to get them for us, {name}.\n\nKill cultists at the Masters' Gate until you find them.", objectives = "Collect the Masters' Gate Plans.", progress = "Those plans are the key to everything.", completion = "<The examiner takes a look at the plans that you hand to him.>\n\nThis is just gibberish!\n\nWhat does this even say? What language is that?" }
WordHunterWoW_QuestEN[27006] = { title = "Fly Over", description = "I tried ta fly o'er the terrace an have a look fer myself, but those toastie eatin' pansies kept shootin' at me, an I couldn't get near.\n\nYa look like ya might be handy with the reins. Why don' ya take yer flyin' beastie up there ta the southwest and see what all the fuss is about?", objectives = "Investigate the central area in the back of the Masters' Gate.", progress = "What'd ya see? What are those cheese lovers up ta?", completion = "A waygate?! The culties dug up a Titan waygate?" }
WordHunterWoW_QuestEN[27007] = { title = "Silvermarsh Rendezvous", description = "Excellent work, {name}.  We know exactly where the meeting location is.\n\nThe Upper Silvermarsh is a mercury swamp to the east of here.  It's normally only inhabited by elementals and occasional stone troggs, but our scouts have seen some Twilight activity in the region.\n\nMake your way there and let's find a way to eavesdrop on the Forgemaster's meeting.", objectives = "Go to the Upper Silvermarsh in Deepholm.", completion = "This is the place.  Our scouts confirmed the presence of high-ranking Twilight officers nearby as well as potential trogg hunting parties.\n\nBe on the lookout, <name>." }
WordHunterWoW_QuestEN[27008] = { title = "Fly Over", description = "I'm quite adept at riding my flying carpet. Unfortunately, when I tried to investigate what the cultists had uncovered up at the Masters' Gate, they nearly shot me down.\n\nYou look as if you might be skilled with the flying reins as well. Would you mind flying up there to the southwest to see what they've unearthed?", objectives = "Investigate the central area in the back of the Masters' Gate.", completion = "A waygate?! They unearthed a Titan waygate.\n\nThis is very interesting and potentially very bad." }
WordHunterWoW_QuestEN[27009] = { title = "The Coldbringer", description = "Amnennar the Coldbringer rules over the Razorfen Downs with very dark and powerful Scourge magic. I have managed to clear an opening in the thorns just above his seat of power, but his sorcery prevents me from launching an assault.\n\nIf you venture up the Spiral of Thorns and engage him, he will be distracted long enough for me to attack him briefly, weakening him before he can use his most deadly spells. Once he is weakened, destroy him without mercy.", objectives = "Kill Amnennar the Coldbringer.", completion = "A job well done, <name>. The Quilboar here can no longer be saved, but at least they are no longer organized for attack, or slaves under Amnennar's tyrannic rule.\n\nLeave quickly, please. Razorfen Downs is without hope. It must be purged." }
WordHunterWoW_QuestEN[27010] = { title = "Quicksilver Submersion", description = "The troggs in Deepholm have proven to be every bit as hostile as the ones in Azeroth.  Yet perhaps their presence will prove useful to our efforts.\n\nThe crates they use for trawling through the mercury will conceal you perfectly if you submerge yourself beneath the marsh.\n\nUse it to approach the Twilight's Hammer camp in the eastern end of the Upper Silvermarsh undetected.", objectives = "Obtain a Trogg Crate and use it to submerge yourself and eavesdrop on the Twilight's Hammer camp to the east.", completion = "We have the information we need.  Let's not tip our hand by engaging the enemy too soon." }
WordHunterWoW_QuestEN[27011] = { title = "Redpine Thievery", description = "Farther to the south, you will find Redpine gnolls... a new arrival to the area.  You probably passed some on your way here.  Nathaniel pretends like they're not a problem, but I know better.\n\nI've seen them running away with our lumber at night.  I don't know what they'd do with lumber - they don't seem particularly handy - but that doesn't stop them from stealing it.  Head down to their camps and steal that lumber back.", objectives = "Retrieve 10 piles of Northridge Lumber from the Redpine Camp in Western Plaguelands.", progress = "Some of the older lumberjacks tell me that the Redpine lived in the area several years ago, but left when the plague arrived.  That doesn't make it OK for them to steal, though.", completion = "I'll just put this back over in the lumber stores outside.  Nathaniel probably won't even notice it was missing." }
WordHunterWoW_QuestEN[27012] = { title = "A Gnoll's Resolve", description = "I have my doubts about those gnolls' intentions.  They haven't attacked us yet, but their numbers are growing, and they seem to always have their weapons ready.  I'm no military expert, but that seems a little aggressive to me.\n\nMaybe if we took away some of their weapons, they'd be a little less likely to pose a threat to our mill.  I'd feel much better about the whole situation if you went down there and brought some of their weapons back to me.", objectives = "Obtain 6 Redpine Staves and 6 Redpine Clubs from Redpine Gnolls.", progress = "I don't want to order some sort of mass gnoll genocide because of a mother's worries.  I'd just like to feel safe in my own home.", completion = "Thank you, <name>.  I'll be throwing these in the fire.  We don't want those gnolls just sneaking in and stealing them back." }
WordHunterWoW_QuestEN[27013] = { title = "Too Close for Comfort", description = "I'm happy for Nathaniel: he's spent so long trying to return to Northridge, and now with the Scarlet Crusade out of the way, he can finally move back home.  It's just... even for such a seemingly-idyllic setting, it's not really the best place to raise a family.\n\nFor example: along this valley's edge, you will find rabid foxes searching for innocent prey.  Every once in a while I catch a glimpse of one looking right at me.\n\nPlease, {class}, remove some of these foxes.  I don't feel safe with them near.", objectives = "Kill 12 Rabid Foxes near Northridge Lumber Mill in Western Plaguelands.", progress = "I have a family to raise, and I need to do whatever I can to protect them.", completion = "I feel a bit more relieved, <name>.  Thank you." }
WordHunterWoW_QuestEN[27014] = { title = "Hallowed Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the priest trainer, Seer Ravenfeather. If this note is from the seer, I would go looking for her immediately.", objectives = "Speak to Seer Ravenfeather in Camp Narache.", progress = "I am pleased to meet you, <name>.", completion = "You have arrived at last. During your training in Camp Narache, I will guide you in the ways of the <class>. You have much to learn and I look forward to counting you among my students." }
WordHunterWoW_QuestEN[27015] = { title = "Consecrated Note", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the paladin trainer, Sunwalker Helaku. If this note is from the sunwalker, I recommend going to see him immediately.", objectives = "Speak to Sunwalker Helaku in Camp Narache.", progress = "I am pleased to meet you, <name>.", completion = "We have much to cover. In time, the ways of the sunwalkers will be as plain and natural to you as the shaman's conversations with the elements." }
WordHunterWoW_QuestEN[27016] = { title = "The Joy of Boar Hunting", description = "Try to contain your excitement, {name}, for you are in the presence of the greatest boar hunter in Azeroth!\n\nTheir cunning intellect, rapid speed, ferocious strength, and resilient hide... yes, boars are the quarry of only the most masterful of hunters. Amateurs need not apply!\n\nWhy, I bet you've never even hunted such an exotic beast. I'll bet silver any day that you can't match my record of ten boars killed. Try the ones on the eastern shore of the loch... but don't hurt yourself now, rookie!", objectives = "Kill 10 Mudbelly Boars.", completion = "You've killed ten already? H...hah! While you were out, I've broken my previous record! To ten... hundred! Yes, ten hundred boars!\n\nA bet is a bet, I suppose... here's your consolation prize, <name>!" }
WordHunterWoW_QuestEN[27017] = { title = "Memories from a Lost Past", description = "It's funny the things you remember.  I spent 16 hours a day working the fields, and every seventh day I'd head into bustling Andorhal to sell what I'd grown.  It was a tough life, but we did alright.\n\nBut I barely remember any of that.  When I think back to those days, I think about Gloria's smile, or Andrea waving from the window whenever I'd look up from the plow.\n\nThe farm's just a bit to the east, but I'm not sure I'm ready to go back, {name}.  I'd just like to make sure I hold on to these memories.", objectives = "Travel to the farm house in Gahrron's Withering and gather any mementos you can find.", progress = "I wouldn't expect you to indulge the whims of a nostalgic old man, <name>.  Still, if you find yourself in the area...", completion = "This... Gloria used to read from this prayer book every night!  How had I forgotten?  She was so devout, <name>.\n\n\n\nOh...\n\nThis painting... my daughter, Andrea... she loved to... to paint..." }
WordHunterWoW_QuestEN[27018] = { title = "The Herald <NYI>", description = "", objectives = "" }
WordHunterWoW_QuestEN[27019] = { title = "Scourge of the Downs", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but somebody needs to do it and I seriously doubt other adventurers will wander into this desolate place.", objectives = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us <name>, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top." }
WordHunterWoW_QuestEN[27020] = { title = "The First Lesson", description = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before.\n\nYour first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy in Camp Narache and practice using Charge.", completion = "You have done well, <name>. Return to me when you are in need of further training." }
WordHunterWoW_QuestEN[27021] = { title = "The Hunter's Path", description = "It is time for your first lesson, <name>. You have a long way to go to master the ways of the hunter, but as you complete more of your journey, you begin to take new steps on that path.\n\nGo, get more experience, and figure out a new ability. Then, use it on the training dummies here.", objectives = "Reach level 3 to learn Steady Shot. Locate a Training Dummy in Camp Narache and practice using Steady Shot 5 times.", completion = "You have done well, <name>. Return to me when you are in need of further training." }
WordHunterWoW_QuestEN[27022] = { title = "Extinguishing the Idol", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; they...they literally consume their abductees from the Barrens.  I can shut down the idol and render it useless, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.\n\nAre you with me, <race>? Can I count on you to help me end their atrocities?", objectives = "Protect Belnistrasz.", completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in your kind has been once more renewed.  Take this as a reward befitting of a hero.\"" }
WordHunterWoW_QuestEN[27023] = { title = "The Way of the Sunwalkers", description = "It is always a pleasure to meet a fellow Sunwalker. We are not as numerous as some of the more ancient orders, but our ways are no less powerful and our members no less respected.\n\nAs you continue on your journey, you will grow closer to the light and gain abilities you couldn't have imagined.\n\nGo, get more experience, and return when you've learned a new ability. Demonstrate it to me.", objectives = "Reach level 3 to learn Seal of Command. Locate a Training Dummy in Camp Narache, cast Seal of Command on yourself and hit the dummy.", completion = "You have made me proud, <name>. You will make a fine Sunwalker. Return when you desire further training." }
WordHunterWoW_QuestEN[27024] = { title = "Partners in Crime", description = "Although Amnennar is the primary threat here, he is far from the only. You need to slay his lieutenants as well if their hold on the Downs is to be released.\n\nGlutton guards the beginning of the Spiral of Thorns.\n\nMordesh stands atop The Bone Pile inciting the Scourge into a ravenous frenzy.\n\nTuten'kash resides underground. In order to bring him out, you must strike the gong in The Caller's Chamber three times.\n\nGood luck, brave hero.", objectives = "Kill Glutton, Mordresh Fire Eye, and Tuten'kash.", completion = "Well done! Without their leaders, the Scourge will pose no significant threat." }
WordHunterWoW_QuestEN[27025] = { title = "Thistle While You Work", description = "It's stabthistle season! Stabthistle seeds are responsible for up to 89% of seed-related injuries among hunters.\n\nYou'll find stabthistle seeds mostly in the lower woodland just north of the lodge. They're commonly found at the base of trees, and they will stab and hurt you.\n\nI'd advise you to avoid them, but I actually need someone to help remove them for the sake of safety! Bring me back stabthistle seeds so we can make sure others don't get hurt.", objectives = "Collect 6 Stabthistle Seeds.", progress = "Handle them safely, now!", completion = "I've been informed there's a bear warning active for the woodlands as well! They love those stabthistle seeds.\n\nIt's a good thing you gathered those so they don't attract more bears!" }
WordHunterWoW_QuestEN[27026] = { title = "Defcon: Bobcat", description = "Stop everything! It's come to my attention that there's been bobcat sightings near the lodge. Bobcats!\n\nNow mind you, I've never seen a bobcat, but they're surely dangerous. They're like mountain lions or something. I don't want anyone leaving until the area is secure!\n\nAnyone but you, that is. I'll pay you to help secure the area, {class}. But don't get your face ripped off.", objectives = "Kill 8 Bobcats.", completion = "Okay, yes, I have already been informed that bobcats are much smaller than I was assuming. But that's still pretty dangerous for gnomes!\n\nYou've done a good thing for the safety of this lodge, <name>!" }
WordHunterWoW_QuestEN[27027] = { title = "Primal Strike", description = "I know you've been busy helping the braves protect Camp Narache from the bristlebacks. We're going to need all the hammers and all the luck we can get.\n\nAs your skills increase, so does your connection to the elements. This gives you access to new abilities.\n\nThe first of these that we learn is Primal Strike. It should help you fell your enemies faster. Learn it, and then try it out.", objectives = "Reach level 3 to learn Primal Strike, and then locate a Training Dummy in Camp Narache and practice using Primal Strike 3 times.", completion = "Well done, <name>. I see you will have no trouble mastering our more advanced arts as you gain experience. Return to me when you need further training." }
WordHunterWoW_QuestEN[27028] = { title = "Hornet Hunting", description = "We're always looking for new game around here. Daryl may like his boars, but the rest of us prefer things more exotic.\n\nNow, I'd never say the Loch draining was a good thing, but it did have a silver lining. The swampy ground's brought in new prey: Hornets!\n\nGiant hornets, mind you. Not many hunters have tussled with massive bugs before. It's rather novel.\n\nIf you'd like to give it a try, I'll wager with you. Bring me back some of those nice glossy wings of theirs and I'll pay up.", objectives = "Collect 6 Glassy Hornet Wings.", progress = "How go those wasps?", completion = "Lovely specimens you've got there! Here's my wager, lad." }
WordHunterWoW_QuestEN[27029] = { title = "Cure the Scourge", description = "Far more effective than killing swarm after swarm of Scourge is finding a method to prevent living creatures from ever being turned into them. I have an idea for a fine powder that, when inhaled, may stop the entire process.\n\nI need withered tusks off the unliving Quilboar here to make this powder. Bring me an ample amount, and we may be able to stop the Scourge's growth for good.", objectives = "Collect 20 Withered Tusks.", progress = "Do you have the tusks?", completion = "I have faith that this substance will prevent many future headaches. Thank you, <class>." }
WordHunterWoW_QuestEN[27030] = { title = "Foxtails By The Handful", description = "We've seen more foxes in the hills lately. Cunning creatures, they are. A good test of a hunter's skills, and a fine profit to boot!\n\nIt's their tails, lad. Fine and fluffy, they're just as good hung on yer belt to ward off fleas as they are to line the gloves of some fancy noble.\n\nListen to me prattle on. I'm no goblin; the thrill's in the hunt! But if you bring me back some foxtails, I'll still gladly pay you for 'em. You'll find the foxes just north of the lodge in the lower woodlands.", objectives = "Collect 7 Fluffy Fox Tails.", progress = "What've you got for me?", completion = "Ahh, you see? Goods of the finest quality. Good work gettin' these." }
WordHunterWoW_QuestEN[27031] = { title = "Wing Nut", description = "I'm through with gyrocopters. Sure, they work, but when has that ever been good enough for a real gnome? I want real flight, with WINGS!\n\nI've been studying birds for years now, trying to unlock the final secret to building a machine that flies just like them. That elegant soaring and swooping, the rush of wind over the wings, ahh.\n\nYou! You can help me. I need the finest flight feathers you can find. The golden eagles circling near the lodge would be a fine choice...", objectives = "Collect 3 Pristine Flight Feathers from Golden Eagles.", progress = "Only the finest feathers will do!", completion = "Beautiful. you've got an eye for quality!\n\nGreat minds think alike! It's clear you've got an enthusiasm for flight and fowl, so maybe you can help me further..." }
WordHunterWoW_QuestEN[27032] = { title = "Bird is the Word", description = "I've actually nearly perfected my dream machine: The Skystrider! The world's first flying Mechanostrider! But, well\n\nWhen I was putting the finishing touches on it in my secret cavern lab, my other creations became, er, jealous. Giving mechanical birds a personality to begin with was probably a bad idea, but that's already done.\n\nI need the Supermechanical Robo-Widget from the original Skystrider if I want to rebuild it! Please, journey into the cave and retrieve it for me!", objectives = "Find the Rusted Skystrider inside Ironwing Cavern.", completion = "<The Skystrider sits silent, its chance to fly gone. An obvious hatch on the front is marked \"SRW\".>" }
WordHunterWoW_QuestEN[27033] = { title = "Skystrider's Heart", description = "Opening the hatch, you find an imposing looking mechanical device hooked to several wires, gears, and who knows what else.\n\nIt's easily detached. Time to bring it back to Bingles.", objectives = "Return the Supermechanical Robo-Widget to Bingles Blastenheimer at the Farstrider Lodge.", completion = "Perfect! Now that I've perfected the wing balance and have all the parts I need, all we need is a pilot." }
WordHunterWoW_QuestEN[27034] = { title = "He's That Age", description = "I'm not making the Skystrider for me, {name}. Not even for gnomekind. I want my son to be the one to fly it.\n\nI'm old, and my reflexes aren't what they used to be. But my boy Ando could be the best pilot Azeroth's ever seen, if he'd just get over his teenage moodiness!\n\nHe sits out by the loch, staring at the sky all day. Something's been bothering him, and yet he refuses to talk to his own father about it. I'm at a loss!\n\nPlease, {name}, could you go talk to him? Tell him I need him to pilot the Skystrider!", objectives = "Speak to Ando Blastenheimer on the east side of the Loch.", completion = "I don't care about my father and his silly inventions! It's all just nonsense!" }
WordHunterWoW_QuestEN[27035] = { title = "Standing Up", description = "Look at them. The Twilight's Hammer ruined this land!\n\nThat cult caused this Cataclysm, and broke the Stonewrought Dam, and drained the entire Loch. And now they wander around the ruins like it's their home!\n\nIf there was any justice in this world, someone would march into their camp and break that artifact of theirs in half. But I'm too weak to even try it.\n\nAnd nobody else is brave enough either! Not even you! You see? It's all so stupid...", objectives = "Destroy the Twilight Landshaper at the center of the Twilight's Hammer Camp.", progress = "See what I mean? You don't even care either.", completion = "You did it? You did! You fought them and won!\n\nThere's hope after all..." }
WordHunterWoW_QuestEN[27036] = { title = "Vyrin's Revenge", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the cave to the north.", objectives = "Kill Ol' Sooty and obtain his head.", progress = "Ah, <name>! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks of it.\n\n<He runs a finger along his scar unconsciously.>\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n<He trails off then starts to visibly shake.>\n\nOh, take that away take it away! Get that grisly thing out of here!" }
WordHunterWoW_QuestEN[27037] = { title = "Vyrin's Revenge", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", objectives = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", progress = "Great job, <name>! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, <name>. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it." }
WordHunterWoW_QuestEN[27038] = { title = "Missing Parts", description = "<The Sergeant turns his attention to you.>\n\nLook here, if you want to help speed things up around here, get Flintlocke off my back. A whole shipment of siege engine parts was misplaced and now it's scattered all up and down the dock.\n\nGather up the missing parts and get them to Flintlocke so he can finish construction. He's just across the road from me, waiting.", objectives = "Gather up 5 Missing Parts from around the Stormwind Harbor.", progress = "Eh wot?\n\nMy parts. Where are they? You can't build a tank without parts!\n\nIf yeh did, it'd be small. An' mostly inner-fectual.", completion = "<Flintlocke greedily digs through the machine parts, tossing choice picks over his shoulder.>\n\nOh aye, 'ere's the stuff.\n\n<He sticks his head all the way into one of the crates.>\n\nBut where's me powder? Everything's here but for the powder. I need explosives, man!\n\nYou tell the King, no powder, no power. I need me some kersplosions or I ain't leavin' port." }
WordHunterWoW_QuestEN[27039] = { title = "Dangerous Intentions", description = "Do you know why Mortuus appends 'nub' to your name, {name}? Because he is an incompetent sycophant that has trouble seeing through his oversized helmet. 'NUB' is your classification. You are now part of the NEW UNDERCITY BATALLION.\n\nBut enough with the comedy! I sent Deathstalker Yorick on a shadow operation two days ago. Her goal was to get information on the Gilneas Liberation Front and return. Three days and no word from her.\n\nHead southwest to the Ivar Patch and look for Yorick, {name}.", objectives = "Find Deathstalker Yorick at the Ivar Patch in Silverpine Forest.", completion = "Belmont gets a little nervous and sends some newbie to look for me? Listen, I've been staking out the old Ivar cottage from inside this outhouse for three days. Your presence threatens the whole damn operation!\n\nThere's no time to explain. We have to act now or this mission will be compromised." }
WordHunterWoW_QuestEN[27040] = { title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you be a sweetie and take the plans back up there to run them through their one-time decryption engines?", objectives = "Decrypt 6 plans." }
WordHunterWoW_QuestEN[27041] = { title = "Decryption Made Easy", description = "We don't have the tools to decipher these encrypted plans. The Twilight's Hammer do, though.\n\nWould you take the plans back up there and run them through their one-time decryption engines?", objectives = "Decrypt 6 plans." }
WordHunterWoW_QuestEN[27042] = { title = "Fight Fire and Water and Air with...", description = "Did ye hear the blatherin' idiot while ye were up there? That's none other than Haethen Kaul, their leader.\n\nThe man's gone daft with power. He's pullin' it straight from them bound elementals, makin' him nigh invincible.\n\nThe only thing I can think of to get ye into proper shape fer a fight with him is fer ye to first kill all o' them elementals, gettin' their wards. That should protect ye from Haethen's spells.\n\nWell, most o' them anyway.", objectives = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", completion = "That's the ol' spirit! One less nasty in this world that the little ones will have ta worry about when they go ta sleep at night.\n\nNot ta mention that we won't have ta be worrying about him none no more neither!\n\nNow let's see here. I think we have somethin' in our crates that'll make a fittin' reward fer ya." }
WordHunterWoW_QuestEN[27043] = { title = "Fight Fire and Water and Air with...", description = "Did you hear the man going on with his incessant yelling while you were up there? That's Haethen Kaul, their leader.\n\nIt's a well known fact that he's gone insane from the power he's drawing from their bound elementals. Unfortunately, it makes him nigh invincible.\n\nIf you're to fight him, you'll first have to kill each of the elementals, gaining their wards in the process. That should protect you from Haethen's magic.\n\nWell, most of it anyway.", objectives = "Acquire the Fire, Water, and Air Wards, and then slay Haethen Kaul.", completion = "An excellent display of <class> prowess.\n\n\n\nI believe that a reward is in order. Something appropriate for a powerful man such as yourself." }
WordHunterWoW_QuestEN[27044] = { title = "Peasant Problems", description = "I'm not quite ready to go back to the keep yet. Would you like to help me with something?\n\nRecently some of the local farmers were petitioning the King about some missing livestock. My father promised someone would investigate, but the city guard is stretched so thin it'll take weeks.\n\nI thought I would help! It'll encourage the farmers to see someone take action, especially from the royal family. Besides, it's just some missing cows. Nothing dangerous.\n\nTake me to Farmer Wollerton here in the city!", objectives = "Escort Prince Anduin to Farmer Wollerton at the Wollerton Stead within Stormwind City. If he's no longer with you, you can find him in Stormwind Keep.", completion = "<On seeing the Prince Regent, Farmer Wollerton collapses awkwardly down on one knee.>\n\nY- Y- Your highness!" }
WordHunterWoW_QuestEN[27045] = { title = "Waiting to Exsanguinate", description = "The Gilneas Liberation Front leader, Darius Crowley, has been meeting with another worgen inside this cottage for the past three days. I'm not sure what's going on, but we need to get inside the cottage and find a good hiding place from where we can eavesdrop.\n\nIt's now or never, {race}. We may never get another shot.\n\nJust promise me that if I don't make it, you'll return to Forsaken High Command and inform Belmont of whatever we discover.", objectives = "Enter the Ivar Cottage and find a suitable hiding place upstairs. Then eavesdrop on Lord Darius Crowley.", completion = "Alas, poor Yorick! I knew her, <name>. An assassin of infinite courage...\n\nNow, tell me what's going on? What did you and Yorick discover?" }
WordHunterWoW_QuestEN[27046] = { title = "Fear of Boring", description = "The gyreworms infest the rock, eating away at it until our home will one day collapse. For every one that is killed, twice as many burst forth to follow, but we must carry on the fight. They must be extinguished.\n\nGo to the Crumbling Depths and slaughter any worms that you can find.", objectives = "Kill 10 gyreworms.", progress = "Your flesh is well suited for the task. It does not corrode from their attacks as our rockskin does.", completion = "You wage a war that we cannot. Thank you for your help." }
WordHunterWoW_QuestEN[27047] = { title = "Motes", description = "Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much.\n\nAs a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?", objectives = "Recover 10 Motes of Painite.", progress = "Painite is one of the most valuable materials to us, particularly due to our inability to reach most of the deposits on our own.", completion = "Well done, <race>. These will do well." }
WordHunterWoW_QuestEN[27048] = { title = "Underground Economy", description = "Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits.\n\nUse these bombs to blow out chunks from the bigger formations.\n\nI've got a nasty habit of packin' the explosives a bit thick. Mind the kick.", objectives = "Use Ricket's Tickers to gather 3 Deep Alabaster Crystals, 3 Deep Celestite Crystals, 3 Deep Amethyst Crystals, and 3 Deep Garget Crystals.", progress = "Boom?", completion = "Well played!\n\nI've got this pretty sweet deal going. A bunch of shmucks go up there to Therazane's Throne and give all kinds of gold to D'lom for who-knows-what kinda crap. He forks all that cash over to me for these crystals. I go home freakin' rich for a couple chunks of rock.\n\nDon't tell no one though. I don't want no competition springin' up.\n\nThink you can come back later to help me get another load of crystals out?" }
WordHunterWoW_QuestEN[27049] = { title = "Soft Rock", description = "The corruption of the Crimson Expanse has not subsided. Destroy the Fungal Behemoths that shower their filth upon our realm. If they continue to rise, we will continue to destroy them.", objectives = "Kill 8 Fungal Behemoths.", completion = "Once the growth starts, it is near impossible to stomp back into submission. Through persistence our realm will one day be cleansed." }
WordHunterWoW_QuestEN[27050] = { title = "Fungal Fury", description = "Something upon the Crimson Expanse continues to spur disgusting growths upon the rock. New fungi are rising, and they need to be crushed before they can spread.", objectives = "Destroy 10 of the newly sprouted mushrooms in the Crimson Expanse.", completion = "You are proficient at stepping on things. You would make an excellent giant." }
WordHunterWoW_QuestEN[27051] = { title = "Through Persistence", description = "The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse.\n\nHunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.", objectives = "Retrieve a Bag of Verlok Miracle-Grow from the Verloks upon the Crimson Expanse.", progress = "Have you done as I've asked of you? We must weed out the whatever growth agent remains within their possession.", completion = "Thank you, <race>. We will weed the rest out of their possession in time." }
WordHunterWoW_QuestEN[27052] = { title = "Lingering Twilight", description = "Twilight drake riders remain in Deepholm. They are scattered. Defeated. Yet they remain.\n\nTake wing with Aeosera's flight and hunt them down. The stone drakes await you on the ledge to the southeast.\n\nWe will destroy every last one of the Twilight. In the Stonemother's name.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Hunt down a Twilight Drakerider on a Crystalwing Stone Drake." }
WordHunterWoW_QuestEN[27053] = { title = "Gahrron's Withering Cauldron", description = "My analysis is complete!  The blight that affects the animals here is no residual disease.  No, it is something new... and I think I know what it is.\n\nThe Cult of the Damned maintains a plague cauldron on a farm called Gahrron's Withering.\n\nThis farm is due southeast of us, close to where the Eastern Plaguelands begin.  I need a sample from this cauldron to verify my suspicions.\n\nEliminate the cauldron lord present there for its key.  You will then be able to access the cauldron and obtain my sample.", objectives = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.", progress = "An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.", completion = "Cauldron Lord Soulwrath's key disintegrates as it touches the lock on the access panel at the base of the cauldron's platform.  A slight clanking noise is heard within, and the access panel swings open to reveal more viscous toxins within the cauldron's framework.\n\nThere is a small spigot that the bottle fits well enough under, allowing you to draw a sample for Field Agent Kaartish back at the Menders' Stead." }
WordHunterWoW_QuestEN[27054] = { title = "Desperate Acts", description = "The Cult of the Damned maintains a small camp to the east, Malicia Outpost, which they use for field training outside of the Scholomance.  We may have allowed them to proceed unchecked with this training for too long.\n\nIf cultists are truly using this plague to inoculate the wildlife, then Malicia Outpost must be where the inoculation is occurring.\n\nInstructor Malicia runs the outpost.  Find her, slay her, and find out who she's taking orders from.", objectives = "Kill Instructor Malicia and obtain her Cult Orders.", progress = "You take a look at the paperwork Malicia was carrying...", completion = "The orders in Malicia's possession incriminate Darkmaster Gandling of the Scholomance, but they also conceal another important bit of information." }
WordHunterWoW_QuestEN[27055] = { title = "Students of Krastinov", description = "The Cult orders state that the plague from the cauldron at Gahrron's Withering is in fact being used for TWO purposes.  The first is the practice of spreading disease through the animals of the plaguelands, which you already knew about.\n\nThe remainder of the plague is being shipped to the Weeping Cave, a cavern north of Malicia's Outpost, for use in some dark experiments.  Students of the Scholomance are using this plague to re-animate the dead!\n\nCertainly they must be stopped.", objectives = "Kill 2 Krastinovian Disciples, 2 Flesh-Cobbled Brutes, 2 Flesh-Cobbled Rippers, and 4 Unholy Corpuscles within the Weeping Cave in Western Plaguelands.", progress = "How is your investigation proceeding, <name>?", completion = "You have gone above and beyond, <name>.  Not only have we set back the Cult of the Damned in their crusade to re-plague the plaguelands, but you have uncovered another set of dire plans: they continue to re-animate the dead!\n\nYour name will definitely be mentioned when this information is presented to Highlord Fordring, <name>.  You have my thanks, and the blessing of the Argent Crusade." }
WordHunterWoW_QuestEN[27056] = { title = "Belmont's Report", description = "<Belmont hands you a sealed envelope.>\n\nDeliver this report to Lady Sylvanas Windrunner. It is my assessment of the situation in Silverpine based upon your and Yorick's field work.\n\nIf we do not stamp out the worgen insurgents, they will overrun us. The time to act is now!", objectives = "Deliver Belmont's Report to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", progress = "Kneel before your queen, <name>.", completion = "Crowley... A gnat. An insect, waiting to be crushed beneath my boot heel.\n\nSo he thinks to rouse the feral worgen of Silverpine? We shall show him and his allies the might of the Forsaken!\n\nBut first we must clean up the mess made by the Warchief's fleet. Without their aid we may lose this war." }
WordHunterWoW_QuestEN[27057] = { title = "Return to the Stead", description = "You carefully close the spigot in the control panel, watching the cauldron's putrid ichors drip into the empty bottle.\n\nWith the poison in hand, it is time to return to Field Agent Kaartish at the Menders' Stead.", objectives = "Bring the Filled Gahrron's Withering Bottle to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", progress = "Gahrron's Withering houses a viciously potent plague cauldron.  Once we have a sample of the plague it spews forth, we will be able to determine whether the Cult of the Damned is truly responsible for continuing to poison the land.", completion = "Good work.  One moment please...\n\n<The draenei takes a moment to compare your sample with a sample he presumably had distilled earlier.>\n\nYes, this appears to be the same corruption that is affecting the wildlife.  With this knowledge, and with your combat expertise, we may have the power to stop this." }
WordHunterWoW_QuestEN[27058] = { title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", objectives = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", completion = "You did it! You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Mowi gets up on her tippy toes and gives you a kiss on the cheek.>\n\nNow I'm certain that I have something around here for you.\n\n<She begins rummaging around for your reward.>" }
WordHunterWoW_QuestEN[27059] = { title = "The Wrong Sequence", description = "The Twilight's Hammer must be stopped from using the Waygate. There's only one thing to do.\n\nPunch in the wrong activation sequence and destroy it.\n\nHmm, let's see. Yes, here's one that opens upon the explosive depths of the Firelands, the elemental plane of fire. That should do nicely.", objectives = "Use the Waygate Controller to punch in the wrong activation sequence, thereby destroying the Waygate.", completion = "You did it! Excellent work, my boy. You found out what the Twilight's Hammer were up to and you stopped them dead in their tracks!\n\n<Examiner Rowe pats you on the back with his bony hand.>\n\nNow I'm certain that I have something around here for you.\n\n<He begins rummaging around for your reward.>" }
WordHunterWoW_QuestEN[27060] = { title = "Unholy Cow", description = "<Farmer Wollerton tries to pull himself together.>\n\nCows? You're asking about the missing livestock?\n\nI normally just let the cows graze north of the house here. Occasionally one gets spirited away. Leaves a trail of gore. Who would do such a thing?\n\nI'm afraid to follow that trail myself... something sick is happening in Stormwind!", objectives = "While escorting Anduin Wrynn, follow the trail of gore from Farmer Wollerton's Stead to the crime scene. Keep Anduin alive. If he's not with you, he will be waiting in Stormwind Keep.", completion = "That was a close one! I can't believe you stood your ground against so many at once.\n\nIt looks like this site was used for some kind of twisted Twilight's Hammer initiation ritual. They're definitely active in Stormwind. What's this?\n\n<Anduin finds a badge resting on the shrine.>\n\nThis badge shows a crossed axe and hammer. It looks old. If we keep poking around, we might figure out what it means..." }
WordHunterWoW_QuestEN[27061] = { title = "The Twilight Overlook", description = "The dragon they're speaking of is Abyssion, {name}.  It's not going to be easy to get the fragment off of him.\n\nMeet with Mylra again.  She is operating nearby at the Twilight Overlook.\n\nShe will tell you what our next move will be.", objectives = "Speak to Stormcaller Mylra at the Twilight Overlook in Deepholm.", completion = "So we're going to have to take on Abyssion to get the fragment?  This operation just got a whole lot more difficult all of a sudden." }
WordHunterWoW_QuestEN[27062] = { title = "Looming Threat", description = "The Quilboar in Razorfen Downs seem to have allied with the Scourge. This is dark news for us, {class}. We have dire enough problems dealing with these Grimtotem, we won't be able to handle an attack by the Scourge. Venture into Razorfen Downs, east of here, and see if you can find anyone that may be able to help you stop them before they decide to attack here.", objectives = "Find help in Razorfen Downs.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here." }
WordHunterWoW_QuestEN[27063] = { title = "Looming Threat", description = "The Scourge are a direct affront to nature. They have managed to corrupt the Quilboar in Razorfen Downs and now threaten to spread further into Thousand Needles and eventually, I fear, west into Feralas. You must go there and do anything you can to confine them. Perhaps you can find someone in the area to help you? The winds whisper of a powerful presence in the area.", objectives = "Find help in Razorfen Downs.", completion = "You seem an able warrior. Perhaps you can help me put an end to the terrible evil here." }
WordHunterWoW_QuestEN[27064] = { title = "He's Holding Out on Us", description = "<name>, it almost seems like Samuelson is trying to intentionally waste your time. The dockworkers don't know anything. More importantly, explosives are missing from Stormwind Harbor!\n\nYou know what I think? I bet Samuelson knows more than he's letting on. He probably has a lead on Twilight's Hammer and wants all the credit and glory for himself.\n\nWe should peek through his records at the SI:7 headquarters. Take me there and I should be allowed to look at his files and find out what he really knows.", objectives = "Escort Anduin Wrynn to the third floor of SI:7 Headquarters in the Old Town district of Stormwind. If he is no longer with you, you can find Anduin in Stormwind Keep.", completion = "This is REALLY suspicious, <name>! Samuelson doesn't have a shred of info here about the Twilight Hammer - it's almost like he's not investigating them. Yet he's got a complete catalog of the missing explosives.\n\n\n\nAnd I found this funny badge with a symbol on it: A crossed axe and hammer.\n\nIt all means something, but what?" }
WordHunterWoW_QuestEN[27065] = { title = "The Warchief's Fleet", description = "Our reinforcements from Kalimdor arrived last night. Three orc gunships full of supplies, weapons and soldiers. Three orc gunships lost to Bloodfang's damned worgen.\n\nHow could an entire orc fleet lose to a small band of enemy combatants that lack any siege weaponry? An important question that you will answer for me.\n\nGather your gear and report to the orc admiral, Hatchet, at the Forsaken Rear Guard, southwest of here.\n\nGet those orcs operational, {name}.\n\nI await your full report.", objectives = "Report to Admiral Hatchet at the Forsaken Rear Guard in Silverpine Forest.", completion = "This fiasco may go down as one of the biggest embarrassments in the history of naval warfare. How did this happen? Drunk happened. That's how." }
WordHunterWoW_QuestEN[27066] = { title = "Learning the Word", description = "As you become more skilled, your skills will expand, and you will gain access to many new powers.\n\nGo - get some experience out there, and come back to me when you've learned something new. You can demonstrate on the training dummies nearby.", objectives = "Reach level 3 to learn Shadow Word: Pain. Practice using it 5 times on Training Dummies in Camp Narache.", completion = "Thank you for your help in seeing to the wounded braves. I'm sure that you will often find your healing skills in demand. Return to me when you need further instruction." }
WordHunterWoW_QuestEN[27067] = { title = "Moonfire", description = "As you develop your skills, druid, you will begin to feel your connection to the Earthmother deepening. You will begin to understand new secrets of nature, and learn to cast new spells.\n\nGo now, get more experience, and return to me when you've learned a new spell. Demonstrate what you've learned.", objectives = "Reach level 3 to learn Moonfire. Practice using it on a Training Dummy in Camp Narache.", completion = "You have a knack for the healing arts, <name>. Wherever you go, your skills as a healer will be in demand. Return to me when you are ready for more training." }
WordHunterWoW_QuestEN[27068] = { title = "Chief Ukorz Sandscalp", description = "Take a good look, mon. Dis is how it goes, betrayal after betrayal. I backstab you for the sword, and den Chief Ukorz go and backstab me even better for it.\n\nThat's life, yah! Or was...\n\nNow, I know you don't got no love for Mazoga. But I know you goin' in der anyway. Kill him for me, mon. Spill more blood on the sand, an' give Chief Ukorz Sandscalp what every one of de Sandfury deserves...a gory death.\n\nMaybe I leave some of my belongin's without a curse before passin' on if you do, yah?", objectives = "Kill Chief Ukorz Sandscalp.", completion = "He's gone? Did he have the sword?\n\nNah...don't tell me. Don't matter no more. Mazoga don't care.\n\nI'm off now, mon. De consequences of my actions await me. Take whatever I was holdin'... I don't need it where I'm goin'..." }
WordHunterWoW_QuestEN[27069] = { title = "Steel Thunder", description = "We may not have to live down the shame of this defeat, {name}. The Warchief will likely have us all executed instead.\n\nI'll be damned if we don't go down without a fight. Although the whole beachhead is overrun by Bloodfang worgen, there may still be hope. I want you to accompany one of our sea pups to the beachhead, directly west of here, and recover our supplies. Return to me when the pup can carry no more.", objectives = "Recover 5 Sea Dog Crates.\n\nSpeak with Admiral Hatchet to get another Orc Sea Pup if you unexpectedly lose yours.", progress = "The pups might be the only orcs not drunk at this base.", completion = "Within these crates are held STEEL THUNDER! With our weaponry returned we might have a chance to redeem ourselves." }
WordHunterWoW_QuestEN[27070] = { title = "A Fool's Errand", description = "I heard that a troll in here, Hydromancer Velratha I think she was called, has come into the possession of a very rare, beautiful, and powerful piece of jewelry called the Tiara of the Deep. She uses it to control the powerful demigod Gahz'rilla, whose very scales are said to crackle with energy. Do you know what all of that means, {race}?\n\nI need it! Kill Velratha, take the Tiara of the Deep, and kill Gahz'rilla for one of his scales. Bring them all back to me pronto! I'll reward you handsomely.", objectives = "Obtain the Tiara of the Deep and Gahzrilla's Electrified Scale.", progress = "Do you have what I need?", completion = "Excellent! This Tiara will grant me complete control of the water around here, and the Electrified Scale will serve to power all the machines I need to use it all to my advantage!\n\nYou're going to make me a very rich and powerful goblin! You can have this, it's nothing compared to what I'll have soon." }
WordHunterWoW_QuestEN[27071] = { title = "Wrath of the Sandfury", description = "De Sandfury are a resilient tribe. Dey have survived sandstorms an' years an' years of other tings long covered by da sands. It would be foolish to assume that the only forces here are da trolls. We been tamin' da scarabs, breedin' da sul'lithuz, an' raisin' our dead to keep on fightin' for all eternity as zombies.\n\nRuuzlu, da right hand of Chief Ukorz Sandscalp, be plannin' to use dem to retake Tanaris for de Sandfury empire. You best be killin' da trolls in charge of dis if you want to live, mon.", objectives = "Kill Theka the Martyr, Witch Doctor Zum'rah, Antu'sul, and Ruuzlu.", progress = "If dey ain't dead yet, you can't guarantee your own life, <race>.", completion = "You killed dem? All of dem? And you return alive?\n\nTake what you want off my body, den. It's mostly curse-free, Mazoga promises." }
WordHunterWoW_QuestEN[27072] = { title = "The Old Barracks", description = "I recognize the symbol on these badges from before Deathwing's attack on the city. It belonged to soldiers in the old barracks, west of town overlooking the harbor.\n\nYour timing couldn't be better. One of my top agents, Jack Bauden, has been trying to infiltrate the Twilight's Hammer cult for me. Last night he went missing. If you and Anduin are right, the cultists are holed up in the old barracks. Time is urgent! Assault the old barracks, take out those cultists, and rescue Jack Bauden.", objectives = "Go to the Old Barracks and slay 6 Crazed Cultists, then locate Jack Bauden.", completion = "<You slap Bauden around until he wakes up.>\n\n<class>? What are you doing here?\n\nI'm SI:7 Agent Jack Bauden. This is the longest day of my life." }
WordHunterWoW_QuestEN[27073] = { title = "Give 'em Hell!", description = "It's the goblins' fault, {race}!\n\n<hic!>\n\nYou see, we set off for Silverpine from Bilgewater Harbor, over in Azshara. Huge mistake that was! Never has such a den of inequity and sin existed in our great empire. Those damnable goblins fueled our every vice and set us off to sail with barrels full of ale. \n\n<hic!>\n\nThe shame of it all leaves a mark greater than any scar. Honor must be restored! Kill the Bloodfang worgen that ambushed us. They're scavenging the wreckage to the southwest.", objectives = "Kill 10 Bloodfang Scavengers.", progress = "Give 'em hell, <race>!", completion = "Looks as if you really gave those worgen a beating and, in the process, lifted the \"shame haze\" they cast over us. Perhaps the sea dogs will quit drinkin' now.\n\nWho am I kidding?\n\nHah!" }
WordHunterWoW_QuestEN[27074] = { title = "Fight the Hammer", description = "You've done what I thought was impossible! I'm done moping around here. It's time to gnome up.\n\nI've got to find my father. But you! Don't bother yourself with me any longer. You've got to keep fighting these cultists.\n\nGo talk to Ashlan Stonesmirk to the east. He's trying to stop the Twilight's Hammer, but he has nobody to help him. You're his only hope!\n\nDon't give up, {name}. I won't.", objectives = "Talk to Ashlan Stonesmirk near Mo'grosh Stronghold in Loch Modan.", completion = "You hit the twilight camp at the center of the lake? Not bad, lad!\n\nIf you're ready to take the fight right to their doorstep, I've got your chance." }
WordHunterWoW_QuestEN[27075] = { title = "Servants of Cho'gall", description = "The Twilight's Hammer started as a clan of the savage Horde. Their leader, Cho'gall, slowly turned his band of ogres into a death cult, welcoming anyone insane enough to wish for the end of all existence. As you can see, there's still plenty of ogres among their ranks; deranged, fanatical, and just as strong as before.\n\nThese crude monsters have the gall to come here and spread their filth across our land. The more you kill, the better off Loch Modan will be, {name}.", objectives = "Kill 7 Mo'grosh ogres in the Mo'grosh Stronghold.", completion = "It may look grim, but we'll win with your help, <name>. They won't keep the dwarves down." }
WordHunterWoW_QuestEN[27076] = { title = "Breaking and Entering", description = "A good buddy of mine, Weegli Blastfuse, joined up with Sergeant Bly and his group of outcasts to invade Zul'farrak and claim the legendary Sul'thraze as their prize. Of course, they underestimated the Sandfury tribe and now they're all trapped awaiting execution to please their demigod, Gahz'rilla!\n\nIf you free him, he'll help you blast your way to Ukorz's private chamber where he keeps at least part of the blade.\n\nKill his captors, Nekrum Gutchewer and Shadowpriest Sezz'ziz as revenge...I'll repay ya.", objectives = "Free Weegli Blastfuse and kill Nekrum Gutchewer and Shadowpriest Sezz'ziz.", progress = "Are Nekrum and Sezz'ziz dead? If they are, I know Weegli will be here any minute now.", completion = "Wow! I knew I could count on you! Here's something for your troubles." }
WordHunterWoW_QuestEN[27077] = { title = "Clutching at Chaos", description = "The cultists of the Twilight's Hammer use their powers to draw elementium metal from deep beneath the earth. They coax it out into twisted spikes to form their buildings, rooted right into the defiled ground.\n\nThe ogres here seem to be in the middle of weaving the stuff, and we need to strike while they're still twisting it into shape.\n\nTear the spikes right out of the ground while they're still pliable, and bring them back to me! We're not going to give these curs a single inch of our land.", objectives = "Pull up 10 Nascent Elementium Spikes from the ground of the Mo'grosh Stronghold.", progress = "Did you tear up the spikes?", completion = "Shame that these half-formed things are too brittle and warped to be used for some weapons of our own. But it's thanks to you that we had the chance to get them out before they set. I'm not about to complain." }
WordHunterWoW_QuestEN[27078] = { title = "Gor'kresh", description = "The ogre left to watch over these crude fools goes by the name of Gor'kresh. He's big enough to boss even these brutes around, and cunning to boot. Never assume an ogre's stupid, that's when they'll get you.\n\nIf you take him out, we'll show the Twilight's Hammer that Loch Modan isn't a stepping stone for them. Stand strong against Gor'kresh and drive these fools back into the highlands!", objectives = "Defeat Gor'kresh.", progress = "You can do it, <name>.", completion = "You've done it! We may not have stopped the cult dead, but we've shown them we're not easy pickings and given them a welt to prove it.\n\nTake this with my gratitude, and try not to blush if anyone in Thelsamar calls you \"hero\"!" }
WordHunterWoW_QuestEN[27079] = { title = "Twilight Gate Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[27080] = { title = "Twilight Gate Tracking", description = "", objectives = "" }
WordHunterWoW_QuestEN[27081] = { title = "rusting the Traitor", description = "These two are useless. Can I at least count on you to get some work done around here, young adventurer? We've come into contact with Mazoga, a traitor to the Sandfury. He says he can help us find the legendary blade Sul'thraze so we can use it to kick out the Sandfury forever!\n\nWe'll probably sell it afterward to the highest bidder, honestly. This place doesn't pay for itself. Go do what he wants...just keep an eye on him. A traitor's a traitor all the same. He's at our camp just east of Zul'Farrak.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Mazoga.These two are useless. Can I at least count on you to get some work done around here, young adventurer? We've come into contact with Mazoga, a traitor to the Sandfury. He says he can help us find the legendary blade Sul'thraze so we can use it to kick out the Sandfury forever!\n\nWe'll probably sell it afterward to the highest bidder, honestly. This place doesn't pay for itself. Go do what he wants...just keep an eye on him. A traitor's a traitor all the same. He's at our camp just east of Zul'Farrak.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[27082] = { title = "Playing Dirty", description = "Have you seen the huge lumbering ettins roaming the forests? Cursed things came from Gilneas. Now they wander the land searching for their next juicy meal. We've managed to subjugate and utilize some of them to haul our wagons, but the others... well, they must be killed!\n\nUnfortunately, we can't spare any soldiers to do the job. That's where you come in, {class}!\n\nI have a plan, but it's going to require some materials. Head out into the forests around this base and collect diseased beast organs.", objectives = "Collect 8 Diseased Organs from Giant Rabid Bears and Rabid Worgs.", progress = "We are Forsaken! This is how we do it, <class>.", completion = "Excellent! Now to prepare the \"meal.\"" }
WordHunterWoW_QuestEN[27083] = { title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Forsaken that you are a hero of the first battle of Andorhal.  Koltira has requested your presence immediately.", objectives = "Report to Koltira Deathweaver at Andorhal in Western Plaguelands.", completion = "Thassarian and the humans made their move.  I thought I had an agreement with Thassarian... but I suppose this will do." }
WordHunterWoW_QuestEN[27084] = { title = "The Farmers' Militia", description = "The battle started when they attacked us from the rear.  I let my guard down, and a group of poorly-armed farmers and militiamen swung into our flank from the Writhing Haunt.\n\nThey may be weak, but unchecked, they threaten to overwhelm us with their numbers.\n\nLindsay's pet abominations can handle the melee combat.  You take this collar, stay in the rear, and use it to release my ebon gargoyle upon these farmers.", objectives = "Use the Ebon Gargoyle Collar on 6 Provincial Militiamen within Andorhal.", completion = "Merely a dent in their numbers... but the sight of their fellow men falling from the skies surely weakened their resolve." }
WordHunterWoW_QuestEN[27085] = { title = "Supporting the Troops", description = "While it is true that these farmers threaten to overrun us, we still cannot forget about the Alliance's main forces.\n\nTravel west into Andorhal and slay the human soldiers that are fighting with our deathguards.  We need all the help we can get.", objectives = "Slay 15 Andorhal Defenders.", completion = "You fight well, <name>.  I wish I had your ability... and your bravery." }
WordHunterWoW_QuestEN[27086] = { title = "Ashes to Ashes", description = "To the west, deep within Alliance-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The humans won't stand a chance.", objectives = "Slay 3 Andorhal Force-Commanders.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Thassarian, for honor and for Andorhal." }
WordHunterWoW_QuestEN[27087] = { title = "Lindsay Ravensun, Revealed", description = "I was informed that that worthless woman, Lindsay Ravensun, would be here to support me in this battle, but so far, she's done nothing but brood within the basement of the greathall behind me.  All the better, I suppose.  She was a bit of a distraction.\n\nStill, I cannot and will not stand for insubordination.  Find her, and bring her to me.", objectives = "Report to Lindsay Ravensun at Andorhal in Western Plaguelands.", completion = "You won't be taking me anywhere, <name>.\n\nWhile Koltira prances about with his playmate, Thassarian, I plan to win this battle.  Then I'll make Koltira suffer for his weakness.\n\nDon't believe me?  Fine, I'll let you in on a little secret..." }
WordHunterWoW_QuestEN[27088] = { title = "It's Only Poisonous if You Ingest It", description = "Take this cage, {class}. I've placed inside it one of my own mutant bush chickens, with a few slight modifications. Within the butt of this bush chicken is a stick of dynamite laced with gunk from the diseased organs you brought me.\n\nTake the cage out into the surrounding forest and locate the wandering forest ettin. Release the chicken and sit back as my masterwork does its job. The ensuing explosion should be sufficient to kill the ettin or greatly weaken it, allowing you to finish it off.", objectives = "Use the Mutant Bush Chicken to kill the Forest Ettin.", progress = "Have you dealt with the ettin?", completion = "<Apothecary Wormcrud laughs maniacally.>\n\nWas there ever any doubt? An ettin is no match for science!" }
WordHunterWoW_QuestEN[27089] = { title = "Ace in the Hole", description = "You have no idea how difficult it was to stay disguised while I watched Koltira let this war slip away from us.  Even now, those infernal farmers threaten to overwhelm us.  All because he refused to slay a friend.\n\nTake my val'kyr again, {name}.  With her by your side, kill these farmers, convert them to Forsaken, and mobilize them.  Then take a group of them into Alliance-held western Andorhal and hunt down this death knight, Thassarian.\n\nWe will win this war yet.", objectives = "With the Enthralled Val'kyr by your side, kill 5 Frightened Provincial Minutemen so that they can be turned into Forsaken Troopers. Then find Thassarian in western Andorhal.", progress = "This skeleton... what could it mean?", completion = "This is the body of Lurid, Thassarian's trusted knight.  With Thassarian nowhere to be found, it would seem that the Alliance forces have withdrawn.\n\nThe Forsaken have won the battle for Andorhal." }
WordHunterWoW_QuestEN[27090] = { title = "Andorhal, Once and For All", description = "Sylvanas will want to know about Thassarian's departure from Andorhal.  You resolve to return to the Forsaken-held side of town.", objectives = "Report to Lady Sylvanas Windrunner at Andorhal in Western Plaguelands.", completion = "See?  All it took was a little help from the val'kyr.  These creatures are turning to be much more helpful than I had first thought.\n\nNow, on to other matters." }
WordHunterWoW_QuestEN[27091] = { title = "Charge!", description = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.\n\nGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", objectives = "Reach level 3 to learn Charge. Locate a Training Dummy outside the Sunspire and practice using Charge.", completion = "I think you've mastered the basics of the charge, <name>. Don't forget to return when you need more training." }
WordHunterWoW_QuestEN[27092] = { title = "Cataclysm in the Catacombs", description = "Don't worry about me, <class>. I've uncovered the Twilight's Hammer plot. They've been stealing and stockpiling explosives coming into Stormwind harbor. Somehow, they've gotten access to the catacombs underneath the Cathedral of Light. I've heard talk of someone called \"The Black Bishop.\"\n\nThere's no time to warn the guard, <name>! You've got just minutes to get into the catacombs and disarm that bomb. Go! Now! Or THOUSANDS of PEOPLE will DIE!", objectives = "Enter the Cathedral of Light and descend into the catacombs below. Slay the Black Bishop and disarm the Pile of Explosives nearby.", completion = "<3 ... 2 ... 1 ...>\n\n<You wet your fingers and snuff out the fuse. The cathedral is saved!>\n\nUnderneath the powder kegs you find a heap of notes and papers. Apparently the cultists were trying to destroy the evidence behind them.>" }
WordHunterWoW_QuestEN[27093] = { title = "Lost in the Darkness", description = "Some would say that we are lucky to be alive. Those people would be idiots. At least had we died we would not have had to face the Warchief's wrath. Alas, what's done is done! Now we must attempt to regain our lost honor.\n\nThe third ship in our fleet sank off the coast of the Skittering Dark, northwest of here. Those that made it to shore quickly found themselves swarmed by the giant spiders of the area and encased in webbing.\n\nIf there are survivors we must free them! Go, {name}! To the Skittering Dark!", objectives = "Rescue 6 Orc Sea Dogs from the Skittering Dark.", completion = "Lok'tar, <name>! Once the ale wears off my orcs will be ready!" }
WordHunterWoW_QuestEN[27094] = { title = "Deeper into Darkness", description = "The Skitterweb matriarch is nearby! You can put an end to the Skitterweb menace by killing her!\n\nFind the brood mother at the end of the cave in the Skittering Dark and destroy her!", objectives = "Kill the Skitterweb Matriarch.", progress = "You killed the Skitterweb matriarch?", completion = "You rescued our orcs and killed the Skitterweb matriarch? We owe you a great debt of gratitude. You've saved us all from certain execution, <name>. I'm sure we can rouse these drunken idiots now." }
WordHunterWoW_QuestEN[27095] = { title = "Skitterweb Menace", description = "Vengeance is all consuming, {name}! Our third ship sank off the coast of the Skittering Dark, northwest of here. The men that made it off that boat were either captured or killed by the Skitterweb spiders of the region. For that, the spiders must die! ALL OF THEM!\n\nTravel to the Skittering Dark and crush those insects!\n\nBe on the lookout for their matriarch. Perhaps if we find her we can end this menace forever!", objectives = "Kill 12 Skitterweb Spiders.", completion = "The root of this evil must be found and destroyed! The Skitterweb matriarch must be nearby. No doubt hiding in the nearby cave!" }
WordHunterWoW_QuestEN[27096] = { title = "Orcs are in Order", description = "<Admiral Hatchet hands you an envelope sealed with the mark of the Horde.>\n\nThis is your commendation letter. It's the least I could do for you given the circumstances.\n\nReturn to Lady Sylvanas Windrunner with the letter and inform her of our status. Let her know that we will be ready to march on her command.\n\nGoodbye, {name}. You are an excellent soldier.\n\nNortheast, lad. To Forsaken High Command!", objectives = "Deliver the Admiral's Commendation Letter to Lady Sylvanas Windrunner at Forsaken High Command in Silverpine Forest.", progress = "And the orcs?", completion = "<Sylvanas raises an eyebrow.>\n\nSo the orcs are in order?\n\n<Sylvanas reads the commendation letter.>\n\nRecovered their supplies? Killed a dozen worgen? Toppled an ettin? Freed their soldiers and destroyed the Skitterweb matriarch?\n\nI say this rarely, <name>, but I am impressed. Perhaps your ability matches your aspirations. We shall see, for now you will be tested!" }
WordHunterWoW_QuestEN[27097] = { title = "Rise, Forsaken", description = "Fenris Isle stands defiantly at the heart of Lordamere Lake - a cruel memory of a time long since passed.\n\nThough no longer infested by gnoll vermin, a new threat has emerged.  Human refugees, driven from their holdings in Hillsbrad, have fled to Fenris Isle in hopes of escaping defeat at our hands. A critical error on their part.\n\nYou are to take Agatha with you to Fenris Isle and slaughter all humans. She will raise the fallen as Forsaken, bolstering our forces in the process.\n\nDo not fail me, {name}.", objectives = "Raise 15 Forsaken by killing humans on Fenris Isle.", progress = "Victory!", completion = "I see everything, <name>. Through Agatha all is known to me." }
WordHunterWoW_QuestEN[27098] = { title = "Lordaeron", description = "Ride with me to the Sepulcher, {name}. There are many things I wish to discuss with you. It is imperative that you understand the history of Lordaeron and the plight of the Forsaken.", objectives = "Accompany Lady Sylvanas Windrunner to the Sepulcher in Silverpine Forest.", completion = "Do you now understand the importance of our mission here? Crowley and his Alliance dogs must be stopped!" }
WordHunterWoW_QuestEN[27099] = { title = "No Escape", description = "You must strike at their leaders, {name}. You will find them holed up in the old keep. Battle your way inside and find the holdouts! Turn them for your queen!\n\nNone shall escape the mighty grasp of the Forsaken!", objectives = "Find the Refugee Leadership inside Fenris Keep.", completion = "It would seem that Crowley is more formidable than I anticipated. Still, he is a man - flesh and bone - full of secrets. Secrets that I know all about...\n\nYou have served me well, <name>. I could use someone of your ability at the Sepulcher. I have a plan to deal with Crowley and his insurgents once and for all. Will you help?" }
WordHunterWoW_QuestEN[27100] = { title = "Twilight Research", description = "The book you found appears to detail some form of research carried out by a member of the Twilight's Hammer.\n\nIt deals with the oozes in some way, but there are multiple pages missing.\n\nPerhaps if you found additional notes you might be able to make sense of it.", objectives = "Obtain 4 Twilight Research Notes from Mercurial Oozes in the Upper Silvermarsh.", progress = "<You scroll through the notes, trying to put them in order.>", completion = "The notes deal with High Cultist Maziel's research on the elemental properties of quicksilver.\n\nHis obsession with the subject borders on the insane." }
WordHunterWoW_QuestEN[27101] = { title = "Maziel's Revelation", description = "The notes continue Maziel's rambling research into the properties of quicksilver and mercurial oozes.\n\nHe appears to have made a major discovery.  He mentions hiding his journal in the Lower Silvermarsh to the southwest.", objectives = "Find Maziel's Journal at the Lower Silvermarsh in Deepholm.", completion = "Maziel's journal appears to be undamaged by the mercury." }
WordHunterWoW_QuestEN[27102] = { title = "Maziel's Ascendancy", description = "Maziel's journal chronicles a ritual of ascendancy that would transfigure his body to one of pure quicksilver.\n\nThe ritual would take place in the cave near the Lower Silvermarsh, where Maziel would feed upon the mercurial oozes until achieving full strength.\n\nPerhaps it is not too late to put an end to his madness.", objectives = "Slay Maziel inside the Silverlight Cave in Deepholm.", completion = "You've disposed of an enemy before he could grow more powerful.  By eliminating Maziel you've also ensured that his powers will not be used against the Earthen Ring." }
WordHunterWoW_QuestEN[27103] = { title = "Shards of the Felvine", description = "The satyr Alzzin the Wildshaper has exerted his corrupt dominion over this part of Eldre'Thalas.  The Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin. It may be the key to purify this ancient place.\n\nWhen the great satyr falls, capture whatever essence of the Felvine you can.  Seal it in this Reliquary of Purity, and bring it to me.\n\nGood luck, and Cenarius' speed.", objectives = "Use the Reliquary of Purity to capture a Felvine Shard.", progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.", completion = "You have done well, <class>, and for that I am forever in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this gold as a token of my enduring gratitude.  If we ever cleanse Dire Maul, know that you will be welcomed here as a hero. Thank you." }
WordHunterWoW_QuestEN[27104] = { title = "Alzzin the Wildshaper", description = "The monster responsible for the ruin you see before you is called Alzzin the Wildshaper. To reach him, however, you will need to also slay Zevrim Thornhoof, the satyr who currently holds the still noble ancient Old Ironbark in his grasp.\n\nOnce Ironbark is free, he will help you make an entrance into Alzzin's domain. Enter and slay him without mercy, for there is no other way.", objectives = "Kill Zevrim Thornhoof and Alzzin the Wildshaper.", progress = "Time is running short, <race>. I trust you will not fail.", completion = "Ah, very well done indeed. You've made an old spirit very happy this day. You deserve proper thanks for the risks you've taken." }
WordHunterWoW_QuestEN[27105] = { title = "An Unwelcome Guest", description = "You will find that Dire Maul is filled with many nature and arcane elementals. Somehow, a water elemental has found its way into this area. Please gather its essence and take it to me. I am curious as to how one of their kind got here, and what sort of agenda it may have against the natural elements of Eldre'Thalas.", objectives = "Collect the Hydrospawn Essence.", progress = "Do you carry the essence, or did the task prove too difficult?", completion = "It is very troublesome that a water elemental was here, let alone one that powerful. Take this as my thanks for your efforts. I must examine this essence for any knowledge it may contain." }
WordHunterWoW_QuestEN[27106] = { title = "A Villain Unmasked", description = "<You find a complete list of all the Twilight's Hammer cultists in Stormwind.>\n\n<More importantly, you discover a letter from Major Samuelson to his compatriots outlining this entire scheme. The Prince was right: Samuelson is the real villain here, using his connections as commander of the city guard to disguise cult activity.>\n\n<It's time to return to Stormwind Keep and bring Samuelson to justice!>", objectives = "Unmask and slay Major Samuelson in the Stormwind Keep Throne Room.", progress = "You have evidence incriminating Samuelson? Let's see what he has to say for himself!", completion = "Samuelson - corrupted by the Twilight's Hammer? This must have been going on for years. Right here in my very keep!\n\nI am grateful that you and my son were able to get to the bottom of this before my city was brought to harm. I've underestimated how much Anduin has grown - his command of the holy light just saved my life, if not the entire kingdom.\n\nAs for you - words alone can't do justice to your heroism this day. Thank you, <class>." }
WordHunterWoW_QuestEN[27107] = { title = "Pusillin The Thief", description = "Me take quick nap earlier and stupid fast imp take book! Dagg'thol need book to follow orders and Master need book to conquer! Gah!\n\nYou {race} help me get book from imp, and I give you shiny something. Go, imp right there to da left! KILL!!!", objectives = "Convince Pusillin to give up the Book of Incantations.", progress = "<race> has book?", completion = "Now you watch Master use book to kill stupid trees and stupid goat men! YAR!" }
WordHunterWoW_QuestEN[27108] = { title = "Lethtendris's Web", description = "Blood Elf Lethtendris has web to catch magic here. She use for herself, but Master want to use for good of whole world! You help get web from stupid elf and not only will Dagg'thol reward you, you see how Master use it way better!", objectives = "Obtain Lethtendris's Web.", progress = "<name>, you have stupid elf's web?", completion = "This web have lots of magic! Master will be very happy now!\n\nAnd you make Dagg'thol happy, <race>. Take this so you believe how happy you make Dagg'thol!" }
WordHunterWoW_QuestEN[27109] = { title = "The Warped Defender", description = "The Ironbark and Warpwood were once the mighty protectors of Eldre'Thalas. Look at how they have fallen! Ultimately, their fate lies at the hands of myself and my fellow Highborne. We were reckless with our power, {race}.\n\nBut you, you can right the wrongs here! Venture forth and put Tendris Warpwood to rest. He was the mightiest and last defender of this area, and deserves spiritual release. Be wary, for if you do not dispose of the Ironbark Protectors prior to engaging Tendris, he will call them to assist.", objectives = "Kill Tendris Warpwood.", completion = "Your work here was noble. Fret not, for Tendris' soul was crying to be put to rest. He is thankful." }
WordHunterWoW_QuestEN[27110] = { title = "The Madness Within", description = "This madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the five pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced from the demon's demise, attack and end him as well. Lay the spirits of this city to rest, adventurer, and make the Prince pay for his wrongdoings.", objectives = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", progress = "Be wary, adventurer. The Prince is... persuasive.", completion = "We thank you, hero." }
WordHunterWoW_QuestEN[27111] = { title = "The Treasure of the Shen'dralar", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.", objectives = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", completion = "You open the chest to find..." }
WordHunterWoW_QuestEN[27112] = { title = "The Cursed Remains", description = "There are remaining beings here that pose a direct threat to us ever reclaiming this sacred city. Magister Kalendris and Illyana Ravenoak are both extremely dangerous and need to be disposed of as quickly as possible.\n\nExercise caution, for with there being so few remaining feeding off of Immol'thar's energies, they are likely to be stronger than they first appear.", objectives = "Kill Magister Kalendris and Illyana Ravenoak.", completion = "Your dedication will make this all that much easier." }
WordHunterWoW_QuestEN[27113] = { title = "The Shen'dralar Ancient", description = "Some beings here have miraculously managed to remain free of the darkness that runs so rampant. On the second story of the Court of the Highborne rests a Shen'dralar Ancient. Seek it out, it may hold a wealth of wisdom, perhaps even the secret to freeing Eldre'Thalas.", objectives = "Speak to the Shen'dralar Ancient.", completion = "Our meeting is no coincidence, <name>." }
WordHunterWoW_QuestEN[27114] = { title = "The Gordok Taste Test", description = "", objectives = "You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!" }
WordHunterWoW_QuestEN[27115] = { title = "Ando's Call", description = "You've done great work here, {name}. While you were out, that young Ando fellow was here looking for you. Said something about a metal bird.\n\nYou might want to go back to the shores of the Loch and see what he wanted.", objectives = "Talk to Ando Blastenheimer.", completion = "It's working! My father brought it!" }
WordHunterWoW_QuestEN[27116] = { title = "The Winds of Loch Modan", description = "Father finished the Skystrider. It's amazing! Once we get the bugs worked out, I'm going to use it to fight for justice, just like you.\n\nI know you've got to move on, and help other people, being a hero and all, but how about a ride? I'm about to take the Skystrider on its first flight, and I'll be honored if you join me. I'll drop you off at Algaz Station.\n\nWhat do you say?", objectives = "Ride the Skystrider to Algaz Station and then speak with Mountaineer Stormpike.", completion = "What in blazes WAS that? A flying mechanostrider?\n\nYou know what, I don't want to know. I'm just going to pretend that didn't happen, and we'll be all nice and businesslike." }
WordHunterWoW_QuestEN[27117] = { title = "Brute Strength", description = "Gandling has brought his lieutenant, the Ravenian, with him.  This lumbering brute is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find the Ravenian within a tower near the southern end of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", objectives = "Kill the Ravenian within Andorhal.", completion = "Excellently done, <name>." }
WordHunterWoW_QuestEN[27118] = { title = "A Broken Trap", description = "", objectives = "A large, broken trap lies before you.  From the looks of it, the ogres have tried to repair the trap but to no avail.\n\nA hastily written note lies next to the trap, and strangely enough it details exactly how to repair it: just a few simple adjustments ought to do it.  Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.\n\nClearly, it would seem fortuitous that very few ogres know how to read.\n\nClearly." }
WordHunterWoW_QuestEN[27119] = { title = "The Gordok Ogre Suit", description = "If you're going to fight the king of the Gordok then you're going to need to get by Captain Kromcrush. Now, you can get by him by killing him, sure. You might actually want to leave him alive.\n\nHow, you ask? I think I know! An ogre suit!\n\nI'll make you one if you bring me an Ogre Tannin from upstairs. I'm not going anywhere like this...", objectives = "Bring an Ogre Tannin to Knot Thimblejack.", progress = "Just get me that Ogre Tannin, and I'll whip you up an ogre suit that will fool Captain Kromcrush into thinking you're one of his men.", completion = "Yeah, this will do the trick.  Just a slip here, and tuck here... heh - this is going to work out just fine!  <A broad smile beams from the chained goblin's face.>\n\nHere you go, you're all set.  Remember- this isn't the most securely fashioned item in the world.  You'll have ten minutes of use before it falls apart, and then you're not going to fool anybody!  Try using it just before you approach him to make sure it lasts as long as you're going to need it." }
WordHunterWoW_QuestEN[27120] = { title = "The Gordok Ogre Suit", description = "", objectives = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me another Ogre Tannin, and I'll make you another ogre suit.", progress = "Need another suit, do ya?  Well, I'm not going anywhere soon it seems - bring me another Ogre Tannin, and I'll make you another ogre suit.", completion = "Here ya go <name> - put this thing on, and you'll have ten minutes to do whatever.  Good luck!\n\nOh, and if you happen to find a key to get me out of here, BY ALL MEANS LET ME KNOW!!!" }
WordHunterWoW_QuestEN[27121] = { title = "Free Knot!", description = "", objectives = "" }
WordHunterWoW_QuestEN[27122] = { title = "Fired Up and Not So Good To Go.", description = "Leave it to the Dark Irons to work with Ragnaros' toadies and worse. You can bet that insane Twilight's Hammer cult is behind the lot of this!\n\nTime to end their attacks on Ironforge once and for all. Oh, and tell Commander Cragfist what's happened here when we return; I'll need to work on getting the city and its good people back in order.", objectives = "Slay Grand Ambassador Flamelash and inform Commander Cragfist in Ironforge.", completion = "Dark Iron dwarves and Ragnaros the Firelord, ye say? At the behest of the Cult o' Twilight's Hammer?\n\nWell done! Ironforge is in yer debt." }
WordHunterWoW_QuestEN[27123] = { title = "Deepholm, Realm of Earth", description = "I knew you'd heed our call, {name}.  When Deathwing was first defeated by the other dragon aspects, he retreated to Deepholm, the realm of earth.\n\nDeathwing's return to our world left a rift open between Azeroth and Deepholm.\n\nIf we don't mend the breach, this land will be torn asunder.\n\nWe're doing our best to contain the damage on this side of the rift.  Aggra will take you through the rift so you can help repair the damage from the other side.\n\nGet on her wyvern when you're ready.", objectives = "Jump on Aggra's Wyvern and fly into the breach at the Maelstrom. Once you're on the other side, speak to Maruut Stonebinder.", completion = "You've arrived just in time, <name>.  All our resources are tied up keeping the rift stable.\n\nWe need someone like you to help us recover the fragments of the World Pillar." }
WordHunterWoW_QuestEN[27124] = { title = "Unfinished Gordok Business", description = "Now you da king, so maybe you get prized Gordok artifact back from Guard Mol'dar!  Da king before you never listened, just like all da other kings since da old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  You find it and it will become mighty gauntlet you wear forever!  Yar, I show you!", objectives = "Speak to Guard Mol'dar in Dire Maul.", completion = "Wow... you ARE da true king! Old king never even ask about da gauntlet!\n\nLook - this mark on da gauntlet an old old OLD timey magic mark, older than da Gordok they say.  Well, I learn one thing as little ogre - how to make mark come to life and give power back to gauntlet!\n\nI do it for you, king!  Here, take da gauntlet and rule FOREVER!" }
WordHunterWoW_QuestEN[27125] = { title = "King of the Gordok", description = "In Gordok society, their king is simply their strongest warrior. If anyone, ogre or otherwise, kills the current king, they are automatically hailed as the new one.\n\nThe new king receives tribute from any living guards, Stomper Kreeg, and Captain Kromcrush. Find and kill King Gordok while killing as few of their other leaders as possible, and not only will your reward be great, you will be able to use your power as king to halt the Gordok invasion without conflict!", objectives = "Kill King Gordok.", progress = "I have faith that you will be able to complete the task set out before you.", completion = "Yes! I can see that you were indeed successful. You have received your tribute, the Gordok advance will exist no longer, and the Gordok are blissfully ignorant! This is a true winner's scenario, <name>." }
WordHunterWoW_QuestEN[27126] = { title = "Rush Delivery", description = "Peak Grindstone's team broke down somewhere out there to the west.\n\nThink you can make yourself useful for a change and rush some parts out to them, {race}?", objectives = "Deliver the Catapult Parts to Peak Grindstone on the Fractured Front in Deepholm.", progress = "Are those spare parts you have there?", completion = "I can't thank you enough, <class>. Now, let's see if we can get this catapult moving again." }
WordHunterWoW_QuestEN[27127] = { title = "Fired Up and Not So Good To Go.", description = "Dark Irons? Cho'gall?! We'll show them what becomes of those who attack Orgrimmar.\n\nLet us attack! We'll hurl their limbless corpses into the magma they so adore.\n\nYou'll tell Blood Guard Kang what's happened here when we're done, yes? Doubtless I'll need to spend time organizing the repair of the city...", objectives = "Slay Grand Ambassador Flamelash and inform Blood Guard Kang in Orgrimmar.", completion = "Dark Iron dwarves and Ragnaros the Firelord, you say? At the behest of the Cult of Twilight's Hammer?\n\nWell done! Orgrimmar is in your debt." }
WordHunterWoW_QuestEN[27128] = { title = "King of the Gordok", description = "You kill Gordok leader, you new ogre king. If you king, then ogre leaders like Kromcrush and Kreeg that survive pay you big tribute and you stop Gordok invasion. If you do that, then me very happy ogre and we take Dire Maul FOR DA HORDE!!!\n\nGo, little {race}! Kill ugly Gordok ogre king and maybe dis be new Stonemaul Hold! Yar!", objectives = "Kill King Gordok.", progress = "You new Gordok king?", completion = "Little <race> did it! Now Horde more powerful than ever! YAR!" }
WordHunterWoW_QuestEN[27129] = { title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own. Taking Dire Maul would be a major step in reclaiming Feralas for our people.\n\nYou can find Dire Maul to the southeast of here.", objectives = "Speak to Furgus Warpwood.", completion = "Have you been in contact with a druid of the talon recently, <class>? I can feel the lingering presence of one." }
WordHunterWoW_QuestEN[27130] = { title = "Saving Warpwood", description = "Just inside the eastern wing of Dire Maul one of the warpwood ancients, Furgus Warpwood, still lives uncorrupted. You must travel there and help him drive out the terrible creatures that have taken it as their own before they set their sights on Camp Mojache. Perhaps we can even enlist his aid afterward to ensure we maintain our presence in Feralas with enemies on so many sides.", objectives = "Speak to Furgus Warpwood.", completion = "Your face shows signs of desperate conflict. I honor your presence, brave <class>." }
WordHunterWoW_QuestEN[27131] = { title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of the Highborne, it is an effort I must support for the good of Feralas. May the wind carry your spirit there with great swiftness.\n\nYou will find Dire Maul to the southeast. ", objectives = "Speak to Estulan.", completion = "I sensed your coming all the way from Dreamer's Rest. Your assistance would be most welcome." }
WordHunterWoW_QuestEN[27132] = { title = "The Highborne", description = "Estulan, a powerful and uncorrupt Highborne, has managed to enter the western wing of Dire Maul and has asked for assistance in cleansing it. Regardless of your personal convictions of his kind, it is an effort I must support for our own good. Please hurry, we need every foothold in Feralas that we can get.\n\nYou will find Dire Maul to the west.", objectives = "Speak to Estulan.", completion = "I sensed your coming all the way from Camp Mojache. Your assistance would be most welcome." }
WordHunterWoW_QuestEN[27133] = { title = "Eyes in the Sky", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. I requested a druid of the talon to go there and scout it out. If he still lives, speak with him and he will act as your commander to stop the Gordok before they decide to attack.\n\nThat's an order, {class}.", objectives = "Speak to the Druid of the Talon.", completion = "Speak softly, <name>. The Gordok may not be intelligent, but they are still dangerous warriors." }
WordHunterWoW_QuestEN[27134] = { title = "Ogre in the Field", description = "The most dire, and most organized, threat to us in Feralas are the Gordok ogres in the northern wing of Dire Maul. If we eradicate them and take Dire Maul for the Horde, we will possess a heavily fortified seat of power in this region with numerous artifacts to sweeten the deal. I sent in a small army of Stonemaul Ogres inside earlier - if any have survived, speak with them and finish the job.\n\nThat's an order, {class}.", objectives = "Speak to the Stonemaul Ogre.", completion = "These ogres no pushovers. I need you help me finish Orhan's task, <race>." }
WordHunterWoW_QuestEN[27135] = { title = "Something that Burns", description = "Alright, we need something that's going to make the compound go, \"Boom\"!\n\nI'm all out of gun powder, but I think I know what we can use instead... the heart of my fire elemental!\n\nHere, take my fire totem east to the Blood Trail. Just flip the switch on it near any of the lava pools over there and Magmatooth should be summoned. Bring back his heart and we'll be in business.", objectives = "Obtain the Burning Heart.", progress = "You have the heart yet?", completion = "Uh oh. Sounds like he wasn't very happy about the situation. How was I to know? I'm just an initiate after all.\n\nAnyway, I'll worry about Magmatooth later." }
WordHunterWoW_QuestEN[27136] = { title = "Elemental Energy", description = "It's taking every ounce of our power to keep this realm stable in the absence of the World Pillar.\n\nAs shaman we can tap directly into the energies of the elementals that inhabit Deepholm and use them to heal the damage that the rift is causing.\n\nTake this totem and place it on the ground outside.  Any energized geodes or lodestone elementals destroyed in its proximity will fill it with the energy we require.", objectives = "Destroy 8 Energized Geodes or Lodestone Elementals near the Depleted Totem.", completion = "Thank you, <name>.  We need all the power we can muster to keep Deepholm stable." }
WordHunterWoW_QuestEN[27137] = { title = "Earth Girls Aren't So Easy", description = "", objectives = "Ol' Theradras was behind all the movin' amd shakin', ye say?\n\nAnd the Cult o' Twilight's Hammer put her up to it?\n\nWell done! Ironforge is in yer debt." }
WordHunterWoW_QuestEN[27138] = { title = "Earth Girls Aren't So Easy", description = "", objectives = "Theradras wreaking havoc for the Cult of Twilight's Hammer, eh? And she's in pieces, now?\n\nWell done! Orgrimmar is in your debt." }
WordHunterWoW_QuestEN[27139] = { title = "Hobart Needs You", description = "Heya, boss, Hobart Grapplehammer's wants to speak with you. He says it's a matter of some urgency.", objectives = "Speak with Hobart Grapplehammer at the Town-In-A-Box on the Lost Isles.", completion = "There you are, my boy. I have something very important for you to do!" }
WordHunterWoW_QuestEN[27140] = { title = "Alexi's Gambit", description = "I require your assistance, <class>. Find the undead mage Vectus and the warrior Marduk deep within here. They run the scourge's plagued dragon operation and must be destroyed.\n\nPlace this Gambit in the viewing room where they are located. Hopefully, it will react with their forces and utterly destroy them!\n\nOh, defeating Vectus and Marduk afterward shouldn't be a problem.  Right?", objectives = "Place the Gambit in the Viewing Room and slay Vectus and Marduk.", completion = "You did it!  They are defeated!  And the Gambit... did it work?\n\nVery interesting. You've done well, <name>." }
WordHunterWoW_QuestEN[27141] = { title = "Exploding Through", description = "What a find!\n\nRight here... exactly where my notes predicted it would be.\n\nWith any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise.\n\nThat's right, {name}. It's not just a myth. I believe it truly exists.\n\nI'll explain more later. For now, just give me a hand with these explosives.", objectives = "Assist Harrison Jones at the Khartut's Tomb.", completion = "Shake it off, kid.\n\nHappens to me all the time..." }
WordHunterWoW_QuestEN[27142] = { title = "The Lich, Ras Frostwhisper", description = "One of Kel'Thuzad's most trusted students oversees the operations in Scholomance. You must confront the lich, Ras Frostwhisper, in his lair. The door to his chamber is adjacent to the viewing room.\n\nDestroy him, <name>. Leave no trace of his existence so that he may never again bring such horrors into our world.", objectives = "Destroy Ras Frostwhisper.", completion = "Ten thousand souls cry out in unison, <name>! You have struck a mortal blow to the Scourge and their masters." }
WordHunterWoW_QuestEN[27143] = { title = "Barov Family Fortune", description = "Within Scholomance lays the Barov family fortune. Alexi and I are the last two Barovs in existence.\n\nHowever, I am the only living Barov, so our family's vast empire belongs to me! Find me the deeds to Caer Darrow, Brill, Tarren Mill, and Southshore and I will repay you generously. The Barov estate will be reborn at long last!", objectives = "Recover The Deed to Caer Darrow, The Deed to Brill, The Deed to Tarren Mill, and The Deed to Southshore.", progress = "Bow your head in my presence, <race>. I am a noble, after all, and you are a copperless peasant.", completion = "Excellent work, <race>. Alexi deserves nothing for his foolishness." }
WordHunterWoW_QuestEN[27144] = { title = "The Reckoning", description = "Your performance was admirable, soldier.  You make the Forsaken proud, which is more than I can say for our general, Koltira Deathweaver.\n\nI intend to have a word with that death knight.  He has shamed himself and his cause.", objectives = "Stand by as Lady Sylvanas Windrunner speaks with Koltira Deathweaver.", progress = "Yes?", completion = "I have nothing against the Knights of the Ebon Blade, but Koltira needs to be reminded who he works for now.  His loyalty must lie with the Horde.\n\nOr, more specifically, the Forsaken.\n\nI wouldn't plan on seeing Koltira anytime soon.  Now that I have him... you can rest assured that any bonds he may have had with that Alliance scum will be thoroughly broken." }
WordHunterWoW_QuestEN[27145] = { title = "Plagued Hatchlings...For Now", description = "One of the 'projects' underway here is the plagued dragonflight. Thankfully, they're only hatchlings right now, but if we wait much longer they will become one of the scourge's most powerful weapons and a major threat to all of Azeroth, especially my family's land!\n\nSlay ten of their whelps and be sure to take care of Rattlegore as well. He is in the small space beneath where the whelps are housed and prepares supplements to catalyze their growth. Hurry...before they get any bigger!", objectives = "Kill 10 Plagued Hatchlings and Rattlegore.", completion = "Well done, <name>!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!" }
WordHunterWoW_QuestEN[27146] = { title = "Doctor Theolen Krastinov, the Butcher", description = "Doctor Theolen Krastinov is responsible for the deaths of thousands. His nickname, The Butcher, is well earned for the atrocities he takes joy in executing. He must be punished, justice must be meted out.\n\nFind him and exact upon him the agony he has inflicted upon countless innocents, including me and my husband. Once he is destroyed, burn our remains. Turn them to ashes, <name>. Release our grieving souls.", objectives = "Destroy Doctor Theolen Krastinov, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff.", completion = "I can feel my spirit healing, <name>. You have done my husband and I a great service." }
WordHunterWoW_QuestEN[27147] = { title = "Kirtonos the Herald", description = "With blood, Kirtonos may be summoned. It is with blood, then, that Kirtonos must be destroyed.\n\nWithin the Chamber of Summoning, you will find a brazier, upon which you shall place a drop of your own blood. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.\n\nShould you succeed, you will earn more than just our gratitude.", objectives = "Destroy Kirtonos.", completion = "With the death of Kirtonos, a chapter in the horrible tale of Scholomance comes to a close. You have my deepest, everlasting gratitude for your bravery." }
WordHunterWoW_QuestEN[27148] = { title = "School's Out Forever", description = "Darkmaster Gandling serves as headmaster of Scholomance, and is therefore responsible for countless deaths at the hands of his students. For that he must be punished.\n\nHe will not come out easily. Lure him out by slaying his six professors whose rooms connect to the Headmaster's Study. Be wary, for when the last falls he will come, and he will come infuriated with vast magic backing his assault. Don't let him make it out of here alive.", objectives = "Kill Darkmaster Gandling.", completion = "Without a headmaster, the school will descend into chaos. It will not put forth any more of its vile 'students' into the field. Thank you." }
WordHunterWoW_QuestEN[27149] = { title = "School of the Damned", description = "Greetings! As you can see, the Western Plaguelands is very nearly free of the last remnants of the scourge. However, their school of necromancy, Scholomance, still sits full of lost young souls training to become scourge sorcerers! Our work here will be for naught if we do not stop this flow of fresh, not to mention very powerful, necromancers.\n\nTravel southeast to Scholomance and find Weldon Barov. He is the last living member of the Barov line that once owned all these lands and is our current contact.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Walden Barov in Scholomance.Greetings! As you can see, the Western Plaguelands is very nearly free of the last remnants of the scourge. However, their school of necromancy, Scholomance, still sits full of lost young souls training to become scourge sorcerers! Our work here will be for naught if we do not stop this flow of fresh, not to mention very powerful, necromancers.\n\nTravel southeast to Scholomance and find Weldon Barov. He is the last living member of the Barov line that once owned all these lands and is our current contact.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[27150] = { title = "The Menders' Stead", description = "It's likely that the battle for Andorhal will start up again soon.  In the meantime, you could probably stand to practice your skills as a {class}.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle.  I don't doubt that they'll have some work for you.", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.It's likely that the battle for Andorhal will start up again soon. In the meantime, you could probably stand to practice your skills as a <class>.\n\nEast of here is a large farm that has been taken over by the Argent Dawn and the Cenarion Circle. I don't doubt that they'll have some work for you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[27151] = { title = "Taelan Fordring's Legacy", description = "Greetings.  How do you do?  My name is Daria.\n\nI am one of the priests in charge of preserving the peace here in Hearthglen.  One of my duties involves maintaining the tower down the trail to the southeast of Hearthglen.  This particular tower is of personal importance to the Highlord.  It's the place where his son was killed.\n\nWith the recent incursion of gnolls, however, maintenance of the tower has grown difficult.  Will you help me rid the trail of some of these gnoll vandals, so I can do my duty?", objectives = "Kill 10 Redpine Looters.", completion = "I must admit, <name>... I have been using my mind vision spell to keep tabs on you.  And I must say... the number of gnolls you found on the trail is truly staggering!" }
WordHunterWoW_QuestEN[27152] = { title = "Unusual Behavior... Even For Gnolls", description = "Allow me to concentrate for a moment.\n\n<You feel Daria's mind vision travel elsewhere, then it returns to you.>\n\nFurther down the trail, south of Taelan's Tower, the gnolls have carved out a small meeting area to the east of the main road.  Something is happening there... I'm not certain what.  We should investigate.  I will look for anything out of the ordinary... you just protect yourself.", objectives = "Investigate the gnoll hideout along the trail to Hearthglen in Western Plaguelands.", completion = "Gnolls and necromancy... what a surprise!  And I thought that, here in the Western Plaguelands, we had put these dark days behind us.\n\n<You sense Daria's eyes focusing on something on the ground.>\n\nWait... what is THAT?" }
WordHunterWoW_QuestEN[27153] = { title = "The Good People of Hearthglen", description = "See those reagents over there?  And these supplies right here?  Those belong to the Argent Crusade.\n\nGnolls are known for thievery, but as far as I know, Hearthglen hasn't had any incursions since the Redpine came.  Very suspicious.\n\nI know a few helpful folks within Hearthglen: Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus.  All can be trusted, and are well-connected.  Question them, to find out if they know anything about these lost supplies.", objectives = "Speak with Morris Vant, Outfitter Mendelev, Bree Ironstock, and High Cleric Alphus within Hearthglen.", completion = "Did you notice, <name>?  Many names were mentioned, but one name was mentioned far more than the others.\n\nBisp." }
WordHunterWoW_QuestEN[27154] = { title = "Bagging Bisp", description = "Magus Bisp is one of Hearthglen's most preeminent arcanists.  To imagine that he would be interacting with gnolls... and dabbling in necromancy?  Unthinkable.\n\nYou'll find him atop the tower near Hearthglen's main gate.  Hopefully he'll have an explanation for all of this.  If not, well... I wouldn't go to the top of that tower unprepared, {name}.", objectives = "Speak with Magus Bisp atop the mage tower in Hearthglen.", completion = "I suppose that we can take his aggression as an admission of guilt.  You alright, <name>?" }
WordHunterWoW_QuestEN[27155] = { title = "Turning Yourself In", description = "So... you killed a member of the Argent Crusade, inside of Hearthglen.  Usually that's not smiled upon, even in self-defense.\n\nI recommend you come back to Mardenholde Keep, and turn yourself in to Highlord Fordring.  Hopefully he will hear you out, and will be sympathetic with your situation.  I hope I haven't gotten you in any trouble.", objectives = "Report to Highlord Tirion Fordring at Hearthglen in Western Plaguelands.", completion = "I'm already aware of your actions, <name>.  I welcome you into my town, give you my blessing, and what do you do?\n\nYou slay the traitor that we've been hunting down for weeks.  Well done.  Your heroism is budding much earlier than even I had anticipated." }
WordHunterWoW_QuestEN[27156] = { title = "It's About Time!", description = "Finally!  You're here!  Get to work!\n\nMy men have been sparring with these wooden practice dummies for far too long.  Sure, you can learn how to swing a sword by practicing with a dummy, but real combat requires a real combatant.\n\nHmmm... I had asked for them to send me someone imposing, but I suppose a skinny-armed {race} {class} will have to do.\n\nNow get in there and teach my men how to fight!", objectives = "Challenge and defeat 7 Hearthglen Trainees.", progress = "I'm not paying you to talk to me.  I'm paying you to talk with my soldiers... and then fight with them.", completion = "I'm just looking over my paperwork here, and it says that we were expecting a FEMALE <race> <class>.  You're not, umm...\n\n\n\nNever mind.  It would appear that you are not the person that I originally hired, but you did a good job.  So I'm going to pay you anyhow." }
WordHunterWoW_QuestEN[27157] = { title = "Drudges... <Sigh>", description = "Say, I never caught your name.  {name}?  Pleased to meet you, {name}.\n\nI've got one more problem that needs fixing, and you have a look about you that just screams \"I'm a problem-fixer\".\n\nThere's a small mine on the northern edge of Hearthglen, where we get most of the ore that the town needs.  My drudges who work the mine normally do a decent job.\n\nUnfortunately, it seems that a larger-than-average spider has taken up residence within this cave.  Think you can clear things up for me?", objectives = "Kill Shadril within the mine inside Hearthglen.", completion = "Nice work!  In retrospect, I'm glad that other <race> <class> never showed up... you've proven to be all the help I need." }
WordHunterWoW_QuestEN[27158] = { title = "The Battle for Andorhal", description = "Hurry, {name}... there isn't time to waste.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.  With Arthas dead, now is the time for the Alliance to start to retake Lordaeron.\n\nSpeak with the gryphon master, Bibilfaz Featherwhistle, when you are ready, and he will put you on the first flight out there.", objectives = "Report to Thassarian within Andorhal in Western Plaguelands.", completion = "It's about time you arrived, <class>." }
WordHunterWoW_QuestEN[27159] = { title = "Scourge First... Horde Later", description = "Darkmaster Gandling of the Cult of the Damned leads the Scourge offensive here in Andorhal.  My old counterpart, Koltira, leads the Forsaken forces.  If we're to win Andorhal, we'll have to defeat both, but we will certainly fail if we take on both at once.\n\nI know Koltira well enough to know that he will focus on the Scourge first.  We will do the same.\n\nTake out the weaker, desiccated Scourge to reduce their numbers.  The Forsaken will have to wait to taste our wrath.", objectives = "Slay 15 Desiccated Scourge within Andorhal.", completion = "You may not act quickly, but at least you do not fail me.\n\nVery well.  I will have a more important task for you, <name>, when the time is right." }
WordHunterWoW_QuestEN[27160] = { title = "War Machines", description = "Dried-up Scourge... weak.  Abominations... strong.\n\nWe defeat strong abominations... we win war.", objectives = "Destroy 6 Opengut Behemoths in Andorhal.", completion = "Abominations... strong.\n\n<name>... stronger." }
WordHunterWoW_QuestEN[27161] = { title = "The Endless Flow", description = "Araj the Summoner is bolstering the Scourge defenses with simple skeletons... an army of weaklings that will overwhelm you before it overpowers you.  He has assembled animi within Andorhal's northern towers that spew these skeletons out at an alarming rate.  But I've got the solution!\n\n<Lang passes you a handful of grenades.>\n\nTheir function is simple.  Throwing these grenades at a bone animus... or, for that matter, a mob of skeletons... will reduce them to splinters.", objectives = "Use Lang's Hand Grenades to kill 5 Stickbone Berserkers and to destroy a Scourge Bone Animus.", progress = "I know what those devices sound like when they've blown up... and I haven't heard that sound yet.  Get back out there, <name>.", completion = "These grenades are all explosives, nothing more.  I may not be a goblin engineer... but I still understand the value of being able to just explode things every once in a while." }
WordHunterWoW_QuestEN[27162] = { title = "Scholomancer", description = "The Scholomance is one of the few Scourge holdouts remaining west of the Thondroril.  The headmaster of Scholomance, a cultist by the name of Darkmaster Gandling, has made an appearance on the battlefield.\n\nThis will be his final mistake.\n\nYou will find Gandling in a square near the southern end of town.  I want you to fight and weaken Gandling.  I will join you to help finish him off.", objectives = "Kill Darkmaster Gandling within Andorhal.", completion = "Excellently done, <name>.  And now, with the leader of the Scourge forces eliminated from Andorhal, we bide our time." }
WordHunterWoW_QuestEN[27163] = { title = "Brute Strength", description = "Gandling has brought his lieutenant, Rattlegore, with him.  This clattering horror is far more dangerous than any of the other Scourge you will find upon the battlefield... even the abominations.\n\nYou will find Rattlegore within an old town-hall building, near the center of town.  I recommend caution before fighting him, {name}.  He will not be a pushover.", objectives = "Kill Rattlegore within Andorhal.", completion = "Excellently done, <name>." }
WordHunterWoW_QuestEN[27164] = { title = "Araj the Summoner", description = "With the animus destroyed, the next logical step is to take out Araj himself, and to take a shard of his phylactery.  You've probably already seen him, lurking at the fountain in the center of town.\n\nTake my grenades with you.  They won't do anything to Araj, but if he decides to summon any of those skeletons, you can use them to blow them away.  Again.", objectives = "Kill Araj the Summoner. You may use Lang's Hand Grenades to destroy Stickbone Berserkers.", progress = "Araj is a formidable opponent.  Be prepared.", completion = "Araj dead... this is good.  That gnome has done his part in winning this war.  As have you, <name>." }
WordHunterWoW_QuestEN[27165] = { title = "Victory, For Now", description = "The Alliance are victorious, and our forces are still strong.  Military strategy dictates that we attack the Forsaken now, while they are recovering and unaware.  I made a deal, however...\n\nWe will wait.  We attack Koltira and his troops when the time is right.  In the meantime, speak with Ginny Goodwin and take a flight to the Chillwind Camp, to our south.  Commander Ashlam Valorfist will give you your next assignment.\n\nYou will hear from me when you are needed again in Andorhal.", objectives = "Report to Commander Ashlam Valorfist at Chillwind Camp in Western Plaguelands.", completion = "Word arrived shortly before you did, <name>.  With the Scourge ejected from Andorhal, we are one step closer to retaking Lordaeron." }
WordHunterWoW_QuestEN[27166] = { title = "Go Fletch!", description = "We must always be prepared for battle, {name}.  Whether that battle is against the Forsaken in Andorhal, against the Scourge in the east, or against some yet-unknown foe is unknown.  What is known, is that we must be ready.\n\nWe are low on arrows.  I can obtain the shafts and heads, but I still need feathers.  The birds that circle to the northwest typically molt this time of year.  Would you mind traveling out into the field and gathering some of these feathers for our camp?", objectives = "Obtain 9 Brownfeather Quills.", progress = "It's good to see you back, <name>.", completion = "I will have my fletchers get to work on these.\n\nI'm glad to see you being so useful right away, <name>.  Perhaps later I will have some more exciting tasks for you." }
WordHunterWoW_QuestEN[27167] = { title = "A Mighty Hunger", description = "I hail from Westfall, far to the south... as do these men that travel with me.  We are farmers, and nothing more.\n\nI had been told that Lordaeron had been healed, and that it was ready for tilling.  However, this \"Commander\" now tells me that it's too dangerous to proceed.  He says that there's a war going on, and that the plaguelands still aren't healed.\n\nBefore anything else, I need to get some food in my men's stomachs.  Anything will do.  Bear seems to be plentiful.", objectives = "Obtain 5 Sides of Bear Meat from Shaggy Black Bears in Western Plaguelands.", progress = "We've traveled a long way.  Anything you can spare would be appreciated.", completion = "You hunt like a true <class>.  Even if we can't set up our homesteads... at least we can still eat." }
WordHunterWoW_QuestEN[27168] = { title = "Those That Couldn't Let Go", description = "Sorrow Hill, up the road to the northeast, was one of the first places that the Argent Crusaders and Cenarion Circle were able to heal.  The area is now freed of the Scourge.\n\nHowever, there are still many specters of the past that, for some reason, have not passed on into the next world.  They may be mourning, they may have unfinished business... or they may just be lost.\n\nTake my thurible and use it to douse them with holy incense.  One way or another, we will help them move onto the next plane.", objectives = "Use the Holy Thurible on 12 Withdrawn Spirits in Sorrow Hill, and slay them if they react negatively.", completion = "Hopefully most of them passed on peacefully.  I thank you, <name>." }
WordHunterWoW_QuestEN[27169] = { title = "Uther's Blessing", description = "These farmers from the south wish to take these farms, but I can't let them enter the plaguelands unprepared.  Even with the Scourge gone, danger still looms in the form of the Forsaken.  No, we must be ready to fight... and that includes our new visitors.\n\nBefore doing anything else, however, I would recommend that you travel to Uther's Tomb, to the east, and place this tribute before his statue to ask for his blessing.  Speak with the priest that tends to the tomb when you are finished.", objectives = "Enter Uther's Tomb, and use the Chillwind Tribute before his statue.", progress = "Uther was a great hero.  It is my honor to serve him, even after he has passed.", completion = "You and the humans at Chillwind Camp wish to re-take Andorhal?  I wish you luck." }
WordHunterWoW_QuestEN[27170] = { title = "The Abandoned Crypt", description = "If you truly intend to move forward in this battle for Andorhal... well, perhaps I can help.\n\nTo the east lies a large crypt.  The bottom level of the crypt was once used for storage of weapons and armor... until the Scourge came.  Now that the undead have left, the weapons are free for the taking.\n\nMost of the weapons are probably rusted and rotten by now, but they will serve better than tunics and pitchforks.", objectives = "Find the Weapons Crate at the bottom of the Crypt in Western Plaguelands.", completion = "Scattered all over the bottom level of the crypt, you find shattered crates that once held weapons and armor.\n\nIt appears that somebody got here before you did." }
WordHunterWoW_QuestEN[27171] = { title = "Ambushed!", description = "As you turn around, you see the silhouettes of shambling skeletons on the stairs.\n\nThe undead aren't gone from this crypt.  They were lying in wait!  Furthermore, they appear to be armed with the weapons that you came looking for.\n\nYou'll have to escape from the crypt.  On your way out, you should gather as many pieces of equipment as you can.", objectives = "Obtain 4 Time-Worn Breastplates and 4 Rusted Swords.", progress = "What happened at Uther's Tomb, <name>?", completion = "Attacked by ghosts?  Strange.  I suppose that crypt wasn't fully healed after all.\n\nYou just missed Thurman Grant... you remember, that oaf of a farmer that was here earlier.  He took his men with him and traveled to the nearest farm... against my orders." }
WordHunterWoW_QuestEN[27172] = { title = "The Writhing Haunt", description = "The farmers traveled to the Writhing Haunt, an old farm to the northeast, across the river.  Someone needs to keep an eye on them.\n\nBring them those rusty weapons and armor you found.  We can't have them fighting with pitchforks.", objectives = "Bring the Battered Weapons and Armor to Thurman Grant at the Writhing Haunt in Western Plaguelands.", progress = "Did Valorfist send you?  He doesn't know when to let up, does he?", completion = "Well, now that you're here, we'll gladly take that armor off your hands.\n\nYou can keep the weapons, though.  These men wouldn't know which end to hold." }
WordHunterWoW_QuestEN[27173] = { title = "This Is Our Army", description = "I told Commander Valorfist that we could hold our own, and we intend to.  I had a little conversation with the death knight general, Thassarian, on my way over here.  We farmers plan to help in our own way.\n\nWe will take control of this farm, begin to cultivate the land... and then when the battle for Andorhal commences, we will attack the Forsaken from the rear.  They'll never expect it.\n\nFirst, we need to get rid of these Forsaken outriders.  Kill some, then return to me.", objectives = "Kill 10 Forsaken Outriders.", progress = "My men need your help, <name>.", completion = "You fight well, <race>.  My men could stand to learn a few moves from an experienced <class> like you." }
WordHunterWoW_QuestEN[27174] = { title = "Combat Training", description = "In fact, you might still be able to help train some of my men.  You probably noticed the abomination outside.  We initially tried to fight him, but he didn't fight back.  He seems to want to help out on the farm.\n\nTake a group of four settlers and challenge this abomination to combat.  He seems to be pretty tough, but with one of him and five of you, I think you'll have a chance at beating him.", objectives = "Speak with Gory at the Writhing Haunt and challenge him to combat.", progress = "If we're going to help out in this battle for Andorhal, we need to learn how to fight.", completion = "We can handle things from here.  I thank you for your help, <name>.\n\nI assume that when we next meet, it will be in battle.  Take care of yourself until then.  We'll need all the help we can get." }
WordHunterWoW_QuestEN[27175] = { title = "The Menders' Stead", description = "These men and women here at Chillwind Camp have noble goals, but their ultimate purpose is war.  I would like to offer you an opportunity to pursue more peaceful goals.\n\nAt the Menders' Stead, beyond war-torn Andorhal to the north, the Argent Crusade has joined forces with the Cenarion Circle.  Together, we work on healing this land from the plague that used to reign here.\n\nAre you interested in joining our cause, {class}?", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, <class>.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land." }
WordHunterWoW_QuestEN[27176] = { title = "A Strange Disc", description = "The etching around the surface of this object indicates that it is of ancient origins, and yet no signs of wear can be detected.\n\nA hole on its edge, full of splintered wood, indicates that it is meant to be put atop a wooden staff of some sort.\n\nBefore showing this to Doctor Jones, you should find the other piece.", objectives = "Obtain the Sultan's Staff, then use the Elaborate Disc to create the Shaft of the Stars.", progress = "Yes, <name>?", completion = "<Doctor Jones puts on his spectacles.>\n\nLet's have a look at this. Shall we?" }
WordHunterWoW_QuestEN[27177] = { title = "Salvage Operation", description = "Between the Horde and the naga, our fleet has been decimated. We can't do anything to bring back the men who gave their lives to the sea, but sink me if I allow all of our supplies to be lost forever.\n\nSwim out to the Obsidian Breakers southwest of Highbank and retrieve our supplies from the wrecks and the ocean floor.", objectives = "Retrieve 8 Recovered Supplies from Waterlogged Crates in the Obsidian Breakers.", progress = "How much were you able to recover?", completion = "Look at all this! You were able to recover more than I thought. We can outfit a whole squad of marines with this stuff.\n\nWe have the gear. If we only had some way to bolster our numbers here in the Highlands..." }
WordHunterWoW_QuestEN[27178] = { title = "Naga Reinforcements", description = "They've come slithering up from the ocean depths, {name}. The naga. I think their intent is to reinforce the Bastion of Twilight, probably by heading inland via the Verrall river. We can't let that happen!\n\nTeach them that these shores are ours now, and send them scurrying back to the lightless depths.\n\nKill the Blackscale naga worming their way through the Obsidian Breakers! ", objectives = "Slay 10 Blackscale Myrmidons or Blackscale Seacallers.", completion = "That'll send 'em packing, <name>! Cho'gall won't be able to count on the naga to back him up in this fight. From here on out, it's just us versus the Twilight's Hammer.\n\n\n\n...And the Horde." }
WordHunterWoW_QuestEN[27179] = { title = "Field Work", description = "This unfortunate pygmy was in the wrong place at the wrong time.\n\nAs you ponder his bad luck, you take notice of the symbols covering his shield - far too elaborate for pygmy scrawl.\n\nConfident that Doctor Jones will find such objects of interest, you set out to find more fragments like this one.", objectives = "Collect 10 Ancient Tablet Fragments.", progress = "What'dya have there, friend?", completion = "These tablets are covered with titan writings. There's never-before seen information here, <name>!\n\nMissing pieces to an ancient puzzle...\n\nGood work!" }
WordHunterWoW_QuestEN[27180] = { title = "Honor the Dead", description = "A convoy of veteran troopers and Forsaken catapults were ambushed earlier today while attempting to cross Olsen's Farthing, directly south of here. It was a total loss: all troopers were killed and all catapults destroyed.\n\nBloodfang's pack was responsible for the ambush, though likely they have all fled back into the hills, preparing their next cowardly strike. Their day will come, but for now I want you to go to Olsen's Farthing and honor our fallen.\n\nRecover their Forsaken insignias.", objectives = "Recover 6 Forsaken Insignias from Veteran Forsaken Trooper corpses.", progress = "Have you recovered the insignias?", completion = "I will see to it that these insignias are returned to the Undercity at once. The registrar will place their names in our records so that their sacrifice may never be forgotten." }
WordHunterWoW_QuestEN[27181] = { title = "Excising the Taint", description = "It looks like a group of the ambushers stayed behind. Make them pay for their insolence! Kill all of the Bloodfang stalkers at Olsen's Farthing. For Sylvanas! For the Horde!", objectives = "Kill 10 Bloodfang Stalkers.", progress = "You found the ambushers?", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYou have avenged the fallen, <name>, but there is more to be done." }
WordHunterWoW_QuestEN[27182] = { title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", objectives = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!" }
WordHunterWoW_QuestEN[27183] = { title = "Marsh Frog Legs", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", objectives = "Collect 10 Marsh Frog Legs from Giant Marsh Frogs.", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew." }
WordHunterWoW_QuestEN[27184] = { title = "Jarl Needs Eyes", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", objectives = "Collect 20 Unpopped Darkmist Eyes from Darkmist spiders.", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh." }
WordHunterWoW_QuestEN[27185] = { title = "Cutting the Competition", description = "Look, I'm not about t' play games with ye. The Scarlet Crusade's Crimson Hammersmith was nothin' worth mentionin' before, but now that they're Balnazzar's Risen, the damned dreadlord has taught him t' make all sorts of powerful demonic weaponry.\n\nIt's simple. Find their blacksmithing plans and kill the Risen Hammersmith when he comes for 'em, so that we can make sure their army doesn't get their hands on demon armaments. They're powerful enough as it is!", objectives = "Kill the Risen Hammersmith.", progress = "Are we back on top of the arms race?", completion = "Nicely done, lad! Without them new weapons, they're just as easy t' kill as they were when they were alive!" }
WordHunterWoW_QuestEN[27186] = { title = "Jarl Needs a Blade", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", objectives = "Obtain Razorspine's Sword.", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks." }
WordHunterWoW_QuestEN[27187] = { title = "Do the World a Favor", description = "Hyenas, on their best day, are a nuisance.\n\nThese foul specimens have a particularly nasty disposition, are riddled with all manner of disease, and are simply a blight on the face of dogdom.\n\nDo the world a favor and rid the deserts of Uldum of this mangy menace.", objectives = "Kill 12 Mangy Hyenas." }
WordHunterWoW_QuestEN[27188] = { title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", objectives = "Gather information by defeating 10 Risen Husks or Risen Spirits.", progress = "What have you learned from the spirits haunting this place?", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, <name>!" }
WordHunterWoW_QuestEN[27189] = { title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, {name}. It may be our only hope.", objectives = "Collect 9 sprigs of Witchbane near Witch Hill.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here." }
WordHunterWoW_QuestEN[27190] = { title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", objectives = "Plant the Witchbane Torch at the end of the dock and defeat the evil haunting Witch Hill.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, <name>. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily." }
WordHunterWoW_QuestEN[27191] = { title = "Hungry as an Ogre!", description = "You meet some people out here sometime. Nice people. Met an ogre once. Ogres get hungry just like me.\n\nI'll never forget what he said. He said \"Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you.\"\n\nSo I got him those fish and he ate 'em up. That's when I started too. The heads are the best part, all soggy-like.\n\nDon't crush those heads now. It makes them sad. Sad heads aren't good eating. Get me happy heads and I'll eat them and be happy too.", objectives = "Collect 8 Mirefin Heads from Mirefin Murlocs.", progress = "Jarl's hungry. Just like that ogre.", completion = "Wonder what it's like to be an ogre. Big people have to eat more.\n\nOgres must be even hungrier than me. That doesn't sound very fun." }
WordHunterWoW_QuestEN[27192] = { title = "The Great Ezra Grimm", description = "Men as far as Kul Tiras spoke of the legendary Ezra Grimm's premium tobacco. It was a delicacy enjoyed by every single person of importance that visited Stratholme. King Terenas, Uther the Lightbringer, Highlord Fordring...yes, they all enjoyed Grimm's specialty.\n\nSadly, Ezra stayed in his shop when Stratholme was invaded, swearing on his life that the Scourge would never touch his tobacco. Venture forth and see if even one bit remains here...it is worth its weight in gold, I assure you.", objectives = "Recover a box of Ezra Grimm's Premium Tobacco.", progress = "Did you find any?", completion = "Truly, you have uncovered the snuff of legends. It is nearly impossible to place a value on this historical tobacco.\n\nHere, have a few coins." }
WordHunterWoW_QuestEN[27193] = { title = "Seek and Destroy", description = "<The Banshee Queen's voice invades your thoughts once more.>\n\nSearch the nearby farmhouses for Alliance stragglers. Keep an eye out for any information that could lead us to Crowley and Bloodfang. Seek and destroy all that would stand in your way, {name}!", objectives = "Search the Farmhouses at Olsen's Farthing.", progress = "What is your status?", completion = "<The Banshee Queen's words float in your head.>\n\nThis book documents a recent meeting with Ivus Bloodfang. The location mentioned is the Deep Elem Mine. I know of this place. It has only one entrance.\n\nWe shall corner and crush them!" }
WordHunterWoW_QuestEN[27194] = { title = "Cornered and Crushed!", description = "<The Banshee Queen speaks through your mind.>\n\nWe must act quickly, {name}. They mustn't be given the chance to flee. I am dispatching a squadron of my most powerful troopers to the Deep Elem Mine. I'm also sending the Horseman with them to ensure that nothing goes wrong. Meet him at the Deep Elem Mine, east of Olsen's Farthing, and CRUSH those rats.", objectives = "Report to Master Forteski at the Deep Elem Mine in Silverpine Forest.", completion = "I 'spose we're to corner them first then crush, eh?" }
WordHunterWoW_QuestEN[27195] = { title = "Nowhere to Run", description = "The mistress has put me in charge of this lot. Our primary mission is to get in there, corner the rats, and kill 'em all, including Bloodfang.\n\nYou've done us a solid service in gettin' the information, {name}. Join in the glory and help us drive a sword through their miserable skulls!\n\nLet me know when you're ready and I'll call for the charge.", objectives = "Escort Master Forteski through the Deep Elem Mine.", completion = "WHAT!?\n\n<Sylvanas shrieks.>\n\nCROWLEY!!!!!\n\nBastards. Those were some of our strongest soldiers. I have underestimated Crowley and Bloodfang for the last time. Clearly they are an enemy the likes of which we have never seen - willing to sacrifice their own to set a trap like this... unheard of in Alliance warfare." }
WordHunterWoW_QuestEN[27196] = { title = "On to Something", description = "This is remarkable work you've done! Especially for someone who hasn't taken my courses.\n\nThese tablets provide new information on several subjects.\n\nThey indicate that these obelisks are part of an enormous ancient mechanism that once kept this whole region masked from the rest of the world.\n\nThey also depict how to recharge the mechanism, which is where your Shaft of the Stars comes in...\n\nGet ready, {name}. We have some history to make!", objectives = "Accompany Harrison Jones to the Chamber of the Stars.", progress = "Alright, now let's see what this staff can show us...", completion = "Would you get a load of this place!" }
WordHunterWoW_QuestEN[27197] = { title = "The Battle Resumes!", description = "Word is in from Andorhal, {name}.  The battle has resumed.\n\nIt has become somewhat well-known among the Alliance forces that you're a hero of the first battle of Andorhal.  Thassarian has requested your presence immediately.", objectives = "Report to Thassarian at Andorhal in Western Plaguelands.", completion = "Word has it that you helped those farmers arm themselves.  Well, now they've initiated the attack without my order!  They've forced my hand.\n\nThe battle has resumed.  This time, we fight the Forsaken... and I fight Koltira, my old brother of the Ebon Blade." }
WordHunterWoW_QuestEN[27198] = { title = "Supporting the Troops", description = "I'm no military expert, but this battle looks to be in our favor.  Our defenders are equally matched with their deathguards, but the farmers' militia has taken them by surprise from the rear.  For the Alliance!\n\nStill, we should all do what we can to make sure that we win.  Travel east into Andorhal and slay the Forsaken deathguards that are fighting with our men.  The sooner they die, the quicker we can re-take Andorhal!", objectives = "Slay 15 Andorhal Deathguards.", progress = "For the Alliance!", completion = "You fight well, <name>.  I wish I had your ability... and your bravery." }
WordHunterWoW_QuestEN[27199] = { title = "Ashes to Ashes", description = "To the east, deep within Forsaken-held Andorhal, you will find their commanders.  They do not fight, but call out orders from horseback.\n\nHunt down and slay these commanders, {name}.  The Forsaken won't stand a chance.", objectives = "Slay 3 Deathguard War-Captains.", progress = "You will find them to the east, <name>.  Do not fail me.", completion = "Well done.  With them out of the way, I have no more excuses.\n\nSoon, I must battle Koltira, for honor and for Andorhal." }
WordHunterWoW_QuestEN[27200] = { title = "Siren's Song", description = "She's still out there... Ophelia, the Siren of the Highlands! Her terrible song will lure you to the depths. I've vowed to stay behind and avenge my fallen crewmates, {class}. If you want to join me, just say the word.\n\nWe'll lash ourselves to the mast, we will. We'll shut our eyes. We'll stuff our ears with wax. And when her beautiful illusion drops... we'll strike.\n\nAre you in?", objectives = "Slay Ophelia, the Siren of the Highlands.", completion = "She had me under her spell, <name>. I wouldn't have made it out of there alive if it weren't for you. Thank you!\n\nMaybe the rest of the Alliance fleet can finally anchor here in peace..." }
WordHunterWoW_QuestEN[27201] = { title = "Val'kyr Incursion", description = "The val'kyr were one of the Scourge's primary weapons.  Not only were they skilled in battle, but they could be used to convert corpses into Scourge minions.  To think that Sylvanas is stooping to such levels for the sake of the Forsaken...\n\nWe need to stop the val'kyr before they wipe us out and turn our army against us.  Slay as many as you can find.  And bring some of these minutemen with you.  If they've survived this long, then they must have some battle skill.", objectives = "Kill 9 Lesser Val'kyr within Andorhal.", completion = "For every val'kyr you slay, you save dozens of our men... and prevent the Forsaken forces from growing.\n\nStill, they press on.  We may not win this battle after all." }
WordHunterWoW_QuestEN[27202] = { title = "Brother Against Brother", description = "Our militia has been nearly wiped out.  Only I and these few farmers remain.\n\nThose winged creatures... they took the bodies of our men and... and turned them into walking, undead corpses!  With every one of our men they took, they bolstered their own ranks.\n\nIt pains me to admit it, but you will need to fight them too, along with the deathguards and val'kyr.  As they did in life, they hunt in packs, so take some of my minutemen with you.", objectives = "Kill 20 Forsaken Troopers within Andorhal.", completion = "You fought valiantly, but we're getting nowhere.  Every body that falls just fuels their forces." }
WordHunterWoW_QuestEN[27203] = { title = "The Maelstrom", description = "Thank the spirits you're here, {name}.\n\nWe're not sure how much longer we can maintain the rift in the Maelstrom.\n\nOur most powerful members, led by Thrall, are barely preventing the tear.\n\nLast I heard, our only hope was to go through the breach and attempt to stabilize it from the other side.\n\nI will conjure a portal.  Take it and report to Thrall as soon as you can.", objectives = "Go through the Portal to the Maelstrom and speak to Thrall.", completion = "<Thrall's muscles strain as primal energy flows through him.  His eyes shift your way, acknowledging your arrival.>\n\nIt is good to see you, <name>." }
WordHunterWoW_QuestEN[27204] = { title = "Aradne", description = "Our last hope of victory lies in defeating the val'kyr.  You've done well up until now... but you're only one man and there are literally dozens of them raining destruction on the battlefield.\n\nOne enormous val'kyr sits atop the tower to our south... you can see her from here.  Perhaps if we eliminate her, the remaining val'kyr will dissipate.\n\nThis is our only hope.  Bring some of Grant's men with you.  You'll need their protection for this battle.", objectives = "Slay Aradne atop the tower in western Andorhal.", completion = "I watched your victory from below.  Well-fought, but ultimately, it was for naught.\n\nThe val'kyr and the Forsaken press on; soon, they will overtake us.  We have lost Andorhal." }
WordHunterWoW_QuestEN[27205] = { title = "The Depravity of the Forsaken", description = "We nearly have this battle won, {name}.  I can taste victory.  The Forsaken never stood a...\n\nWhat the hell is that!?", objectives = "Find out what Thassarian is looking at.", completion = "Val'kyr?  Koltira brought val'kyr to this fight?  Has he gone mad?\n\nNo, this is not Koltira's work.  This was Sylvanas." }
WordHunterWoW_QuestEN[27206] = { title = "Alas, Andorhal", description = "Head south, to Chillwind Camp.  Tell Commander Ashlam Valorfist everything that happened here.\n\nMe?  I'm going west, into Tirisfal.\n\nMy battle's not over yet.  I've got an appointment with that harpy that calls herself a Banshee Queen... and I'm finding out what she did to Koltira.", objectives = "Report the events of the battle of Andorhal to Commander Ashlam Valorfist.", completion = "Lost?  No... next, they'll be coming for Chillwind, I suppose.  This was a major strategic blow to the Alliance's plans for Lordaeron.\n\nVery well.  I will report the results of this battle to King Wrynn.  I don't expect him to be happy." }
WordHunterWoW_QuestEN[27207] = { title = "This Blows", description = "Is THAT what's behind the storms assailing my city?\n\nLet's push on. That towering windbag can bellow and blow all he likes, but this is the end of him. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", objectives = "Slay Prince Sarsarun and inform General Marcus Jonathan in Stormwind City.", completion = "A massive prince of the wind, you say? The herald of Al'Akir, the Windlord?\n\nMadness. All of it.\n\nStormwind is in your debt, hero." }
WordHunterWoW_QuestEN[27208] = { title = "The Dreadlord Balnazzar", description = "With the fall of the Scarlet Crusade, their disguised demon leader, Balnazzar, released the possessed body of Grand Crusader Dathrohan and went on a rampage, killing every remaining crusader here. He then used his necromantic power to raise them all as vile undead slaves.\n\nBalnazzar refers to his new army as the Risen. We cannot let him grow this army - they are extremely powerful and, unlike Arthas' Scourge, Balnazzar will not hold his forces back. Kill him while we still have a chance, {class}.", objectives = "Kill Balnazzar.", progress = "The Light commands you.", completion = "It's good we stopped Balnazzar now. Before long, his army would have overtaken all of Stratholme, giving him a powerful center for his new unholy empire." }
WordHunterWoW_QuestEN[27209] = { title = "This Blows", description = "So. This is what evil lies behind the attacks on fair Thunder Bluff.\n\nLet us move forward. It is time to put an end to this abomination.\n\nTell Hamuul Runetotem what has happened here upon our return; I'll need to oversee the return of my people, repairs, and the like.", objectives = "Slay Prince Sarsarun and inform Hamuul Runetotem in Thunder Bluff.", completion = "A massive prince of the wind, you say? The herald of Al'Akir, the Windlord?\n\nMadness. All of it.\n\nAll of Thunder Bluff is in your debt, <class>." }
WordHunterWoW_QuestEN[27210] = { title = "Traitors Among Us", description = "It's good to meet you, {class}. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", objectives = "Confront 5 Deserter Agitators in Theramore.", completion = "Well done, <name>. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further." }
WordHunterWoW_QuestEN[27211] = { title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", objectives = "Obtain the Deserter Propaganda from the boat at the end of the Theramore docks.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it." }
WordHunterWoW_QuestEN[27212] = { title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", objectives = "Distribute the Altered Leaflets to 6 Theramore Guards.", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!" }
WordHunterWoW_QuestEN[27213] = { title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", objectives = "Defeat Gavis Greyshield aboard the ship southeast of Theramore.", progress = "Have you completed your assault on the deserter base?", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, <name>. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the <class> who ended the deserter threat." }
WordHunterWoW_QuestEN[27214] = { title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", objectives = "Report to Captain Wymor at Sentry Point.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, <name>." }
WordHunterWoW_QuestEN[27215] = { title = "The Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", objectives = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?" }
WordHunterWoW_QuestEN[27216] = { title = "This Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", objectives = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit." }
WordHunterWoW_QuestEN[27217] = { title = "Thresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", objectives = "Collect 4 containers of Thresher Oil from Murk Threshers beneath the Theramore docks.", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp." }
WordHunterWoW_QuestEN[27218] = { title = "Dastardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", objectives = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know." }
WordHunterWoW_QuestEN[27219] = { title = "Is it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", objectives = "Talk to Nat Pagle at Nat's Landing in Dustwallow Marsh.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part." }
WordHunterWoW_QuestEN[27220] = { title = "Nat's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim into the deep part of Tidefury Cove to the southwest. Let me know how it works!", objectives = "Smear Pagle's Fish Paste, Extra Strength on yourself, then swim into Tidefury Cove.", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime." }
WordHunterWoW_QuestEN[27221] = { title = "Oh, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", objectives = "Speak with Major Mills at the docks in Theramore.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations." }
WordHunterWoW_QuestEN[27222] = { title = "Take Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", objectives = "Use the mortars to defeat Tethyr.", completion = "Well done, <name>! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!" }
WordHunterWoW_QuestEN[27223] = { title = "Retribution", description = "Where Market Row meets Festival Lane, you will encounter The Unforgiven. If you slay the entirety of Crusaders' Square, you will coax out Timmy the Cruel. Both of these former champions committed heinous acts against innocents here in the name of gaining unholy power.\n\nYou must destroy both of them and rid Stratholme of their foul presence. Take caution, for they were powerful fighters in life, and their new dark powers will only have made them even more deadly. ", objectives = "Kill The Unforgiven and Timmy the Cruel.", progress = "Show them no mercy.", completion = "You may have this as a suitable reward. I found it nestled in the armor of one of the scourge here." }
WordHunterWoW_QuestEN[27224] = { title = "Andorhal Phase Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[27225] = { title = "A Summons from Signilda Hardforge", description = "Signilda Hardforge has sent word that she wishes to honor you for your mastery of arms and your dedication to the Alliance. Make your way to Stormwind, and speak with her at the Training Hall to the south of Old Town. I do not know what she has planned, but it sounds like she has been impressed with your rapid progress.", objectives = "Speak to Signilda Hardforge at the Training Hall in Stormwind.", completion = "It's good to see that you received my message. I have something important I wish to discuss with you." }
WordHunterWoW_QuestEN[27226] = { title = "Hair of the Dog", description = "Thank the Warchief that you're here, {name}. I've made a critical error with the sea dogs and need your help to rectify the situation.\n\nYou see, I sent them out against the worgen coming from Fenris Isle stone cold sober. They attacked the beasts and promptly got their butts handed to them. Many of them died, but a few still live, barely clinging on to dear life.\n\nTake this barrel of ale to the Decrepit Fields, east of here, and force it down the throats of fallen sea dogs.", objectives = "Rouse 8 Orc Sea Dogs.", completion = "A-HA! I knew it! Lesson learned, I suppose. We will not fail again. I will be sure to have some ale on hand at the front lines." }
WordHunterWoW_QuestEN[27227] = { title = "Lord Aurius Rivendare", description = "This Chapel is the last Light amongst so much darkness. Ras Frostwhisper took his own life in the slaughterhouse, carving his face into a macabre smile in front of the Lich King, who raised him into the Lich that now haunts Scholomance.\n\nThe ground where that atrocity occured is now Scourge holy ground, blessed by the Lich King with the very darkest magic. Lord Aurius Rivendare, new ruler of Stratholme, now guards it and continues his master's evil work. Slay him without pause.", objectives = "Kill Lord Aurius Rivendare.", progress = "Don't waste our time. Every second spend chatting away is a second we aren't taking Stratholme back for the Light.", completion = "Stratholme will become a paragon of all that is good in this world. You have my thanks for your part in this mission." }
WordHunterWoW_QuestEN[27228] = { title = "Man Against Abomination", description = "Deep within, you will find Ramstein the Gorger. I cannot bear to tell you the atrocities this monster has commited. Know only this - he deserves to feel the full wrath of countless lost souls, a wrath you will bring upon him.\n\nHave no mercy. Be unwavering in your fury.", objectives = "Slaughter Ramstein the Gorger.", completion = "I respect the power you demonstrated in killing Ramstein. With proper rage backing your actions, I think even the Scourge can know fear." }
WordHunterWoW_QuestEN[27229] = { title = "SMASH BROODQUEEN", description = "<The following is written in very large print.>\n\nSPIDERS IN NORTH CAVE BAD. POISON OGRES. OGRES GET SICK. BAD!\n\nBIG BIG SPIDER IN CAVE MAKE MORE SPIDERS. MORE SPIDERS BAD!\n\nKILL BIG SPIDER, STOP MORE SPIDERS. KILL BIG SPIDER, GET BIG PRIZE! GOOD!\n\n<A crude drawing accompanies this.>", objectives = "Obtain the Broodqueen Pedipalp.", progress = "Are you here about the sign?\n\nI don't want to talk about it unless you've got proof of a kill.", completion = "By Grom, I'm glad that's over with. If you read that sign you may have some idea how desperate I got after trying to communicate to these lumbering oafs." }
WordHunterWoW_QuestEN[27230] = { title = "Weapons for War", description = "The Scourge are adept at forging powerful armaments for their soldiers, making it difficult for our men to kill 'em! There are blacksmithing plans near the Baroness Anastari's ziggurat that their chief swordsmith plans to use for an extremely powerful weapon for Lord Aurius.\n\nWe're going to prevent that weapon from being made and stop their regular arms flow with one blow! Go take the plans and kill the Black Guard Swordsmith when he comes to defend 'em, and it'll make our mission much easier.", objectives = "Kill the Black Guard Swordsmith.", progress = "You need to kill their swordsmith! Go!", completion = "Great! Without a steady flow of their weapons, we'll win through attrition!" }
WordHunterWoW_QuestEN[27231] = { title = "Reinforcements from Fenris", description = "Those that survived your assault on Fenris managed to drink the blood of the wolf. They turned into ferocious worgen, hell-bent on vengeance. Now they paddle across Lordamere Lake and assault my sea dogs. Many have already been killed. The worgen monsters must be stopped!\n\nMake your way to the Decrepit Fields, east of here, and kill the Hillsbrad worgen that infest the area. Once you've killed them all, make your way to the Horde communication panel, located at the docks. I'll be in touch.", objectives = "Kill 10 Hillsbrad Worgen.", progress = "Report?", completion = "<Hatchet's communication device crackles.>\n\nHatchet here, are they all dead?" }
WordHunterWoW_QuestEN[27232] = { title = "The Waters Run Red...", description = "<The communication console hums.>\n\nThose worgen you killed were the scouting party. There are hundreds more incoming! Looks like Crowley and Bloodfang made the blood offering to every human in Lordaeron.\n\nGet in one of those Horde cannons and send them all back to their makers. Let the waters of Lordamere Lake run red with their blood!", objectives = "Kill 50 Hillsbrad Worgen with the Horde Cannon.", completion = "Though you killed a large number of the newly turned worgen, many more are sure to appear. Still, their assault will have softened. Well done, <name>!" }
WordHunterWoW_QuestEN[27233] = { title = "The Menders' Stead", description = "I can handle training from here.  If you're looking for something else to do, I recommend heading up the road to the northwest.  The Cenarion druids and Argent Crusade have a small camp set up there, at Dalson's old farm.  Maybe they can keep you busy until we need your help again.", objectives = "Report to Field Agent Kaartish at the Menders' Stead in Western Plaguelands.", completion = "Welcome, <class>.  As you can see, our camp is a joint expedition between Argent Crusade members and Cenarion Circle druids, but we welcome all who wish to help heal the land." }
WordHunterWoW_QuestEN[27234] = { title = "Defias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas... the symbol of the Defias!\n\nThe reports indicate their leader resides on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", objectives = "Obtain the Defias Orders from Garn Mathers.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron." }
WordHunterWoW_QuestEN[27235] = { title = "Renn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", objectives = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", progress = "Well met, <class>. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo." }
WordHunterWoW_QuestEN[27236] = { title = "Secondhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", objectives = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work." }
WordHunterWoW_QuestEN[27237] = { title = "Recover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", objectives = "Collect 1 Salvaged Strongbox.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here...." }
WordHunterWoW_QuestEN[27238] = { title = "Jaina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, {name}. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", objectives = "Speak with Lady Jaina Proudmoore in Theramore.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. Now, we must confirm your findings. The implications are too great if we are wrong." }
WordHunterWoW_QuestEN[27239] = { title = "Survey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the mystery of the Defias' involvement in this kidnapping.", objectives = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island.", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias have allied themselves with HER? The traitor?\n\n<Lady Jaina composes herself and prepares to explain.>" }
WordHunterWoW_QuestEN[27240] = { title = "Proof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to Grand Admiral Jes-Tereth in Stormwind castle that the Defias are the ones who carried out the Varian's kidnapping. I have little doubt that Stormwind's armies will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", objectives = "Speak with Jaina to travel to Stormwind and meet with Grand Admiral Jes-Tereth.", completion = "So it was the Defias who served as the hands of Onyxia in this plot?\n\n<The admirall's face grows red with anger and her hands clench into fists.>\n\nYou and Lady Jaina have done Stormwind a great service this day. The traitors will not live long enough to regret their crimes." }
WordHunterWoW_QuestEN[27241] = { title = "Return to Jaina", description = "We must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", objectives = "Return to Lady Jaina Proudmoore in Theramore.", completion = "I have no doubt that the king meant every word when he told you he plans to destroy the Defias once and for all. He does not make promises lightly, and the enemies of Stormwind should know it." }
WordHunterWoW_QuestEN[27242] = { title = "Raptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture Bloodfen raptors or Bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", objectives = "Use the Sturdy Rope to capture 6 Bloodfen Raptors or Bloodfen Screechers.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them." }
WordHunterWoW_QuestEN[27243] = { title = "Unleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", objectives = "Place the Raptor Bait near the windmill in Blackhoof Village.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two." }
WordHunterWoW_QuestEN[27244] = { title = "The Lost Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", objectives = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, <name>.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp..." }
WordHunterWoW_QuestEN[27245] = { title = "Prisoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, {class}, just bring back my men alive.", objectives = "Collect Grimtotem Keys from the Grimtotem Tauren in Blackhoof Village and use them to free 5 Theramore Prisoners.", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men." }
WordHunterWoW_QuestEN[27246] = { title = "The Orc Report", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", objectives = "Bring the Spy's Report to Lieutenant Aden in Theramore.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!" }
WordHunterWoW_QuestEN[27247] = { title = "Captain Vimes", description = "Captain Vimes should see the orc report you found, {name}.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", objectives = "Bring the Spy's Report to Captain Garran Vimes.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says..." }
WordHunterWoW_QuestEN[27248] = { title = "Mission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!" }
WordHunterWoW_QuestEN[27249] = { title = "Inspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the monsters who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", objectives = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates." }
WordHunterWoW_QuestEN[27250] = { title = "REUSE - BAD COPY", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?Upon completion of this quest you will gain:", objectives = "Speak with Vincent Hyal in Menethil Harbor.Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[27251] = { title = "They Call Him Smiling Jim", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", objectives = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble." }
WordHunterWoW_QuestEN[27252] = { title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", objectives = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn." }
WordHunterWoW_QuestEN[27253] = { title = "Inspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. I had a man placed in that inn as a spy and I don't trust in the competence of these humans to uncover what happened.\n\nWhatever you find, don't give a scrap of it to that investigator. We'll handle this ourselves.", objectives = "Investigate the Shady Rest Inn in at the border of the Barrens in Dustwallow Marsh.", completion = "<The inspector regards you with what can only be disdain and distrust.>\n\nLeave this place be, errand boy, or I'll be sure to bring a contingent of guard with me next time to sink the lesson home." }
WordHunterWoW_QuestEN[27254] = { title = "The Black Shield", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", objectives = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", progress = "What's that you have there, <name>? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?" }
WordHunterWoW_QuestEN[27255] = { title = "The Black Shield", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", objectives = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", progress = "Something for me, <class>?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, <name>.\n\nYou should know that." }
WordHunterWoW_QuestEN[27256] = { title = "The Black Shield", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", objectives = "Collect 5 Acidic Venom Sacs from Darkmist spiders.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, <name>. Now I rip them open and pour them onto the shield..." }
WordHunterWoW_QuestEN[27257] = { title = "The Black Shield", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", objectives = "Speak with Krog in Brackenwall Village.", completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything..." }
WordHunterWoW_QuestEN[27258] = { title = "The Black Shield", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", objectives = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", progress = "Hello there, <class>. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, <name>. I craft so many different shields and sets of armor, I can't keep track of them all." }
WordHunterWoW_QuestEN[27259] = { title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead." }
WordHunterWoW_QuestEN[27260] = { title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", objectives = "Bring Reethe's Badge to Krog in Brackenwall Village.", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "Hmm... now this is interesting." }
WordHunterWoW_QuestEN[27261] = { title = "Questioning Reethe", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", objectives = "Go with Ogron to speak with Reethe.", completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere." }
WordHunterWoW_QuestEN[27262] = { title = "Suspicious Hoofprints", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", objectives = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead." }
WordHunterWoW_QuestEN[27263] = { title = "Lieutenant Paval Reethe", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", objectives = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that." }
WordHunterWoW_QuestEN[27264] = { title = "Lieutenant Paval Reethe", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", objectives = "Find out more about Reethe from Adjutant Tesoran in Theramore.", completion = "Hello, <name>. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book." }
WordHunterWoW_QuestEN[27265] = { title = "Ezul'aan Calls", description = "Ezul'aan, one of the foremost paladins in the realm, has asked to speak with you personally. I do not know what he has planned, but it sounds like he has been impressed with your rapid progress.\n\nYou should make your way to Stormwind immediately and meet him at the Training Hall in the Old Town district.", objectives = "Speak to Ezul'aan at the Training Hall in Stormwind.", completion = "It heartens me to see that my message found you, <name>. We have much to discuss." }
WordHunterWoW_QuestEN[27266] = { title = "Dalgrun Calls", description = "Dalgrun Steelpine oversees the training and coordination of hunters in the service of Stormwind. He has asked to speak to you personally. As soon as you are able, travel to Stormwind and meet with Dalgrun at the Training Hall in Old Town.\n\nI have no idea what he has planned, but it sounds like he has been impressed with your rapid progress.", objectives = "Speak to Dalgrun Steelpine in Stormwind.", completion = "Ah, you've arrived. Make yourself at home, <name>. We have much to discuss." }
WordHunterWoW_QuestEN[27267] = { title = "Make Contact with SI:7", description = "It seems that the leaders of SI:7 have taken an interest in your progress and your service to the Alliance. Veruca Darkstream, a high ranking member of SI:7, has asked to speak with you. Veruca is awaiting your arrival at the Training Hall in Stormwind.\n\nI'm not sure what she wants with you, but it seemed important.", objectives = "Speak with Veruca Darkstream at the Training Hall in Stormwind.", completion = "I hope my message didn't unnerve you, <name>. I have called you here to recognize your accomplishments." }
WordHunterWoW_QuestEN[27268] = { title = "Patrice Lancaster Sends Word", description = "I have an urgent message for you from Stormwind, {name}. It seems that Speak to Patrice Lancaster has asked to speak with you at the Training Hall in Stormwind's Old Town district. The messenger did not say what the matter concerned, but that you should travel to Stormwind with all haste.", objectives = "Speak to Patrice Lancaster at the Training Hall in Stormwind.", completion = "It heartens me to see that you received my message and responded so quickly." }
WordHunterWoW_QuestEN[27269] = { title = "The Temple of the Moon", description = "I have an urgent message for you from Darnassus. The message is from the High Priestess of Elune, Tyrande Whisperwind, herself! The messenger did not say what the matter concerned, but that you should travel to the Temple of the Moon in Darnassus and meet with the high priestess at once.", objectives = "Speak to Tyrande Whisperwind at the Temple of the Moon in Darnassus.", completion = "Welcome to the Temple of the Moon, <name>. I am glad that you chose to answer my summons so quickly." }
WordHunterWoW_QuestEN[27270] = { title = "An Audience with Mulric", description = "I have an urgent message for you from Stormwind, {name}. It seems Mulric Boldrock has asked to speak with you the next time you're in the city.\n\nThe messenger gave no explanation for the shaman's invitation, but you should travel to Stormwind and find Mulric Boldrock at the Training Hall to the south of Old Town as soon as you can.", objectives = "Speak with Mulric Boldrock at the Training Hall in Stormwind.", completion = "Welcome, <name>. I am glad that you decided to accept my invitation." }
WordHunterWoW_QuestEN[27271] = { title = "Frazzle's Request", description = "I just received a message from Stormwind, {name}. One of Stormwind's most renowned mages, Frazzle Frostfingers, has requested that you visit him at the Training Hall in Stormwind. The Training Hall is located in the Old Town district of Stormwind.\n\nI do not know what he has planned, but it sounds like he has been impressed with your rapid progress.", objectives = "Speak with Frazzle Frostfingers at the Training Hall in Stormwind.", completion = "Welcome to the Wizard's Sanctum, <name>. I have been watching your progress with interest." }
WordHunterWoW_QuestEN[27272] = { title = "A Message From Evelyn Thorn", description = "It seems that the elders in our ranks have taken notice of your progress and dedication, {name}. Evelyn Thorn, one of the oldest and most respected members of our circle, has sent word that she wishes to speak with you. You should not take such an invitation lightly. Most only speak with her in the course of their lessons, but if she has asked to see you personally, it must be an important matter.\n\nHurry back to Stormwind and look for her at the Training Hall to the south of the Old Town district.", objectives = "Speak with Evelyn Thorn at the Training Hall in Stormwind.", completion = "I see that my message managed to reach you. Good. We have much to discuss." }
WordHunterWoW_QuestEN[27273] = { title = "An Invitation from Moonglade", description = "You just missed the messenger from Moonglade, {name}. He said little, except that he carried an urgent message from Loganaar, one of the honored trainers of the Cenarion Circle. Head to Moonglade as quickly as you can, {name}. The matter sounds important.\n\nLook for Loganaar in the village of Nighthaven.", objectives = "Speak to Loganaar at Nighthaven in Moonglade.", completion = "I'm glad to see that you have arrived safely in Nighthaven, <name>. I offer you the welcome and the hospitality of the Cenarion Circle." }
WordHunterWoW_QuestEN[27274] = { title = "Patrice Lancaster Sends Word", description = "I have an urgent message for you from Stormwind, {name}. Patrice Lancaster has asked to meet with you in Stormwind. The message didn't say what the priest trainer wanted to discuss, but you should make your way to Stormwind as quickly as you can. Look for Patrice Lancaster at the Training Hall in the Old Town district of the city.", objectives = "Speak to Patrice Lancaster at the Training Hall in Stormwind.", completion = "I see that you received my message. Excellent!" }
WordHunterWoW_QuestEN[27275] = { title = "Together Again", description = "We saw to it that the sentinel was healed and re-equipped. I already sent her back into the field.\n\nHead back up and go to Darkcloud Pinnacle. She'll meet you there.", objectives = "Speak with the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", completion = "Good to see you again, <name>. Let us put the fear of the Goddess into the Grimtotem." }
WordHunterWoW_QuestEN[27276] = { title = "Together Again", description = "We saw to it that the brave was healed and re-equipped. I already sent him back into the field.\n\nHead back up and go to Darkcloud Pinnacle. He'll meet you there.", objectives = "Speak with the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", completion = "I am honored by your presence, <name>. Let us put the fear of the Earth Mother into the Grimtotem." }
WordHunterWoW_QuestEN[27277] = { title = "An Audience with Feenix Arcshine", description = "I've received an urgent message from Orgrimmar for you, {name}. The renowned mage, Feenix Arcshine, wants you to meet with him in Orgrimmar. I'm not sure what this is about, but if I was you, I would travel to the capital as fast as possible and seek out Feenix Arcshine at The Barracks in the Valley of Honor.", objectives = "Speak with Feenix Arcshine at The Barracks in Orgrimmar.", completion = "Ah, good. It seems my message did find you." }
WordHunterWoW_QuestEN[27278] = { title = "Tamanji's Call", description = "A courier from Orgrimmar just delivered a message for you. I'm to tell you that Tamanji, master of the hunters in Orgrimmar, has asked to meet with you.\n\nTravel quickly to Orgrimmar and present yourself to Tamanji at The Barracks in the Valley of Honor.", objectives = "Speak with Tamanji at The Barracks in Orgrimmar.", completion = "Good, you're here. Let's get started." }
WordHunterWoW_QuestEN[27279] = { title = "The Shattered Hand", description = "A messenger just arrived from Orgrimmar bearing a communication for you. Thega Graveblade, the senior rogue trainer in Orgrimmar, has sent for you. You must head to Orgrimmar immediately and meet with her at The Barracks in the Valley of Honor.\n\nWhen Thega Graveblade summons you, the prudent thing to do is obey. Do not keep her waiting, {name}.", objectives = "Speak with Thega Graveblade at The Barracks in Orgrimmar.", completion = "Now that you are here, we can begin." }
WordHunterWoW_QuestEN[27280] = { title = "The Riverspeaker Calls", description = "News travels upon the winds, young shaman. Your deeds have not gone unnoticed! It seems Hretar Riverspeaker wishes to discuss something with you. Make your way to Orgrimmar as quickly as you can and speak with him at The Barracks in the Valley of Honor. He will be among the others who offer training.", objectives = "Speak with Hretar Riverspeaker at The Barracks in Orgrimmar.", completion = "I see you are both obedient and talented, <name>. Stay that way, and you will go far in the Horde." }
WordHunterWoW_QuestEN[27281] = { title = "Gormok Ogrefist", description = "I just received word that you are needed in Orgrimmar, {name}. Gormok Ogrefist, the honored trainer of warriors in the city, has sent for you. It would not be wise to ignore such a summons.\n\nTravel quickly to Orgrimmar and visit The Barracks in the Valley of Honor where Gormok awaits your arrival.", objectives = "Speak with Gormok Ogrefist at The Barracks in Orgrimmar.", completion = "I see you are both obedient and talented, <name>. Stay that way, and you will go far in the Horde." }
WordHunterWoW_QuestEN[27282] = { title = "Kazak's Behest", description = "{name}, I have received word that you are needed back in Orgrimmar. Kazak Darkscream, one of the senior warlock trainers, has something important that he wishes to discuss with you. It seems like the kind of thing that cannot wait.\n\nMake your way back to Orgrimmar and speak with him as soon as you can. You will find him at the Training Hall in the Valley of Honor.", objectives = "Speak with Kazak Darkscream at The Barracks in Orgrimmar.", completion = "Ah, you're here at last." }
WordHunterWoW_QuestEN[27283] = { title = "A Journey to Moonglade", description = "As you have heard, Moonglade is the home of the Cenarion Circle, the brotherhood of druids. All who dwell there do so in the peace of Cenarius. It is in that spirit that the trainer Loganaar has extended an invitation to visit him in Moonglade.\n\nYou will find him in the village of Nighthaven.", objectives = "Speak with Loganaar in Nighthaven.", completion = "Welcome to Moonglade, <name>. I have been looking forward to meeting you." }
WordHunterWoW_QuestEN[27284] = { title = "The Black Shield", description = "I'm sorry I can't be of much help, {name}, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", objectives = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work." }
WordHunterWoW_QuestEN[27285] = { title = "The Black Shield", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", objectives = "Speak with Captain Garran Vimes in Theramore.", completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened." }
WordHunterWoW_QuestEN[27286] = { title = "Daelin's Men", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", objectives = "Return the information about Reethe to Captain Garran Vimes in Theramore.", completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance." }
WordHunterWoW_QuestEN[27287] = { title = "The Deserters", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, {name}. He may be a tough nut to crack.", objectives = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", completion = "Did Vimes send you? Couldn't do his dirty work himself, could he..." }
WordHunterWoW_QuestEN[27288] = { title = "The Deserters", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", objectives = "Speak with Captain Garran Vimes in Theramore about Reethe.", completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him." }
WordHunterWoW_QuestEN[27289] = { title = "Vimes's Report", description = "You've done some good work, {name}, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.", objectives = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore." }
WordHunterWoW_QuestEN[27290] = { title = "To Forsaken Forward Command", description = "The time has come to destroy Crowley, Bloodfang and every dog at their command. To do this, though, will require cunning and planning the likes of which they would never dare dream!\n\nAs one of my most trusted soldiers, {name}, I need you to go to Forsaken Forward Command, located in Gilneas, and report to Deathstalker Commander Belmont. I have sent Belmont ahead with my plans. He awaits your arrival.\n\nArthura will escort you to Forward Command. Tell me when you are ready and I will send you on your way.", objectives = "Report to Deathstalker Commander Belmont at Forsaken Forward Command in Gilneas.", completion = "Well if it isn't Seamannub!\n\nI hope you're ready for battle, because that's all you'll find in this hellhole. We're at the heart of contested territory and these worgen mongrels won't give an inch!" }
WordHunterWoW_QuestEN[27291] = { title = "Peace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the stones in the graveyard just north of Theramore's gates.", objectives = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand." }
WordHunterWoW_QuestEN[27292] = { title = "Return to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", objectives = "Speak with Krog at Brackenwall Village.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects." }
WordHunterWoW_QuestEN[27293] = { title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", objectives = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. We knew nothing of these plans and we lost a good man because of it. I don't trust that we're not next on their list." }
WordHunterWoW_QuestEN[27294] = { title = "More than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm led to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", objectives = "Collect 7 Blackhoof Armaments from Blackhoof Village.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems." }
WordHunterWoW_QuestEN[27295] = { title = "Seek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", objectives = "Speak with Tabetha at her farm in the Quagmire.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students." }
WordHunterWoW_QuestEN[27296] = { title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", objectives = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. If I know him, he'll appreciate the taste of vengeance." }
WordHunterWoW_QuestEN[27297] = { title = "Justice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh, though I get the impression you probably don't mind that. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nGo tell your leader that his vengeance has been sated.", objectives = "Return to Krog at Brackenwall Village.", completion = "<Krog listens to your report.>\n\nI'm impressed, <name>. I would've thought that the Grimtotem criminals would've been more difficult to locate. The Alliance are truly incompetent.\n\nIn truth, I just sought to answer the death of one of my men, but this situation has been more fortunate than expected. If the Grimtotem choose to retaliate, it will likely be against the Alliance. Perhaps we will soon have the manpower to drive the scum from these shores once and for all." }
WordHunterWoW_QuestEN[27298] = { title = "Seek Out Avaros Dawnglaive", description = "Avaros Dawnglaive, a senior Blood Knight and advisor to the warchief, requires your presence in Orgrimmar. He has taken an interest in your training, {name}, and it is imperative that you speak with him immediately.\n\nThe message I received didn't mention the reason he requested your visit, but you should set out for Orgrimmar right away. Avaros Dawnglaive can be found at The Barracks in the Valley of Honor.", objectives = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", completion = "I've heard much about you, <name>. You have a bright future ahead of you in the Horde." }
WordHunterWoW_QuestEN[27299] = { title = "Torn Ground", description = "It won't be takin' much convincin' to turn us against da Twilight - dat's already our goal. We've already come to battle here though, so we may be needin' ya help before we can turn towards dere fortress.\n\nDa Twilight have already brought Iso'rath up from da ground to the south, I'm sure ya noticed. Its tentacles have been burstin' from da ground all around us. We could use a hand beatin' them down if you be willin'.", objectives = "Kill 3 Tentacles of Iso'rath.", progress = "Did ya have any luck with dose tentacles?", completion = "Tank ya, <class>. A bit of breathin' room helps a lot." }
WordHunterWoW_QuestEN[27300] = { title = "Pushing Back", description = "Da Twilight's Hammer have destroyed a Dragonmaw town to the south and are performin' dey're summonin' rituals from there. Offer dem no respite to continue wit dey're incantations. Bring tha battle to dem!", objectives = "Kill 12 Twilight's Hammer at the Ruins of Drakgor.", completion = "Revenge is bittersweet, but I'm glad we be havin' someone as powerful as you do see dis done." }
WordHunterWoW_QuestEN[27301] = { title = "Unbroken", description = "We are preparing a ritual that may be of use in destroying Iso'rath, the old god bred abomination that the Twilight's Hammer have brought up from the depths. We are delayed though, for one of our strongest was captured during an assault on their encampment.\n\nEarthcaller Yevaa is within the ruins to the south. She is not dead. I am sure of it. Please, rescue her. If any of us is deserving of your aid, it is her.", objectives = "Find Earthcaller Yevaa within the Ruins of Drakgor.", completion = "Thank the elements that you've come. Did my brothers send you?" }
WordHunterWoW_QuestEN[27302] = { title = "Simple Solutions", description = "I'm new to this gig. Very new. But ya know what? That gives me perspective!\n\nThese shaman buddies of mine have come upon somethin' great, but they're too single minded! They lean on the elements and they forget to make use of the common materials all around them.\n\nIn the ruins to the south, I saw those Twilight goons tote in barrels of flammable oil! They used it when they razed the town. I say we use it when we raze them.", objectives = "Gather 10 barrels of Pyreburn Oil.", progress = "I wonder what happens when you douse an elemental with that stuff. Jumbo-super-bonfire-elemental? I'm thinkin' so. We'll have to try.", completion = "Now that's what I'm talkin' about! Can you think of all the uses for this stuff? I definitely can't. But I can think of a lot, and I'm liking the possibilities." }
WordHunterWoW_QuestEN[27303] = { title = "Mercy for the Bound", description = "It goes without saying that I had no desire to stay here, but there were materials we needed for the ritual... I delayed to secure them, and that is what lead to my capture.\n\nI will return to the circle, but I would be indebted to you if you would finish what I could not. We need hearts from the bound fire elementals that the Twilight's Hammer enslave in the western portion of the encampment.\n\nThe elementals are without hope, but in this sacrifice they can extract their revenge.\n\nFind me at camp.", objectives = "Gather 5 Fleshburner Hearts.", progress = "Did you recover the hearts?", completion = "Thank you, <name>. You are quite capable. I'm extremely grateful that you've chosen to aid us." }
WordHunterWoW_QuestEN[27304] = { title = "Meet With Avaros Dawnglaive", description = "Avaros Dawnglaive sends word from Orgrimmar -- he wishes to speak with you when you're in the city. I needn't remind you that Avaros is an honored member of our order and his requests should not be ignored.\n\nNext time you are in Orgrimmar, travel to The Barracks in the Valley of Honor and speak with him.", objectives = "Speak with Avaros Dawnglaive at The Barracks in Orgrimmar.", completion = "I've heard much of your contributions to the Horde, <name>." }
WordHunterWoW_QuestEN[27305] = { title = "Of Love and Family", description = "Inside the Scarlet Bastion is a painting of great personal value to Highlord Tirion Fordring. Search for a painting of our twin moons. Chip away at the paint until you uncover the master work, 'Of Love and Family.'\n\nMay the Light guide your actions, and please handle the painting with the utmost care.", objectives = "Find 'Of Love and Family.'", progress = "The painting, <name>. Do you have the painting?", completion = "Master Fordring will be glad beyond measure to see this painting again." }
WordHunterWoW_QuestEN[27306] = { title = "Talk to Ogron", description = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast.", objectives = "Find Ogron to the southeast of Brackenwall Village.", completion = "Ogron? Yeah, that me.\n\nShh. Keep voice down. Crocs hear you." }
WordHunterWoW_QuestEN[27307] = { title = "The Elements Cry Out", description = "Do you feel it, <class>?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest.  Thus far we have been unsuccessful and now turn to others that may aid us.  Speak with Erunak Stonespeaker in Stormwind and see how you might be able to aid us.", objectives = "Speak with Erunak Stonespeaker in Stormwind.Do you feel it, <class>?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest. Thus far we have been unsuccessful and now turn to others that may aid us. Speak with Erunak Stonespeaker in Stormwind and see how you might be able to aid us.", completion = "I'm glad you've come, <class>.  These are troublesome times and we could use all the help we can get." }
WordHunterWoW_QuestEN[27308] = { title = "The Elements Cry Out", description = "Do you feel it, <class>?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest.  Thus far we have been unsuccessful and now turn to others that may aid us.  Speak with Earthmender Norsala in Orgrimmar and see what tasks she may have for you.", objectives = "Speak to Earthmender Norsala in Orgrimmar.Do you feel it, <class>?  The elements are uneasy. We members of the Earthen Ring have struggled to find the cause of the unrest. Thus far we have been unsuccessful and now turn to others that may aid us. Speak with Earthmender Norsala in Orgrimmar and see what tasks she may have for you.", completion = "I'm glad you've come, <class>.  These are troublesome times and we could use all the help we can get." }
WordHunterWoW_QuestEN[27309] = { title = "The Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them to form the full Grimtotem Battle Plan." }
WordHunterWoW_QuestEN[27310] = { title = "No Weapons For You!", description = "Alright, these cowards want to fight? Let's see how well they do without any weapons.\n\nI'm sure you must have a torch, or something. Burn their weapon racks.\n\nBurn them all!", objectives = "Burn 8 Grimtotem Weapon Racks.", completion = "Let's see them wage their war now!" }
WordHunterWoW_QuestEN[27311] = { title = "No Weapons For You!", description = "The Grimtotem want to fight? Let us see how well they do without their weapons.\n\nI'm sure you must have something that burns. Set their weapon racks ablaze, my {class} friend.\n\nLet nature take its course.", objectives = "Burn 8 Grimtotem Weapon Racks.", progress = "We shall have to burn more of their weapon racks than that if we are to put a dent in their ability to fight.", completion = "Let us see how well they fight without their weapons." }
WordHunterWoW_QuestEN[27312] = { title = "Darkcloud Grimtotem", description = "There's no way around it. If you want to win a battle, you have to spill some blood. In this case... a lot of it.\n\nYou know what we have to do.", objectives = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", completion = "That put a dent in their numbers! Can't say that they didn't deserve it." }
WordHunterWoW_QuestEN[27313] = { title = "Darkcloud Grimtotem", description = "There is no alternative: if you intend to win a battle, you must spill the enemy's blood. In this case, unfortunately, a lot of it.\n\nYou know what we have to do.", objectives = "Slay 20 Grimtotem Tauren at Darkcloud Pinnacle.", completion = "While the Earth Mother does not condone such violence, we had no choice. The Grimtotem have ignored Her teachings for too long and are reaping what they have sown." }
WordHunterWoW_QuestEN[27314] = { title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Sentinel training 101: take out their leaders and your enemy's forces will soon fall apart. We're going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. Let's see if we can't take her measure.", objectives = "Slay Isha Gloomaxe.", completion = "She was tougher than I thought. We worked well together, but we're going to have to make sure not to underestimate the other Grimtotem chiefs." }
WordHunterWoW_QuestEN[27315] = { title = "Grimtotem Chiefs: Isha Gloomaxe", description = "Basic brave philosophy dictates that if you kill the leaders of your enemy's forces, they will soon fall into disarray. We are going to do just that, {class}.\n\nIsha Gloomaxe is the closest of the Grimtotem chiefs. We will test her and her axe, and she will be found wanting.", objectives = "Slay Isha Gloomaxe.", completion = "She was more formidable than her reputation suggested. Although we worked well together, we must make certain not to underestimate the other Grimtotem chiefs." }
WordHunterWoW_QuestEN[27316] = { title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nPerhaps the sentinel will have some insight into its significance?", objectives = "Give the Rattle of Bones to the Feralas Sentinel at Darkcloud Pinnacle in Thousand Needles.", progress = "That's the fabled Rattle of Bones, <name>!", completion = "It's true then! What is it doing here, though? And if it's here, that must mean that the writ and the drums are also nearby!\n\nMaybe there's some link between it and the wind serpent that just appeared? I think that I've an idea what that creature is as well." }
WordHunterWoW_QuestEN[27317] = { title = "The Rattle of Bones", description = "A tauren rattle lays here, exuding supernatural power. Its keepers slain, the artifact is undefended.\n\nSurely the brave will have some insight into its significance?", objectives = "Give the Rattle of Bones to the Freewind Brave at Darkcloud Pinnacle in Thousand Needles.", progress = "The fabled Rattle of Bones, <name>!", completion = "It is true then! What is it doing here, though? And if it is here, that must mean that the writ and the drums are also nearby!\n\nPerhaps there is some link between it and the wind serpent that just appeared? I think that I have an idea what that creature is as well." }
WordHunterWoW_QuestEN[27318] = { title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman of immense power. Supposedly, he is a direct disciple of Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he's here and that he's been training their geomancers. We have to kill him, {class}.", objectives = "Slay Elder Stormhoof.", completion = "That's two of them. Two more to go.\n\nI wonder what he meant about being \"chosen\"?" }
WordHunterWoW_QuestEN[27319] = { title = "Grimtotem Chiefs: Elder Stormhoof", description = "Elder Stormhoof is a shaman chief of immense power. He was taught by Magatha Grimtotem, the Elder Crone, leader of the Grimtotem clan.\n\nWe know that he is here and that he has been training their geomancers. We have to kill him, {class}.", objectives = "Slay Elder Stormhoof.", completion = "That was not pleasant. I wonder what he meant by calling you, \"the Chosen\"?" }
WordHunterWoW_QuestEN[27320] = { title = "The Writ of History", description = "In shu'halo myth, the Rattle of Bones is connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts.\n\nWe must keep our eyes peeled if we're to find the other two. The writ will most likely look like some kind of pictographic scroll if the stories are to be believed.", objectives = "Collect the Writ of History.", progress = "We'll need the actual writ, not just any tauren scroll hanging.", completion = "I'm fairly certain that's it. This is very intriguing, <name>. What are they doing here? Are they being used as a weapon?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?" }
WordHunterWoW_QuestEN[27321] = { title = "The Writ of History", description = "The Rattle of Bones is a part of shu'halo ancient myth. It is always connected with the Writ of History and the Drums of War. They are supposed to be powerful tauren artifacts; gifts from the Earth Mother if the tales are to be believed. I cannot imagine Her being connected with the drums, though.\n\nWe must be vigilant if we are to find the other two. The writ will look like a pictographic scroll if memory serves.", objectives = "Collect the Writ of History.", progress = "We will need the actual writ, and not just any scroll hanging.", completion = "This is very exciting and also worrisome, <name>. What are these artifacts doing here? Are they being used as a weapons against us by the Grimtotem?\n\nThe wind serpent flew northwest to that next bluff. Maybe that's where the drums are?" }
WordHunterWoW_QuestEN[27322] = { title = "Korok the Colossus", description = "The monstrosity has fallen, granting a brief reprieve to the Forsaken soldiers on the front lines.\n\nTake Korok's second head and return it to Forward Commander Onslaught at Forsaken Forward Command.", objectives = "Take Korok's Second Head to Forward Commander Onslaught at Forsaken Forward Command in the Ruins of Gilneas.", progress = "Korok is dead?", completion = "That towering behemoth has killed hundreds of Forsaken soldiers. You've done a great thing, <name>." }
WordHunterWoW_QuestEN[27323] = { title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the infamous Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe should take this opportunity to make sure that he doesn't go anywhere else.", objectives = "Slay Grundig Darkcloud.", progress = "We need to find and slay Grundig Darkcloud, <name>.", completion = "<The sentinel gives you an appraising look.>\n\nWhat is it with you? Why do they all seem spooked by you being here?" }
WordHunterWoW_QuestEN[27324] = { title = "Grimtotem Chiefs: Grundig Darkcloud", description = "One of the most accomplished Grimtotem leaders of the Stonetalon Mountains has returned home.\n\nWe must make the most of this chance and put an end to his campaign of terror once and for all.", objectives = "Slay Grundig Darkcloud.", completion = "<The brave gives you an appraising look.>\n\nThere is something special about you, <name>. That much is certain." }
WordHunterWoW_QuestEN[27325] = { title = "The Drums of War", description = "Whatever the Grimtotem are doing with these Drums of War, we don't want them to have them.\n\nDon't worry, {name}, we'll figure it all out. But first, we need to gather all of the pieces of the puzzle.", objectives = "Collect the Drums of War.", progress = "The tauren love their drums. I can only imagine the Drums of War will be somehow different from the others.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, <name>. Great danger lies ahead if Magatha Grimtotem has taken notice of you." }
WordHunterWoW_QuestEN[27326] = { title = "The Drums of War", description = "Whatever it is that the Grimtotem are doing with the Drums of War, we do not want them to keep them.\n\nDo not worry, {name}, we will figure out what is going on here. But first, we need to gather all of the artifacts.", objectives = "Collect the Drums of War.", progress = "War is not an activity to engage in for those who are faithful to the Earth Mother's teachings.", completion = "Surely that was the voice of the Elder Crone!\n\nWe must be very careful, <name>. Great danger lies ahead if Magatha Grimtotem has taken notice of you." }
WordHunterWoW_QuestEN[27327] = { title = "Grimtotem Chiefs: The Chief of Chiefs", description = "And now the time has come to take out the leader of all of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nIt is said that he's the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. Supposedly, his indiscretions have left him in a state of disfavor with her.\n\nBut none of that matters right now. All that matters is that we kill him. For good this time.", objectives = "Slay Arnak Grimtotem.", progress = "We have to kill Arnak, <name>, if we are to win the battle for the tauren of Freewind Post.", completion = "For some reason they all think that you've been sent by Magatha Grimtotem. I know it must have something to do with that wind serpent that's been hanging around.\n\nDoesn't matter. Their leader is dead. It's only a matter of time before the tauren of Freewind Post regain their home.\n\nIf I were them, I'd push back a little to teach the Grimtotem a lesson, but they probably won't. They're tauren." }
WordHunterWoW_QuestEN[27328] = { title = "Grimtotem Chiefs: The Chief of Chiefs", description = "The time has come to deal with the leader of the Darkcloud Pinnacle Grimtotem: Arnak Grimtotem.\n\nHe is the disgraced nephew of Magatha Grimtotem, the Elder Crone and matriarch of the Grimtotem clan. His indiscretions have left him in a state of disfavor with her.\n\nNone of that matters now. All that matters is that we deal with him. Once and for all.", objectives = "Slay Arnak Grimtotem.", progress = "Arnak must fall, <name>, if we are to win the battle against the Grimtotem.", completion = "They all believed that you have been sent by Magatha Grimtotem. There is no arguing that her pet, Arikara, has been lurking about.\n\n<The brave gives you a long look.>\n\nIt does not matter. Arnak is dead. It is only a matter of time before we take back Freewind Post.\n\nPerhaps now we will be able to establish a lasting peace with the Grimtotem?" }
WordHunterWoW_QuestEN[27329] = { title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", objectives = "Defeat Arikara.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands." }
WordHunterWoW_QuestEN[27330] = { title = "Invoking the Serpent", description = "I am familiar with these artifacts. I believe that they were brought here by Magatha Grimtotem herself. But she's not amongst the Grimtotem on Darkcloud Pinnacle. She disappeared right after she arrived, and no one knows where she is now.\n\nMaybe we can find out.\n\nTake the rattle, the writ, and the drum out to Arikara's Needle. If my guess is correct, the wind serpent will appear again. You'll have to defeat it to gain knowledge of where Magatha is hiding.", objectives = "Defeat Arikara.", progress = "Only by subduing Arikara will you discover where Magatha Grimtotem is hiding.", completion = "So, she's been taken prisoner by the Twilight's Hammer. I can't say that I feel sorry for her, but she might prove even more dangerous in their hands." }
WordHunterWoW_QuestEN[27331] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", completion = "Thank you for coming to see me, <name>." }
WordHunterWoW_QuestEN[27332] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", completion = "The spirits knew that you would answer my call, <name>." }
WordHunterWoW_QuestEN[27333] = { title = "Losing Ground", description = "I don't know how much longer we can hold out for, {name}. Crowley and Bloodfang's worgen know every hidey hole and safe spot in Gilneas. One minute they're standing in front of you and the next minute they're gone! We're gonna lose this war to attacks of opportunity, even though we have a superior military presence.\n\nBut momma didn't raise no quitter! Forsaken until the end, my friend.\n\nHead west into the headlands and help our soldiers on the front line. Kill the attacking worgen rebels!", objectives = "Kill 12 Worgen Rebels.", progress = "Kill the rebels!", completion = "If I could still breathe I'd let out a sigh of relief.\n\nDon't get too comfortable, though, <name>, your mission here has just begun." }
WordHunterWoW_QuestEN[27334] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", completion = "There you are, <name>. I was beginning to think my message hadn't found you." }
WordHunterWoW_QuestEN[27335] = { title = "Journey to Orgrimmar", description = "A messenger just asked me to pass along an invitation. It is from the priest trainer, Martin Goodchilde, at The Barracks in Orgrimmar.\n\nHe asks that you meet with him at your soonest convenience. The Barracks can be found within the Valley of Honor.", objectives = "Speak with Martin Goodchilde at The Barracks in Orgrimmar.", completion = "Welcome, <name>. I'm glad that you accepted my invitation. We have much to discuss." }
WordHunterWoW_QuestEN[27336] = { title = "The Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", objectives = "Use the Captured Totem to set it on the ground, and kill 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws near it to test its effects.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility." }
WordHunterWoW_QuestEN[27337] = { title = "A Fitting Weapon", description = "From your earliest days, {name}, your trainers identified you as a natural talent. Your rapid progress and dedication have made you an example.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nLegend has it that the cursed Shadowfang Keep in Silverpine Forest is home to a variety of materials that you will need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ander told me to expect you. It's quite an honor to be crafting a weapon for you, <name>. With these materials, it will be a fine blade indeed." }
WordHunterWoW_QuestEN[27338] = { title = "Our Boys on the Shore", description = "The situation here in the Highlands changes by the minute. Our objective is to storm the Bastion of Twilight, but I can't even secure a landing zone on the shore without the blasted Horde creating trouble.\n\nWhile I scrape together the remains of the fleet, I need men on the shore securing the beach head.\n\nReport to Lieutenant Emry on the shore and help his marines to beat back the Horde!", objectives = "Report to Lieutenant Emry at the Twilight Shores in the Twilight Highlands.", completion = "Keep your head down 'fore you lose it, <class>!\n\nThis is MY beach.\n\nThe Horde WANTS my beach.\n\nThey will NOT have my beach.\n\nIs the beach situation clear?" }
WordHunterWoW_QuestEN[27339] = { title = "The Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", objectives = "Collect 6 vials of Marsh Venom from Darkfang Creepers or Noxious Shredders.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference." }
WordHunterWoW_QuestEN[27340] = { title = "Direhorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", objectives = "Kill 12 Grimtotem in Direhorn Post.", progress = "Have you made any progress in stopping the Grimtotem attacks?", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?" }
WordHunterWoW_QuestEN[27341] = { title = "Scouting the Shore", description = "It's them or us, {class}. Only one of us can command this beach.\n\nNorth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand up and down the shore!\n\nI need to know what the current situation is. Scout the beach head control point, marked by that enormous flag, and return to me.\n\nYou don't have to try to capture it, unless you're spoiling for a fight...", objectives = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", completion = "That's the lay of the land, soldier. If you're having trouble fighting here on the coast, you might consider pitching in and helping us take and hold that hill." }
WordHunterWoW_QuestEN[27342] = { title = "In Time, All Will Be Revealed", description = "The Dark Lady has sent you and Arthura here for a very specific purpose. Before I tell you more, we must make preparations.\n\nHead east into the forest of Gilneas and search near the trees and rocks of the region for a special plant known as wolfsbane. Gather as much of the wolfsbane as you can carry and return to me.\n\nOur mission here goes far beyond the scope of the battlefield, {name}. In time, all will be revealed.", objectives = "Collect 6 Wolfsbane.", progress = "Did you gather the wolfsbane?", completion = "<Belmont takes the wolfsbane from you.>\n\nGood. Now just do as Forward Commander Onslaught commands. Try your best to fit in with the rest of the soldiers. We don't want the Gilneas Liberation Front to get suspicious.\n\nOh, you didn't know they were watching us? Right now there are five different worgen spies looking down on our position. Just be calm and follow orders. I'll let you know when we are ready to proceed." }
WordHunterWoW_QuestEN[27343] = { title = "The Hand of the Light", description = "I have been watching your progress, {name}, and I can only conclude that the Light shines brightly upon you. You are becoming an exemplary {class}.\n\nTo honor your dedication, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials to make your weapon are unique, and only found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Do you have the materials for your weapon?", completion = "Lord Grayson has told me much about you and your dedication to the Light and the Alliance. It will be a great honor to craft a hammer for you, <name>." }
WordHunterWoW_QuestEN[27344] = { title = "A Well-Earned Reward", description = "I am not the only one impressed by your progress {name}. Your mastery of bow and pet and your dedication to the Alliance have reached the ears of King Wrynn.\n\nIn recognition of your service, the king has commissioned the royal bowyer to craft a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the unique materials needed for your weapon. Travel there and obtain the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain the Godfrey's Crystal Scope from Lord Godfrey, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Who knew that cursed old keep hid such valuable items? I'll be honored to craft them into a fine weapon for you." }
WordHunterWoW_QuestEN[27345] = { title = "The F.C.D.", description = "Communications are down with all of our frontline outposts, {name}. As of right now I don't have a damn clue as to the status of our troops in Gilneas. We need to re-establish communications.\n\nI need you to head west into the headlands and find our outpost on the coast. By now the soldiers there are likely all dead, but their F.C.D. might be operational. Grab the device and get back to me.", objectives = "Recover the Forsaken Communication Device.", progress = "Recover the F.C.D.", completion = "With this device I will be able to communicate with you in the field. Now to check the rest of our frontline outposts." }
WordHunterWoW_QuestEN[27346] = { title = "The Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and its pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", objectives = "Speak with Moxie Steelgrille at Beezil's Wreck.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway." }
WordHunterWoW_QuestEN[27347] = { title = "Corrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, {class}! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", objectives = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage." }
WordHunterWoW_QuestEN[27348] = { title = "Secure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", objectives = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now." }
WordHunterWoW_QuestEN[27349] = { title = "Break in Communications: Dreadwatch Outpost", description = "I'm not gonna lie to you, {name}. What I'm about to ask you to do is suicide. Chance of failure is about 95%.\n\nAll communication from Dreadwatch Outpost has been severed. With the worgen constantly rushing us we have no means by which to get to Dreadwatch to check on our soldiers. I need you to head south to the outpost and check on our soldiers. I'll keep in contact through the Forsaken communication device - F.C.D. - from here on out.\n\nKEEP CLEAR OF THE MAIN ROAD.", objectives = "Investigate Dreadwatch Outpost.", completion = "<The F.C.D. crackles with static.>\n\nDreadwatch is lost? This is bad, <name>. Real bad.\n\nIf Dreadwatch is compromised it means we've lost Gilneas City." }
WordHunterWoW_QuestEN[27350] = { title = "Break in Communications: Rutsak's Guard", description = "<The F.C.D. hums.>\n\nOur next outpost is Rutsak's Guard, located due east of Dreadwatch. Make your way to Rutsak's while avoiding the worgen rushers, {name}. You don't want to deal with those monsters by yourself.\n\nIf you make it there in one piece, look for Captain Rutsak.\n\nJust be prepared for the worst.", objectives = "Find Captain Rutsak at Rutsak's Guard in the Ruins of Gilneas.", completion = "Th... Af... After we lost Gilneas City, the port fell.\n\nHU... HUM... HUMANS ARE HERE! Reinforcements from Stormwind! They slaughtered my men. Left me alive to witness their strength. To tell high command... To tell them that the 7th Legion are here..." }
WordHunterWoW_QuestEN[27351] = { title = "A Royal Reward", description = "SI:7 has been watching your progress with interest. You service to the Alliance is well-known and tales of your deeds have reached the king's ears.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is home to the exotic materials for your weapon. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain the Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "It was quite an honor to receive the commission for your weapon, <name>. When Tony mentioned using so many exotic materials, I had my doubts, but it seems you managed to find them all. This will be a fine reward for all you've done for the Alliance." }
WordHunterWoW_QuestEN[27352] = { title = "Liquid Gold", description = "As the Scourge swept through Stratholme like a plague, the Knights of the Silver Hand manufactured holy water to use against the invaders. They stored it inside small crates along with other vital supplies, and distributed them throughout the city. Unfortunately, the citizens turned into Scourge reinforcements before the supplies could ever be used!\n\nThese supply crates will prove extremely useful to our efforts. Bring me a vial of Stratholme Holy Water, we need to have it replicated in mass quantities.", objectives = "Find a vial of Stratholme Holy Water.", progress = "Is that the vial of Stratholme Holy Water?\n\nWait, is that just regular water? Don't play games with ol' Stonebruiser!", completion = "Excellent! I think the holy water will prove devastating in large volumes." }
WordHunterWoW_QuestEN[27353] = { title = "Blessings of the Elements", description = "Your talent has attracted much attention in shamanic circles, {name}. Word of your mastery of the elements and dedication to the Alliance has even reached the palace.\n\nIn recognition of your service, King Wrynn has commissioned the royal armorer to forge a special weapon.\n\nThe materials for your weapon can only be found in Silverpine Forest's cursed Shadowfang Keep. Travel there and retrieve Lord Walden's talisman, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", objectives = "Go to Shadowfang Keep and obtain Walden's Talisman, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I have rarely had the chance to work with such exotic materials, but even I can sense the power residing within them. I will have the honor of crafting an incredible weapon for you, <name>. The farseer did not underestimate your abilities when she told me about you." }
WordHunterWoW_QuestEN[27354] = { title = "Mastering the Arcane", description = "You have proven yourself a brilliant student and a dedicated servant of the Alliance. Word of your accomplishments has even reached the ears of the king.\n\nIn recognition of your service, King Wrynn has commissioned the royal enchanter to create a special weapon.\n\nThe materials required for your staff are found only in Silverpine Forest's cursed Shadowfang Keep. Travel there and find a lost heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", objectives = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, I have been expecting you, <name>. Maginor Dumas has spoken highly of you and the royal commission only confirms his words. It is an honor to be able to craft a staff for you." }
WordHunterWoW_QuestEN[27355] = { title = "A Boon for the Powerful", description = "The king is finally beginning to take note of our power and our value to the Alliance, thanks to your deeds. Perhaps they are beginning to accept our kind.\n\nKing Wrynn has commissioned the royal enchanter to create a powerful weapon in recognition of your achievements.\n\nThe materials you will need come from Silverpine Forest's Shadowfang Keep. Travel there and obtain the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the castle.", objectives = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I won't ask what you had to do to come by such rare and powerful materials, but I'm glad to have the chance to work with them. Your weapon will be magnificent!" }
WordHunterWoW_QuestEN[27356] = { title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the <class> Loganaar was talking about. It is a pleasure to finally meet you. Loganaar and other members of the circle speak highly of you. It will be an honor to make a weapon for such a <class>." }
WordHunterWoW_QuestEN[27357] = { title = "The Captive Bride", description = "Of course! Lakota Windsong! Why didn't I think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her into being his bride. She managed to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe has to be around here somewhere. She's become quite the mystic in recent years. I'm guessing she'll know what to do with these tauren artifacts.", objectives = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, <race>?" }
WordHunterWoW_QuestEN[27358] = { title = "The Captive Bride", description = "Lakota Windsong! Why did I not think of this before?\n\nArnak kidnapped Lakota years ago and tried to force her to be his bride. With help, she was able to escape, but in the chaos of the recent attack on Freewind Post, he took her again.\n\nShe must be near. She has become quite the shaman in recent years. I am sure that she will understand the significance of the rattle, the writ, and the drums.", objectives = "Speak with Lakota Windsong at Darkcloud Pinnacle in Thousand Needles.", completion = "It is embarrassing to have been kidnapped by Arnak again. I heard the fighting outside. Did you kill him?\n\n<The shaman looks sad for just a moment.>\n\nI am happy to be free once more. Now, how can I help you, <class>?" }
WordHunterWoW_QuestEN[27359] = { title = "Argent Reinforcements", description = "The Scourge have some sort of ward in place that's preventing me from opening a portal so that our reinforcements can help us take the city! It's like a neverending screaming inside of my head! Agh!\n\nI'm doing all I can to retain my sanity from that noise with this barrier. My best guess is that the banshees are maintaining the defense. If you could bring me some of their essences, I think I can use them to counteract the ward and get our boys in here!", objectives = "Obtain 4 Banshee Essences.", progress = "Were you able to obtain the essences? Be careful, they're deadly spellcasters.", completion = "Oh my... the banshees are very tortured souls indeed. Merely holding their essence is emotionally painful...\n\nEnough of that for now. I'll get to work on counteracting their magic, then we'll have a portal up and running in no time. Stratholme will be ours soon, I just know it." }
WordHunterWoW_QuestEN[27360] = { title = "Vengeance for Our Soldiers", description = "7th Legion... They rushed us in the dead of the night. Their captain barked orders as the submariners slaughtered my men. Then he came to me, put his face in mine, and said something I'll never forget:\n\n\"The name's Master Sergeant Pietro Zaren, officer in the 7th Legion. When you see your soldiers being slaughtered in your nightmares - if you even still dream - remember my name and tremble.\"\n\nAvenge my soldiers! Kill the 7th Legion occupying the Cathedral Quarter of Gilneas City, southwest of here.", objectives = "Kill 10 7th Legion Submariners.", completion = "Though we were shamed in battle, the enemy was not victorious. I will not soon forget this, <name>.\n\nIf I make it back to Silverpine I will likely retire from the service. War is not in my blood." }
WordHunterWoW_QuestEN[27361] = { title = "Favored of the Light", description = "The Light truly shines in you and your dedication to the Alliance, {name}. You serve as an example to your fellow priests and comrades in arms.\n\nIn recognition of your deeds, King Wrynn has commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears." }
WordHunterWoW_QuestEN[27362] = { title = "Favored of Elune", description = "You are a true servant of Elune, an example to our people, and stalwart servant of the Alliance. The Temple of the Moon and the court of Stormwind wish to honor your achievements.\n\nWe have commissioned the royal enchanter to create a staff for you.\n\nThe materials for your staff can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears." }
WordHunterWoW_QuestEN[27363] = { title = "A Budding Young Surgeon", description = "You have shown yourself to be a capable priest and a credit to the people of Gnomeregan. The high tinker and the king of Stormwind wish to honor your contribution to the Alliance.\n\nThey have commissioned the royal enchanter to create a special staff.\n\nThe materials for such a weapon can only be found in the cursed Shadowfang Keep in Silverpine Forest. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and ghostly essence from the spirits haunting the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I can't believe you managed to get all those materials. I wouldn't think of venturing into Shadowfang Keep! The stories about that place are horrific.\n\nEnough of that, though. This is a time to recognize your achievements, not prattle on about my silly fears." }
WordHunterWoW_QuestEN[27364] = { title = "On Whose Orders?", description = "<The F.C.D. buzzes.>\n\nThe 7th Legion are an elite special ops regiment. They've been there, behind the scenes, for almost every major offensive and military engagement the Alliance has ever done. This is bad news. How did they get past our warships? And on whose orders are they here?\n\nWe need to get our hands on their orders. This Pietro character will undoubtedly have vital information. Find him at the Cathedral Quarter in Gilneas City and take him out. Search his corpse for clues.", objectives = "Recover the Orders from High Command.", progress = "Status?", completion = "<The F.C.D. crackles with electricity.>\n\nAn Alliance armada is en route? How could this have happened?\n\n<Forward Commander Onslaught cuts out for a moment. You hear worgen howling in the background.>\n\nYou've got to hurry, <name>. We're being overrun up here at Forward Command." }
WordHunterWoW_QuestEN[27365] = { title = "A Fitting Weapon", description = "From your earliest days, your trainers always knew you would make your mark on the Horde. You have fought bravely and given our enemies reason to fear.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost Silverlaine family sword, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain the Silverlaine Family Sword from Baron Silverlaine, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Grezz Ragefist told me to expect you. Those materials will make a fine sword. Always use it for the glory of the Horde." }
WordHunterWoW_QuestEN[27366] = { title = "Landgrab", description = "The Horde's Axebite Marines are all up in my precious, precious beach.\n\n<The Lieutenant points north, along the shore.>\n\nKill them.", objectives = "Slay 12 Axebite Marines on the Twilight Shores in Twilight Highlands.", completion = "Dead? By the dozen?\n\nIt's a start, <class>. It's a start." }
WordHunterWoW_QuestEN[27367] = { title = "Gidwin Goldbraids", description = "I love my boys, don't get me wrong.  But I TOLD them that I needed FIVE MINUTES to water and brush the horses, and what did they do?  They made a stupid bet with each other and ran off!  I should have known better... this always happens.\n\nGidwin's the short one.  He headed north, along the river.  If you're headed that direction, would you tell him to come back?  We've got to get to Light's Hope Chapel, and I'm not against leaving without him.", objectives = "Find Gidwin Goldbraids in Eastern Plaguelands.", completion = "Tarenar?  Is that you?\n\nWhoever you are, would you mind helping me out of this thing?" }
WordHunterWoW_QuestEN[27368] = { title = "Just Encased", description = "You should have seen me fight!  I must have killed six of those beasts, when...\n\nOh wait, you can count the bodies, can't you?  OK, fine.  I killed four of them, when the fifth one shot me with this web.  To make things even worse... when he blasted me with web juice, my mouth was open!\n\nI can't seem to break these webs, and I doubt you'll be able to, either.  No, you'll have to get some of the stomach juice from those undead spider-things.  That'll do the trick.", objectives = "Obtain 8 vials of Crypt Bile from nerubians in Terrorweb Tunnel.", progress = "Oh boy... Fiona is going to be madder than a wet harpy.  You'd better hurry.", completion = "You're back?!  Thank the Light!\n\nBefore you throw that acid on me, I need to ask: Are you the guy who was here before, or are you one of those eight-legged cowards?  I need to know whether or not I should smack you on my way out." }
WordHunterWoW_QuestEN[27369] = { title = "Greasing the Wheel", description = "Sorry about that.  I was pretty sure you were one of those spider-beasts, doing a bad {race} impression.\n\nHow do you do?  Gidwin Goldbraids, at your service.  I'm in a bit of a hurry back to my caravan, but I was wondering if you might do me one last favor?  My pal Fiona runs a small shop, and she could probably use some of these herbs that grow along the river shore.\n\nI'm thinking if we give her some nice herbs, she'll be MUCH less likely to murder me.  That's the plan, anyway.", objectives = "Loot 10 Banshee's Bells from the shore of the Thondroril River.", progress = "Giddy's got you mixed up in all of this now?", completion = "I'll tear that pint-size paladin to shreds before he... wait a minute are those Banshee's Bells?  You brought these for me?\n\nOh, Gidwin asked you to get them for me!  That sweet little guy.  Alright.  He's off the hook for now." }
WordHunterWoW_QuestEN[27370] = { title = "Tarenar Sunstrike", description = "As soon as we stopped, they made a bet about \"who could kill the most undead in five minutes.\"\n\nIt's been an hour, and I'm still waiting for them to come back.\n\nI saw Tarenar run off to the southeast.  Unfortunately, I can't leave the caravan here by itself.  If you end up traveling in that direction, could you find him and send him back to me?", objectives = "Find Tarenar Sunstrike at Death's Step in Eastern Plaguelands.", completion = "I've found them, <race>.  The Scourge.  How I've longed for this day." }
WordHunterWoW_QuestEN[27371] = { title = "What I Do Best", description = "I remember when I was young, I would sneak off into the Ghostlands and just beat up zombies for hours on end.  Nobody even PAID me.  I just did it.\n\nNow, look in front of you.  Those are some serious zombies.  I was just about to start beating them up, too.  Care to join me?", objectives = "Kill 5 Death's Step Miscreations at Death's Step in Eastern Plaguelands.", completion = "Five should be good enough.\n\nYikes, look at the time!  I need to head back to camp." }
WordHunterWoW_QuestEN[27372] = { title = "A Gift For Fiona", description = "My traveling companion, Fiona, runs a small vendor's shop out of her caravan.  She and I, along with our friend Gidwin, are all on our way to Light's Hope Chapel.  I'm sure you can join us, if you like... though Fiona might be a little mad at me.\n\nFiona always forgets why she's mad if you give her a gift.  Kill some of the plaguehounds north of here, then bring their blood to Fiona at the caravan, down by the river.  She'll love it.  We'll talk again there.", objectives = "Obtain 10 samples of Plaguehound Blood.", progress = "I should have guessed it.  Tarenar made you get me a gift?  That thoughtless idiot!\n\nUmm... what was the gift, anyhow?", completion = "Why, this is exactly what I needed!  Fine, I'll forgive Tarenar for running off.\n\n<name>, you're welcome to join us anytime." }
WordHunterWoW_QuestEN[27373] = { title = "Onward, to Light's Hope Chapel", description = "Now that the boys are back, we can head out.  You headed east?\n\nPlease, join us!  I insist!  Yesterday, we were in the Menders' Stead, and I was telling Tarenar, \"We have two paladins and a shopkeeper, but you know what we really need?  A {class}!\"\n\nDon't look at me that way!  I'm serious!  Come on, hop in the cart.", objectives = "Board Fiona's Caravan at the Thondroril River in Eastern Plaguelands.", completion = "Hope the ride wasn't too bumpy for you.\n\nHave a look around the tower while the horses rest.  It's no Light's Hope Chapel, but I'm sure you can find some way to keep yourself busy." }
WordHunterWoW_QuestEN[27374] = { title = "The Maw of Madness", description = "I can't believe it, {name}. Me own son - me own flesh and blood! Throwing his lot in with those fiends from the Twilight's Hammer. Did you see what he became when he tried to destroy the wedding? Oh ... why? Why?\n\nIt's that beast, {name}. The enormous mouth emerging from the earth to our west. \"The Maw of Madness!\" My son said it spoke to him, but I thought it was just nightmares.\n\nThe Earthen Ring is trying to destroy it. Go to Earthcaller Torunscar, west of here, and see how you can help!", objectives = "Speak to Earthcaller Torunscar at the Ring of the Elements.", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help." }
WordHunterWoW_QuestEN[27375] = { title = "The Weeping Wound", description = "A beast, {name}! I saw a beast. A great maw, an even greater hungering. They can't possibly know what they unleashed.\n\nIt is here. Its terrible shapeless body is erupting right into the Highlands.\n\nI saw you in my vision, {name}. You struggle with the Earthen Ring to contain the beast. You will face the darkness.\n\nGo now, before the beast grows in power. Speak to Earthcaller Torunscar at the Circle of the Elements, northwest of here atop the ridge beyond the ruined Drakgor Encampment. Hurry!", objectives = "Speak with Earthcaller Torunscar at the Ring of the Elements.", completion = "Welcome, brotha. You've chosen a harsh time to be joinin' us, but that is to our fortune. We could use ya help." }
WordHunterWoW_QuestEN[27376] = { title = "The Maw of Iso'rath", description = "We are ready to attack the beast. First, we need to destroy it's tentacles, then Yevaa will perform a ritual to summon a powerful fire elemental that we will drop into its maw.\n\nI want you to fly out with our first group attack. Hold steady until an opportunity presents itself, then join the battle with the rest of the shaman in cutting the tentacles down.\n\nTake any one of the gryphons when you're ready to join the assault.", objectives = "Mount a gryphon to join the attack on Iso'rath.", completion = "The tentacles swept us off of our gryphons as well! They were far more nimble than we anticipated.\n\nNo matter. We were prepared for this possibility. I can summon the elemental from here if you can keep me safe." }
WordHunterWoW_QuestEN[27377] = { title = "Devoured", description = "We knew this was a possibility, but we had no idea how the beast would defend itself. Iso'rath's body is reacting quickly to our threat.\n\nI can complete the summoning from here, but only if you can hold back Iso'rath's defenses. Keep them busy! We will survive this!", objectives = "Defend yourself and Earthcaller Yevaa from Iso'rath's bodily defenses.", completion = "I've brought you back from the brink of death, hero!\n\nDeathwing is upon us! We need your help." }
WordHunterWoW_QuestEN[27378] = { title = "The Worldbreaker", description = "There's no time! Deathwing struck before we could form against him. If you do not stop him, the Earthen Ring will end this day!", objectives = "Defeat Deathwing, the Aspect of Death.", completion = "You're awake! Thank the elements. I'd almost lost all hope." }
WordHunterWoW_QuestEN[27379] = { title = "The Terrors of Iso'rath", description = "We need you! You were stuck in some kind of nightmare. So are many of the other shaman.\n\nIt doesn't matter... our plan is falling apart. Some of our shaman are channeling protective auras that should combat the digestive juices and keep you alive, but we need you to rescue the other shaman from the tentacles.  We won't be able to defeat Iso'rath without them!\n\nDon't stay out in the stomach without the other shaman for too long or you'll be digested alive!", objectives = "Rescue Hargoth Dimblaze, Earthmender Duarn, Stormcaller Jalara, and Stormcaller Mylra.\n\nReturn to the safety of the other shaman if Iso'rath's defenses are eating away at you.", progress = "The battle is not over. The shaman within Iso'rath need you!", completion = "United with the Earthen Ring, we can survive the horrors of Iso'rath. Now it is time to turn our vengeance upon him!" }
WordHunterWoW_QuestEN[27380] = { title = "Nightmare", description = "Iso'rath's brain is revealed! The shaman you've saved should keep you somewhat safe amidst his defenses.\n\nStrike at the brain and destroy Iso'rath!", objectives = "Destroy the Brain of Iso'rath.", completion = "You saved many of my closest allies today, <name>. I can only imagine what horrors you witnessed within Iso'rath, but you have the thanks of all of the Earthen Ring." }
WordHunterWoW_QuestEN[27381] = { title = "Traveling Companions", description = "While we're waiting here at this tower, we might as well see if anybody else is headed to Light's Hope Chapel.  The more, the merrier, I say!\n\nAsk around to see if anybody wants to join us on our trip.  I'm sure you can find somebody who's headed to Light's Hope.", objectives = "Find someone at Crown Guard Tower who will join your caravan.", progress = "Any luck?", completion = "Argus Highbeacon... that old guy on the top of the tower?  Great!\n\nA man his age must have been in the Argent Crusade for a long time.  Maybe he can put in the good word for us at Light's Hope." }
WordHunterWoW_QuestEN[27382] = { title = "Rough Roads", description = "The Argent Crusade built these towers to be points of light in the darkness of the Plaguelands.  I walk the paths between these towers, protecting and maintaining them.\n\nThe roads have been dangerous lately.  Plagued wildlife runs rampant, and bats swoop down upon unsuspecting travelers.  It would make the next leg of my journey much easier if you could clear some of this wildlife out of the way for me.", objectives = "Slay 13 Plaguebats along the path to Light's Shield Tower.", completion = "Of course a young <race> like you would have no trouble taking care of a few wild animals.  With the roads clear, my journey to the next tower will be much easier." }
WordHunterWoW_QuestEN[27383] = { title = "Little Pamela", description = "The battle for Darrowshire still haunts me, {race}.  I wake up in cold sweats, convinced that I'm still there; that it is happening all over again.\n\nI've coped with the loss of my comrades, but the loss of my family members is still cripplingly painful.  One of my kin lost during the attack was my young niece, Pamela.\n\nIf you are brave enough to enter Darrowshire, will you search for any sign of Pammy?  Darrowshire's ruins are due south of here.", objectives = "Find Pamela Redpath in Darrowshire.", completion = "Hello.  I'm Pamela, what's your name?" }
WordHunterWoW_QuestEN[27384] = { title = "Pamela's Doll", description = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!\n\nBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!\n\nAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.\n\nWill you find my doll for me?", objectives = "Find Pamela's doll.", progress = "Did you find my doll?", completion = "You found it!  You found my doll!  Oh, thank you!" }
WordHunterWoW_QuestEN[27385] = { title = "Uncle Carlin", description = "I'm going to play with dolly, but I don't want to play with daddy's sword after all.  You'd better keep it.\n\nEven better, can you give it to my uncle Carlin?  I'm not sure where he is, but sometimes I hear him crying.  It sounds like he's nearby, to the north.\n\nI hope he's not crying for me!  {name}, will you find my uncle and tell him I'm alright?\n\nIf you find him say I'm waiting for him, and I want to hear the story he used to tell... the one about the rabbits and the berry jam!  That story's so funny!", objectives = "Return to Carlin Redpath at Crown Guard Tower in Eastern Plaguelands.", progress = "Any news of my Pammy?", completion = "You've seen Pamela?  She's alive?\n\nShe's dead?  No!  Oh, Pamela!  Why does your spirit still suffer in this world?  Why are you perished, while fortune keeps me alive?  In an instant I would switch places with you and wander dead Darrowshire, a ghost and alone!\n\nAh, but this news cannot change fate.  Thank you, <name>.  Now my duty, my duty to revenge, burns hot as ever.\n\nSay, what is that sword you have there?" }
WordHunterWoW_QuestEN[27386] = { title = "A Strange Historian", description = "That sword belonged to Joseph Redpath, Pamela's father - though you probably already knew that.  I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.\n\nPamela's fate is sealed, but perhaps we can change Joseph's fate.\n\nA strange gnome arrived here at this tower not long ago.  Her name is Chromie.  Take that sword to her.  I have a feeling she will be able to help us.", objectives = "Bring Joseph's Hunting Blade to Chromie.", progress = "There is something timely about your visit.  You're not from the future, are you?", completion = "What is this?  A warsword?  A butter knife?  I'm useless when it comes to blades.  Let me see...\n\nAh!  This sword was once in the hand of a great man, but there is much tragedy in that man's past.\n\nAre you here to help him?  It's far too late for him now... but perhaps we can help him in the past!" }
WordHunterWoW_QuestEN[27387] = { title = "Villains of Darrowshire", description = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  He was slain among the foothills north of here, and his skull remains there.\n\nMarduk the Black was never defeated, but his fabled sword now rusts, ownerless.  It can be found near the road to our southeast.\n\nRetrieve these items, {name}.  I know not why, but I am certain their fate lies with you.", objectives = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Chromie at Crown Guard Tower in Eastern Plaguelands.", progress = "Did you find the skull and the sword, <name>?", completion = "You found them!  Well done, <name>!  These relics hold within them the memories of the Scourge forces at Darrowshire.  We will need these if we are to save your Joseph Redpath." }
WordHunterWoW_QuestEN[27388] = { title = "Heroes of Darrowshire", description = "The heroes of Darrowshire held relics of their own, and inside of those relics lie more precious memories.\n\nFirst, speak with Carlin and obtain the Extended Annals of Darrowshire.  Within the tome lies the narrative that will drive our excursion through time.\n\nThen, you will need to head west to the Marris Stead.  The former owner of the Marris farmhouse collected relics from the battle of Darrowshire - for what reason, I am not certain.\n\nGather these relics, and return to me.", objectives = "Obtain the Extended Annals of Darrowshire from Carlin Redpath, and obtain Davil's Libram and Redpath's Shield from the Marris Stead.", progress = "Do you have the relics, <name>?", completion = "You have the relics?  Good.  I will get to work on resolving any temporal discontinuities.\n\nDon't worry... that's not something you have to worry about.  You just gather the reagents." }
WordHunterWoW_QuestEN[27389] = { title = "Marauders of Darrowshire", description = "I require a rare reagent for the powerful spell I intend to cast: skulls from the scourge who took part in the battle of Darrowshire.\n\nTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.\n\nGo, {name}.  You'll find scourge champions in the Fungal Vale to the north.  Go.", objectives = "Bring 5 Resonating Skulls to Chromie at Crown Guard Tower in Eastern Plaguelands.", progress = "Do you have the skulls?  They are critical for my spell, which will give us the chance to save Darrowshire.  Maybe.", completion = "Excellent work, <name>.  Are you certain you haven't done this before?" }
WordHunterWoW_QuestEN[27390] = { title = "The Battle of Darrowshire", description = "Now, {name}, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", objectives = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square.", progress = "I think I heard ghosts outside.  They whisper scary things to me...", completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if came to our house, so I made some tea!\n\nI hope you like lots of sugar!" }
WordHunterWoW_QuestEN[27391] = { title = "Hidden Treasures", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you {name}.  Thank you!  You're a very nice man!", objectives = "Bring Joseph's Key to Joseph's Chest.", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens..." }
WordHunterWoW_QuestEN[27392] = { title = "I'm Not Supposed to Tell You This", description = "My daddy always kept two swords: one for fighting with men, and one for hunting the animals.  I wasn't supposed to touch his swords, but I knew where he hid them.\n\nOne day, he told my mommy that he was going to fight a \"lone hunter\" in the hills to the east, but he brought his animal sword with him!  When he came back, he didn't have his sword with him.\n\nWhen daddy comes back, he'll be so happy when I give him his animal sword!  Will you go and find it?", objectives = "Obtain Joseph's Hunting Blade from The Lone Hunter in Eastern Plaguelands.", progress = "Daddy loved his animal sword.  He seemed sad when he didn't have it anymore.", completion = "That's my daddy's sword!  How did you find it?  Did you find the bad hunter?" }
WordHunterWoW_QuestEN[27393] = { title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", objectives = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", completion = "The Wavespeaker was right. There's something here." }
WordHunterWoW_QuestEN[27394] = { title = "The Call of the Blade", description = "I sense a strong power calling to me from the ruins. Can you check again on that southern battle site for me?  I'm certain that there's something there.", objectives = "Investigate the battle site at the southern end of the Ruins of Vashj'ir.", completion = "The Wavespeaker was right. There's something here." }
WordHunterWoW_QuestEN[27395] = { title = "A Marksman's Weapon", description = "You have picked up the ways of the hunter quickly, {name}. Your skills have made you a credit to the Horde and an example to the younglings.\n\nAs a reward for your progress and hard work, the warchief has commissioned his personal bowyer to create a unique weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials we'll need. Travel there and retrieve the scope from Lord Godfrey's gun, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain Godfrey's Crystal Scope, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I'm honored that the warchief chose me to craft a weapon for you, <name>. With such exotic materials, it will be a very fine bow." }
WordHunterWoW_QuestEN[27396] = { title = "Blade of the Shattered Hand", description = "Many members of the Shattered Hand do not survive their training, {name}. Not only have you survived, but you will soon become a feared blade of the Horde.\n\nAs a reward for your progress, the warchief has commissioned his personal smith to forge a weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover Commander Springvale's sharpening stone, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain Springvale's Sharpening Stone from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Gordul told me that you would be bringing a variety of unusual materials, but I didn't expect anything like this. Moonsteel is said to be very rare and there's only one place I know to get it. You have risked much for this weapon, <name>, and I'll see to it that you receive a fitting reward." }
WordHunterWoW_QuestEN[27397] = { title = "Hretar's Task", description = "The elements and spirits speak to you with clear voices, {name}. You have become a powerful shaman and an example to others wishing to serve the Horde.\n\nWord has even reached the warchief, and he has commissioned his personal smith to forge a special weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and obtain Lord Walden's talisman, the Book of Lost Souls, and essence from the ghosts haunting the keep.", objectives = "Go to Shadowfang Keep and obtain Walden's Talisman from Lord Walden, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be <name>. Kardris said that you were venturing to Shadowfang Keep to find the materials needed for this weapon and I see that you have not disappointed. I will make you a mighty weapon worthy of what you have brought." }
WordHunterWoW_QuestEN[27398] = { title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City for further instructions.", objectives = "Speak to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", completion = "Your aid is most timely, <name>." }
WordHunterWoW_QuestEN[27399] = { title = "The Battle Is Won, The War Goes On", description = "We've defeated the enemy's forces here, {name}.  But Hyjal is not the only place where our foes are moving against us.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", objectives = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Your aid is most timely, <name>." }
WordHunterWoW_QuestEN[27400] = { title = "Mastering the Arcane", description = "All of your trainers agree, {name}, you show an amazing amount of talent for a journeyman. Even the warchief has heard of your rapid progress.\n\nAs a reward for mastering your studies, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find a magical heirloom of the Silverlaine family, a supply of moontouched wood, and the essence of the ghosts haunting the keep.", objectives = "Go to Shadowfang Keep and obtain Silverlaine's Enchanted Crystal from Baron Silverlaine, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Ah, you must be the <class> that Uthel'nay mentioned. I've heard tales about the artifacts the Silverlaine family once kept, but I haven't ever seen one. This should make an excellent focus for your staff. Let's get started." }
WordHunterWoW_QuestEN[27401] = { title = "What Tomorrow Brings", description = "<The F.C.D. buzzes.>\n\nLook around the Cathedral Quarter. There should be a telescope nearby that the 7th Legion uses for spying. Find it and use it to scout the harbor. We need to find out how the 7th Legion got past our fleet.\n\nHurry, {name}. We can't hold these beasts back much longer.\n\nWhat does tomorrow bring?", objectives = "Use the 7th Legion Telescope to Scout the Harbor.", completion = "<The F.C.D. crackles with electricity.>\n\nTORPEDOED! We had everything at the water line covered, but nothing below the line. They must have snuck in beneath our defenses and then blown our warships to smithereens.\n\nAnd now the rest of the Alliance fleet is nearly here..." }
WordHunterWoW_QuestEN[27402] = { title = "Token of Power", description = "Your mastery of our ways continues to grow quickly, {name}, and I am far from the only one impressed by your progress. Even the warchief has taken note of your deeds.\n\nAs a reward for your dedication, the warchief has commissioned his personal enchanter to craft a staff.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and retrieve the tenebrous orb held by Lord Godfrey, the Book of Lost Souls, and the essence of the ghosts haunting the keep.", objectives = "Go to Shadowfang Keep and obtain the Tenebrous Orb from Lord Godfrey, the Book of Lost Souls, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "So you are the <class> who will receive this staff. It will be a fitting reward for one so dedicated to the pursuit of power and the ascendancy of the Horde." }
WordHunterWoW_QuestEN[27403] = { title = "A True Sunwalker", description = "I have watched your training, {name}. Yours is the path of an exemplary Sunwalker, a brave defender of the Horde and a follower of our ways.\n\nAs a reward for your dedication, the warchief has commissioned his personal smith to forge a special weapon.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I haven't worked with the Sunwalkers before, but from all I've heard, the warchief holds you in high regard. It was a great honor to be asked to forge this weapon for you and I hope it will serve you well." }
WordHunterWoW_QuestEN[27404] = { title = "The Circle's Future", description = "The Cenarion Circle is pleased with your progress, {name}. You are a credit to all druids and we look to you and your peers as the future of our brotherhood.\n\nThe circle has decided to honor you with the creation of unique staff.\n\nThe rare and powerful materials needed for your staff can only be found in Shadowfang Keep inside Silverpine Forest. Travel there and retrieve Lord Walden's collection of elixirs, a supply of moontouched wood, and sinew from the ghouls and geists infesting the keep.", objectives = "Go to Shadowfang Keep and obtain Walden's Elixirs from Lord Walden, 5 bundles of Moontouched Wood, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your staff?", completion = "Ah, you must be the <class> Loganaar was talking about. It is a pleasure to finally meet you, <name>. I've often heard members of the circle describe you as a talented and promising <class> and I'm heartened to see their estimations were correct." }
WordHunterWoW_QuestEN[27405] = { title = "Fall Back!", description = "<The F.C.D. buzzes.>\n\n<Howls can be heard in the background.>\n\n{name}, do you read me? Come in, {name}. This is likely my final transmission. The worgen have overrun Forsaken Forward Command. It is now only a matter of time before the base is lost. Belmont and the val'kyr, Arthura, have left. Belmont mentioned that they will rendezvous with you at Emberstone Village, located to the northeast. Find Belmont, {name}. Our mission - our very existence - depends on it.\n\nYou are our final hope.", objectives = "Find Deathstalker Commander Belmont at Emberstone Village in the Ruins of Gilneas.", completion = "Forward Commander Onslaught fought until the bitter end, <name>. It took a pack of bloodthirsty worgen to finally bring him down. We must not let his death, or the death of all of our soldiers in Gilneas, go in vain. Our mission MUST succeed.\n\nNow I will reveal to you why we are here." }
WordHunterWoW_QuestEN[27406] = { title = "A Man Named Godfrey", description = "Lord Vincent Godfrey spent his life defending the kingdom of Gilneas. When the worgen curse ravaged this land, Godfrey was one of the first Gilneans to take up arms against the beasts. It is said that upon discovering that his king was afflicted by the curse, Godfrey took his own life. He would rather be dead than serve the very creatures that he had defended his home against.\n\nWe are going to give him a second chance, {name}. Together we will battle southeast towards Tempest's Reach to collect his corpse.", objectives = "Find the corpse of Lord Vincent Godfrey.", progress = "Lord Vincent Godfrey. The name itself evokes feelings of dread in the hearts of worgen.", completion = "Here we are, <name>. He is a little rotted, but no worse for the wear. We must hurry before the Alliance finds us!" }
WordHunterWoW_QuestEN[27407] = { title = "Bloodfen Feathers", description = "Are you startled by Brogg's presence here, little {race}? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", objectives = "Collect 5 Bloodfen Feathers from Bloodfen Raptors.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual." }
WordHunterWoW_QuestEN[27408] = { title = "Banner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, {name}.", objectives = "Retrieve the Stonemaul Banner from within the Den of Flame.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, <name>. Brogg has big plans for clan banner." }
WordHunterWoW_QuestEN[27409] = { title = "The Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", objectives = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, <name>. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends." }
WordHunterWoW_QuestEN[27410] = { title = "Spirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", objectives = "Put 10 Stonemaul Spirits to rest at the Stonemaul Ruins.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do." }
WordHunterWoW_QuestEN[27411] = { title = "Challenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. {name}, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", objectives = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair and defeat anyone who answers.", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg know Onyxia dead. Brogg know her brood still there. Brogg not let them forget the Stonemaul.\n\nBrogg is grateful for your help, <name>, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong." }
WordHunterWoW_QuestEN[27412] = { title = "WANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", objectives = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", progress = "You look pretty satisfied with yourself. Come to claim the bounty on that monstrous raptor?", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!" }
WordHunterWoW_QuestEN[27413] = { title = "Catch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", objectives = "Collect 8 Wyrmtail stalks in the Dragonmurk or Wyrmbog.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash." }
WordHunterWoW_QuestEN[27414] = { title = "Identifying the Brood", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, {name}? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", objectives = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home." }
WordHunterWoW_QuestEN[27415] = { title = "The Brood of Onyxia", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", objectives = "Destroy 5 Eggs of Onyxia.", progress = "You must hurry to the Dragonmurk, <name>. With Onyxia's eggs riddled around the Wyrmbog, we face overwhelming numbers unless something is done quickly.\n\nDestroy her eggs! Don't let the black dragon plague spread across our homeland!", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, <name>.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south." }
WordHunterWoW_QuestEN[27416] = { title = "The Brood of Onyxia", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", objectives = "Speak with Overlord Mok'Morokk in Brackenwall Village.", completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here." }
WordHunterWoW_QuestEN[27417] = { title = "The Brood of Onyxia", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", objectives = "Speak with Draz'Zilb in Brackenwall Village.", completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done." }
WordHunterWoW_QuestEN[27418] = { title = "Challenge Overlord Mok'Morokk", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny {race}!\n\nYou tell me when ready for good beating.", objectives = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, <name>.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all." }
WordHunterWoW_QuestEN[27419] = { title = "Army of the Black Dragon", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", objectives = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes." }
WordHunterWoW_QuestEN[27420] = { title = "Postponing the Inevitable", description = "You have a keen eye to have seen me here, hidden among the grasses.\n\nAhead of us lies the Fungal Vale, an area that the Scourge still cling tightly to.  They use floating constructs to continually re-plague the land, keeping it vile and polluted.\n\nThe devices are controlled with runes, which are held by dark adepts and shadowmages.  Take the controlling runes that these cultists hold, aim them at the plague disseminators, then overcharge them with this mote.  The results should be amusing.", objectives = "Obtain Control Runes from Dark Cultists and Shadowmages, then use the Overcharged Mote on them to destroy 3 Plague Disseminators.", completion = "The sooner those Scourge are pushed out of the Fungal Vale, the sooner we can heal it.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[27421] = { title = "Amidst Death, Life", description = "Scourge forces have made it a point to ensure that nothing survives in the Fungal Vale - all you will find are husks of rotted mushrooms and scorched grasses.  The three corners of the vale are home to three large ziggurats, which they use to reanimate their dead and summon new soldiers to the battlefield.\n\nYet even in this evil, lifeless place, life finds a way to flourish.  Take my seeds and plant them in the centers of these ziggurats.  Prove to them that life will prevail.", objectives = "Use Rayne's Seeds in the center of the three ziggurats in the Fungal Vale.", completion = "Even if the flowers died out shortly after they bloomed, they proved our point to the Scourge: they are losing, and we are winning.\n\nThank you for your assistance." }
WordHunterWoW_QuestEN[27422] = { title = "A City Under Siege", description = "We will never control the Eastern Plaguelands if we do not control Stratholme. Not only is it a point of incredible strategic importance, it also houses our enemies' leaders - Balnazzar and Lord Aurius Rivendare. Their Risen and Scourge armies threaten to erase all the progress we've made.\n\nThe Argent Crusade is well-suited to this task. Travel west through Stratholme's main gate and speak with Packmaster Stonebruiser. He will direct you further.", objectives = "Speak to Packmaster Stonebruiser.", completion = "What a relief it is to see an able-bodied soldier that's on our side! There's plenty for ye to do around here, <race>." }
WordHunterWoW_QuestEN[27423] = { title = "Resistance is Futile", description = "<The F.C.D. buzzes.>\n\nThis is Commander Lorna Crowley of the Gilneas Liberation Front. If you are hearing this message then you know that the Alliance once again controls Gilneas. Lay down your weapons and surrender. Failure to comply will result in your death.\n\nOur forces have locked on to your position and will arrive shortly. Resistance is futile.", objectives = "Kill 20 Worgen Combatants.", progress = "Surrender? Coward talk...", completion = "No time to bask in the battle glory, <name>. We have a job to do. I have no doubt more of those beasts are on the way." }
WordHunterWoW_QuestEN[27424] = { title = "Overlord Mok'Morokk's Concern", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny {race}, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", objectives = "Collect Overlord Mok'Morokk's grog, snuff and strongbox from Dustwallow Marsh.", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good <race>. Me miss things very much. Me like you now." }
WordHunterWoW_QuestEN[27425] = { title = "A Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", objectives = "Report to Captain Darill at North Point.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help." }
WordHunterWoW_QuestEN[27426] = { title = "Confirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", objectives = "Collect 4 Grimtotem Notes from Grimtotem Elders and combine them into the Grimtotem Battle Plan.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list." }
WordHunterWoW_QuestEN[27427] = { title = "Arms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", objectives = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh." }
WordHunterWoW_QuestEN[27428] = { title = "Tabetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", objectives = "Speak with Tabetha at her farm.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?" }
WordHunterWoW_QuestEN[27429] = { title = "Raze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", objectives = "Use Tabetha's Torch to burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that." }
WordHunterWoW_QuestEN[27430] = { title = "Justice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", objectives = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed." }
WordHunterWoW_QuestEN[27431] = { title = "Tipping the Balance", description = "<Harrison grins.>\n\nThat's it, {name}. The pieces we need are hidden in these statues!\n\nThey look to be a bit off balance as is. Maybe just a little nudge...\n\nI must say, your field work is coming along nicely. If you applied yourself, you could make a fine archaeologist one day.", objectives = "Speak to Harrison Jones in the Chamber of the Stars.", completion = "Talk about bringing the house down..." }
WordHunterWoW_QuestEN[27432] = { title = "Zaeldarr the Outcast", description = "Can you believe that, after all the trouble we have in the Plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from our graveyards, then take them back to their evil, dead troll hideout--the Undercroft to the southwest.\n\nGo there and take out Zaeldarr, {name}.  I'm sick to death of his mischief!", objectives = "Obtain Zaeldarr's Head from Zaeldarr the Outcast.", progress = "Did you find the hideout, <name>?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!" }
WordHunterWoW_QuestEN[27433] = { title = "Shredderectomy", description = "Our tanks have to pull back, and that means repairs in the field.\n\nSmash up summa them diamond-bladed shredders those wee green monsters are using to fell the trees along the coast, and bring me a heap of leftover shredder parts. We'll bang together sumthun' to get our tanks movin' again.  ", objectives = "Destroy Diamond-Blade Shredders to collect 5 Abused Shredder Parts.", progress = "What'd you get me, <name>?", completion = "Oh aye, tha's the stuff! A good engineer can make anything outta just about anything.\n\nThis here doo-jicker could recouple a busted cylinder casing... Oh! And who doesn't want a dongle? ...And you can fashion this jobby into a ... thing.\n\n<Flintlocke sticks one of the grease-smeared engine parts into his mouth.>\n\nYep, perfect." }
WordHunterWoW_QuestEN[27434] = { title = "The Adept's Path", description = "Your time as an apprentice has come to an end, {name}. You are ready to advance to the rank of adept, to become a full blood knight in service to Silvermoon.\n\nTo honor your accomplishments, the warchief has commissioned his personal smith to forge a weapon for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and recover the holy symbol of Commander Springvale, a supply of moonsteel ingots, and sinew from the ghouls and geists there.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 crates of Moonsteel Ingots, and 5 Deathless Sinew.", progress = "Did you bring the materials I'll need for your weapon?", completion = "I don't know how you came by such a large supply of moonsteel, <name>, but I haven't worked with it in years. It will be both a challenge and a pleasure to create this weapon for you." }
WordHunterWoW_QuestEN[27435] = { title = "A Seer's Staff", description = "Your skills have grown and you are now ready to become a full seer. You have completed your early training with skill and dedication.\n\nTo mark this occasion, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Seer Liwatha mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. I see now why she sent you there. Even the twisted magics gripping the keep could not extinguish the power of these items." }
WordHunterWoW_QuestEN[27436] = { title = "A Seer's Staff", description = "Your skills have grown and you are now ready to become a full seer. You have completed your early training with skill and dedication.\n\nTo mark this occasion, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Shadow-Walker Zuru mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. Artifacts from the keep are reputed to possess much hidden power and your efforts are proof that the tales are true. Your staff will be a masterwork." }
WordHunterWoW_QuestEN[27437] = { title = "Forsaken Faith", description = "You have been a diligent student and servant to our cause. Always use your talents in accord with Lady Sylvanas's wishes and you will be blessed by the shadow.\n\nOur queen has arranged for Orgrimmar's master enchanter to create a powerful staff to recognize your service.\n\nThe materials you will need only come from Shadowfang Keep in the heart of Silverpine Forest. Find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Dark Cleric Cecille mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. I see now why she sent you there. Even the twisted magics gripping the keep could not extinguish the power of these items." }
WordHunterWoW_QuestEN[27438] = { title = "The Great Escape", description = "With our mission objective secured, the time has come for us to make our escape. Though Gilneas is lost, with the aid of Godfrey and his lieutenants we will have it back in no time at all.\n\nGo now, {name}. Fly back with Arthura to the Forsaken Front in southern Silverpine Forest. The Banshee Queen awaits your arrival.", objectives = "Escape the Ruins of Gilneas with Arthura and the corpse of Lord Godfrey.", completion = "I had no doubt that you would succeed, <name>. I hope you can understand why I kept the true purpose of your mission a secret. Should Crowley and Bloodfang have found out about our plan, they would have surely gotten to Godfrey first and disposed of the body.\n\nStand by, <name>. The time of their rebirth is at hand." }
WordHunterWoW_QuestEN[27439] = { title = "Staff of the Light", description = "You are quickly becoming a talented servant of the Light and of Silvermoon, {name}. Your loyalty to our people and to the Horde are exemplary.\n\nIn recognition of your dedication, the warchief has commissioned his master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "Tyelis mentioned that you were visiting Shadowfang Keep to find the materials for your new staff. Few would venture into the keep, even to retrieve such valuable things. Your new staff will be a fitting reward for your bravery." }
WordHunterWoW_QuestEN[27440] = { title = "Trolls, Ogres, and Orcs, Oh My!", description = "The black dragonkin Overlord Wyrmthalak oversees the forces of the Lower Spire, who are nearly prepared to launch a full assault on the Dark Iron Dwarves far below. We simply cannot allow the black dragonflight to gain control of the mountain!\n\nYou must kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Their deaths will cause the army's momentum to grind to a halt and will buy us valuable time.", objectives = "Kill War Master Voone, Highlord Omokk, and Overlord Wyrmthalak.", progress = "These are not mindless beasts you are up against, <race>. It is a massive army backed by the ruthless black dragonflight. Exercise caution in these corridors.", completion = "Pardon my saying so, but I am surprised you completed the task set out before you alive. Those monsters were responsible for the deaths of countless thousands, a great many of them heroes still spoken highly of to this day.\n\nYou have earned my respect and a reward for your courage." }
WordHunterWoW_QuestEN[27441] = { title = "A Seer's Staff", description = "I hear that word of your deeds in service to the Horde has even reached the ears of the warchief. He has agreed to allow Orgrimmar's master enchanter to create a staff for you.\n\nThe cursed Shadowfang Keep in Silverpine Forest is the only place to get the materials you'll need. Travel there and find the lost holy symbol of Commander Springvale, a supply of moontouched wood, and the essence of the ghosts that haunt the keep.", objectives = "Go to Shadowfang Keep and obtain the Commander's Holy Symbol from Commander Springvale, 5 bundles of Moontouched Wood, and 5 Ghostly Essence.", progress = "Did you bring the materials I'll need for your weapon?", completion = "You must be the <class> that Brother Silverhallow mentioned. Welcome, <name>. Let me see those materials you gathered from halfway around the world. They seem well worth the travel and you will not be disappointed with your staff." }
WordHunterWoW_QuestEN[27442] = { title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Farseer Krogar at the Western Earthshrine in Orgrimmar for further instructions.", objectives = "Speak to Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Your aid is most timely, <name>." }
WordHunterWoW_QuestEN[27443] = { title = "The War Has Many Fronts", description = "We find ourselves in a much better position against our enemies in Vashj'ir than before you arrived.  Don't get me wrong, your aid is still needed here, but perhaps other fronts are in an even more urgent situation.\n\nI've been informed that our allies in the Earthen Ring have put out a call for aid in a matter I've been assured is most critical.\n\nSpeak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City for further instructions.", objectives = "Speak to Earthspeaker Naraat at the Eastern Earthshrine in Stormwind City.", completion = "Your aid is most timely, <name>." }
WordHunterWoW_QuestEN[27444] = { title = "The False Warchief", description = "Rend Blackhand was the son of an Orc Warchief. His father was slain by Orgrim Doomhammer, who became the new Warchief over the young orc. Rend now stands as the supposed leader of a false Horde of Blackrock orcs, backed by Nefarian and his army of dragons.\n\nThe fool claims that the Horde is also his by birthright, and threatens to take it by force! We cannot allow this to occur in light of his master's influence. Find him in the Upper Spire and bring an end to the false warchief, <class>.", objectives = "Kill Warchief Rend Blackhand.", completion = "You saw Nefarian when you fought Rend?\n\n<Acride sighs.>\n\nI wish I had accompanied you, then. I could have faced him unaware, outside his lair...but no matter. Nefarian will die by my claw.\n\nYou've done well." }
WordHunterWoW_QuestEN[27445] = { title = "General Drakkisath, Hand of Nefarian", description = "Nefarian makes his domain further up the mountain in Blackwing Lair. Though there is a way in through the Upper Spire, we may bring a far larger force if we use the teleportation orb close by. However, we cannot teleport until we brand ourselves with a different orb.\n\nDrakkisath, General of Nefarian's armies, personally guards this second orb. Eliminate him and secure his orb for our use. You will find him in the Spire Throne within the Upper Spire.", objectives = "Kill General Drakkisath.", completion = "Excellent! It is only a matter of time before the son of Deathwing feels my claws." }
WordHunterWoW_QuestEN[27446] = { title = "Tanaris is Calling", description = "Heya, {name}, Kelsey Steelspark down in Tanaris left a message for you. She says that the gnomes down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.", objectives = "Speak with Kelsey Steelspark at Gadgetzan in Tanaris.", completion = "Greetings and salutations, friend. Welcome to Tanaris!" }
WordHunterWoW_QuestEN[27447] = { title = "Tanaris is Calling", description = "Heya, {name}, Megs Dreadshredder down in Tanaris left a message for you. She says that the goblins down there in Gadgetzan heard about what you've been doing up here.\n\nAnyway, the Cataclysm hit them hard, too. Not as hard as us, but I'm certain they could use your help.\n\nBesides, that Megs is a hottie!", objectives = "Speak with Megs Dreadshredder at Gadgetzan in Tanaris.", completion = "Well hello there, <class>. Welcome to Tanaris!" }
WordHunterWoW_QuestEN[27448] = { title = "The Trek Continues", description = "I believe the horses are ready.  Argus Highbeacon, the gentleman who works with the Argent Crusade, spoke with me earlier.  I understand he will be coming with us... that's great!  I'll make room for him.\n\nI know that you are busy, so there's no hurry.  Whenever you're ready, hop into the caravan, and we will proceed to the next tower.", objectives = "Board Fiona's Caravan when you are ready to move to the next tower.", progress = "Once we get to Light's Shield Tower, the boys can head over to Light's Hope Chapel.  It's close enough that they can walk.", completion = "We've enjoyed having you ride with us, <name>.  Hopefully, once Gidwin and Tarenar join the Argent Crusade, we can continue to travel together." }
WordHunterWoW_QuestEN[27449] = { title = "Honor and Strength", description = "My name is Vex'tul, and I have watched you fight, {race}.  You are strong.\n\nYou killed my master, Zaeldarr, but this does not bother me.  I value strength over any loyalty that I held for him.  I value strength over anything else.\n\nProve to me one final time your strength, {race}.  Do so, and I will lend you MY strength for whatever purpose you may desire.", objectives = "Pass Vex'tul's test of strength.", progress = "Honor means nothing.  Strength is everything.", completion = "Yes, you are indeed strong... and I submit to you.\n\nI will join you and your friend, the worgen.  My strength is yours." }
WordHunterWoW_QuestEN[27450] = { title = "Frederick's Fish Fancy", description = "I love the sea.  Yes, it was I, Frederick Calston, who introduced the sea life to that lake in the southwest.  I had hoped to provide the Crusade with a source of fresh food from within the borders of the Plaguelands.\n\nHowever, some of the fish turned out to be predators, and they now terrorize the other animals.  If we're not careful, they will kill them all!\n\nSwim down to the bottom of the scar and save some snails, crabs, and pufferfish before it's too late.", objectives = "Obtain 8 Plague Puffers, 8 Infectis Inchers, and 8 Infectis Scuttlers from the Infectis Scar.", progress = "Did... did you bring the fish?", completion = "Hmm... they didn't survive the trip out of the water as well as I had hoped.\n\nOh well!  Seafood salad for Frederick tonight!" }
WordHunterWoW_QuestEN[27451] = { title = "To Kill With Purpose", description = "Greetings, stranger!  You've entered the heart of the Plaguelands.  I hope you brought your undead-killing gear with you.\n\nThe plague spreads more slowly these days, so the Cult of the Damned has stepped up production in order to keep the land brown and dead, as they like it.  I've got a plan to stop them.  Take my mortar and pestle, and use it on living rot from the undead creatures in Corin's Crossing to the southeast.  We're going to make a little present for the cultists!", objectives = "Travel to Corin's Crossing to the south and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", progress = "How are things looking in Corin's Crossing?", completion = "Hello!  It's me.  Hope you don't mind a little home-brewed magic to allow me to communicate with you in the field.  It'll save us both some time.\n\nWe're going to incorporate that living rot into a mixture that'll ruin their next batch of plague.  That'll show them!" }
WordHunterWoW_QuestEN[27452] = { title = "Dark Garb", description = "Some of my counterparts have told me that the land wants to heal, but several high-ranking undead - along with the Cult of the Damned - are not allowing it to.  That means we have to stop them!  I've got a plan, but first, you're going to need a cultist disguise.\n\nHead southeast into Corin's Crossing, and take the clothing from the human cultists that roam through the town.  I'll contact you when you've completed this step.", objectives = "Obtain Death Cultist Headwear and Death Cultist Robes from cultists within Corin's Crossing.", progress = "Everything going alright so far, <name>?", completion = "You've got both pieces!  Good.  These will help when trying to sneak into their death camp." }
WordHunterWoW_QuestEN[27453] = { title = "Catalysm", description = "Coagulated rot is potent on its own, but we need something to activate its concealed powers... a catalyst.  You can find just such a catalyst to the south, in Lake Mereldar.\n\nIf you look down, you'll notice that I slipped a set of flasks into your bags while you weren't looking.  These flasks can be used on the water elementals in the lake.  The living, corrupted water that flows through their bodies will be the perfect catalyst!", objectives = "Use Betina's Flasks on living elementals within Lake Mereldar to obtain 8 Active Liquid Plague Agents.", progress = "We're nearly ready to strike, <name>.", completion = "Uh oh... it looks like we may have gathered a little too much coagulated rot.  Oh well, we'll just have to improvise, then!\n\nWhat could possibly go wrong?" }
WordHunterWoW_QuestEN[27454] = { title = "Just a Drop in the Bucket", description = "Now, mix a tiny amount of rot into the water, and mix thoroughly.  There, that's it.  This solution will still be very powerful, and we only need a little bit of it.\n\nOn the lake's southeastern border, you will find a plague cauldron with several cultists nearby.  Put on your cultist disguise, then approach the cauldron and put in ONE DROP of the solution you made.  No more, or you may risk your very life!", objectives = "Use your Death Cultist Disguise to enter the Death Cultist Base Camp, then put Betina's mixture into the Mereldar Plague Cauldron.", completion = "It should take them weeks to get their operation running again.  Thank you, <name>." }
WordHunterWoW_QuestEN[27455] = { title = "Boys Will Be Boys", description = "As soon as we arrived here at Light's Shield Tower, those two lunkhead paladins ran off to Light's Hope Chapel.  It's still a ways away, but if we're going to follow Argus along his tour of the towers, this is about as close as we're going to get.\n\nCheck in on them and make sure they're alright?  I know they can handle themselves, but still, it'd make me feel better to know that you were watching over them while I'm stuck here with the caravan.", objectives = "Find Gidwin Goldbraids at Light's Hope Chapel in Eastern Plaguelands.", completion = "I can't believe it.  We're literally FEET away from becoming sworn members of the Argent Crusade.\n\nWe'd be in there already if it weren't for Tarenar's dallying.  If he doesn't quit chatting with the locals soon, I'm going to head in there myself." }
WordHunterWoW_QuestEN[27456] = { title = "Gathering Some Grub(s)", description = "We have problems maintaining our food supplies here in the far east.\n\nAround here, the only manner of beast unaffected by the ravages of the plague are the carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. We will need several hundred more pounds to be fully-stocked.\n\nWhile you can find carrion worms all over the Plaguelands, they can be found in particularly high density to the south of the chapel.  And remember: larger worms mean more meat.", objectives = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest 15 Slabs of Carrion Worm Meat.", progress = "You will grow to tolerate the taste, <race>.  I did.", completion = "May the Earthmother watch over you! Bless you, young one." }
WordHunterWoW_QuestEN[27457] = { title = "An Opportune Alliance", description = "With your contributions to the food stores, my current assignment is complete.\n\nI will be heading north, to the Plaguewood, next.  I understand you may be headed in the same direction.\n\nDo you mind if I join you on the road?\n\nI will head northwest, to Eastwall Tower.  If you're interested in teaming up, you can meet up with me there.", objectives = "Check in with Fiona at Eastwall Tower in Eastern Plaguelands.", completion = "You brought us a shaman!  From the Earthen Ring, no less!\n\nI have no idea how we'll fit him in the caravan, but we'll find a way.  Welcome aboard, Rimblat Earthshatter!" }
WordHunterWoW_QuestEN[27458] = { title = "Smokey and the Bandage", description = "Hey there!  Interested in makin' a buck?\n\nI need to get a bandage.  Well, actually, I got a friend who needs to get a bandage.  Well actually... let's just say it's complicated, but if you go get this bandage, you make money.  And so do I.  And my friend.  Possibly other people.\n\nStephen Browman used to own the mill to the north, now he's dead.  A zombie.  The guy at the top wants to have the wrappings from Browman's body.\n\nWhat's the matter, you don't like money?", objectives = "Obtain Browman's Wrappings from Stephen Browman at Browman's Mill.", progress = "You've been fightin' undead.  Did ya find Browman?", completion = "Well well well!  Someone who goes and gets things done!  Here's your cut, chief.  I'll be seein' you around." }
WordHunterWoW_QuestEN[27459] = { title = "The Brotherhood of Light", description = "The Brotherhood of Light has a history of brash, thoughtless decisions.  They bridged a gap between the Scarlet Crusade and the Argent Dawn.  They were among the first to plunge into Northrend, while many of us lingered behind.\n\nHowever, they also have a history of getting results, which I respect.  They fight on two fronts now: one battle in Stratholme, and another, more immediate battle to the south at Tyr's Hand.\n\nI suggest you speak with Angela Dosantos at Tyr's Hand.  You may be of service.", objectives = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "A <class>!  Just what we needed.  Your arrival couldn't have been more timely." }
WordHunterWoW_QuestEN[27460] = { title = "Soft Landing", description = "We were only given one hundred men to complete this mission, and we're already down by one.  Our scout was sent into the enemy stronghold to clear out some of the guards that patrol the area, and to send off a flare so we could enter with a coordinated attack.  Our ninety-nine remaining men lie at the ready, waiting for that flare.  I need a talented {class} like you to sneak into Tyr's Hand, take out as many of their guards as possible, and then set off that flare.\n\nAre you up to it?", objectives = "Kill any 10 Scarlet Crusade creatures within Tyr's Hand.", completion = "The flare is fully assembled, and the matches lie unused next to the fuse.\n\nThe fallen Argent centurion got much closer to setting off this flare than you had guessed." }
WordHunterWoW_QuestEN[27461] = { title = "To Take the Abbey", description = "The Scarlet Crusade maintains a well-fortified abbey in the lower western tier of Tyr's Hand.  The abbey will need to be secured before proceeding any further into the stronghold.", objectives = "Report to Commander Eligor Dawnbringer outside the abbey at Tyr's Hand in Eastern Plaguelands.", completion = "Well met, <name>.  Can I trust you to assist me in taking this abbey away from these abominations?" }
WordHunterWoW_QuestEN[27462] = { title = "To Take the Barracks", description = "One of the key fortifications within Tyr's Hand is the barracks, which lies right next to this flare.  The Brotherhood of Light and their centurions will need all the help they can get in sacking it.", objectives = "Report to Crusade Commander Korfax in front of the Barracks at Tyr's Hand in Eastern Plaguelands.", completion = "I'll be handling things from here, <class>.\n\nFine, you want an assignment?  I suppose I can afford to send you in on a mission or two." }
WordHunterWoW_QuestEN[27463] = { title = "A Boyhood Dream", description = "I've always wanted to join the Crusade.  It's the reason I became a paladin.  Years of practice, honing my craft... I'm finally ready.\n\nTarenar thinks he's ready, too, but I'm not sure.  He's a bit of a showboat, and he never took his lessons seriously.  Still, we promised we'd do this together, and here we are.\n\nShall we head into the chapel now?", objectives = "Speak with Lord Maxwell Tyrosus within Light's Hope Chapel.", completion = "Welcome to Light's Hope Chapel.\n\nYou wish to join the Crusade?  Very well.  We have plenty of tasks for new recruits.\n\nBut first, a test." }
WordHunterWoW_QuestEN[27464] = { title = "Argent Call: The Trial of the Crypt", description = "Behind our chapel, you will find a small crypt.  Interred within are the bodies of our fallen heroes; those who gave their lives in the war against the Scourge.\n\nTheir spirits are at peace, but they return intermittently to test new members of the order.\n\nThe three of you may test together.  Enter the crypt, then read from this scroll.  Lord Raymond George - my predecessor - will preside over your test.", objectives = "Enter the Crypt behind Light's Hope Chapel, read from the Argent Scroll, then complete his test.", progress = "Your test is not yet complete.", completion = "Remember that your ancestors always watch over you.  As a brother of the Argent Crusade, you will join a family that has a long line of such fallen ancestors.  Their vigil and protection will be your strength as you press forward against the Scourge.\n\nCongratulations Tarenar, Gidwin, and <name>.  Welcome to the Argent Crusade." }
WordHunterWoW_QuestEN[27465] = { title = "Argent Call: The Noxious Glade", description = "Browman's Mill, to the north, is infested with undead.  The Noxious Glade, even farther to the north, is even more heavily infested.  Despite their proximity to our chapel, we have been unable to completely remove them.\n\nVigilance is key.  Travel into the Noxious Vale and slay as many undead as you can find... and the cultists that roam among them.\n\nWhile there, make sure to avoid Garginox, the flesh giant that roams the vale.  I suspect you are not strong enough to defeat him.", objectives = "Slay 16 Scourge and 8 Cultists within Browman Mill and the Noxious Glade. Return to Light's Hope Chapel if Tarenar or Gidwin is slain.", completion = "You've returned sooner than I expected.  Excellent.\n\nWe will continue our path into the north.  Next, you will be completing a similar task - this time, in Northdale." }
WordHunterWoW_QuestEN[27466] = { title = "Argent Call: Northdale", description = "Tyrosus has given us our next task: slaying more undead in Northdale.  Gidwin is excited to move forward, but I think we should show a little more caution.\n\nLet's meet up with Fiona.  She should be at the next tower by now... Eastwall Tower, I think it's called.  It's close by, to the northwest of Light's Hope.  We can rest there, and plan our attack on Northdale.", objectives = "Speak with Fiona at Eastwall Tower in Eastern Plaguelands.", completion = "Hello, <name>!  Glad to see you've rejoined the caravan!\n\nTarenar and Gidwin arrived here before you.  Tarenar's just right there, and Gidwin's... well... he's in a little bit of a mood right now.  I think he's in the tower." }
WordHunterWoW_QuestEN[27467] = { title = "Buried Blades", description = "The Noxious Glade is a quagmire, both literally and figuratively.  There's enough Scourge up there to give us trouble for the rest of both of our lifetimes.\n\nThey can re-animate the weaker ones when they die, {name}.  They will never stop coming if we don't do something.\n\nTake these blades and drive them through the corpses of any Scourge troopers you find.  The blade is simple, but its enchantment will prevent the dead bones from being reanimated.  Forever.", objectives = "Bury the Light-Touched Blades in the bodies of 10 Slain Scourge Troopers.", completion = "Our duty for the day is done.\n\nIt is only a matter of time before we defeat the Scourge.  Today, we made progress." }
WordHunterWoW_QuestEN[27468] = { title = "Siege Tank Rescue", description = "One by one, we're gonna have to pull our siege tanks outta the muck. Take these 'ere spare parts you've collected and give 'em to a siege tank commander who's perched on one o'those banged-up machines.\n\nThen defend the tank while engineers repair the blasted thing.\n\nGo an' make me proud, {class}!", objectives = "Speak with a Siege Tank Commander standing on top of a wrecked Highbank Siege Tank. Defend the tank while engineers make repairs.", progress = "Rocks an' stumps an' hills an' mud... Bah.\n\nI hate nature.", completion = "Yep, one more tank limpin' back home for repairs.\n\nAll these trees an' stumps an' mud an' rock - you couldnae drive a golfball into this turf, much less a tank.\n\nWe're gonna need a new approach." }
WordHunterWoW_QuestEN[27469] = { title = "Friends on The Other Side", description = "I come with news from Blackrock Spire. We have a new visitor. His name is Acride.\n\nHe seeks people of strength, people of intelligence, of dexterity. You ought to go to Blackrock Spire and speak with him.", objectives = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nI'm sorry, who sent you? I'm afraid I've never heard of such a dwarf." }
WordHunterWoW_QuestEN[27470] = { title = "A Potential Ally", description = "It is no secret that we aren't fans of the orcs in Blackrock Mountain, but we do carefully watch their every move. Nothing happens in that Mountain without me knowing about it, {class}.\n\nRecently, a different sort of orc came into Blackrock. He resides just inside Blackrock Spire, and I know he's somehow planning to overthrow Nefarian and his whole army of orcs. Normally I wouldn't trust their kind, but we share a common goal for the time being. Find him, he's called Acride.", objectives = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nSo Overseer Oilfist sent you? Listen carefully, we have much to discuss in little time." }
WordHunterWoW_QuestEN[27471] = { title = "Blackrock Anomaly", description = "There is an orc inside Blackrock Spire much unlike the others. He speaks with the intelligence and wisdom of one beyond his appeared years, and does not fight against our soldiers like the others do.\n\nYou must travel northwest to Blackrock Spire and find this orc, known only to us as Acride. Perhaps he is the key to stopping the orcish army. Perhaps we can stop Nefarian before it is too late...", objectives = "Find Acride.", completion = "Hello, what is your business in a place like this?\n\nSo you come at the will of Miss Brightwing, do you? Very interesting indeed." }
WordHunterWoW_QuestEN[27472] = { title = "Rise, Godfrey", description = "You are unwavering in your loyalty to the Forsaken, {name}. Know that what you have done for us - for the Horde - will not go unnoticed. With Lord Godfrey and his men recovered, we will have a great advantage over the Gilneas Liberation Front and the rest of the Alliance dogs.\n\nNow stand by my side as Lord Godfrey is reborn as one of us. Together we will bring him and his men into the fold.", objectives = "Stand by Lady Sylvanas Windrunner as she initiates Lord Godfrey and his men.", completion = "Today marks a new beginning for the Forsaken and the end of the Alliance in Lordaeron!" }
WordHunterWoW_QuestEN[27473] = { title = "What's Shaking in Ironforge", description = "Things have grown worse in Ironforge, {name}.  Please, speak with Stormcaller Mylra in Ironforge and see if you can lend a hand in some way.", objectives = "Speak with Stormcaller Mylra in Ironforge.Things have grown worse in Ironforge, <name>. Please, speak with Stormcaller Mylra in Ironforge and see if you can lend a hand in some way.", completion = "It is good that you've come, <name>.  We need all the help we can get with the situation here." }
WordHunterWoW_QuestEN[27474] = { title = "Breaking the Barrier", description = "While Godfrey and I make preparations for our assault upon Gilneas, I want you to lead our attack upon Ambermill, directly east of here.\n\nThe former Dalaran magi of Ambermill have erected a magical barrier that somehow cloaks them from vision. They currently reside within some type of pocket dimension, awaiting orders from the Alliance to begin their attack. We must prevent their assault by making a pre-emptive strike. Venture to Ambermill and find information that would grant us access to the mages.", objectives = "Find the Ambermill Codex.", progress = "Have you found anything yet?", completion = "Clever mages. The codex is sealed by a magical ward.\n\nPity that they weren't clever enough to realize that former archmages of Dalaran are now Forsaken." }
WordHunterWoW_QuestEN[27475] = { title = "Unyielding Servitors", description = "The magi of Ambermill have employed foul magic to keep us away. Elemental servitors, created with immunities that we cannot breach, protect their territory.\n\nVenture east to Ambermill and slay the unyielding elemental servitors that guard the town and recover their cores. Bring their cores back to me so that I may devise a method by which we are able to destroy them all!", objectives = "Retrieve 6 Servitor Cores.", progress = "Have you recovered the servitor cores?", completion = "Well done, <name>. The praise the Banshee Queen lavishes upon you is apparently not unfounded." }
WordHunterWoW_QuestEN[27476] = { title = "Dalar Dawnweaver", description = "Take the codex and travel north to the Sepulcher. Once there, find Dalar Dawnweaver. Dalar is a former archmage of the Kirin Tor. Surely he will be able to bring down the protective wards surrounding this codex and pry its secrets loose.\n\nHurry, {name}.", objectives = "Deliver the Ambermill Codex to Dalar Dawnweaver at the Sepulcher in Silverpine Forest.", progress = "Yes? What is it?", completion = "The Dark Lady requires my expertise? Well of course! Give it here, boy." }
WordHunterWoW_QuestEN[27477] = { title = "The Corpulent One", description = "North of here and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor.  Borelgore has been known to devour others who tried to hunt him.", objectives = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him.", completion = "Keep this up and I may have to keep you here at Eastwall, <race>." }
WordHunterWoW_QuestEN[27478] = { title = "Relios the Relic Keeper", description = "The Dark Lady is correct in her assertion that I am able to unlock the codex. Unfortunately, I need a signet ring from a Dalaran archmage to do it. My own ring was taken when I died many years ago, but there still might be a way.\n\nWhile Dalaran has floated away, the outskirts of the city remain. Far to the east lie the ruins of Dalaran. It is there that you will find an archmage known as Relios. \"Take\" his signet ring and bring it back to me.\n\nYou may use the portal behind me to get to the crater.", objectives = "Find a Dalaran Archmage's Signet Ring.", progress = "Did you recover a Dalaran Archmage's Signet Ring?", completion = "Perfect. I hope this wasn't too much trouble to come by, <name>. Relios was a pupil of mine back when I was a mortal man thereby making him a competent and formidable adversary. I suppose I could have warned you ahead of time.\n\nNow, let us see the ring.\n\n\n\nThere we are..." }
WordHunterWoW_QuestEN[27479] = { title = "Righteous Indignation", description = "The Mossflayers of Zul'Mashar spit in the face of the Light!  They cannibalize, they criminalize, they prioritize the forces of evil over good!  I advise that you remove their eyes, and give rise to the demise and the goodbyes of the unwise!\n\nYou will travel north, and you will rain down on them with righteous justice and indignation, {name}.  The fury that they have wrought in the eyes of the Light shall be channeled through you.", objectives = "Obtain 30 Mossflayer Eyes from Mossflayer trolls in Zul'Mashar.", progress = "<Deacon Andaal is deep in prayer.>", completion = "Oh, hallelujah, and praise, praise be to the Light, my brother!" }
WordHunterWoW_QuestEN[27480] = { title = "Ley Energies", description = "The arcane remnant pulses with strange energy. Perhaps you should search for more remnants. Surely Dalar would be interested in such a find.", objectives = "Recover 8 Arcane Remnants.", progress = "What's that you've got there, <name>?", completion = "Smart boy! I can most definitely use these arcane remnants in my studies. Indeed, Dalaran was built upon a massive ley line. It's no wonder, then, that such things exist at the crater." }
WordHunterWoW_QuestEN[27481] = { title = "Out of the Ziggurat", description = "It is time that I asked a favor of you, {name}.\n\nFar to the north of Eastwall Tower, hidden among the hills, is the Mossflayer capital city of Zul'Mashar.  It was here that I was born, and here that I died.\n\nThe traitor, Thresh'jin, sits atop Zul'Mashar's ziggurat.  It was my every right to be there, but he took the seat from me with treachery and deceit.  He is not strong.  He is weak.\n\nI will meet you in Zul'Mashar, and we will kill him.  Your strength and mine.  Together.", objectives = "Obtain the Body of Warlord Thresh'jin.", progress = "I have waited long for this day.", completion = "My duty is not over yet.  In many ways, this was the easy step." }
WordHunterWoW_QuestEN[27482] = { title = "Into the Flames", description = "This is the last time you will see me, {name}.  I am leaving the caravan.\n\nIf you want to continue fighting by my side, hang on to Thresh'jin's body.  I can wait for a while longer.  When you are ready to say goodbye, throw the body into the bonfire atop Zul'Mashar's ziggurat.\n\nThank you for your companionship, {name}.  You were strong.", objectives = "When you are ready to part with Vex'tul, throw Warlord Thresh'jin's body into the bonfire atop Zul'Mashar's ziggurat." }
WordHunterWoW_QuestEN[27483] = { title = "Practical Vengeance", description = "Under ordinary circumstances I am not a vengeful man. In fact, I am somewhat of a pragmatist. You see, practicality is a paradoxical notion to vengeance. Most revenge ploys are highly impractical.\n\nBUT... in this case - since you're already going to the ruins of Dalaran - you might as well kill every Dalaran affiliated human that you see. The reasons that I want them dead range from hatred to anger to betrayal, but I assure you they are all legitimate gripes. Do this for me and I will pay you handsomely.", objectives = "Kill any 12 Dalaran humans.", completion = "I thought for sure that with the death of a dozen of my most hated enemies I would feel a great burden lifted from my shoulders. Sadly, I do not feel a thing. Perhaps I am a psychopath." }
WordHunterWoW_QuestEN[27484] = { title = "Only One May Enter", description = "<Dalar flips through the codex.>\n\nHAHAH!\n\nOh... That's bad.\n\n<Dalar closes the codex and looks up at you.>\n\nWith this ring only ONE may enter the pocket dimension at Amber Mill. That person will then need to fight through an army of magi and kill the archmage that is generating the phase from the inside. Only then will the dimension fold, ejecting all of the magi.\n\nThe portal to entry is hidden at the back of a cave in Beren's Peril.\n\nThat's all I know. Take the ring back to Sylvanas.", objectives = "Take the Dalaran Archmage's Signet Ring to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", progress = "What have you learned?", completion = "Only one may enter? I know just the person for this mission.\n\n<Sylvanas nods at you.>\n\nI will prepare our forces and have them at the ready." }
WordHunterWoW_QuestEN[27485] = { title = "Warm Welcome", description = "I'm glad you're back! Saving the world or something, I'm sure.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nCare to take a crack at earning a bit of trust with Lirastrasza at Vermillion Redoubt to the southwest? Anything that might soften her up a bit for me would be lovely.", objectives = "Meet with Lirastrasza at Vermillion Redoubt.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous." }
WordHunterWoW_QuestEN[27486] = { title = "Warm Welcome", description = "Good. You're back. Saving the world again I assume.\n\nI was dispatched to establish relations with the red dragons in the area, but I'm finding this bunch somewhat less accommodating than the ones at Wyrmrest were. I have, however, been told that you are the type that solves problems.\n\nA problem solver as it were.\n\nI need you to gain the trust of Lirastrasza at Vermillion Redoubt to the southwest. Our association with the Dragonmaw has complicated things, but I'm hoping you can ease relations.", objectives = "Meet with Lirastrasza at Vermillion Redoubt.", progress = "I believe Lira wanted a word with you.", completion = "I'm glad Lira didn't scare you off. I won't say her concerns aren't warranted, but we have a common enemy. She is perhaps a bit overzealous." }
WordHunterWoW_QuestEN[27487] = { title = "Ix'lar the Underlord", description = "I know we're supposed to head to Northdale, but that can wait, right?  Besides, this lovely little goblin was just telling me about some Scourge that are even closer by.\n\nSo apparently there's this nerubian underlord named Ix'lar that has been trying to make a name for himself ever since the Lich King was slain.  He's set up a camp of undead to our north.\n\nSure, Tyrosus wants us to kill banshees in Northdale.  We'll get to that.  But let's kill this nerubian first, while we're close!", objectives = "Kill Ix'lar the Underlord and 10 of his minions.", completion = "I couldn't stop him.  While you and Tarenar were out, Giddy ran north all alone!\n\nTarenar, you should have known better!  Gidwin gets so impatient sometimes, and you only egg him on.  If Giddy gets into any trouble, I'm blaming you for this." }
WordHunterWoW_QuestEN[27488] = { title = "Impatience", description = "Damn that dwarf.  He's always getting me in trouble with Fiona.  Look at her!  She won't even TALK to me!\n\nI'm going to stay here and try to mend my friendship with our worgen friend.  Would you mind going out and making sure Gidwin is alright?  I'm sure he's fine; he knows how to take care of himself.  He headed north, and he can't have gone far.", objectives = "Search for Gidwin Goldbraids in Northdale.", progress = "Northdale is home to a few ghosts and banshees.  Nothing ol' Giddy can't handle.", completion = "You didn't see him?  Where could he have gone then?\n\nHis... his prayer book?  Why would he leave that behind?\n\nOh...\n\nBy the Light, what have I done?" }
WordHunterWoW_QuestEN[27489] = { title = "Nobody to Blame but Myself", description = "This is my fault.  I... I ignored his warnings, his complaints, everything.  I couldn't help myself - I saw those Scourge just beyond the tower, and I... I HAD to go kill them.\n\nArgus says that Gidwin was taken northwest, and that's our only lead, so that's where we'll head.\n\nNorthdale and the Argent Crusade be damned!  We're getting Gidwin back from those Scourge trash.", objectives = "Hop in Fiona's Caravan and ride to Northpass Tower.", progress = "We have no time, <name>!  We must press on!", completion = "Time is wasting, <name>.  Every minute we waste gives the Scourge another chance to kill Gidwin.  If he isn't dead already.\n\nNot that I think he is.  Giddy may be a stick-in-the-mud, but when it comes down to it, he can swing the Light like a champion." }
WordHunterWoW_QuestEN[27490] = { title = "SI:7 Drop", description = "Mathias Shaw and the SI:7 are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nThe Wildhammer are being kind enough to give us a lift in. The agents have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with Angus Stillmountain and get yourself a squad to drop off. You'll fly them in. A big blue X marks the spot.", objectives = "Get a Wildhammer Hellions squad from Angus Stillmountain and then escort them to the drop off point in the Twilight Gate.", progress = "I need you to escort those SI:7 agents safely to their destination, <name>.", completion = "That must have been deadly.\n\nWhile I don't approve of their methods, no one can question the effectiveness of Master Mathias Shaw and his SI:7. Not to mention that you're here. Our victory is all but assured." }
WordHunterWoW_QuestEN[27491] = { title = "Kor'kron Drop", description = "Garona and a detachment of the Kor'kron are here to assist us with operations up top in the Twilight Citadel. I need you to escort them there.\n\nI've called upon a local tribe of trolls to give us a lift in with their wind riders. The assassins have some things that they need to do down in the Twilight Gate area first, though.\n\nSpeak with the troll chief, Jon-Jon Jellyneck and get yourself a detachment of Kor'kron to drop off. You'll fly them in. A big red X marks the spot.", objectives = "Get a Crushblow Wind Rider squad from Jon-Jon Jellyneck and then escort them to the drop off point in the Twilight Gate.", progress = "I need you to get those Kor'kon assassins safely to their destination, <name>.", completion = "That must have been exciting.\n\nDespite any losses that the Kor'kron may have incurred along the way, no one will be able to doubt their effectiveness, nor that of Garona. And with you in the mix, it's only a matter of time before victory is ours." }
WordHunterWoW_QuestEN[27492] = { title = "Ogres & Ettins", description = "As with any offensive, you first need to soften them up. We've been having a heck of a time getting in there. But someone like you... well, let's just say I have no doubt in my mind that you can get into the Twilight Gate to the southwest and teach the Bloodeye Clan ogres and ettins a thing or two!", objectives = "Slay 10 ogres or ettins at the Twilight Gate.", progress = "What's the matter? You Alliance boys don't have the stomach to get the job done?\n\n<Kurdran gives you a wink.>\n\nNeed me to fly over there and kill them for you?", completion = "That's the spirit, lad! Today's already shaping up to be a good one." }
WordHunterWoW_QuestEN[27493] = { title = "Ogres & Ettins", description = "I want you to get in there past those boulders to the northwest at the Twilight Gate. Kill every Bloodeye Clan ogre and ettin in sight. Think you can handle that for me, {name}?", objectives = "Slay 10 Bloodeye Clan ogres or ettins at the Twilight Gate.", progress = "There are more to be killed, tauren. You do have the stomach for that, yes?", completion = "And here I thought that today couldn't get any better.\n\nI enjoy being wrong, occasionally." }
WordHunterWoW_QuestEN[27494] = { title = "Move the Mountain", description = "If the Twilight Gate is to fall, we need to get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your SI:7 agents took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", objectives = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate." }
WordHunterWoW_QuestEN[27495] = { title = "Move the Mountain", description = "If the Twilight Gate is to fall, we must get Skullcrusher the Mountain out of there!\n\nBefore they left, I saw to it that your Kor'kron assassins took some explosives hidden in a Twilight's Hammer crate. By now, they will have planted them on the steps leading up to the upper portion of the Citadel.\n\nI want you to set the explosives off and then signal us when that monster's out of the way.\n\nThat's when we'll attack and finish off the ogre compound!", objectives = "Detonate the Hidden Explosives to lure Skullcrusher the Mountain away from the Twilight Gate." }
WordHunterWoW_QuestEN[27496] = { title = "Call in the Artillery", description = "I prefer a stand up honorable fight. These monsters deserve nothing better than to be destroyed by the weapons in our hands. However, this particular situation calls for the use of more powerful measures.\n\nTake this flare and mark each of the four buildings within the Twilight Gate to the southwest. Our cannons will handle the rest.", objectives = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", completion = "Thanks to you, our cannoneers hit their marks. Tell me about the situation within the Twilight Gate." }
WordHunterWoW_QuestEN[27497] = { title = "Call in the Artillery", description = "A pity that we're no longer allowed to drop the Plague on our enemies. It would prove quite effective in this situation. Oh well, at least we have war machines to destroy their precious gates.\n\nI want you to take this flare. Use it to mark each of the four buildings within the Twilight Gate to the northwest. The war machines will handle the rest.", objectives = "Use the Artillery Flare to target the Northern, Northeastern, Southwestern, and Southern buildings at the Twilight Gate.", completion = "I must say that I rather enjoyed the sight of their buildings being hit." }
WordHunterWoW_QuestEN[27498] = { title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Victor's Point to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate." }
WordHunterWoW_QuestEN[27499] = { title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, it's time to signal your forces at Crushblow to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate." }
WordHunterWoW_QuestEN[27500] = { title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Cassius and Kurdran will want proof of their deaths.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel." }
WordHunterWoW_QuestEN[27501] = { title = "Four Heads are Better than None", description = "Now while the attack upon the Twilight Gate is launched, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nYou're fairly certain that Lady Cozwyn and Zaela will want proof of their deaths.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack? I hope that it's not yours.", completion = "<The noble lady grins wickedly.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel." }
WordHunterWoW_QuestEN[27502] = { title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the SI:7 forces to Master Mathias Shaw.\n\nHe's hiding somewhere up top. The SI:7 squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", objectives = "Speak with the SI:7 Squad Commander and then escort the SI:7 squad." }
WordHunterWoW_QuestEN[27503] = { title = "Up to the Citadel", description = "Now that the attack is underway, it's time to deal with the Twilight Citadel. If you don't mind, I'd like for you to escort the Kor'kron forces up to Garona.\n\nShe's hiding somewhere up top. The Kor'kron squad commander can tell you where.\n\nThank you, {name}. We look forward to joining you in the assault upon the Citadel!", objectives = "Speak with the Kor'kron Squad Commander and then escort the Kor'kron squad." }
WordHunterWoW_QuestEN[27504] = { title = "Even Dragons Bleed", description = "I won't be so impolite as to refuse your aid if you're offering it.\n\nWe're locked in constant battle with the twilight drakes and dragons to the south. Our strikes have not been entirely without success, but the dragons coming out of Grim Batol have been breathing some kind of corruption upon us that takes time to cleanse.\n\nVelastrasza and Baleflame are attending to our injured brothers. Go and see if you can be of help to them.", objectives = "Speak to Velastrasza within the Vermillion Redoubt.", completion = "Calen has become very trusting. It is not often that strangers are permitted within the redoubt." }
WordHunterWoW_QuestEN[27505] = { title = "Draconic Mending", description = "Our dragons are returning from battle covered in Twilight corrupted flame and pursued by Twilight drakes.\n\nMy menders can tend to our dragons' wounds, but they must be defended. Keep the drakes off of my menders. Lend your healing to our dragons as well if you are able.\n\nThank you for your help with this. Our battles for Grim Batol are never-ending. We need to get our strongest dragons back into the battle as soon as possible.", objectives = "Safeguard 5 Vermillion Menders as they heal wounded dragons.", progress = "Keep the menders safe as they heal our wounded dragons!", completion = "We will take Grim Batol back from the Twilight's Hammer and thier allies. It may take time, but this is one charge that we cannot forsake." }
WordHunterWoW_QuestEN[27506] = { title = "Life from Death", description = "{race}, I have a task for you.\n\nTake these ruby seeds and plant them at the corpses of any dragonkin that you come across. Twilight or Vermillion, whelping or dragon, it matters not. We need to see that their bodies are returned to the earth so that life can continue to flourish.\n\nIn death, there should always be new life. This may be our one consolation during times of war and great tragedy.", objectives = "Plant Ruby Seeds at the corpses of 6 dragonkin within the Vermillion Redoubt.", progress = "Have you done as I asked?", completion = "In this, we deny Deathwing the destruction that he so passionately seeks. In this, life continues." }
WordHunterWoW_QuestEN[27507] = { title = "Encroaching Twilight", description = "Fragile Twilight invaders litter the redoubt. They're pouring in from somewhere to the west.\n\nThere can be no mercy offered to them within this hallowed place. Whatever violence grips your moral heart, release it upon them.", objectives = "Kill 12 Twilight invaders within the Vermillion Redoubt.", completion = "You have a talent for killing I see. In times like these, that has its place." }
WordHunterWoW_QuestEN[27508] = { title = "Far from the Nest", description = "Look... I know you have no reason to be fond of me, just as I'm not terribly fond of you, but I need any help I can get.\n\nOur eggs are being stolen by these Twilight invaders. I have no doubt that they want to take them back to Grim Batol to experiment on and pervert. I will NOT let that happen.\n\nIf you truly do want to help us, stop them! Recover the eggs. Bring them back to me.", objectives = "Recover 6 Vermillion Eggs.", progress = "Twilight dragons were born of these disgusting experiments of theirs. The Twilight's Hammer have gone too far. Deathwing has gone too far.", completion = "I don't know if you did this for me or the young inside these eggs, but it doesn't really matter, either way it's clear that you want to be an ally of our flight. I appreciate that.\n\nI cannot forgive the attacks by your allies against my brood, but for now, it seems you have chosen the right side." }
WordHunterWoW_QuestEN[27509] = { title = "Breach in the Defenses", description = "Every inch of air and every hill surrounding the redoubt is constantly under the watchful eye of Lira's drakes. They must have found a way into the shrine from beneath.\n\nTake this Flashgrowth mote. It should prove more than sufficient to close any hole, tunnel, or portal they might have used to get inside our defenses.\n\nFind the breach in our defenses. Close it.", objectives = "Find the source of the Twilight's Hammer in the Vermillion Redoubt and destroy it.", completion = "Well done. Thank you, <race>.\n\nI will not be so foolish as to let such an oversight happen again." }
WordHunterWoW_QuestEN[27510] = { title = "A Wolf in Bear's Clothing", description = "These worgen take us for fools! One would think that only an idiot would mistake one of their druids in bear form as a real bear. Unfortunately, there are many idiots here at the Forsaken Front. We've already lost a few battalions to organized worgen bear attacks. Yes, it's even more idiotic than it sounds.\n\nDirectly east of here, heading towards Hillsbrad, you will find worgen druids roaming the woods, masquerading as bears. Kill them and make our southern supply line safe again.", objectives = "Kill 10 Inconspicuous Bears.", completion = "I only hope that we don't end up getting beat down by inconspicuous birds, cats and trees next... or seals. Could you imagine it?" }
WordHunterWoW_QuestEN[27511] = { title = "The Thrill of Discovery", description = "What a find! And somehow it's all remained untouched by plunderers...\n\nListen, {name}. I need to document this site before we disturb anything. While I do, why don't you have a look around - you know, explore a bit. You've earned it.\n\nKeep your eyes open for anything unusual.\n\nOh! And please... don't break anything, ok?", objectives = "Explore the Chamber of the Stars.", completion = "Your exploration of the Chamber of the Stars has yielded more questions than answers..." }
WordHunterWoW_QuestEN[27512] = { title = "Transdimensional Warfare: Chapter I", description = "<Sylvanas hands you the signet ring.>\n\nTake the ring and make your way to Beren's Peril, southeast of here, located in a cave in the hills. Once there, search the cave for the portal to the pocket dimension that conceals the Ambermill magi.\n\nI will communicate with you through your thoughts, {name}. Once you have reached the portal I will give you your marching orders.", objectives = "Find the Ambermill Dimensional Portal.", progress = "<The portal hums.>", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nYes, this is it. Now run the ring along the runes of the portal and you should become attuned for transdimensional travel." }
WordHunterWoW_QuestEN[27513] = { title = "Transdimensional Warfare: Chapter II", description = "<The Banshee Queen's words float in your head.>\n\nYou are now ready to use the portal. Be warned, {name}, once you step through you will appear in another dimension at Ambermill. There will be a hundred, perhaps a thousand, magi waiting to kill you.\n\nYou must persevere and kill all in your path.", objectives = "Kill 20 Ambermill mages.", completion = "<The Banshee Queen's voice invades your thoughts.>\n\nExcellent work, <name>. Now to eject them into our waiting hands!" }
WordHunterWoW_QuestEN[27514] = { title = "Bird Down! Bird Down!", description = "While you were fighting along the coast, I spotted a gryphon tumble out of the clouds almost due west of here.\n\nIt wasn't one of ours.\n\nLikely it belonged to one of the Wildhammer. I know that Kurdran wanted to establish contact with the lost Wildhammer clans as one of his primary objectives after taking the beach. \n\nI can't spare any more of my men to scout it out, but I can spare you. Find that downed Wildhammer!", objectives = "Locate Thordun Hammerblow, a downed Wildhammer gryphon-rider, at the Twilight Shores in Twilight Highlands.", completion = "Aw dang crap it all. You're just an Alliance <class>. I was hoping for a rescue." }
WordHunterWoW_QuestEN[27515] = { title = "Roots'll Do 'Er", description = "Look here, mate. She's on her last legs! If me bird dies, I'm as good as worthless.\n\nSo make yerself useful. Here on the peninsula you can dig up thorny stankroots. Oh the smell will knock you on yer patoot but steeped in water it'll boil up into a right powerful cure-all.\n\nGather some while I defend me bird. An' hurry! You Alliance wanks don't have a reputation for timely intervention, right?", objectives = "Gather 8 Thorny Stankroots from the Twilight Shores.", progress = "Didja get me roots, <class>? Well?", completion = "Oh, that's the stuff all right! Hope ya didn't eat any. Gives you the cramps something awful but it does wonders for birds." }
WordHunterWoW_QuestEN[27516] = { title = "Wings Over Highbank", description = "Aye, look! I think she's perkin' up already.\n\nOkay Mr. Alliance fancy-pants {class}. Is that your base I see on the shore? \"Highbank\" you say. Can me and my bird hunker down there until she's better?\n\nHop on! We'll fly together back to Highbank!", objectives = "Speak with Thordun Hammerblow and fly together back to Highbank.", completion = "Well done, <name>! Aiding that downed gryphon-rider has given us our first contact with the old Wildhammer clans. We'll be able to find out who's still left, and in what numbers.\n\nOur campaign is looking up!" }
WordHunterWoW_QuestEN[27517] = { title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nYou can never have too much of this stuff!\n\nYou resolve to scrounging every scrap of it you can find from the skeletons here.", objectives = "Collect 6 Rope Pieces.", progress = "What have you found, <name>?", completion = "Ahh, rope! Thanks, kid.\n\nSomething tells me I'm going to need this." }
WordHunterWoW_QuestEN[27518] = { title = "Transdimensional Warfare: Chapter III", description = "<Sylvanas speaks directly through you.>\n\nYou must find the being responsible for keeping this dimensional pocket active. Likely that fool, Ataeric... Search the compound for him. Should you find him, do what you must to stop him from channeling his magic. He is undoubtedly protected by a powerful arcane shield, and will send minions of arcane energy after you.  Defeat the minions while they are near him to unleash their energies.  No mage can handle that much power!", objectives = "Overload Archmage Ataeric with arcane power to bring down the Transdimensional Shield.", completion = "Had I not witnessed what you did with my own eyes I would not have believed it, <name>. Now, with the Ambermill magi on our side, there is but one thing left to do before we retake Gilneas and send those Alliance dogs running for Stormwind." }
WordHunterWoW_QuestEN[27519] = { title = "Under the Choking Sands", description = "No... it cannot be.\n\nOrsis is all but buried beneath the desert sands.\n\nThe enemy will pay for this.\n\nBut first we must aid my people.  Quick, {name}.  We do not have much time before the last of my brethren are buried alive!", objectives = "Rescue 8 Orsis Survivors.", completion = "I thank you, <name>.  Orsis was punished for not joining the forces of Deathwing.\n\nPrince Nadun has offered my people refuge in his city.  I must go there and tend the survivors." }
WordHunterWoW_QuestEN[27520] = { title = "Minions of Al'Akir", description = "Al'Akir has sent his minions to do Deathwing's bidding.\n\nThe message is clear.  We join them or they destroy us.\n\nI do not know much about you, {race}.  But I do know this.  If you prove yourself to be an enemy of Al'Akir's, your aid will not go unnoticed.\n\nWhat do you say, {class}?", objectives = "Slay 6 Scions of Al'Akir.", completion = "You continue to prove to be a valuable ally, <name>." }
WordHunterWoW_QuestEN[27521] = { title = "Wretched Hive of Scum and Villainy", description = "{race}... please, I ask your help.\n\nSomething's happened to my people.  Our commander, Ranger Lord Hawkspear, came upon an item of magical energy, and my friends, my family... they succumbed to its seductive power.\n\nThey're corrupted, {race}.  All of them.\n\nMy Ellaria wouldn't want to live like that, nor would any of my brothers.  Please, put them out of their misery.  Quel'lithien Lodge is not far; it's just up the hill, to the northwest.", objectives = "Kill 9 Wretched at Quel'lithien Lodge in Eastern Plaguelands.", progress = "You have no idea how difficult it was for me to pull myself away, <race>.  I nearly ended up one of them.", completion = "Do not feel sorry for me.  Those were my friends that you saw at Quel'lithien Lodge, but they were already as good as dead." }
WordHunterWoW_QuestEN[27522] = { title = "Beat it Out of Them", description = "We paladins are normally taught to exercise judgment and control when dealing with foes, but this is an emergency, and I never paid too much attention to my trainers anyhow.\n\nI'm going to head into the Plaguewood and find out what I can about Giddy.  You deal with the Scourge just to our northeast, on the other side of this tower.  The undead don't fear death, but if you beat them enough, their tongues might slip, and we may get some clues to Gidwin's location.", objectives = "Beat down at least 6 Scourge Siege Engineers to discover details about Gidwin's location and his captor.", completion = "It sounds like you were successful.  Hopefully this is enough information to find Gidwin." }
WordHunterWoW_QuestEN[27523] = { title = "Duskwing, Oh How I Hate Thee...", description = "I have seen many things in my day, {race}.  The peaks of Mt. Hyjal... the oddities of Outland... a wall of Scourge soldiers, proceeding into war.  But I have never seen a bat as big, or as shockingly white, as Duskwing.\n\nHow he taunts me from his roost!\n\nThis albino demon bat circles to the southwest of here, due north of Blackwood Lake.  Track him down and destroy him.  If he flies too high for you to reach, use my flare to get his attention.\n", objectives = "Obtain a Patch of Duskwing's Fur.", progress = "I hope you've done away with that creature.", completion = "Excellent work.  I can now continue my work without the distractions of that great white beast.\n\nI shall fashion this fur into something you can use." }
WordHunterWoW_QuestEN[27524] = { title = "Blind Fury", description = "Tarenar wasn't joking when he said that he didn't care about judgment and caution.  He nearly took off that high elf's head as he ran into the Plaguewood, looking for Gidwin.  You should go after him.\n\nThe Plaguewood is a big place, {name}.  Good luck.  I hope to see you boys come out of the woods in one piece.", objectives = "Find Tarenar Sunstrike within the Plaguewood in Eastern Plaguelands.", completion = "I haven't found anything but brainless undead, and plenty of them.  I was just about to kill my way into Stratholme when you arrived.\n\nDid you have any more success?" }
WordHunterWoW_QuestEN[27525] = { title = "Guardians of Stratholme", description = "Baroness Anastar holds him?  Here in the Plaguewood?\n\nThe Plaguewood is a big place... but we will find him.  We WILL find Gidwin.\n\nImmediately to our east and our west are a pair of necropoli that flank the entrance to Stratholme.  Inside them, you will find a pair of death knights - Rivendare's lieutenants.  I doubt either would have any use for a paladin hostage, but perhaps they will have some information on his location.", objectives = "Kill Omasum Blighthoof and Karthis Darkrune.", progress = "We're getting close.  I only hope it's not too late.", completion = "We've got to keep moving!  We're getting so very close!" }
WordHunterWoW_QuestEN[27526] = { title = "Gidwin's Fate Revealed", description = "Quickly - find an entrance to the slaughterhouse to our south.  I will meet you on the inside.\n\nBe ready for a fight!", objectives = "Search for Gidwin Goldbraids within the slaughterhouse in central Plaguewood.", completion = "You have no idea how happy I am to see you two!  You're a sight for sore eyes... sore eyes that have been starin' through a banshee for far too long now.\n\nI'm sorry for causing so much trouble.  Will you take me back to the caravan?" }
WordHunterWoW_QuestEN[27527] = { title = "Journey's End", description = "I've had just about enough of the funk of this place.  Undead stink is bad enough, and then you add mushrooms to the mix?  I hate mushrooms!\n\nI'm going to head back to Light's Hope Chapel, {name}... and I'm taking Tarenar and Fiona with me.  I think we've all earned a well-deserved break.\n\nLet me give you this.  It's my hearthstone - you can use it to travel instantly back to Light's Hope.  I won't need it - I'm going to be riding in the caravan.\n\nIn the FRONT SEAT.", objectives = "Speak with Fiona at Light's Hope Chapel in Eastern Plaguelands.\n\nProvided item:", completion = "You've been more help than anyone expected of you, <name>.  The doors of my caravan are always open to you.\n\nThe boys and I have even put together a little something special for you.  Here, take your pick!" }
WordHunterWoW_QuestEN[27528] = { title = "Scourged Mass", description = "You can't just kill the Scourge.  They will come back.  You must destroy the vile matter that makes up their being... and even then, they may come back as spectres.\n\nFew undead use up as much mass as the lumbering abominations.  Kill them, then burn their bodies.  You will find them all over the Plaguewood.\n\nNever let your rage dissipate, {race}.  Remember: these abominations are sewn together from the bodies of good people.  Their crime is that they exist.", objectives = "Kill 8 Overstuffed Golems, then use the Crusader's Torch on their corpses.", completion = "A blessed fire cleanses even the most corrupt of flesh.\n\nThey stood no chance in the face of the Light." }
WordHunterWoW_QuestEN[27529] = { title = "Defenders of Darrowshire", description = "The battle of Darrowshire was one of the many tragedies that we humans suffered at the hands of the Scourge.  Its effects are still felt even today.\n\nMany of the town's valiant defenders now roam again as the ghastly servants of the Scourge.  We will end their misery.\n\nHunt cannibal ghouls here within the Plaguewood.  Many of these fiends were once the good folk of Darrowshire, and destroying their forms now will set their souls free.", objectives = "Free 8 Darrowshire Spirits from the bodies of Cannibal Ghouls, then speak with them.", completion = "It is good to hear you found the tortured souls of my brethren and freed them.  I find my strength renewed, knowing at least some of the defenders of Darrowshire no longer wallow in the vile subservience of the Scourge." }
WordHunterWoW_QuestEN[27530] = { title = "The Corpsebeasts", description = "To the south, gutless cultists are focused on a grim task: re-animating enormous hunks of flesh, to create giants known as corpsebeasts.  Luckily for us, these giants are still lifeless and weak.\n\nTake this charm - using it will place a font of holy energy on the ground.  If you can manage to place three of them near one of the corpsebeasts that the cultists are reanimating, the holy energy should overload it, destroying its body forever.", objectives = "Destroy the hulks of three Corpsebeasts by placing three or more Argent Lightwells next to them. You cannot place Argent Lightwells while in combat, and you may not place them within ten yards of one another.", completion = "You are a true Champion of the Light, <name>.  I wish you luck in your future endeavors, wherever they might take you.\n\nIf you need anything in the future, you can always find me here - knee-deep in the corpses of the slain." }
WordHunterWoW_QuestEN[27531] = { title = "Counter-Plague Research", description = "I once worked for the so-called \"Banshee-Queen\", Sylvanas, as an apothecary.  I used to admire her, but something's changed within her.  She's not herself anymore.\n\nI broke my vows with the Forsaken and joined the Crusade.  Now, I use my knowledge of alchemy to seek a counter-plague agent.  And the Plaguewood is the perfect place to do so.\n\nI need to resupply a few reagents, any of which can be found within the Plaguewood.  I'll pay you if you can find any of these items.", objectives = "Obtain 20 Rotberries, 5 Disembodied Arms, and 1 pile of Flesh Giant Foot Scrapings.", progress = "You got the stuff?", completion = "I love the smell of fresh foot scrapings, don't you?\n\nIf we're going to find a cure to the plague, we need to get creative with our ingredients.  Now, if you don't mind, I'm going to get back to work." }
WordHunterWoW_QuestEN[27532] = { title = "The Plaguewood Tower", description = "With the recent, unfortunate developments involving Gidwin, it might not be wise for a man my age to take the dangerous trip through the Plaguewood.  This is fine - I can visit the Plaguewood Tower on my next trip around the loop.\n\nI do, however, have a delivery that I need to get to Judkins.  You are younger than I, and stronger in combat.  Will you take this delivery to him?", objectives = "Bring Highbeacon's Parcel to Argent Apothecary Judkins at Plaguewood Tower in Eastern Plaguelands.", progress = "Highbeacon's Parcel... is Argus safe?  Did something happen?", completion = "Whew.  Every time Argus comes plodding through that Plaguewood, I fear it to be his last.  It's good to see that he's wise enough to send a youngblood like you in his stead." }
WordHunterWoW_QuestEN[27533] = { title = "A Fate Worse Than Butchery", description = "The people of Terrordale, they were sick, then they turned bad.  Definitely not good times.\n\nThe pigs, though... they also got sick!  What did pigs do to deserve to get sick?  Hah hah hah!  Nothing!\n\nPeople I can forget about, but the bad pigs still make me sad.  If you kill them, though... I might get happy.", objectives = "Kill 9 Plagued Swine.", progress = "I cry for the poor pigs.", completion = "I see them!  Can you?  The little pig spirits, on their way to the great sty in the sky..." }
WordHunterWoW_QuestEN[27534] = { title = "Augustus' Receipt Book", description = "I'm ready for business!  What do you want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", objectives = "Get Augustus' Receipt Book from the inn in Terrordale.", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, <name>!  Stupendous!  Insanely good, I say!" }
WordHunterWoW_QuestEN[27535] = { title = "Just a Little Touched", description = "I like to check in on Augustus in Terrordale every once in a while, just to make sure he's alright.  Some of us undead cope with the plague better than others, I suppose.\n\nTerrordale is west of here.  Would you mind checking in on him for me?", objectives = "Speak with Augustus the Touched in Terrordale.", completion = "You've come to the right place, mister!  No place better than Terrordale, yes siree, that's right!  The jewel of Lordaeron!" }
WordHunterWoW_QuestEN[27536] = { title = "Mostly Harmless", description = "Here's another favor you can do for me, pal.\n\nWe had a whole shipment of Landmines come in from Booty Bay just the other day. But someone stole the whole lot of 'em in the night!\n\nWhoever it was must be sloppy, because they dropped them all over the swamp to the east. No goblin I know would be that careless.\n\nI need you to go gather those landmines up for me. I'm sure they're perfectly safe and disarmed. Every single one. Yup.", objectives = "Collect 8 Disarmed Land Mines from the Sorrowmurk to the east of Bogpaddle.", progress = "Hey, you get those things I asked you about?", completion = "What did I tell you, eh? Perfectly safe!\n\nI'll see about getting some of these over to to your friends, <name>. At a discount." }
WordHunterWoW_QuestEN[27537] = { title = "Any Portal in a Storm", description = "Our friends in the Earthen Ring have been trying to open portals back to Stormwind, with no luck. But Thordun here tells me he might just have the key.\n\nThe crazed water elementals in the nearby Verrall River Delta have been sent into a frenzy. Thordun tells me we can channel their energy into a portal.\n\nI don't understand all this elemental-claptrap, but I understand one thing: killin' elementals and takin' their whirlpool cores. Deliver them to Talaa in the courtyard! ", objectives = "Slay Muddied Water Elementals to collect 5 Whirlpool Cores.", progress = "Hello, <class>. Kurdran tells me you've got a solution to getting this portal opened?", completion = "My word, <name>. These elemental energies are so powerful, so chaotic - no wonder the Twilight's Hammer has chosen to build their stronghold here!\n\nI should be able to channel these energies into something more benign and productive though. Let's give it a try..." }
WordHunterWoW_QuestEN[27538] = { title = "The Perfect Poultice", description = "Are you goin' by way of the Verrall river delta? I've got a tip that'll help your men here... and my bird!\n\nWhen water elementals carve their way through rock, they create a peculiar kind of muck. It dries hard as stone but carries with it the rejuvenating power of water. You make a cast out of that muck and broken bones knit together like iron.\n\nBring some of that muck to Talaa, your shaman downstairs. She'll know what to do with it!", objectives = "Collect 10 piles of Verrall River Muck.", progress = "What is this I keep hearing about the muck of the Verrall River?", completion = "Oh... mud. You brought me mud?\n\nWow - this stuff oozes with power! I see what Thordun was saying, now. I'll distribute this to all of the healers. Our wounded will be on their feet in no time!" }
WordHunterWoW_QuestEN[27539] = { title = "Add 'em to the Pile", description = "I've been collecting the skulls of the skeletons I defeat.  I've amassed a small pile of them.\n\nIf you come across any skulls, you are welcome to add them to my pile.  The huge pile of skulls seems to keep the waves of undead at bay and... well... it also just makes me happy to look at it.", objectives = "Obtain 16 Stinking Skulls from Cursed Mages and Scourge Soldiers in the Plaguewood.", progress = "You seem to have your hands full.  Are those skulls I see?", completion = "May my pile never stop growing." }
WordHunterWoW_QuestEN[27540] = { title = "The Wildhammer", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns.  The Earthen Ring struggles to understand what is going on.  We've been fortunate to gain assistance from the Wildhammer shamans.\n\nGavan Grayfeather is in Stormwind Keep to help coordinate our efforts with the various faction leaders.  Speak to him and see what you may learn about these events, {name}.", objectives = "Speak to Gavan Grayfeather in Stormwind Keep.No doubt you've felt the earthquakes. You may even have seen elementals attacking the lands or towns. The Earthen Ring struggles to understand what is going on. We've been fortunate to gain assistance from the Wildhammer shamans.\n\nGavan Grayfeather is in Stormwind Keep to help coordinate our efforts with the various faction leaders. Speak to him and see what you may learn about these events, <name>.", completion = "Well met, <class>.  I am Gavan Grayfeather, emissary of the Wildhammer shaman.\n\nThere is much work to be done.  The leaders fear for their citizens, as many have turned to cults.  We shaman are concerned with the elemental unrest.\n\nOur advice to you, <class>, is to be vigilant.  Help where you can, be it calming the people or putting the elementals at rest.  There is plenty to do." }
WordHunterWoW_QuestEN[27541] = { title = "Lessons From the Past", description = "This unfortunate explorer has clearly suffered a bit of bad luck in the recent past.\n\nPrudence dictates that you perform the unenviable task of searching the corpse for clues that might shed light on your surroundings...", objectives = "Acquire the Broken Goggles.", progress = "Any news, <name>?", completion = "Odd...\n\nIt looks as if someone used gemstones as lenses.\n\nI should be able to fix them without too much trouble." }
WordHunterWoW_QuestEN[27542] = { title = "Taking the Battlefront", description = "", objectives = "The hour of victory approaches, <name>. Godfrey has devised a plan to decimate our enemies. I am sending you into the field with him and his men to bring the rebel insurgents to their knees and seal the fate of the Alliance filth encroaching upon our lands.\n\nOur final march begins when you are ready." }
WordHunterWoW_QuestEN[27544] = { title = "Cenarion Tenacity", description = "Those druids never give up, I swear.  I'd given up on the Plaguelands years ago, but the Cenarion Circle folks keep telling me that the land is not beyond hope.\n\nThe most recent visitor was a night elf, on her way to the Fungal Vale, to the north.  She told me that these lands will make a full recovery, if we try hard enough.  I'm not sure I believe her.\n\nDo you buy this drivel?  Maybe you and her should talk.  She should still be up there.", objectives = "Speak with Rayne near the entrance to the Fungal Vale.", completion = "I suppose I had better work on my stealth, if you were able to find me.\n\nAre you interested in helping me heal the Plaguelands?" }
WordHunterWoW_QuestEN[27545] = { title = "The Way is Open", description = "My fellow Shaman and I will stay here to keep the portal open.\n\nYou should go upstairs and notify Kurdran that the work here is done. It'll please him to hear some good news for once.", objectives = "Speak with Kurdran Wildhammer at Highbank in Twilight Highlands.", completion = "Ho! I knew you were a <class> I could count on, <name>. Use that portal anytime you need to get from Stormwind back to the Highlands.\n\nNow then, time to get to business. We need to locate and unite the lost Wildhammer clans scattered around the Highlands. Talking with Thordun here is a good start!" }
WordHunterWoW_QuestEN[27546] = { title = "Speak with Captain Anton", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here.  Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, {class}, speak with Captain Anton in Stormwind Keep and see how you might assist him.", objectives = "Speak with Captain Anton in Stormwind Keep.No doubt you've felt the earthquakes. You may even have seen elementals attacking the lands or towns. We have sent many of our brightest minds to Nagrand to commune with the elements.\n\nBut there is still much work to be done here. Stormwind Guards are being overwhelmed with citizens worried about their loved ones.\n\nPlease, <class>, speak with Captain Anton in Stormwind Keep and see how you might assist him.", completion = "King's honor, <class>.  I am Captain Anton.  I am leading the investigation into the cultists that have appeared in Stormwind." }
WordHunterWoW_QuestEN[27547] = { title = "Of No Consequence", description = "Our forces in Pyrewood were recently taken by way of sneak attack. The 7th Legion managed to infiltrate the town with their scouts, ultimately decimating our troops.\n\nThe Dark Lady has tasked us with a rescue mission. We are to find survivors and get them out of Pyrewood safely. If any soldiers live they are likely worthless, but we do as the Dark Lady commands.\n\nLet's get this nonsense over with, {name}. Pyrewood is directly southwest of the Forsaken Front.", objectives = "Rescue 8 Cowering Troopers.", progress = "The sooner we rescue survivors the sooner we can burn down the whole of Pyrewood.", completion = "What happened here today is between us. Say a word to anyone and you will find yourself in a corpse pit next to these poor fools." }
WordHunterWoW_QuestEN[27548] = { title = "Lessons in Fear", description = "Our enemies are becoming smarter - adapting to our tactics. Recently an attack was made upon Pyrewood Village, southwest of here. Our troops occupying the town were decimated, of course, but what made the attack especially interesting was the racial composition of the attacking force. No humans were used.\n\n<Walden laughs.>\n\nRightfully, they fear being reanimated as Forsaken.\n\nLet us teach the non-humans a lesson in fear. Together we will show them what happens to corpses that we cannot use.", objectives = "Kill 12 7th Legion Scouts.", progress = "Pyrewood Village must be reduced to ashes and our enemies slain!", completion = "I suspect we'll see fewer humans at the Battlefront. The risk for these cowards is too great." }
WordHunterWoW_QuestEN[27549] = { title = "By the Light of the Stars", description = "Look at this, {name}.\n\n<Harrison holds up the dead scout's goggles.>\n\nI tightened the clamp in the middle and crimped the wires on the edges. They may not be the most comfortable, but they should hold together.\n\nIf I've translated your tablets correctly, there's something hidden here - a final piece to our puzzle.\n\nI hope your spectacles hold the key.\n\nLet me know what you find!", objectives = "Collect 7 Suspended Starlight.", progress = "So?\n\nFind anything interesting?", completion = "Well, kid, it looks like you've done it again.\n\n<Harrison points to an image on the tablets.>\n\nThis starlight is exactly what we were missing.\n\nNow we can get to work!" }
WordHunterWoW_QuestEN[27550] = { title = "Pyrewood's Fall", description = "The attacks against our front are a distraction. With our attention turned towards the worgen onslaught, the Alliance has managed to take Pyrewood Village from our occupying forces.\n\n<Godfrey hands you a bundle of torches.>\n\nIt must be purged.\n\nWith these torches we will burn Pyrewood Village to the ground, leaving only ashes for the enemy to hide behind.\n\nLet us not waste another minute. Pyrewood Village is located southwest of the Forsaken Front. Lead us there, {name}.", objectives = "Use the Bundle of Torches to torch the Pyrewood Town Hall, Pyrewood Inn and Pyrewood Chapel.", progress = "I feel no remorse.", completion = "The part of me that was Gilnean died at Tempest's Reach. Only vengeance remains, <name>. To that end, we have work to do. Spare me your pointless queries." }
WordHunterWoW_QuestEN[27551] = { title = "The Baroness' Missive", description = "The note is from Baroness Anastari, and it describes a ritual that is about to happen in the Plaguewood's central slaughterhouse - just south of where Tarenar is at.  This could be where they're holding Gidwin!\n\nTarenar will want to know about this... and quickly, before it's too late!", objectives = "Bring the Baroness' Missive to Tarenar.", progress = "What?  Did you find something?", completion = "This is it!  If this missive is to be believed, then he's literally right over this hill!\n\nWhat are we waiting for, <name>?" }
WordHunterWoW_QuestEN[27555] = { title = "Fiona's Lucky Charm", description = "", objectives = "Fiona has left some of her charms inside the caravan.\n\nAs a trader, she seems to be pretty good with money.  Maybe carrying one of her charms will help out with your finances." }
WordHunterWoW_QuestEN[27556] = { title = "Gidwin's Weapon Oil", description = "", objectives = "Gidwin has left several bottles of weapon oil inside the caravan.\n\nHe seems to be quite a fierce combatant up close.  Perhaps his weapon oil will help you out as well." }
WordHunterWoW_QuestEN[27557] = { title = "Tarenar's Talisman", description = "", objectives = "Tarenar has laid a few holy talismans inside the caravan.  They appear to be unused.\n\nThey appear to be magical in nature.  If Tarenar isn't using them, what's the harm in borrowing one for a while?" }
WordHunterWoW_QuestEN[27558] = { title = "Pamela's Doll", description = "", objectives = "You see a small doll sitting in the back corner of the caravan.\n\nTarenar tells you that it must belong to Gidwin, and Gidwin says that it's probably Tarenar's." }
WordHunterWoW_QuestEN[27559] = { title = "Vex'tul's Armbands", description = "", objectives = "Vex'tul has left some of his wrappings within the caravan.  Surprisingly, he was courteous enough to keep them folded and separate from everyone else's belongings.\n\nVex'tul values strength over everything else.  Leaning in close, you can sense some of his residual strength emanating from within these armbands." }
WordHunterWoW_QuestEN[27560] = { title = "Argus' Journal", description = "", objectives = "You see a trail-worn journal inside the caravan.  Judging by the Argent Crusade emblem on its spine, it must belong to Argus.\n\nWritten within the journal are several accounts of Argus' experiences during his tenure in the Crusade.  It should prove to be an interesting read while on the road." }
WordHunterWoW_QuestEN[27561] = { title = "Rimblat's Stone", description = "", objectives = "You notice a small heap of stones within the caravan.\n\nThey do not appear out-of-the-ordinary, yet one of them attracts your attention.  You sense a warmth coming from within it." }
WordHunterWoW_QuestEN[27562] = { title = "Beezil's Cog", description = "", objectives = "It looks like Beezil has already made himself comfortable, and has stuffed several peculiar gizmos into the caravan.\n\nMost of them seem too impractical or dangerous to take with you.  One small cogwheel, however, looks to be fairly well-crafted." }
WordHunterWoW_QuestEN[27564] = { title = "In Defense of the Redoubt", description = "Calen sent word - the Twilight are within the redoubt!\n\nIf there will ever be a time when you can earn his favor, this is it!", objectives = "Speak to Calen in the Vermillion Redoubt.", completion = "I hope you're as tough as your gear suggests. The Twilight's Hammer have made their way within the redoubt somehow and I need someone to hunt them down." }
WordHunterWoW_QuestEN[27565] = { title = "Into the Prison", description = "We've managed to infiltrate the Dark Iron Prison!\n\nWell...we may have, anyway.\n\nKevin Dawson had the...honor...of seeing what was going on over there, and we haven't heard back from him since. You look like the type that doesn't like to die, you should go see if he's ok!\n\nHe's supposed to be inside the hall on the south end of the cavern ahead...though something tells me he may not have made it quite that far.", objectives = "Find Kevin Dawson.", completion = "I don't know how I'm still alive. The patrols keep walking past me like I'm not even here.\n\n...Am I dead, <class>?" }
WordHunterWoW_QuestEN[27566] = { title = "A Gathering in Outland", description = "Greetings, {class}.  The elements have grown more restless and we seem to be making little progress to a solution for this problem.  Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with Gavan Grayfeather, he will surely have some task for you.", objectives = "Speak with Gavan Grayfeather at the Throne of Elements in Nagrand.Greetings, <class>. The elements have grown more restless and we seem to be making little progress to a solution for this problem. Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with Gavan Grayfeather, he will surely have some task for you.", completion = "It is good to see you, <name>.  Here at the Throne of Elements we may be able to uncover what ails Azeroth." }
WordHunterWoW_QuestEN[27567] = { title = "Twilight?! No!", description = "This is a little hard to believe, but there are Twilight's Hammer members here in Blackrock Depths! I don't know how many there are crawling throughout this place, but I did hear that their lead interrogator, Gerstahn, is in this hallway.\n\nI don't know what they're here torturing for, but maybe you can find out by confronting Gerstahn?", objectives = "\"Interrogate\" High Interrogator Gerstahn.", progress = "Go! Go! Go!", completion = "I see...she did not cooperate. Hopefully we can still stop them before something else terrible happens." }
WordHunterWoW_QuestEN[27568] = { title = "Infiltrating Shadowforge City", description = "Can ye keep a secret? I have a secret tae share with ye if ye can.\n\nEverybody here is CRAZY!!!\n\nThere's goblins over there, Dark Irons right over there, and a giant living fire thing right past this gate! An' that's just what I see in this little cave!\n\nAnd ye! What're ye doin' here!?\n\nOh, I see. Winky sent ye, did he? Sent ye tae talk t' Prospector Seymour, past this gate and t' the right, did he? Well go! Oralius doesn't even care!\n\n...I'll GET YOU FOR THIS WINKY!!!\n\n<Oralius begins to sob.>", objectives = "Speak to Prospector Seymour.", completion = "I would stay away from Oralius. Far, far, far away. He isn't quite right in the head.\n\nNow, let's get onto business!" }
WordHunterWoW_QuestEN[27569] = { title = "Dark Iron Tacticians", description = "General Angerforge and Golem Lord Argelmach lead the Dark Iron armies and their golems against us. If we are to overcome them, the two must be slain.\n\nGo through this door and unlock The Shadowforge Lock, which separates the East and West Garrisons. Then, follow the stairs and keep to the left at the top until you reach the West Garrison. It is there you will find the General and Golem Lord.\n\nKeep your wits about you, they are both well-seasoned combatants. Find Mayara Brightwing should you succeed.", objectives = "Kill General Angerforge and Golem Lord Argelmach.", completion = "I'm sure you are up to the task I have for you if you've made it this far in one piece.\n\n<Mayara Brightwing lowers her voice to a whisper.>\n\nBetween you and me, you may want to enjoy yourself in the Grim Guzzler while you're there. It could be the last drink you ever have." }
WordHunterWoW_QuestEN[27570] = { title = "The Situation So Far", description = "No doubt you've felt the earthquakes.  You may even have seen elementals attacking the lands or towns.  The Earthen Ring struggles to understand what is going on.  We've been fortunate to have one of the greatest shaman as our Warchief.\n\nThrall has been consulting with his advisors, and we don't want to interrupt his council.  But perhaps our brother, Gotura Fourwinds, has learned of Thrall's plans.", objectives = "Speak with Gotura Fourwinds in Grommash Hold in Orgrimmar.", completion = "Greetings, <class>.  The situation here is tense.  The elements are restless and the people are scared and confused.  The Warchief is trying to find a semblance of balance between leading the people and protecting Azeroth.  Though it seems he will soon be leaving us to travel to Nagrand and gain insight about the elementals.\n\nRegardless of the Warchief's choice, we still must do what we can.  Help calm the populace, scour the lands for rogue elementals.  These tasks will surely help our cause." }
WordHunterWoW_QuestEN[27571] = { title = "The Grim Guzzler", description = "Some say that the Grim Guzzler is the secret to the Dark Iron war effort. Their warriors recharge there and emerge thirsty for another innocent soul. I think we can seriously hinder them by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Orfus when you're done.", objectives = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", progress = "Hurry, please. Time is not a luxury we currently have.", completion = "The Dark Irons took our Thunderbrew. I'll never let them live after that. I'd kill 'em all myself if I could!\n\nHowever, look ahead and you'll see we have slightly more dire matters to attend to at the moment." }
WordHunterWoW_QuestEN[27572] = { title = "A Gathering in Outland", description = "Greetings, {class}.  The elements have grown more restless and we seem to be making little progress to a solution for this problem.  Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with our Warchief, he will surely have some task for you.", objectives = "Speak with Thrall at the Throne of Elements in Nagrand.Greetings, <class>. The elements have grown more restless and we seem to be making little progress to a solution for this problem. Some of our wisest shaman have gathered in Nagrand at the Throne of Elements to discuss what ails our land.\n\nHead to the Throne of Elements and speak with our Warchief, he will surely have some task for you.", completion = "It is good to see you, <class>.  Here at the Throne of Elements we may be able to uncover what ails Azeroth." }
WordHunterWoW_QuestEN[27573] = { title = "The Dark Iron Pact", description = "Ahead is the creature known only as Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them, so that this nation may perhaps one day be redeemed.", objectives = "Kill Ambassador Flamelash and Doom'rel.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this." }
WordHunterWoW_QuestEN[27574] = { title = "I Never Forget a Face", description = "You have discovered a partially digested head. Lord Godfrey perks up when he sees it. Perhaps you should give it to him.", objectives = "Give the Partially Digested Head to Lord Godfrey in Silverpine Forest.", progress = "I never forget a face!", completion = "I know that face, <name>. This head belongs to a former Gilnean known as Sean Dempsey. He was imprisoned with Crowley before the great outbreak.\n\n\n\nI wonder if it would be possible to put him back together. The rest of him must be in the belly of these crocolisks." }
WordHunterWoW_QuestEN[27575] = { title = "From the Belly of the Beast", description = "I think we can rebuild him. Perhaps if we put him back together he can give us information about Crowley.\n\nWe must kill every crocolisk in this marsh until we find the rest of Sean Dempsey's body! From the belly of the beast this man will be reborn!", objectives = "Recover Dempsey's Torso, Dempsey's Appendages and Dempsey's Giblets.", progress = "At the very least we'll have some crocolisk hides to make fancy shoes out of.", completion = "Now let's see if I can do this.\n\n<Godfrey starts mumbling under his breath.>\n\n...leg bone connects to the thigh bone...\n\n...arm bone to torso...\n\n...sprinkle on a little Forsaken necromancy...\n\nTA-DA!" }
WordHunterWoW_QuestEN[27576] = { title = "Patchwork Command", description = "Recent events make it even more apparent that holing up here and making sporadic attacks isn't enough to keep our kind safe, much less retake Grim Batol. We need to be more aggressive, we need to strike into their heart.\n\nI've agreed to send dragons to the aid of your commanders. They were already hatching a plan to strike at Grim Batol, so you should focus your attention there first.\n\nYou should be able to find Patch in Dragonmaw Pass, in the canyon below us to the south.", objectives = "Speak to Patch in Dragowmaw Pass.", completion = "You got the dragons in the game! Good on you.\n\nWe'd already laid out plans for our ambush by the time the dragons contacted us. They're helping by cutting off their retreat.\n\nIt's not too late for you to join in on the fun though. We saved some for you." }
WordHunterWoW_QuestEN[27577] = { title = "7th Legion Battle Plans", description = "While destroying Pyrewood will certainly garner us an advantage over the Alliance upon the field of battle, our true purpose here is to leave them crippled.\n\nSouthwest of here, near the Greymane Wall, lies the 7th Legion Base Camp. We must search the base camp for battle plans. With the 7th Legion battle plans we will be able to pinpoint all Alliance troop advancement in Silverpine Forest.", objectives = "Recover the 7th Legion Battle Plan.", progress = "Search every filthy dwarven corpse.", completion = "<Walden flips through the battle plan.>\n\nIt looks like the reinforcements from the ships in Gilneas are marching soon. Crowley and Bloodfang have set up an encampment to the southeast for the Gilneas Liberation front." }
WordHunterWoW_QuestEN[27578] = { title = "Morgan's Fruition", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", objectives = "Kill Emperor Dagran Thaurissan.", progress = "If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", completion = "You've done it! You've actually done it! Morgan's years of planning and waiting have finally come to fruition.\n\nShe may have lost her land and family when Ragnaros tore this land asunder, but with the Dark Iron crippled we'll be able to safely build a new kingdom of our own in the Burning Steppes. Not even the Firelord himself will be able to breech the capital's walls!\n\nMake sure you come back someday when we've finished, you'll be our guest of the highest honor. I thank you with all my heart, <name>." }
WordHunterWoW_QuestEN[27579] = { title = "Into the Prison", description = "Da Twilight's Hammer be here for some reason. We don't know why, but Thal'trak be lettin' you in on a lil' secret of ours - da rogue Lexlort waits outside da hall where High Interrogator Gerstahn be so he can kill her if he gets da chance.\n\nShe's too smart for dat, though, so you gonna go in an' do it, ya? Go talk to Lexlort and let him know. I'm sure he be ok with it.", objectives = "Find Lexlort.", completion = "Get over here. If you blow my cover, I swear to the Warchief I'll kill you where you stand." }
WordHunterWoW_QuestEN[27580] = { title = "Sowing Discord", description = "The Alliance reinforcements have established a foothold in the southwest region of Silverpine called 7th Legion Base Camp. Our primary goal at the base camp is to sow discord amongst the troops. This is a lightning fast assassination mission to kill their field commander, General Marstone. His death won't stop the Alliance advance, but it will certainly soften their ranks.", objectives = "Assassinate General Marstone.", progress = "Marstone is a decorated field general. He will not go down easy.", completion = "The rest of the Alliance fleet will arrive shortly, only to find their base camp decimated. Now for the second and most important part of our battle plan." }
WordHunterWoW_QuestEN[27581] = { title = "Twilight?! No!", description = "Gerstahn is too heavily guarded and too smart to leave her post, so I'm not going to kill her.\n\nYou are.\n\nI'll throw in a little something I picked up off of a guard to make it worth your while.", objectives = "Kill High Interrogator Gerstahn.", progress = "Does it look like I want to be waiting her any longer than is necessary?", completion = "The Twilight's Hammer's presence only complicates our mission here further, but you've done your part for now.  You've earned a reward for your efforts...and some rest. Let's get out of here." }
WordHunterWoW_QuestEN[27582] = { title = "Infiltrating Shadowforge City", description = "We're fighting a losing battle right now, I'm afraid. The Dark Irons would be difficult to defeat on their own, but their elemental allies have given them new bleeding edge warriors that we simply can't compete with.\n\nI need you to help us infiltrate their domain and kill as many of their vital leaders as possible. Hopefully that will shock their forces and turn the tide in our favor. Report to Razal'blade for further instruction. He's stationed beyond this gate and to the right.", objectives = "Speak to Razal'blade.", completion = "Beyond this door lies the commander of the Dark Iron Army, surrounded by trained soldiers. Are you up for a little killing?" }
WordHunterWoW_QuestEN[27583] = { title = "The Northern Flank", description = "I have ordered a defensive perimeter set up on our northern coast, at the Slithering Cove. Our scouts reported that the naga were trying to make landfall there.\n\nGralok is in charge of the operation - report to him and secure that beach!", objectives = "Report to Gralok at the Slithering Cove in Twilight Highlands.", completion = "Warlord Zaela sent you? Good.\n\nIf you Horde are as strong as your Warchief promised, I expect to see some bloodshed on these shores." }
WordHunterWoW_QuestEN[27584] = { title = "Blood in the Surf", description = "These naga scum think to move upriver to reinforce the Bastion of Twilight. We will RIP off their fish heads and PULL OUT their SPINES.\n\n<Gralok drives his broadsword into the dirt.>\n\nDestroy the Blackscale!", objectives = "Slay any combination of 15 Blackscale Raiders or Blackscale Mistresses.", progress = "After the battle we will mount their heads on pikes and build a wall all along the beach. THAT will show these belly-crawling SNAKES who owns the Highlands.", completion = "<Gralok sizes you up.>\n\nYou're a true fighter, <name>. I liked watching you work. Perhaps the Dragonmaw really DO belong in your Horde." }
WordHunterWoW_QuestEN[27585] = { title = "The 109th Division", description = "General Angerforge and Golem Lord Argelmach are directly responsible for the horrific slaughter of the 109th Division of the Kargath Expeditionary Force. There were a lot of good trolls and orcs in that division, many of them my close friends.\n\nWell, young {race}, it's time for our fallen brothers to at last have their revenge.\n\nUnlock The Shadowforge Lock, go up the stairs and bear left until you reach the West Garrison. Kill Angerforge and Argelmach, and don't you dare show them any mercy.", objectives = "Kill General Angerforge and Golem Lord Argelmach.", progress = "I'm quite surprised to see you here! You'll be very useful indeed.", completion = "Up ahead is the Grim Guzzler. A disgusting bar full of all our enemies, intoxicated and therefore unfit for proper battle.\n\n<Hierophant Theodora Mulvadania grins.>\n\nRipe for the slaughter." }
WordHunterWoW_QuestEN[27586] = { title = "Shells on the Sea Shore", description = "I salvaged these mortars from the wreck of our airship when she detonated above Dragonmaw Port. But ammunition is in short supply!\n\nWhile you're running along the beach, do me a favor and pick up any unexploded mortar shells you find.\n\nUnexploded shells are the best kind - you never know WHEN they're going to go off. Perfect for surprising an enemy! ", objectives = "Gather 8 Unexploded Mortar Shells along the beach at Slithering Cove.", progress = "Do you have the shells? Hand them here!\n\n...Gently!", completion = "Oh yeah. YEAH! These are DEFINITELY going to kill somebody.\n\nProbably naga." }
WordHunterWoW_QuestEN[27587] = { title = "Maliciously Delicious", description = "You know, I've got a problem you might be able to help me out with, here.\n\nSee, in addition to the fine pursuit of arms dealing, I'm trying to liven up the entertainment here in Bogpaddle. Apparently there's a bunch of these makrura things in the north waters that don't take kindly to the wild beach parties we've been throwing.\n\nJoke's on them. I'm not gonna be pushed around by giant lobsters; they're my next source of revenue! You bring me some of their tails and we'll turn a problem into profit.", objectives = "Collect 6 Intact Swampshore Tails from Swampshore Makrura.", progress = "You got those tails? Don't be tryin' to push no hacked-up ones on me!", completion = "I can see it now: our own famous Bogpaddle Lobster-Poppers! Made fresh from the sea! Oh, it's like this stuff writes itself...\n\nYour help is very much appreciated, my friend. I'll start seeing if I can't cut your people a favorable arrangement, eh?" }
WordHunterWoW_QuestEN[27588] = { title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate." }
WordHunterWoW_QuestEN[27589] = { title = "The Grim Guzzler", description = "Everyone inside the Grim Guzzler is absolutely hammered and, therefore, easily angered. I think we can seriously hinder the Dark Irons by causing a bit of chaos here.\n\nI need you to start a fight with three of the bar's infamous patrons. Damage the kegs and Hurley Blackbreath will come running. Steal items off the tables near Plugger Spazzring and he'll fight. As for Ribbly Screwspigot...just talk to the little hothead. Report to Thunderheart when you're done.", objectives = "Fight Hurley Blackbreath, Plugger Spazzring, and Ribbly Screwspigot.", progress = "Hurry, please. Time is not a luxury we currently have.", completion = "I hear quite the commotion coming from the Grim Guzzler. I see you've been hard at work.\n\nIf you'll direct your attention opposite me, you'll notice that we have bigger issues to worry about than toying with drunkards." }
WordHunterWoW_QuestEN[27590] = { title = "Signal the Attack", description = "Now that you've lured Skullcrusher the Mountain away from the Twilight Gate, I need you to signal our forces to attack!", objectives = "Use the Attack Signal from atop one of the towers at the Twilight Gate." }
WordHunterWoW_QuestEN[27591] = { title = "The Dark Iron Pact", description = "Inside this chamber lies Ambassador Flamelash. He is the ambassador to the Dark Iron Nation from Ragnaros the Firelord. Beyond that chamber is the Summoners' Tomb, home to the spirits of the seven Dark Iron patriarchs who summoned Ragnaros into our world.\n\nYou may not know of the Great Fire, but he will be the end of Azeroth if he is not stopped, and these individuals are directly tied to his hold over the Dark Iron. Slay them all, and may this unholy union cease.", objectives = "Kill Ambassador Flamelash and Doom'rel.", completion = "I cannot proceed any further alone, regardless of my combat experience. The Lyceum has proven too difficult for me. If you are here, though...you might be the key to all of this." }
WordHunterWoW_QuestEN[27592] = { title = "Drinks on the Rocks", description = "What's up, \"bro\"! We were just in the middle of our completely spontaneous beach party when something terrible happened, \"dude\"!\n\nI had a whole case of Silversnap Ice, the Baron's own drink of choice, until the silt crawlers stole them! I've never seen crawlers drink, but they took them right into the water and down the beach! We need some sort of awesome hero who can help retrieve our specifically-branded favorite beverage!\n\n<Brono stares at you a moment.>\n\nThat means you, \"brah\"!", objectives = "Collect 10 bottles of Stolen Silversnap Ice from Silt Crawlers.", progress = "You got the goods, \"bro\"?", completion = "Our ice-cold, refreshing Silversnap Ice! I can't thank you enough, \"dawg\", for this entirely spontaneous act of heroism!\n\nHere, have your very own bottle as a totally sincere gesture of thanks! Be sure to tell ALL YOUR FRIENDS how good it is." }
WordHunterWoW_QuestEN[27593] = { title = "Rebirth of the K.E.F.", description = "Emperor Dagran Thaurissan has total control over the city from his throne ahead. If we are to stop his armies, we're going to have to end their emperor's reign.\n\nYou'll need to get past his personal guard, including the giant Magmus, to reach him. Move as quickly as possible - if word gets out before you finish, the entire city will descend upon his throne.\n\nNote that the doors across the Lyceum will only open once you've lit the braziers with torches from the flamekeepers. Good luck.", objectives = "Kill Emperor Dagran Thaurissan.", progress = "If you do not succeed, I have no doubt that Thaurissan will execute the lot of us.", completion = "A true <class> if I've ever seen one! You've done the impossible! I knew we could count on you.\n\n\n\nAnd with that, I'd like for you to be the first to know that the Kargath Expeditionary Force is now officially back in business!\n\nI extend to you my personal gratitude for your efforts here. Remember always our motto: \"First in, last out, always victorious. Remember always Kargath.\"\n\nYou are dismissed." }
WordHunterWoW_QuestEN[27594] = { title = "On Her Majesty's Secret Service", description = "Lorna Crowley, daughter of Lord Darius Crowley, is currently at the Gilneas Liberation Front camp, located near the Greymane Wall, to the southeast.\n\nOur primary mission is to infiltrate the camp and capture her alive. The Dark Lady believes that she will be able to use Lorna as a bargaining chip against Crowley. I say we just kill her and bring her back as Forsaken, but we must do as the Dark Lady commands.\n\nWe must hurry before the rest of the Alliance forces arrive.", objectives = "Capture Commander Lorna Crowley and return her to Lady Sylvanas Windrunner at the Forsaken Front in Silverpine Forest.", completion = "You have done it! Finally, everything is in place. Should Crowley not accept our terms, his daughter will be turned." }
WordHunterWoW_QuestEN[27595] = { title = "The Prophet Hadassi", description = "Prophet Hadassi is the wisest and eldest member of the Orsis tribe.\n\nHe has not been accounted for and his well-being is of vital importance.\n\nGo into Orsis and find him.  A great day of reckoning will come to the Al'Akir's lackeys if he's been hurt.", objectives = "Find the Prophet Hadassi in Orsis.", completion = "Who... who are you?  Sent here... to rescue my people and fight our enemies." }
WordHunterWoW_QuestEN[27596] = { title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to The Black Vault near the Hall of Crafting, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", objectives = "Obtain the Heart of the Mountain.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, <name>, take this as payment!" }
WordHunterWoW_QuestEN[27597] = { title = "Crazy Larry", description = "You're gettin' it, {name}. You scratch my back, I scratch yours. Well, more like I scratch the back of your whole army, and just a little harder than the backs of the other side! Was that too complicated?\n\nWhat I'm sayin' is, that's a lot of backs. So I'm gonna have to ask you to scratch mine a few more times. Whoever stole those landmines may have just hit our boys on the eastern shore.\n\nHead to our camp to the southeast and check on Crazy Larry; he'll fill you in when you get there.", objectives = "Find Crazy Larry to the southeast of Bogpaddle.", completion = "Silversnap sent you?! I'm DOOMED!\n\nOh, he sent you to help me! That's different, haha!" }
WordHunterWoW_QuestEN[27598] = { title = "Kill Gil", description = "Gilblins!\n\n<Larry stares at you silently for a while.>\n\nYou never seen a gilblin before? They're crazy! Crazier than me! I just blow stuff up for a living, these guys are WHACKED!\n\nDunno where they came from, but they're like awful fish goblins! Gills and everything! They wiped out all my men down at the beach, and they took our shipping freighter!\n\nYou gotta help! They're just down to the east, go on and get rid of those gilblins!", objectives = "Slay 7 Gilblin Stalkers.", completion = "That'll show those fish-faced freaks! Good work!" }
WordHunterWoW_QuestEN[27599] = { title = "Can't Take It With Them", description = "Any shipping crew I had that you don't see hanging around this camp are DEAD! Those were some fine goblins, but what's worse is they're all still out there! It's a TRAGEDY!\n\nI mean, it's a tragedy they still have all their stuff! It's horrifying to think of all the perfectly good materials and coins sitting out there in the water.\n\nHey! You can do me a favor! If you're killing gilblins out there, go get the ditty bags off my old crewmen!\n\nC'mon, they're not gonna need it anymore! Be real!", objectives = "Collect 6 Ditty Bags from Deceased Bogpaddle Privateers.", progress = "You get those ditty bags? I hope you left the goblins there!", completion = "WOW!\n\nI don't know why I said that. I'm excitable! But man, there was a lot of stuff on these guys, check it out!\n\nHere, you want this?" }
WordHunterWoW_QuestEN[27600] = { title = "In With a Bang", description = "Our trade frigate's still all the way out there on the water, swarming with Gilblins! AHH!\n\nSorry about that. But really! We need a way to get you out there and get back our stuff. There's quality goods left on that ship! QUALITY! LIKE MY MIDDLE NAME!\n\nLucky for you, I have an idea! Head right outside the camp and check along the north wall... my son Jerry'll get you over there with our cannon! If he's been practicing, that is!", objectives = "Speak with Lil' Crazy Jerry to board the ship, then retrieve all three of Crazy Larry's important goods.", progress = "You got it? Did you get it? Did you try the cannon? You didn't explode!", completion = "My high-grade fuse! My imported blasting powder!\n\nAnd my--hello there! I'll just be taking that!\n\nThose are all worth more gold than what you're wearing, you know! Thanks for your help!" }
WordHunterWoW_QuestEN[27601] = { title = "Cities in Dust", description = "Our armies clash across the battlefield. Crowley and his forces are losing ground and they do not yet know the fate of Lorna Crowley. We will meet with Crowley and his compatriots at mid field and I will present them with terms of their surrender. They will either accept or we will kill them all and leave their cities in dust.\n\nAs my most trusted soldier, you are to stand by my side during the exchange. Tell me when you are prepared to leave.", objectives = "Accompany Lady Sylvanas Windrunner to the Battlefield and defeat the Alliance!", completion = "<Lady Sylvanas Windrunner grimaces in pain.>\n\nThis... is not over. Godfrey and his traitorous allies will pay for what they have done as will the remaining Alliance forces occupying Lordaeron.\n\nOur work has only just begun." }
WordHunterWoW_QuestEN[27602] = { title = "The Prophet's Dying Words", description = "We... are... bound by oath... to protect the scepter of Orsis.\n\nListen, {class}, I don't have much time... left.\n\nFind the sacred receptacle... in the southern end of the city.\n\nDo not... let it... fall into their... hands...", objectives = "Find the Sacred Receptacle.", completion = "Though the chest is locked, there is a plaque bearing interesting hieroglyphs above it." }
WordHunterWoW_QuestEN[27603] = { title = "The Sealed Gate", description = "At one end of the Dark Iron Highway stands a massive gate much like the one that protects Shadowforge City on the opposite side. However, we have no idea what's behind it!\n\nAll we know is that it's heavily guarded by Anvilrage patrols and the molten giant Bael'gar. You simply must dispose of them and see if you can pry that gate open!\n\nJust imagine what could lie behind it...there could be an entire other half of the city we never knew about! Or nothing! Who knows!\n\nThough, it's probably something...", objectives = "Kill Bael'gar.", progress = "Were you able to get past the gate? Or scale it? What's behind it???", completion = "Darn it! I simply HAVE to know what's behind that gate! This could be the discovery that makes my career, you know!\n\nHmm....maybe a couple good explosions would do the trick..." }
WordHunterWoW_QuestEN[27604] = { title = "Jammal'an the Prophet", description = "Jammal'an the Prophet, leader of the Atal'ai and Hakkari trolls, has obtained a small amount of Hakkar the Soulflayer's blood. They are injecting it into the green dragons to use their bodies to produce the massive quantities of blood necessary to summon Hakkar into our world.\n\nWe cannot allow this to come to pass. Slaughter Jammal'an and his priests before they get any further in their efforts!", objectives = "Obtain Jammal'an the Prophet's Head.", progress = "Were you able to kill Jammal'an? I'll need proof that the deed is done.", completion = "Excellent! I suspect that without Jammal'an's leadership, the trolls will fall to infighting and Hakkar will never set his eyes upon our world." }
WordHunterWoW_QuestEN[27605] = { title = "Eranikus", description = "The Hakkar blood the Atal'ai have been injecting into the green dragons has had devastating effects on the dragons themselves. It appears that these dragons, former jailors of the Atal'ai, have been corrupted by its presence in their bodies and have become creatures of Nightmare.\n\nEranikus, Ysera's primary consort and lead watcher over the temple, was infused with the largest quantities of blood and has become twisted beyond imagination. After Jammal'an is dead, find Eranikus and end him.", objectives = "Kill Eranikus.", progress = "Did you defeat Eranikus?", completion = "You only defeated Eranikus' Shade? This is most troubling...\n\nLet us hope that his full form does not still exist outside the Temple. Only Ysera herself is stronger than him in our flight." }
WordHunterWoW_QuestEN[27606] = { title = "Blast Him!", description = "Let's go fishing, {name}! Now that the mortars are ready, we can take out the leader of this invasion.\n\nFathom-Lord Heth'Jatar rules over the Blackscale warrior caste. Go to the Heth'Jatari Banners just northeast of here and honk this conch shell. It's like a dog-whistle. For fish.\n\nWhen Heth'Jartar shows up, I'll order the mortars to concentrate fire. You'll see the targets of the incoming shells.\n\nLure Heth'Jatar into our mortar fire and pummel him into submission!  ", objectives = "Blow the Heth'Jatari Conch next to a Heth'Jatari Banner. Kill Fathom-Lord Heth'Jatar. Luring him into incoming mortar fire will help.", progress = "You want me to keep firing?\n\nI can keep firing.", completion = "Boom baby, boom!\n\nWhat? You killed the Fathom-Lord already?\n\nI suppose we should stop shelling his corpse, then." }
WordHunterWoW_QuestEN[27607] = { title = "The Southern Flank", description = "Our new arrangement with the Horde will put my people in direct conflict with the Alliance.\n\nBring. Them. On.\n\nAs we speak, the Alliance moves up the peninsula to threaten Dragonmaw Port.\n\nFind Rok'tar to the south - I believe he has set up a command post on one of the shipwrecks - and ensure that the Twilight Shores remain in our control.", objectives = "Speak with Rok'tar at the Twilight Shores in Twilight Highlands.", completion = "Good timing, <class>. We were just about to unleash a counter-attack." }
WordHunterWoW_QuestEN[27608] = { title = "Four Heads are Better than None", description = "We're about to launch the attack upon the Twilight Gate, but there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nWould you go back in there and kill them?", objectives = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack?", completion = "<The paladin frowns.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead. Regardless, thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel." }
WordHunterWoW_QuestEN[27609] = { title = "Four Heads are Better than None", description = "Now, while we're about to launch the attack upon the Twilight Gate, there is one last loose end to tie up: Za'brox and Beeble'phod, the disciples of Cho'gall.\n\nIntelligence has placed them within the Den of the Disciples, a small ogre cave at the southwest corner of the Twilight Gate.\n\nPlease head back in and kill them.", objectives = "Collect the four heads of Za'brox and Beeble'phod.", progress = "Is that blood dripping from your pack? I hope that it's not yours.", completion = "<The noble lady grins wickedly.>\n\nThat's quite a gruesome trophy collection you have there. I would have believed you if you had simply said they were dead, though I do appreciate the extra effort. Thank you for having the foresight to take care of them.\n\nThe Twilight Gate will soon be ours. Time to move up to the Twilight Citadel." }
WordHunterWoW_QuestEN[27610] = { title = "Scouting the Shore", description = "If the Alliance gains control of this peninsula, they will threaten Dragonmaw Port. Not going to happen.\n\nSouth of here you'll see a small hill with a commanding view of the shoreline. Whoever controls that hill will have the upper hand all along the shore!\n\nRush over there and scout the beach head control point. It's marked by that enormous flag. Then return to me.\n\nYou don't have to capture it, unless you're spoiling for a fight with the Alliance.", objectives = "Scout the Beach Head Control Point on the Twilight Shore. You don't need to capture it, but doing so will give your side a combat advantage and flag you for PvP.", completion = "Good work, <class>. Now you know the lay of the land.\n\nIf you're ever having difficulty fighting here on the Twilight Shores, remember that capturing and holding the Beach Head will give all Horde forces here a combat advantage!" }
WordHunterWoW_QuestEN[27611] = { title = "Blood on the Sand", description = "Our objective in the Twilight Highlands is to storm the Bastion of Twilight, but the Alliance have decided to make war.\n\nSo we will give them war!\n\nSlay their marines until the lesson is learned.", objectives = "Slay 12 Highbank Marines on the Twilight Shores in Twilight Highlands.", completion = "Good, good. Let them reap what they sow!" }
WordHunterWoW_QuestEN[27612] = { title = "Victory From Within", description = "A few of our men didn't make it through portals which were supposed to open inside this very abbey.  You've already proven your elusiveness and battlehardiness... now I need you to do so again.\n\nThe abbey has two wings: a library, and a hall of arms.  In each wing, you should find a portal.\n\nUse this keystone on these portals.  Doing so should force them open, allowing our remaining shock troopers to take this abbey.", objectives = "Open the Argent Portals in the Library Wing and the Hall of Arms within the abbey in Tyr's Hand.", completion = "The abbey will fall shortly.  We can soon move on, deeper into Tyr's Hand." }
WordHunterWoW_QuestEN[27613] = { title = "The Assassin", description = "The fate of the Scarlet Crusade is tragic, if somewhat ironic.  At one point, they led the charge of humanity against the undead.  Now, they resemble those corpses that they once hunted.  What caused their descent into undeath isn't certain, but it doesn't make them any less dangerous.\n\nOne of their deadliest was an assassin who went by the name of Rohan.  We have intel that places him atop the bell tower in this very abbey.  Find him and kill him, {name}.  And try not to die on the way.", objectives = "Kill Rohan the Assassin within the abbey bell tower in Tyr's Hand.", progress = "Fight well, <name>.", completion = "The death of Rohan eases my spirits a bit.\n\nI once fought beside him, you know.  He was an emissary of the Scarlet Crusade; one of the few that deigned to join us in our battle against Kel'thuzad, so many years ago.  How quickly things change." }
WordHunterWoW_QuestEN[27614] = { title = "Scarlet Salvage", description = "This battle was won before it started.  Right now, we're just shooting for style points.\n\nWithin these barracks, the sniveling Scarlet Crusaders cling to their priceless artifacts, even though some of the objects are too holy for their now-undead hand to touch.  So they keep them in chests, hidden from the world.\n\nYou will find these artifacts, and bring them back to me.  They belong to the Argent Crusade.  They belong in the hands of the righteous.", objectives = "Obtain the Crimson Boar, Lihanna's Strand, the Shroud of Uther, and Gavinrad's Sigil.", progress = "I hope you gave them a fight.", completion = "Well done, <name>.  I will deliver these to Tyrosus when we return." }
WordHunterWoW_QuestEN[27615] = { title = "The Wrathcaster", description = "One of the more vile members of the Scarlet Crusade, Mataus the Wrathcaster, lurks within the barracks' dungeon.  Undeath suits his dark manner.\n\nWere I younger and on the front lines, I'd run him through myself.  As things are, I'm left behind to lead our forces from the rear.  So I leave the pleasure to you.", objectives = "Slay Mataus the Wrathcaster.", completion = "You are well on your way to becoming a true champion of the Light, <name>.  Well done." }
WordHunterWoW_QuestEN[27616] = { title = "The Huntsman", description = "We've already lost half a dozen men to a hail of bullets and arrows coming from atop this fortress.  I haven't seen the face of the enemy that's firing, but I don't need to.  I know the name of the man up there.\n\nLeopold.\n\nThat's right, there's only one man up there, picking off my men one-by-one.  And from what I can see, there's only one of you.\n\nSounds like a fair fight to me.", objectives = "Slay Huntsman Leopold.", progress = "If it were up to me, I'd throw him off the edge of the tower.", completion = "One less thing to worry about.  Nice work up there." }
WordHunterWoW_QuestEN[27617] = { title = "Befouled No More", description = "Can you sense it?  The taint is already lifting from this building.\n\nA holy building wants to be holy, and villains like Rohan and the rest of his Scarlet scum only hold it back.\n\nWith the abbey secure, we are a step closer to taking Tyr's Hand.  Report the results of our strike to Angela.  She should be leading the charge on the cathedral from somewhere in the center of town.", objectives = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "Good, the abbey is ours.  I never doubted Eligor's ability for a moment." }
WordHunterWoW_QuestEN[27618] = { title = "Argent Upheaval", description = "I'll say we've done enough damage to these barracks to call this a win.  A commander, a huntsman, and a warlock, all slain... not to mention the relics that we've liberated.  Or shall I say... YOU liberated.\n\nThe cathedral still remains, but not for long.  Talk with Archmage Angela Dosantos, in the central courtyard.  The fate of Tyr's Hand's cathedral falls in her able hands.", objectives = "Report to Archmage Angela Dosantos at Tyr's Hand in Eastern Plaguelands.", completion = "It sounds like Korfax really cleaned house over at the barracks.  It's very much like him to show off like that." }
WordHunterWoW_QuestEN[27619] = { title = "The Commander", description = "Scarlet Commander Marjhan is cunning, shrewd, and willing to do anything to win a battle.  Before all these things, however, she is loyal.\n\nI have no doubt you'll find her in the barracks' central chamber, fighting under a crimson banner, until she either wins or dies.\n\nMake sure it's the latter.", objectives = "Slay Scarlet Commander Marjhan.", completion = "Good, good.  These barracks are as good as fallen." }
WordHunterWoW_QuestEN[27620] = { title = "Like Rats", description = "Well, I'm glad that Eligor and Korfax left some fun for me.  It was a battle unto itself to keep them from rushing headlong into the middle of this cathedral.\n\nThat's YOUR job, after all.\n\nThe cathedral lies ahead of us, the last real bastion of Scarlet power remaining.  Within it, Crusader Lord Valdelmar sits atop Tyr's Hand's crumbling pulpit of lies.\n\nThere will be no escape; there will be no mercy.  The last simpering vestiges of the Scarlet Crusade end here.  Slay him.", objectives = "Slay Crusader Lord Valdelmar.", completion = "While I can't agree with their methods, I can't argue with their results.  In many ways, the Scarlet were well-intentioned, but their zeal grew too strong, and their hate blinded them to reason.\n\nI only hope that the same doesn't happen to our Brotherhood of Light." }
WordHunterWoW_QuestEN[27621] = { title = "Firebeard's Patrol", description = "I was on my way to join Firebeard's Patrol when my bird was shot down.\n\nTwilight's Hammer launched surprise attacks all over the Highlands. Sometimes their buildings crawled right out of the earth in the middle of our villages. It was a nightmare!\n\nIn the chaos, Firebeard is one of the few who's kept his head on straight. He's trying to piece together a full gryphon wing from the survivors.\n\nIf you want to bring the Wildhammer into the Alliance, start by helping out Firebeard, to the west.", objectives = "Seek out Keegan Firebeard at Firebeard's Patrol in Twilight Highlands.", completion = "Come to join the patrol, lad? Glad to have ya.\n\nI need some bodies helpin' to get our defenses under control here. Help me out and I'll see if I can't find some more prestigious work for ya." }
WordHunterWoW_QuestEN[27622] = { title = "Mo' Better Shredder", description = "{name}, I've got plans for a better shredder. But my engineers can't wade into a combat zone alone.\n\nGo locate a salvageable shredder in the Twilight Shores, and use it to signal one of my salvage experts to join you. Defend the shredder while we make some \"upgrades.\"\n\nThe Alliance won't know what hit them! At least, not until my marketing campaign kicks in!", objectives = "Locate a Salvageable Shredder on the Twilight Shores, and use it to summon a Bilgewater Salvage Expert. Defend the shredder until it is operational again.", completion = "That's right baby! That's right! Cold steel and hot death!\n\nWhat should we name our new creation? The Gnugatron? No - better - the <name>-o-matic. That's got a ring to it." }
WordHunterWoW_QuestEN[27623] = { title = "Colossal Guardians", description = "The chest containing the scepter appears to be magically sealed and will not budge.\n\nThe plaque above it depicts two giant statues holding star and moon-shaped stones sockets at their center.\n\nThe two statues are pictured guarding pyramids that look like the ones outside.\n\nPerhaps it's worth your while to investigate these.", objectives = "Obtain the Stone of the Moon and the Stone of the Sun from the Colossal Guardians.", progress = "You wipe away the sand from the hieroglyphs only for them to become covered in a new layer.  You'd best hurry.", completion = "You place the two gems inside the sockets in the wall." }
WordHunterWoW_QuestEN[27624] = { title = "After the Fall", description = "Aww, that was nothin', really.\n\nThose statues were teetering as it was - just needed a little push is all.\n\nHow about you go and sort through that rubble?\n\nI've got a feeling we're close to getting this all sorted out.", objectives = "Collect the Orb of the Morning Star, the Orb of the Evening Star, Orb of the North Star and the Orb of the Shooting Star.", progress = "Find anything interesting, <name>?", completion = "Fine work, <name>.\n\n\n\nIt looks as though our work here is nearly complete." }
WordHunterWoW_QuestEN[27625] = { title = "In Defense of Quel'Danil", description = "The undead are here! The Forsaken! They've been moving closer and closer, but to launch an all-out attack on us... those horrid abominations!\n\nThe young draenei I was charged with have trained with the Highvale elves in combat. They are not defenseless, but they need help!\n\nPlease, {name}, assist them! Drive back the Forsaken!", objectives = "Slay 16 Deathstalker Invaders at Quel'Danil Lodge.", completion = "Such aberrations in the face of the light... You are brave to face them, <name>." }
WordHunterWoW_QuestEN[27626] = { title = "The Highvale Documents", description = "The Highvale have kept detailed records here for years. Deaths, births, seasons... but also vital scouting information and methods of contact with the rest of the Alliance.\n\nThe documents will be scattered in the chaos. If they fall into the hands of the Forsaken, more lives could be at risk! Please, you must retrieve the documents before they are taken by the Horde...", objectives = "Collect the Highvale Report, the Highvale Records, and the Highvale Notes.", progress = "Are they safe?", completion = "Thank the Light. We will not let the Forsaken have anything that can be turned against us, no matter how small." }
WordHunterWoW_QuestEN[27627] = { title = "Just a Fancy Cockroach", description = "Evidently, the ancient statues were home to various species of scarab.\n\nDetermined to leave this site in the best condition possible, you resolve to ridding the chamber of these pests.", objectives = "Kill 5 Amethyst Scarabs, 5 Sapphire Scarabs, 5 Turquoise Scarabs, and 5 Emerald Scarabs." }
WordHunterWoW_QuestEN[27628] = { title = "Send Word to Phaoris", description = "Hurry, {name}.  We must speak to my brother, the king.\n\nHe is bent on averting war with Al'Akir and the Neferset.  He has foolish hopes that there is a diplomatic solution to this problem.\n\nMaybe once he hears what occurred here he will see reason.", objectives = "Speak to King Phaoris at Ramkahen in Uldum.", completion = "This is just the beginning, <name>.  If Deathwing's minions can bury entire cities, we have little chance of defeating them through conventional means." }
WordHunterWoW_QuestEN[27629] = { title = "The Vizier's Vote", description = "Getting Vizier Tanotep to go against my brother's wishes is going to be extremely difficult.  His very position is based on enforcing the will of Phaoris.\n\nI've had little luck making the case for open war against Neferset.\n\nNevertheless you must speak to him.  Perhaps he will listen to an outsider's perspective.\n\nYou will find the Vizier at the Akhenet Fields on official business.", objectives = "Speak to Vizier Tanotep at the Akhenet Fields in Uldum.", completion = "What manner of creature are you?  You will leave the king's lands before...\n\nWait!  You are that <name> I've heard so much about.\n\nYou must pardon my lack of hospitality.  We have seen all manner of hostile intruders since the barrier around Uldum failed." }
WordHunterWoW_QuestEN[27630] = { title = "The High Priest's Vote", description = "High Priest Amet's vote is the only one that is completely outside of our control.\n\nHe will vote as his divinations tell him and nothing we do will dissuade him.\n\nI figure that gives us even odds either way.\n\nThe only problem we face is that his clairvoyance has failed him ever since the barriers around Uldum fell.\n\nHe will not cast a vote unless he regains power over his divinations.\n\nTake the stairs at either side of the Vir'naal Dam and Speak to him to see what you can do to help.", objectives = "Speak to High Priest Amet inside the Vir'naal Dam in Uldum.", completion = "War, you say.\n\nDivinations for war are always difficult.  Some wars must never be fought, even if victory was assured.  Some wars have to be waged even if defeat is certain." }
WordHunterWoW_QuestEN[27631] = { title = "The High Commander's Vote", description = "If we're to pass a resolution for war, the high council's vote needs to be unanimous.\n\nI'm certain High Commander Kamses will give us his vote once he hears about what happened at Orsis.\n\nPlease speak to him in Ramkahen and make sure that's the case.  I must make preparations in case our plan fails.", objectives = "Speak to High Commander Kamses at the Ramkahen Legion Outpost in Uldum.", completion = "No need to fill me in on the events in Orsis, <name>.\n\nI've heard about them already.  And about you.  Any enemy of Al'Akir is a friend of mine." }
WordHunterWoW_QuestEN[27632] = { title = "Tanotep's Son", description = "I have devoted my life to serving the King.  That service is unrivaled in importance by anything... with one exception: my son.\n\nTahet was captured by Neferset sentries.\n\nThey claim my son was trespassing upon their territory.  Phaoris is attempting to negotiate his release... but I fear for the worst.\n\nIf you were to find Tahet, I would pledge my vote to you.\n\nI do not know where they take the prisoners, but I've seen the guards consult maps to guide them through the thick vegetation.", objectives = "Obtain the Vir'Naal Delta Map from a Neferset Guard.", progress = "This might be the map you're after.", completion = "You've obtained a map of the Vir'Naal river delta." }
WordHunterWoW_QuestEN[27633] = { title = "The Blood God Hakkar", description = "Hakkar... The mere mention of The Soulflayer's name will send many running. In the Sanctum of the Fallen God the Atal'ai have recovered a significant portion of his skeleton and seek to restore him to life. Already his children have begun to show up in the area.\n\nPlace this egg in that sanctum, and it will force his summoning prematurely. {name}, do not hesitate. Strike once his avatar appears!", objectives = "Kill the Avatar of Hakkar.", completion = "You have successfully stopped Hakkar here, but I fear we are far from done. The Atal'ai transported most of the blood they produced to Zul'Gurub, where the Hakkari work to summon The Blood God there.\n\n<name>, I do not think that this was ever meant to be the place of Hakkar's arrival - it was merely a test to see if the blood was potent enough! Hakkar can only be summoned in Zul'Gurub...and I fear we may be too late to stop the Hakkari with the blood they now have in their possession." }
WordHunterWoW_QuestEN[27634] = { title = "The God Hakkar", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the Egg of Hakkar.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris." }
WordHunterWoW_QuestEN[27635] = { title = "Decontamination", description = "You've been down here in Gnomeregan for a long time, {name}, and it's amazing that you've survived and kept your wits so long! We need to get you out.\n\nBefore we can send you to the surface to join the rest of the gnomes, you have to go through the decontamination process. Just head into the next room and board the Sanitron 500. It will do the rest! It shouldn't even hurt... much.\n\nWhen you're all done, check in with Technician Braggle and he'll make sure you get some suitable gear.", objectives = "Board the Sanitron 500 to begin the decontamination process.", completion = "There, now you're fit to head off to the surface and start your new life. The High Tinker will be delighted to hear of your arrival." }
WordHunterWoW_QuestEN[27636] = { title = "Just You and Mathias", description = "The SI:7 are all dead. Time to find Master Mathias Shaw.\n\nGood thing the squad commander told you where he would be.", objectives = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the rest of my people?" }
WordHunterWoW_QuestEN[27637] = { title = "Just You and Mathias", description = "That's a blow to our efforts. Damn Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Master Shaw.", objectives = "Find Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.That's a blow to our efforts. Damn Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Master Shaw.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[27638] = { title = "Just You and Garona", description = "The Kor'kron are all dead. Time to find Garona Halforcen.\n\nGood thing the squad commander told you where she would be.", objectives = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", completion = "Where are the Kor'kron?" }
WordHunterWoW_QuestEN[27639] = { title = "Just You and Garona", description = "That's a heavy blow to our efforts. Damn that Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Garona.", objectives = "Find Garona Halforcen at the Twilight Citadel in the Twilight Highlands.That's a heavy blow to our efforts. Damn that Cho'gall!\n\nIt's a good thing that the squad commander told you where to find Garona.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[27640] = { title = "Dunwalds Don't Die", description = "As I understand it, you're to be looking to bring the Wildhammer clans together with the Alliance for war. Not sure you know what you're gettin' into.\n\nAnyway, if it's battle you're preparin' for, there's definitely one family you want by your side. Head southwest, to the opposite side of the Crucible of Carnage, and there you'll find Clan Dunwald's ruins. They're rightly ravaged, but that's not likely to be stoppin' the Dunwalds. It's just a matter of findin' them.", objectives = "Look for Dunwald family survivors in the Dunwald Ruins.", completion = "If it's Dunwalds you be lookin' for, it's Dunwalds you've found. A couple of'm anyway. I can't find me other brothers for the life of me." }
WordHunterWoW_QuestEN[27641] = { title = "While Meeting The Family", description = "Hey there, lad. I'm sure Keely's got you worrying about our brothers, but they can take care of themselves. They'll find their way back here one way or another.\n\nMaybe you can do me a favor while you're out meeting the family... Dunwald territory is still infested with Twilight's Hammer and their servants. I'd appreciate it if you could remind them that they're not welcome.", objectives = "Kill 20 Twilight's Hammer in Dunwald territory.", completion = "Now that's what I'm talkin' about lad. My kinda <race>." }
WordHunterWoW_QuestEN[27642] = { title = "Sifting Through The Wreckage", description = "The Twilight's Hammer were damn thorough when they sacked our town.  Me and me brothers may well be the only ones that held'm back. I gotta be sure though.\n\nAs you're siftin' through the ruins, keep an eye out for the bodies of me kinsmen. I wanna know if dere were any survivors... or if it seems like some might have gotten away.", objectives = "Search for the bodies of 12 Dunwald Victims.", completion = "That many dead, eh? Not seemin' likely that anyone outside of me brothers fought through it then. I guess I already expected as much.\n\nThanks for takin' the time to look for me." }
WordHunterWoW_QuestEN[27643] = { title = "Donnelly Dunwald", description = "So you be lookin' to find us, and I be lookin' to find me brothers. It sounds to me like we got some common ground in there abouts.\n\nDonnelly's our eldest, and while his size shows it, his wits might not. He's usually up in the northern ruins - in the hovel. Do ya think you might go lookin' for him for me? It'd be a right comfort if I knew he were safe.", objectives = "Find Donnelly Dunwald.", completion = "Hi friend! I don't think I know you... I'm Donnelly Dunwald.\n\nWhat's your name? I don't think I know you... Do I know you?" }
WordHunterWoW_QuestEN[27644] = { title = "Eoin Dunwald", description = "Eoin's one of the twins. He's got a penchant for the drink. You'll likely be findin' him over by the old well - the ale stores were in a building there.\n\nMind making him to pay his worrying sister a visit? Shouldn't take much convincin' if you can get to the ale first.", objectives = "Find Eoin Dunwald.", completion = "Of all the buildings in all the towns to collapse, why'd it have to be this one?!" }
WordHunterWoW_QuestEN[27645] = { title = "Cayden Dunwald", description = "Cayden's the other twin. He's got a thirst too, but not for ale. I'm sure he's been havin' a grand time of it since the Twilight came to our doorstep. Gettin' some of that aggression out of his system mayhaps.\n\nI'm thinkin' the best place to go lookin for him is at market row, by the old smithy. He used ta hang out there anyway, but since that place is swarmin' with the most Twilight, he's probably got all the more reason to be callin' it home now.\n\nBring'm back for me. In one piece would be nice.", objectives = "Find Cayden Dunwald.", completion = "Well look at ya, all geared and fancy. Keely send you to keep an eye on old Cayden, eh? Won't be needin' it. I got these louts handled.\n\nHahah! They chose the wrong dwarf to be ambushin' today! Ahahahahah!" }
WordHunterWoW_QuestEN[27646] = { title = "Finding Beak", description = "I lost me gryphon. Beak! Where are you Beak?!\n\nWanna help me find him? I know he's in da hovel. He hasta be.\n\nBeak?! Wheres are ya?\n\nI hope he's okay.", objectives = "Help Donnelly find Beak in Dunwald Hovel.", progress = "Did you find'm?! Please?", completion = "You found'm! You found Beak! I like you, new friend!\n\nI'm gonna go show Keely. Keely like Beak too." }
WordHunterWoW_QuestEN[27647] = { title = "Anything But Water", description = "Look, buddy. Either you're here to help me find some drink, or you're in the way.\n\nWhy don't ya go down to the old storehouse and look downstairs. I had a mighty suspicion that ol' bookkeeper up in there was sneaking sips between pages. I bet he has a keg in his basement!\n\nIf ya find anything, come straight back to me! No dallyin'... this is urgent!", objectives = "Check the cellar Eoin Dunwald mentioned for a keg.", progress = "You stink of sober! Find me some drink!", completion = "Donnelly's belly! That's more like it. Good to not be dyin' of the thirst again.\n\nHere, have some. Good ol' Eoin's never so impolite as ta not share!" }
WordHunterWoW_QuestEN[27648] = { title = "Once More Into The Fire", description = "Fine, fine. You want a piece of the action? You can join in.\n\nLet me know when you're ready ta go.", objectives = "Accompany Cayden Dunwald through the somewhat obvious ambush.", progress = "They keep comin an' I'll keep swinging!", completion = "A thing of beauty, isn't it? An' they keep comin' back for more. Love it!\n\nI'll go find Keely and settle her nerves in a bit. Just one more go through the row." }
WordHunterWoW_QuestEN[27649] = { title = "A Steady Supply", description = "Hey bud. Seeing as how you're so friendly and great and all, think you might do a dwarf a favor?\n\nThese are Dunwald ruins... there's SURE to be more stock in some of these buildings. If you come upon more ale, bring it my way, will ya? A good dwarf can never have enough!\n\nI'm thinkin' I'll find my way back to Keely, so ya might have to hunt me down, but I'll try'n make it worth it to ya.", objectives = "Collect 6 Barrels of Wildhammer Ale.", progress = "Where's me booze?", completion = "Woooooh! That's exactly what my belly needs!\n\nYou get me all the nice things." }
WordHunterWoW_QuestEN[27650] = { title = "Home Again", description = "Ya should find Keely. She'll be eager for word.", objectives = "Speak to Keely Dunwald at the Dunwald Holdout.", completion = "Thank you for bandin' my brothers back together. I know they're tough, but they're even tougher when they're side by side, and there's a lot of Twilight out there.\n\nYou're good to put a gal's heart at ease." }
WordHunterWoW_QuestEN[27651] = { title = "Doing It Like a Dunwald", description = "They already left to hunt down the ettin that lead the attack on Dunwald. I asked them to at least give ya a chance to catch up, but I'm not sure waitin's in their blood.\n\nThey made off towards the town square, in the center of the ruins. You should go join'm before ya miss out on all the fun.", objectives = "Speak to Flynn Dunwald and aid the Dunwald brothers in killing Darunga.", completion = "Thanks for your help. You've got a warrior's spirit in ya - you coulda fooled me for a Wildhammer if it weren't for your... well.. you know.\n\nI know Firebeard sent you to unite us. My love for that dwarf runs shallow, but you know now we've got plenty of reasons to make enemies of Twilight. If you see him, tell him that when the battle starts, the Dunwald family will be there." }
WordHunterWoW_QuestEN[27652] = { title = "Dark Assassins", description = "Even I get hunted. I suppose that's what I get for hiding amongst the sheep.\n\n<Mathias studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice bunch of guys. Dead now. They're made from the souls of the most skilled killers.\n\nWant to do me a favor? Hunt them down. Bring back their soul pendants.", objectives = "Collect 5 Dark Assassin Pendants.", progress = "How many pendants do you have?", completion = "I'm not sure what I'm going to do with all of these. I'll probably fence them and donate the proceeds to the Stormwind orphanage.\n\nNow to find someone sick enough to buy such a thing. It'll probably be a goblin. Or, a gnome warlock." }
WordHunterWoW_QuestEN[27653] = { title = "Dark Assassins", description = "Even I get hunted, {class}. But that's part of the fun of hiding amongst the sheep.\n\n<Garona studies you for a moment.>\n\nThe Twilight's Hammer has taken it up a notch and sent their dark assassins after me. Nice for a group of dead guys. They're made from the souls of only the most skilled killers.\n\nDo me a favor? Hunt them down.\n\nThey wear their souls in pendants about their necks. Bring them back to me. Souls optional.", objectives = "Collect 5 Dark Assassin Pendants.", progress = "How many pendants do you have?", completion = "What do you think I should do with all of these? Maybe I'll melt them down and have the metal imbued into a new dagger that I can thrust into Cho'gall's chest.\n\nThink there's time for that?" }
WordHunterWoW_QuestEN[27654] = { title = "Bring the Hammer Down", description = "No foray into the field would be complete without a good old-fashioned take-the-bad-guys-out kind of mission.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, I'm sure you'll have plenty of targets.\n\nHow you choose to kill them is up to you.", objectives = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", completion = "None of us are too good to get our hands a little dirty. Or bloody, in this case." }
WordHunterWoW_QuestEN[27655] = { title = "Bring the Hammer Down", description = "There's nothing worse than a self-hating Twilight's Hammer cultist. Nothing! These idiots actually want to bring about the end of the world.\n\nThat marks them for extinction in my book.\n\nBetween the citadel veterans, the corrupted elementalists, and the twilight vindicators, you should have no shortage of targets.\n\nI could care less how you choose to kill them.", objectives = "Slay 10 Citadel Veterans, Corrupted Elementalists, and/or Twilight Vindicators.", completion = "Feels good to get a little blood on your hands, doesn't it? Especially when that blood belongs to such self-deluded fools." }
WordHunterWoW_QuestEN[27656] = { title = "Croc-Out", description = "The Stagalbog east of town is swarming with crocolisks. Swarming, you hear me? I've sold every bit of crocolisk you could imagine.\n\nCrocolisk hides, teeth, tails, tongues, eyes, you name it. My point is, they ain't sellin' anymore. There's too many crocs! We're over-supplied and under-demanded.\n\nSo since they're of no use to me, and they occasionally eat my guests, I need you to just kill the suckers. Do me the favor, eh? I'll be here negotiatin' things with your people.", objectives = "Slay 8 Sawtooth Crocolisks.", completion = "All taken care of? Good to hear. Takes a load off my mind.\n\nNow I can focus on proper business for the fine folk of Marshtide and Stonard, weary from the war... and all that junk." }
WordHunterWoW_QuestEN[27657] = { title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Mathias spits.>\n\nWe need help. There's an Earthen Ring woman, Earthcaller Yevaa, southwest at the Elementium mine.\n\nShe and her goblin initiate need help with the shutting down the elemental portals hereabouts. I'm thinking that in exchange, she can help us with our problem.", objectives = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", completion = "<name>! I'm glad you're here.\n\nOf course, I'm more than happy to lend you whatever assistance that I can." }
WordHunterWoW_QuestEN[27658] = { title = "Help from the Earthcaller", description = "My investigation into Cho'gall's artifact has hit a dead end. The Twilight's Hammer enslaved a group of Wildhammer smiths and then drowned them in the lake when they were done with their services.\n\n<Garona spits.>\n\nI hate to say it, but we need help. There's an Earthen Ring woman, a draenei named Earthcaller Yevaa.  She and her pet goblin are southwest at the Elementium mine.\n\nThey need help with shutting down the elemental portals around here. In exchange, she can help us with our problem.", objectives = "Speak with Earthcaller Yevaa at the Elementium Depths in the Twilight Highlands.", completion = "<name>! I'm glad you're here.\n\nOf course, I'm more than willing to help you in any way that I can." }
WordHunterWoW_QuestEN[27659] = { title = "Portal Overload", description = "I used to be the caretaker of the Earthen Ring's portals here. But while we were away helping to save Deepholm, the Twilight's Hammer moved in and corrupted the area.\n\nThey're using powerful ascendants to guard our portals. That's where they've made a critical error.\n\nI want you to go to the portals and use the controllers to overload them. This will unleash all of the portal's energy, debilitating the ascendant. Slay it.", objectives = "Slay Debilitated Apexar, Debilitated Aetheron, and Debilitated Edemantus.", completion = "The last portal is deep within the mine here, but we'll deal with that in a bit." }
WordHunterWoW_QuestEN[27660] = { title = "Spirit of the Loch", description = "I have no knowledge of any artifact that Cho'gall is crafting, but I think I know one that can help.\n\nCountess Verrall is the ancient spirit of Loch Verrall to the north. She has no love for the Twilight's Hammer, who have polluted her waters.\n\nSeek her for the wisdom that you seek.", objectives = "Speak with Countess Verrall at Loch Verrall in the Twilight Highlands.", completion = "I know why you are here, <name>. Your reasons sing within your fluids.\n\nI know about the dead dwarf forgesmith polluting my lake. If you want to find out what his corpse remembers, you must earn it." }
WordHunterWoW_QuestEN[27661] = { title = "Fire the Cannon", description = "My arch-nemesis, Lord Cannon, has foolishly decided to throw his allegiance to the Twilight's Hammer.\n\nIn the past, we've coexisted with a shaky truce, but his change of heart leaves me little choice but to put an end to him. Or, I should say, if you want the information that you seek from the dead dwarf, you're going to kill Lord Cannon for me.\n\nSeek him at Cannon's Inferno to the southeast.", objectives = "Slay Lord Cannon.", completion = "I am pleased. Lord Cannon was always an unworthy adversary.\n\nVery well, <race>, I will help you gain the information which you seek." }
WordHunterWoW_QuestEN[27662] = { title = "Unbinding", description = "Look, if there's one thing I know, it's elementals. I've been able to really gain an appreciation for how they feel. Let me tell you, they don't appreciate being enslaved one bit!\n\nSo, what I'm saying here is that if you were to free the enslaved elementals, I'm sure that not only would they show their gratitude, they'd also likely turn on their masters.\n\nSounds like a win-win to me, {name}.", objectives = "Free 10 Enslaved elementals by slaying them at the Twilight Citadel.", completion = "What'd I tell you? Elementals aren't so bad after all, eh?" }
WordHunterWoW_QuestEN[27663] = { title = "Tastes Like Strider", description = "You there! Yes, you! You want a good word put in with the Trade Baron? Give me a hand!\n\nI heard you're the one that got all those makrura tails. They're wonderful, but not enough for proper swamp food. I need drumsticks for my gumbo!\n\nThere's plenty of swampstriders just outside town in the Sorrowmurk. I want the biggest drumsticks you can find!", objectives = "Collect 9 Jumbo Swampstrider Drumsticks from Swampstriders.", progress = "Have you got those drumsticks?", completion = "Ah, good, good! Just what I needed." }
WordHunterWoW_QuestEN[27664] = { title = "Darkmoon Volcanic Deck", description = "Now that you have gathered all of the Ember cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Volcanic Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Volcanic deck!   Congratulations!", completion = "So you have put together a deck of Embers.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[27665] = { title = "Darkmoon Hurricane Deck", description = "Now that you have gathered all of the Wind cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Hurricane Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Hurricane deck!   Congratulations!", completion = "So you have put together a deck of Hurricanes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[27666] = { title = "Darkmoon Tsunami Deck", description = "Now that you have gathered all of the Wave cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Tsunami Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a Tsunami deck!   Congratulations!", completion = "So you have put together a Tsunami deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[27667] = { title = "Darkmoon Earthquake Deck", description = "Now that you have gathered all of the Stone cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Earthquake Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete an Earthquake deck!   Congratulations!", completion = "So you have put together a deck of Earthquakes.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[27668] = { title = "Pay Attention!", description = "Listen, {race}. It's not that I don't appreciate the rescue and all, but this is a dire situation.\n\nYou have to pay better attention out there!\n\nI was watching, and you passed right over a busted alliance crate.\n\nThere's bound to be something in there that could help me and my boys.\n\nHow about you get out there and take a look-see, hrm?", objectives = "Nazgrim wants you to see what lies in the broken Alliance crate north of The Immortal Coil.", completion = "Sure enough...\n\nThis looks to be something that Nazgrim will take quite an interest in." }
WordHunterWoW_QuestEN[27669] = { title = "Do the Honors", description = "It looks like all that's left to do is to place the orbs on the pedestals at each corner of this mechanism.\n\nWe appear to have stumbled upon what may be the most important find in modern history.\n\n<Harrison looks at you for a moment, then hands you the orbs.>\n\nWell, go ahead, {name}.\n\nWe'd have never made this discovery without you.", objectives = "Use the Orbs of the Stars near the mechanism in the Chamber of the Stars.", completion = "Well, now. Would ya look at that!\n\nAs amazing as this is, I am confident that there's more to our discovery than meets the eye...\n\nMuch more." }
WordHunterWoW_QuestEN[27670] = { title = "Pinned Down", description = "My name is Nevin Twistwrench and I'm the commander of the Survivor Assistance Facilitation Expedition, or S.A.F.E.\n\nI don't know how you managed to survive the radiation down here, {name}, but most of the others haven't fared so well. My team is rounding up the survivors, but the radiation-addled leper gnomes are too numerous for us to hold back much longer. They've lost their minds!\n\nIf you're still strong enough to wield a weapon or cast a spell, would you help us clear out some of these leper gnomes?", objectives = "Kill 6 Crazed Leper Gnomes.", progress = "Help my men get the way cleared out so we can help the other survivors get out of here!", completion = "Well done, <name>. My men can take it from here. Let's focus on getting the other survivors out now." }
WordHunterWoW_QuestEN[27671] = { title = "See to the Survivors", description = "If we don't do something quick, neither Nevin nor the survivors will make it out of here alive. I'm going to give you my squad's emergency teleport beacon. We still have enough strength and ammunition to fight our way out of here, but those survivors are in no condition to make a run for it.\n\nUse the beacon on survivors to arrange for them to be teleported out of here to the safe area my men have set up. Once you've done that, report back to me and we'll make arrangements to get you out of here.", objectives = "Use the Teleport Beacon to teleport 6 Survivors to safety.", progress = "Nevin's team found a lot of survivors this time, but he's cutting it awful close.", completion = "I know Nevin will be pleased with all the survivors you managed to help. I still can't believe you managed to stay so strong down here in the radiation. You've seen the shape the other survivors are in.\n\nLet's get you to the loading room for decontamination." }
WordHunterWoW_QuestEN[27672] = { title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a door which leads to the legendary Chamber of Khaz'mul. Who knows what secrets could be hidden inside!\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to unlock the secrets of Uldaman!", objectives = "Defeat Ironaya.", completion = "Don't worry about the chamber, my boys will check it out! You have more important things to do!" }
WordHunterWoW_QuestEN[27673] = { title = "It's What's Inside That Counts", description = "The Makers built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI fear that one of the Old Gods is responsible for this, and you're going to help me see if that's the case! Topple both of the guardians and bring me their power cores. They'll tell us all we need to know. ", objectives = "Obtain the Obsidian Power Core and the Titan Power Core.", progress = "Where are the cores, lad? By Muradin's Beard, where are the bloody cores?\n\n<Kand takes a deep breath.>\n\nSorry about that. Have you been able to obtain the cores?", completion = "This is incredible, <name>. The power coursing through each core...the contrasting powers so close together!\n\nI'll take this to the proper dwarves right away. These cores are extremely important!" }
WordHunterWoW_QuestEN[27674] = { title = "To the Surface", description = "Nevin has just sent word that he and his men are making their way to the surface. He'll be waiting for you in the building that S.A.F.E. has established as its headquarters.\n\nSee Torben Zapblast over there? Talk to him when you're ready to head to the surface and he'll arrange to have you transported up there. It's been a pleasure meeting you, {name}, and I'm honored to have played a small role in helping you escape from Gnomeregan to start your life on the surface.", objectives = "Speak to Torben Zapblast to get teleported to the surface and report to Nevin Twistwrench.", progress = "It's good to see you again, <name>.", completion = "It's good to see you again, <name>. Without your help, we wouldn't have been able to get so many survivors out of Gnomeregan this time. Everyone is going to be thrilled to meet you and hear your story." }
WordHunterWoW_QuestEN[27675] = { title = "Forged Documents", description = "Find a resident in Stormwind City to accept your forged documents.", objectives = "Find a resident of Stormwind City to accept your Forged Documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>" }
WordHunterWoW_QuestEN[27676] = { title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Explorers' League is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", objectives = "Kill Galgann Firehammer.", completion = "Fantastic! Great work! We'll know all that Dig Three has to tell us in no time at all!" }
WordHunterWoW_QuestEN[27677] = { title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. The secrets on these discs could change everything about how we view our world. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe problem is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for the Explorers' League!", objectives = "Defeat Archaedas.", completion = "Well done, lad! Now go to the discs and learn all you can!" }
WordHunterWoW_QuestEN[27678] = { title = "The Platinum Discs", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with stone watcher and learn what ancient lore it keeps. Then, tell Lead Prospector Durdin what you found out!" }
WordHunterWoW_QuestEN[27679] = { title = "The Chamber of Khaz'mul", description = "In the Map Chamber there is a locked door which I believe leads to the legendary Chamber of Khaz'mul. We do not yet know what artifacts wait inside it.\n\n\n\nWhat we do know is that it is guarded by Ironaya, a Titanic Watcher of immense size and power. You'll need to defeat her if you intend to progress any further into this place.", objectives = "Defeat Ironaya.", completion = "Reliquary agents are en route to investigate the chamber. You have more important matters to attend to." }
WordHunterWoW_QuestEN[27680] = { title = "Archaedas, The Ancient Stone Watcher", description = "The true goal in Uldaman is to obtain the Discs of Norgannon. These platinum discs could grant our order unbelievable power. Countless secrets of the Makers are inscribed on them...their value is beyond any material wealth you could possibly imagine.\n\nThe only problem in obtaining them is that Archaedas, an ancient and powerful creation of the Makers, guards the discs with a venerable army at his disposal. I need you to defeat him and secure the discs for The Reliquary.", objectives = "Defeat Archaedas.", completion = "You are a most reliable agent, <name>. Proceed to the discs and learn all you can. Report back to me immediately after." }
WordHunterWoW_QuestEN[27681] = { title = "Behind Closed Doors", description = "Galgann Firehammer and his band of Dark Irons are in Dig Three guarding a door that we know nothing about!  I've had it with their men getting in the way of our work here! The Reliquary is the only group authorized to handle the artifacts throughout Uldaman!\n\nGo to the dig and dispose of him so that our work can continue undisturbed. I want to know what's behind that door!", objectives = "Kill Galgann Firehammer.", completion = "Well done. Dig Three and any secrets beyond that door will soon be ours and ours alone." }
WordHunterWoW_QuestEN[27682] = { title = "We Require More Minerals", description = "The Titans built two Ancient Stone Keepers to help protect Uldaman from would-be invaders and to oversee daily operations while Ironaya and Archaedas slumber. One is still fully operational in Temple Hall, but the one in Echomok Cavern has been corrupted by something.\n\nI suspect that one of the Old Gods is responsible for this, and you're going to help me see if that is indeed true. Topple both of the guardians and bring me their power cores. They'll tell us all we need to know. ", objectives = "Obtain the Obsidian Power Core and the Titan Power Core.", progress = "Do you have the cores with you, or are you just here to chat? Perhaps we should stop this whole charade and enjoy some snacks and fine wine instead?", completion = "Both of these cores are still far more potent than most of the cores we use  to power our own protectors, and these are ancient devices!\n\nThank you, these will prove extremely valuable to our society." }
WordHunterWoW_QuestEN[27683] = { title = "Into the Woods", description = "I saw the strangest commotion coming through town the other day.  A horse-drawn cart, loaded with crates and chests, a worgen woman at the reins, a blood elf by her side, and a dwarven paladin running behind, yelling some of the most creative obscenities I've heard in quite some time.\n\nThey looked like they were headed to Eastern Plaguelands, though I'd imagine they can't be far past the Thondroril River by now.  I wonder what they were up to?", objectives = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", completion = "Yes?" }
WordHunterWoW_QuestEN[27684] = { title = "Visitors", description = "My sources at the Menders' Stead have informed me that we will be having some visitors soon.  A group of paladins - led by a worgen tradeswoman, of all things - will be arriving here shortly.  I look forward to meeting them.  Particularly one of them.\n\nWould you mind stopping in and checking in on them?  I can't say for sure, but by the time you get there, they should just be crossing the Thondroril River, far to the west.", objectives = "Find a worgen woman at the Thondroril River in Eastern Plaguelands.", completion = "Yes?" }
WordHunterWoW_QuestEN[27685] = { title = "Good Deed Left Undone", description = "G'day, laddie.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nSo... in our rush ta git over here, we left a little unfinished business off to the east a ways.\n\nA little lady was near death herself. We had no choice but ta leave her by a little air vent when we came here to yer rescue.\n\nHow bout yeh git over and help her while there's still time?", objectives = "Speak to Adarrah in the Kelp'thar Forest.", completion = "Oh, finally...\n\nI don't know how much longer I can last!" }
WordHunterWoW_QuestEN[27686] = { title = "Forged Documents", description = "Find a resident in Orgimmar to accept your forged documents.", objectives = "Find a resident of Orgimmar to accept your Forged Documents.", progress = "Do you have something for me?", completion = "<You hand over the forged documents, exchanging only a few words; your masterful skill speaks for itself.>" }
WordHunterWoW_QuestEN[27687] = { title = "An Opened Can of Whoop Gnash", description = "What an accomplishment, felling a  mighty sea giant!\n\nThe new residents of Smuggler's Hole will feel considerably safer knowing this monster is no longer loitering outside their haven.", objectives = "Bring Gnash's Head to Samir in Smuggler's Hole.", progress = "You took down that Sea Giant, <class>?", completion = "It's not much, but it's all I've got down here.\n\nYou're more than welcome to it, <class>." }
WordHunterWoW_QuestEN[27688] = { title = "Distract Them for Me", description = "There are three candidates for Ascendancy that we need to eliminate: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI'd like for you to serve as my distraction. When the time is right, I'll step in and finish them off from behind.\n\nWhatever you do, {name}, do not underestimate them. Each got to where they are by being ruthless and very good at what they do.", objectives = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", completion = "That takes care of most of their leaders outside of the Bastion of Twilight.\n\nWe work well together, <name>." }
WordHunterWoW_QuestEN[27689] = { title = "Distract Them for Me", description = "There are three candidates for Ascendancy that need killing: Dame Alys Finnsson, Master Klem, and Mia the Rose.\n\nI want you to serve as a distraction. When the time is right, I'll step in to finish them off from behind.\n\nJust make sure that whatever you do, you don't underestimate them, {name}. Each of those lunatics got to where they are by being ruthless and very good at what they do.", objectives = "Slay Dame Alys Finnsson, Master Klem, and Mia the Rose.", completion = "That takes care of most of their leaders outside of the Bastion. Not bad work, <name>. Not bad at all." }
WordHunterWoW_QuestEN[27690] = { title = "Narkrall, the Drake-Tamer", description = "{name}, the stronghold at Bloodgulch is the heart of the Dragonmaw empire in the Highlands. It is just up the river. Narkrall Rakeclaw is using his considerable power to amass a wing of drake-riders there.\n\nFor the Dragonmaw to succeed, Bloodgulch must succeed. Go to Narkrall and make sure it is so.", objectives = "Report to Narkrall Rakeclaw at Bloodgulch in the Twilight Highlands.", completion = "<Narkrall sizes you up.>\n\nAnother mewling Horde whelp? Zaela saps our strength by diluting our forces with the weak. Very well, <class>. Prove yourself to me, and show me what your Horde is made of." }
WordHunterWoW_QuestEN[27691] = { title = "Marshfin Madness", description = "I'm afraid the rest of the Steamwheedle here are gone. All the young ones at the camp to the east were lost when the murlocs came.\n\nYes, there's always been murlocs on these shores... but not in these numbers. They came in droves from the sea at night, howling and frothing, swarming up onto the land to attack!\n\nWe can't have them still running around, now can we? Would you put an old goblin at ease and go beat some of them back into the water?", objectives = "Slay 12 Marshfin Murlocs.", progress = "I've still got a few tricks up my sleeve, but I'm not going to tussle with murlocs if I don't have to.", completion = "You have to wonder just what's out there. This is the coast of the Forbidding Sea, with nothing beyond its reaches... but all these fishy folk just stomped right out of it.\n\nWhat's more, I saw where they've been going..." }
WordHunterWoW_QuestEN[27692] = { title = "Princess Theradras", description = "Do not be alarmed, young {race}. I am Zaetar, son of Cenarius, and I come to you for your assistance.\n\nLong ago, I made the mistake of mating with Princess Theradras, a powerful earth elemental aligned with the Old Gods. Our children, the centuar Kahns, turned on me upon birth and slew me mercilessly. Now, Theradras' taint runs deep and threatens far more than just Maraudon.\n\nCome slay her and free my spirit so that we may restore Desolace to a place of verdant life and promise, as Cenarius would want.", objectives = "Kill Princess Theradras.", completion = "Thank you, <name>. As you can see, my mere presence here has resulted in a bloom of glorious life despite my mate's presence. Names aside, perhaps one day you will again venture into Desolace and find it a verdant oasis free of any traces of the Old Gods." }
WordHunterWoW_QuestEN[27693] = { title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", objectives = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions." }
WordHunterWoW_QuestEN[27694] = { title = "Pool of Tears", description = "The trolls that lurk within this temple have done grievous harm to my kind, {name}. We were sent here to guard this place, and were instead used to unleash the terrible powers within.\n\nI must beg you for the help only a mortal can give. You can be my hand within the temple; should I enter by myself, I risk being turned against my brothers as well.\n\nWe shall make a pact. If you wish to help, first gather Atal'ai artifacts from the waters around the temple, and return them to me.", objectives = "Collect 5 Atal'ai Artifacts from the Pool of Tears surrounding the Temple of Atal'Hakkar.", progress = "Your gathering of these artifacts will be a sign of faith. Once rendered, I will perform the ritual.", completion = "The essence of the green dragonflight wafts from these artifacts; the vestiges of my corrupted kin. In purifying them, I form a bond between us.\n\nStep forward, <name>, and receive the Oathstone of Ysera's Dragonflight." }
WordHunterWoW_QuestEN[27695] = { title = "The Elementium Axe", description = "The Twilight cowards have captured and killed too many red dragons, but one yet lives. Do you remember Lirastrasza? She's shackled nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut through her chains.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", objectives = "Obtain the Elementium Axe.", progress = "Do you have the axe? They're going to kill Lirastrasza soon.", completion = "That thing looks sharp. Sharp enough to the do deed, at least.\n\nBut if I'm a judge of weaponry, that's not what Cho'gall's after." }
WordHunterWoW_QuestEN[27696] = { title = "The Elementium Axe", description = "The Twilight cowards have captured and killed many red dragons, but one's still breathing. Do you remember Lirastrasza? She's chained nearby and we're going to free her.\n\nBut first, we need something sharp enough to cut her free.\n\nThere's an old ettin named Blindeye the Guardian. He stands watch at the Altar of Ascension to the south.\n\nHe has a purely-wrought Elementium axe. I wonder if that's Cho'gall's \"ultimate\" weapon?", objectives = "Obtain the Elementium Axe.", progress = "Do you have the axe?", completion = "That's a very sharp axe. It'll do the job, but if I'm any judge of weaponry, that's not what Cho'gall's after." }
WordHunterWoW_QuestEN[27697] = { title = "Corruption in Maraudon", description = "{name}, I require your assistance immediately! I am Zaetar, son of Cenarius, and I am trapped here after an unfortunate series of events! Before saving me is an option, you must help me clean out the corruption that runs so rampant through Maraudon.\n\nLord Vyletongue is the satyr ruler of the purple crystal caverns. He is an insidious agent of the Burning Legion and his continued presence can only lead to chaos and death. He can live no longer!", objectives = "Kill Lord Vyletongue.", completion = "Excellent work, <name>! Eliminating Vyletongue's presence is a key step to freeing me and, ultimately, saving these lands from corruption. Take this as a token of my thanks and an incentive to continue your work here." }
WordHunterWoW_QuestEN[27698] = { title = "Servants of Theradras", description = "Princess Theradras, my former mate, has used her enormous power to corrupt the very nature of Maraudon. Even now her creations run rampant here, and I fear that they may soon escape into the open world to sow the seeds of death and destruction.\n\n{name}, venture forth and kill Noxxion and Razorlash. They are two of her most powerful minions and their deaths would cause the callous Princess much deserved grief and suffering of her own. Then, perhaps, you can help free my spirit from her grasp.", objectives = "Kill Noxxion and Razorlash.", completion = "Without her powerful servants, Princess Theradras is significantly more vulnerable. Find her lair, <name>...it is time to strike." }
WordHunterWoW_QuestEN[27699] = { title = "Shark Weak", description = "That's one tough shark!\n\nYou determine that it's in everyone's best interest to try and distract Budd and hope his attention never returns to Gnaws and this Skeletal Reef.\n\nPerhaps the teeth of the beast will prove captivating enough...", objectives = "Collect 5 of Gnaws' teeth from the Skeletal Reef.", progress = "Whatcha got there, pal?", completion = "What?!\n\nGnaws ain't dead?!\n\nThis kinda takes the quick outta my get rich quick scheme...\n\nThem giant shark teeth are nice and all, but we can't stop 'til that shiney is ours!" }
WordHunterWoW_QuestEN[27700] = { title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her.\n\nI need you to take the Elementium Axe and free her from her bonds.", objectives = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", progress = "Use the axe to break Lirastrasza's chains.", completion = "Isn't she a beauty?\n\nLet's see what she does now that she's free." }
WordHunterWoW_QuestEN[27701] = { title = "Dragon, Unchained", description = "Lirastrasza is the last and greatest of the red dragons that the Twilight's Hammer captured. They're about to kill her, {class}.\n\nYou need to take the Elementium Axe and free her from her bonds before they do.", objectives = "Use the Elementium Axe to break the chains enslaving Lirastrasza.", completion = "Isn't she beautiful? So graceful.\n\nI hope she gets her fill of revenge and then some." }
WordHunterWoW_QuestEN[27702] = { title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are drakes that she's downing that need finishing off, {name}. Wouldn't want the Twilight's healers to get them back up into the air.\n\nTime for a little Coup de Grace.", objectives = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", completion = "Our efforts to improve relations with the red dragons has really paid off, <name>." }
WordHunterWoW_QuestEN[27703] = { title = "Coup de Grace", description = "Look at that. Lirastrasza's destroying them!\n\nThere are still drakes that she's downing that need finishing off, {name}. We don't want the stinking Twilight healers to get them back up into the air.\n\nTime for a little Coup de Grace.", objectives = "Deliver a Coup de Grace on 5 Twilight Skyterrors.", progress = "That's all? I think that you can finish off a few more.", completion = "Good thing that you and Warlord Krogg made friends with the red dragons." }
WordHunterWoW_QuestEN[27704] = { title = "Legends of the Sunken Temple", description = "I will need you to enter the temple first, {name}. I can join you once a path is secure, but I dare not enter blindly. Turned against my kind, I would be a vicious enemy.\n\nYou can start by descending the stairs behind me. Then, swim through the flooded depths of the Broken Hall. Once there, follow the passageway to the right to find the Hall of Masks.\n\nBeware of any temple guards. Once you have found the Hall of Masks, I will contact you through the Oathstone.", objectives = "Journey through the antechambers of the temple to the Hall of Masks.", progress = "You must not falter, <name>. Your actions will pave the way for me to enter the temple myself.", completion = "This is it!\n\nThese are the bones of my kin..." }
WordHunterWoW_QuestEN[27705] = { title = "Step One: The Priestess", description = "My brethren are being butchered here. It's as I thought.\n\nI must ask your help further before I enter, {name}. In the passageway outside this room, the hallway proceeds left and right. To the right, it goes down to the Chamber of Blood. Here the Atal'ai perform their dark rituals.\n\nThey have expected and prepared for my kind for years, but not for you. Enter the Chamber of Blood and slay the Priestess Udum'bra. She is one of three foul presences here that must be vanquished before I may enter.", objectives = "Slay Priestess Udum'bra in the Chamber of Blood.", progress = "You must not falter, <name>. Your actions will pave the way for me to enter the temple myself.", completion = "Good riddance. Another source of corruption in this world put to rest.\n\nI thank you for your bravery, <name>." }
WordHunterWoW_QuestEN[27706] = { title = "The Scepter of Orsis", description = "The chest below unlocks with a loud click as you insert the two stones into the plaque.\n\nObtain the scepter and bring it back to General Ammantep.", objectives = "Obtain the Scepter of Orsis from the Sacred Receptacle.", progress = "You're back, <name>!", completion = "So... this is what Al'Akir wanted all along." }
WordHunterWoW_QuestEN[27707] = { title = "Neferset Prison", description = "Hieroglyphs depicting a chained Tol'vir mark the southeastern corner of the map.\n\nPerhaps Tahet was brought there when he was imprisoned.", objectives = "Go to the Neferset Prison Camp and find the whereabouts of Tahet." }
WordHunterWoW_QuestEN[27708] = { title = "The Warden's Time", description = "<Erunak's image penetrates your mind.>\n\nYou have done well, {name}, but more remains to be done.\n\nBefore moving on from this place, let us be sure that we leave it in disarray.\n\nFind the one who leads these naga and repay him for his misdeeds.", objectives = "Erunak Stonespeaker wants you to slay Warden Azjakir at The Clutch.", completion = "It is good that this operation has been undone.\n\nSoon, I must move on..." }
WordHunterWoW_QuestEN[27709] = { title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", objectives = "Complete the Sentinel's Game by connecting the two red statues." }
WordHunterWoW_QuestEN[27711] = { title = "Back to the Elementium Depths", description = "The Earthcaller's initiate, Goldmine, has need of you.\n\nI think that they're ready for you to help them with whatever's down in that mine.", objectives = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", completion = "<name>, glad you're back! Have I got something fun for us to do!" }
WordHunterWoW_QuestEN[27712] = { title = "Back to the Elementium Depths", description = "The Earthcaller has a goblin initiate? Goldmine is his name? He has need of you.\n\nI think that they're ready for you to do their dirty work with whatever's down in that mine.", objectives = "Speak with Initiate Goldmine at the Elementium Depths in the Twilight Highlands.", completion = "<name>, glad you're back! Have I got something fun for us to do!" }
WordHunterWoW_QuestEN[27713] = { title = "The Day that Deathwing Came", description = "Deathwing made quite a mess when he passed through these parts.  If it weren't for me, he'd probably still be here, layin' waste to all the good people of the Badlands.\n\nWhat, you don't believe me?  Fine, let me tell you the whole story.", objectives = "Listen to Theldurin's tale.", progress = "Are you going to listen or not?", completion = "Some story, huh?  Now you know why Deathwing hasn't come back here since." }
WordHunterWoW_QuestEN[27714] = { title = "The Day that Deathwing Came: The Real Story", description = "Not only was Theldurin's story wrong, it was boring, unimaginitive, and slow.\n\nI'll tell you how things really happened on that day.", objectives = "Listen to Lucien Tosselwrench's version of the story.", progress = "I'm not done with my story yet.  Sit back down.", completion = "The end!  No moral." }
WordHunterWoW_QuestEN[27715] = { title = "The Day that Deathwing Came: What Really Happened", description = "These two have no idea how to tell a story.  Theldurin's story was too short, and Lucien's tale was a little too tall, if you catch my drift.\n\nAlso, neither of their stories had action and fans admiring my awesomeness in them.\n\nSit back, {name}.  I'll tell you what really happened that day.", objectives = "Listen to Martek the Exiled's version of the story.", progress = "I seem to have lost my place... let's see... where was I...", completion = "I can't believe those guys would interrupt me like that.  My story was going so well, too...\n\nAnyhow, thanks for sticking around so long.  It's nice to have someone new to share tall tales with.  I'm sure Lucien and Theldurin feel the same way.\n\nYou have any you'd like to share with us?" }
WordHunterWoW_QuestEN[27716] = { title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Levia Dreamwaker, back with the Nespirah survivors, was looking for something exactly like this.>", objectives = "Bring the Ancient Elven Etching to Levia Dreamwalker. You should find her with the Alliance Nespirah Survivors.", progress = "Hah! Did you see the admiral giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! It will take me a while to translate, but this is precisely the kind of find I was hoping for.\n\nThere's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, <name>. Here... perhaps I have something that may be of use to you." }
WordHunterWoW_QuestEN[27717] = { title = "Piece of the Past", description = "<An ancient, slightly cracked slab of stone with an immense number of inscriptions etched on all sides of it. You're unable to decipher the language, but the sheer amount of text and the semi-ornate nature of the stone suggest that this might carry significant value.>\n\n<Elendri Goldenbrow, back with the Nespirah survivors, was looking for something exactly like this.>", objectives = "Bring the Ancient Elven Etching to Elendri Goldenbrow. You should find her with the Horde Nespirah Survivors.", progress = "Hah! Did you see the captain giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offer us some opportunity to salvage some usefulness out of this whole mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. Wait... what's that you have there?", completion = "Brilliant! I can't have expected much more with the tools I gave you.\n\nI should be able to fill in the blanks and get this all written out shortly. There's no knowing if we will make it out of this place, but if it comes down to it, I will find a way to float this to the surface in hopes that it will one day be found.\n\nThank you again, <name>. You're not bad." }
WordHunterWoW_QuestEN[27718] = { title = "Warchief's Command: Vashj'ir!", description = "All able-bodied members of the Horde are hereby ordered to report to Commander Thorak at Bladefist Bay in Durotar.\n\nNow, more than ever, your help is needed in battling our most hated enemy, the Alliance!\n\nTo reach Bladefist Bay you must travel south through the main gates of Orgrimmar and enter Durotar. From there, follow the path east to the coast. Thorak will be standing at his post near the docks.\n\nOnward, brother! Destiny calls!", objectives = "Report to Commander Thorak at Bladefist Bay in Durotar.", completion = "Lok'tar, brother! You have arrived just in time." }
WordHunterWoW_QuestEN[27719] = { title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen, take your information and be gone from my demesne.", objectives = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?" }
WordHunterWoW_QuestEN[27720] = { title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", objectives = "Ride the mine cart with Initiate Goldmine to the end of the line.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!" }
WordHunterWoW_QuestEN[27721] = { title = "Warchief's Command: Mount Hyjal!", description = "All able-bodied members of the Horde are hereby ordered to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Blackhoof to gain entry into Moonglade. Blackhoof is located at the tauren district in the Valley of Wisdom in Orgrimmar.\n\nOnward, brother! Destiny calls!", objectives = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", completion = "We knew the Horde would send help and not a moment too soon!" }
WordHunterWoW_QuestEN[27722] = { title = "Warchief's Command: Deepholm!", description = "All able-bodied members of the Horde are hereby ordered to report to Farseer Krogar at the Western Earthshrine in Orgrimmar.\n\nThe Earthen Ring, lead by our former Warchief, Thrall, requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world!\n\nThe Western Earthshrine can be found just north of the Valley of Wisdom.\n\nOnward, brother! Destiny calls!", objectives = "Speak with Farseer Krogar at the Western Earthshrine in Orgrimmar.", completion = "Our world is in danger, <name>! We need the help of great heroes, like you, to save it!" }
WordHunterWoW_QuestEN[27723] = { title = "Kyle's Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[27724] = { title = "Hero's Call: Vashj'ir!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Recruiter Burns in Stormwind Harbor.\n\nRecent attacks by the Horde on our trade ships must be met with swift and just force!\n\nStormwind Harbor can be found in the northwest region of Stormwind City.\n\nFor the glory and honor of the Alliance! Fight on, brother!", objectives = "Speak with Recruiter Burns at Stormwind Harbor in Stormwind City.", completion = "All of our war ships are off fighting the Horde. You'll have to take the mercenary ship." }
WordHunterWoW_QuestEN[27725] = { title = "Quel'Danil Lodge", description = "I may appear far from home to you, {class}, but quite a few of my people were led here by Ambassador Rualeth. We have settled with the high elves of the Quel'Danil Lodge, to the northwest, to train in the ways of the Light and enjoy the peaceful beauty of this land.\n\nSuch peace may be short lived. We have seen the Horde moving further west from here. Could you travel to Quel'Danil and give warning to Anchorite Traska? Her cabin is just north of the main lodge.", objectives = "Speak with Anchorite Traska at the Quel'Danil Lodge.", completion = "Yoro sends warning of the Horde? The Highvale have been cautious of an attack for some time now. In fact, we have been--\n\n<Screams and the clash of metal break out to the south.>\n\nBy the light... they are here!" }
WordHunterWoW_QuestEN[27726] = { title = "Hero's Call: Mount Hyjal!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Emissary Windsong at Nighthaven in Moonglade.\n\nOur brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground!\n\nSpeak with Cenarion Emissary Jademoon in Stormwind Keep to gain entry into Moonglade.\n\nFor the glory and honor of the Alliance! Fight on, brother!", objectives = "Speak to Cenarion Emissary Jademoon to secure transportation to Moonglade.", progress = "Help us!", completion = "We knew the Alliance would send help and not a moment too soon!" }
WordHunterWoW_QuestEN[27727] = { title = "Hero's Call: Deepholm!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.\n\nThe Earthen Ring requires our aid! They report that the elemental plane of Deepholm threatens to overtake our world and destroy all life on Azeroth!\n\nThe Eastern Earthshrine can be found directly northwest of Stormwind Keep.\n\nFor the glory and honor of the Alliance! Fight on, brother!", objectives = "Speak with Naraat the Earthspeaker at the Eastern Earthshrine in Stormwind City.", completion = "Our world is in danger, <name>! We need the help of great heroes, like you, to save it!" }
WordHunterWoW_QuestEN[27729] = { title = "Once More, With Eeling", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", objectives = "Kill 8 of any Eel in the Kelp Forest." }
WordHunterWoW_QuestEN[27733] = { title = "The Good Ol' Switcheroo", description = "Look, I'd love to give the order and have my men blast these rebels to bits right now, but I can't because the entire Stockade is under Warden Thelwater's jurisdiction, and he only wants to contain them right now.\n\nRather than disobey orders, we're going to take care of this in a slightly different manner! We've managed to befriend Mortimer Moloch, who just so happens to be the ruthless rebel leader Randolph Moloch's twin. Kill Randolph, and we'll switch 'em so Mortimer can stop the rebellion peacefully!", objectives = "Kill Randolph Moloch.", progress = "We can't make the switch until Randolph is dead!", completion = "Yes, Mortimer just faked his own death. He'll probably take on his brother's name and continue on his 'epic schemes'. We'll just have to deal with that when the time comes." }
WordHunterWoW_QuestEN[27737] = { title = "By Fire Be Saved!", description = "I'm well-versed in first aid and other forms of healing, and with the help of my Lightwell I've been able to nurse many of our men back to full health. The problem we still have is that it's so cold and damp down here that I'm losing them anyways, despite healing their wounds!\n\nThe quakes angered the elements that reside in the prison...when they erupted out of the earth they slaughtered half of the prisoners. If you slay their leader, Lord Overheat, and bring me his core I can use it to warm our men!", objectives = "Obtain Lord Overheat's Fiery Core.", progress = "Do you have the core? Our men are dying in here!", completion = "Thank goodness! With this fire, our men will live through this ordeal!\n\nThank you so much, hero." }
WordHunterWoW_QuestEN[27738] = { title = "The Pit of Scales", description = "A spot on the southern end of the map was marked with hieroglyphs of crocodiles fighting each other.\n\nThat must be where Caimas took Tahet.\n\nGo to the Pit of Scales and find a way to rescue the Vizier's son.", objectives = "Rescue Tahet at the Pit of Scales in Uldum.", completion = "I thank you for what you've done, <name>.  You can count on my vote when High Council convenes." }
WordHunterWoW_QuestEN[27739] = { title = "The Gnoll King", description = "{name}, I'm afraid I must ask of you the impossible.\n\nI received my eyepatch because he willed it so. Countless thousands have perished to his wrath. It was only by sheer miracle that we were able to imprison him here.\n\nDoing so was a grave mistake. We held out as long as we could, but then they came. From the shadows and darkness, gnolls in service of Hogger ripped my best men to pieces.\n\nYou must defeat the Gnoll King, lest he mounts another attack and slaughters us all in cold, bloodthirsty rage.", objectives = "Defeat Hogger.", progress = "Have you defeated Hogger?", completion = "You have performed a deed this day unlike any I have seen in my long career. Hogger's death will plague the Riverpaw for years to come, and hopefully put an end to their attacks on our people.\n\nGreatest of heroes, please take this as a sign of my eternal gratitude." }
WordHunterWoW_QuestEN[27740] = { title = "Baba Bogbrew", description = "Hey, while you were out, the Baron stopped by! He kicked me until money came out!\n\nHe always does that though. But this time he asked me to tell you something! He wants you to go south and help out our herbalist, Baba Bogbrew.\n\nShe's all the way across the water! But just talk to my girl Daisy outside and she'll send you there the Crazy Larry way!", objectives = "Talk to Lil' Crazy Daisy to take a cannon ride to Baba Bogbrew.", completion = "Ah, it's so nice to have help dropped in.\n\nModern convenience... I can't get enough of it." }
WordHunterWoW_QuestEN[27741] = { title = "Show Me Your Papers", description = "After your work in dealing with the Twilight's Hammer cult, Captain Anton recommended you for a delicate assignment.\n\nMy men recently discovered a group of cultists attempting to sneak into the city. The flow of traffic into the Stormwind has come to a halt. The king has decreed that all visitors must be searched before they can enter the gates. Take this copy of his proclamation and read it to the people assembled at the front gates, then assist the guards there in searching those who wish to enter.", objectives = "Go to the front gates of Stormwind, read King Wrynn's Proclamation and search 5 Stormwind Citizens. Keep anything suspicious that you find.", completion = "So there were more cultists waiting to be admitted to the city? It's a good thing that you caught them, <name>. Reading over the note that you found, it seems they're planning something big." }
WordHunterWoW_QuestEN[27742] = { title = "A Little on the Side", description = "You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff!\n\nWhat a waste!\n\nSo, what do you say? 90/10 my way?", objectives = "Collect 6 Elementium Shards.", progress = "How much do you think you can carry?", completion = "<Goldmine slyly looks at the pile of Elementium shards.>\n\nHmm, I don't think that stuff's going to sell for much. I better give you your cut right now so you don't feel ripped off." }
WordHunterWoW_QuestEN[27743] = { title = "While We're Here", description = "You know, while we're here, we might as well take care of the Twilight's Hammer intruders. This place used to be ours, after all!\n\nI'd help, but with my totems and weapons broken, I'm pretty helpless.", objectives = "Slay 12 Twilight's Hammer cultists, either Depths Overseer or Twilight Miners, within the Elementium Depths.", completion = "They had it coming to them." }
WordHunterWoW_QuestEN[27744] = { title = "Rune Ruination", description = "Examining the Twilight Rune of Earth, you can almost feel its power extending further into the Elementium Depths.\n\nIt's probably connected to other runes. Initiate Goldmine thinks that you should destroy all of them.", objectives = "Destroy the Twilight Rune of Earth, Rune of Water, Rune of Air, and Rune of Fire.", progress = "We still have some runes to destroy, <name>.", completion = "That'll teach 'em to move in on our territory!\n\nWhat's that over across the way?" }
WordHunterWoW_QuestEN[27745] = { title = "A Fiery Reunion", description = "That's Magmatooth, my estranged fire elemental. {name}, you gotta kill him or he's gonna kill me!\n\nIt was all just a big misunderstanding. How was I to know he'd be mad about me \"borrowing\" his heart down in Deepholm? He can't die... not permanently anyway!\n\nHe's got the controller to the portal on him for sure. You gotta get the controller and then use it in the Fire portal to take us back to the entrance.", objectives = "Obtain the Fire Portal Controller and use it at the Fire Portal.", progress = "<name>!", completion = "We survived and all of the portals are now shutdown!\n\nYou don't think Magmatooth is going to hold a grudge, do you?" }
WordHunterWoW_QuestEN[27746] = { title = "Empire of Dirt", description = "This war has taken its toll on us as a people. We have lost much to secure our place as the rightful rulers of Lordaeron. And though the moment is won, the battle continues to rage in other parts of the Eastern Kingdoms.\n\nI must return to the Undercity to recuperate. I want you to go to Hillsbrad Foothills in my stead, {name}. As my most trusted soldier, you will lead our forces to absolute domination against our enemies in Hillsbrad.\n\nReport to High Executor Darthalia at Southpoint Blockade, to the east.", objectives = "Report to High Executor Darthalia at Southpoint Blockade in Hillsbrad Foothills.", completion = "News of your conquest in Silverpine emboldens us, <name>. We are prepared to fight at your command and beat back the last remaining vestiges of humanity in Hillsbrad." }
WordHunterWoW_QuestEN[27747] = { title = "Total War", description = "Many of the Wildhammer have already fled their homes. It is time to wipe them from the map.\n\nUp on the ridge to the north you will find abandoned houses in the Thundermar Ruins. Kegs of potent Thundermar ale have been left behind.\n\nThundermar ale is 220 proof; I don't know how that's possible.\n\nSmash open the kegs and set their content aflame. Burn them out! Leave the dwarves nothing to return to!", objectives = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, <name>." }
WordHunterWoW_QuestEN[27748] = { title = "Fortune and Glory", description = "We have to keep moving, {name}. It's just a matter of time before those troops get their act together.\n\nThe coffer should be just beyond these ruins.\n\nStay on your toes. Something tells me this isn't over yet...", objectives = "Kill the Obsidian Colossus.", completion = "Good to see you're still in one piece, <name>." }
WordHunterWoW_QuestEN[27749] = { title = "Arrest the Infiltrators", description = "You were right to bring this note to me, <name>. The king's proclamation came too late; they already have infiltrators at work in the city.\n\nThis note contains instructions and locations for cultists to meet, but it doesn't say what they're doing. Our enemies have grown smarter. It's going to be tough to track down all the infiltrators, but we have to get as many as we can. Use these cuffs to restrain any agents you find, bring them to the entrance of the Stockade, and report to me when you're finished.", objectives = "Use the Heavy Manacles to arrest 5 Cultist Infiltrators and bring them to Warden Thelwater at the Stockade. After you've returned with your prisoners, question one of the Detained Cultists in the Stockade.", completion = "Excellent work, <name>. The note you captured makes sense in light of this ritual the infiltrators mentioned. This city is infested with cultists and their sympathizers. We must act before their plans can come to fruition." }
WordHunterWoW_QuestEN[27750] = { title = "War Forage", description = "<Griff's stomach growls.>\n\nWhenever we Dragonmaw go on the warpath, everyone stops hunting.\n\nThe best tasting food is stolen from the mouths of the enemy. Up on the ridge north of the river there's a bunch of wrecked Wildhammer houses. I bet they're loaded with food.\n\nBring some to my mouth.", objectives = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Hungry.", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! Did you get any for yourself?" }
WordHunterWoW_QuestEN[27751] = { title = "Crushing the Wildhammer", description = "Since my people first claimed the Highlands, the Wildhammer dwarves have been our persistent foe. We fought them in Grim Batol, we fought them in the Wetlands, and even now open warfare rages to our north, across the river, amidst the Thundermar Ruins.\n\nProve your valor to me. Seek out and crush Wildhammer Warbrands. The best among them carry insignias - my warriors collect them by the dozen.\n\nCan you?", objectives = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "Show me the insignias you've collected, <class>.", completion = "<Narkrall clenches the insignias in his weathered hand.>\n\nSo, <class>. There's more to you than meets the eye.\n\nMaybe your Horde can stand with the best of my warriors. Let's try you out..." }
WordHunterWoW_QuestEN[27752] = { title = "Fight Like a Wildhammer", description = "S'not a boast to say that we Thundermars brew the finest ale in the Eastern Kingdoms. It's 220 proof. Yeah, you heard me!\n\nAs folks fled from the south to the town center, they were forced to leave behind their ale.\n\n<Blundy pauses, allowing the gravity of the situation to soak in.>\n\nGET IT BACK! That stuff'll turn even the stringiest of warriors into a whirlin' dervish of mouth-foaming destruction. Get them kegs! S'our only hope!", objectives = "Collect 10 Kegs of Thundermar Ale from the Thundermar Ruins. Careful - it's got some kick!", progress = "Get me that ale, <name>.\n\nHey, you haven't been skimmin' off the top, have you?", completion = "Oh aye ... we get a few of these kegs out to the boys on the front and we're gonna see some fireworks. Thank you, <name>!" }
WordHunterWoW_QuestEN[27753] = { title = "Never Leave a Dinner Behind", description = "Supplies are short, {name}. We've got refugees coming into Thundermar from up and down the ridge - that's a lot of mouths to feed.\n\nPlenty of food stores were left behind as people pulled their families to safety. We need that food!\n\nScour the Thundermar ruins south, east, and southwest of here for food stores.\n\nCareful, {class}! The fighting around the ruins is pretty intense.", objectives = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "Got some eats?", completion = "It's good - hardly a worm or weevil to be found!\n\nThis is a lifesaver to the folk who fled here for survival." }
WordHunterWoW_QuestEN[27754] = { title = "Dragonmaw Takedown", description = "The Dragonmaw!\n\n<Colin spits.>\n\nMonsters, all of them. We've fought them up and down these highlands since the last war. And now they're joining forces with the Horde?\n\nIf you're going to convince us Wildhammers to unite under the Alliance banner, you'd best prove yourself against the Dragonmaw. Wade into the battle that's raging in the Thundermar ruins to the south and southwest. Kill Dragonmaw marauders and collect the insignias that their greatest warriors wear. Then we'll talk. ", objectives = "Kill Dragonmaw Marauders and collect 8 Dragonmaw Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "How goes the fight, <class>?", completion = "Look at that! That's quite a collection of trophies you have there.\n\nI'll spread the word. If a single Alliance <class> can do this, imagine what the rest of your lot can accomplish!" }
WordHunterWoW_QuestEN[27755] = { title = "The Curse of the Tombs", description = "The Neferset are not the only threat to our sacred tombs.\n\nA gnomish expedition stumbled upon our lands a few weeks ago.\n\nThey did not heed our warnings and dug too deep within a cursed vault.\n\nTheir entire expedition is now afflicted by a terrible curse that has robbed them of their sanity and taken control of their minds.\n\nThey now seek access to the deepest vaults of Uldum and pose a great threat. \n\nGo to the Sunstone Terrace and put their wretched souls out of their misery.", objectives = "Slay 6 Crazed Diggers and Mekgineer Mixeltweed.", completion = "They couldn't be saved, <name>.  The ancient curse that fell upon them is irrevocable." }
WordHunterWoW_QuestEN[27756] = { title = "The Foreman", description = "If we're to find out what's going on down here it looks like we're going to have to fight our way through the entire Deadmines! Glubtok the Foreman will be the first major foe you encounter, a powerful ogre magi. Be careful, he possesses the brute strength of his race backed by his wicked spellcasting!\n\nTake this communicator so that I can keep in touch with you as we continue our investigation. Be careful down there.", objectives = "Kill Glubtok.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nNicely done! A clean kill. Now continue on and see what else you can find! We'll crack this case wide open with you on our side, I just know it." }
WordHunterWoW_QuestEN[27757] = { title = "The Darkest Depths", description = "I've been seeing sea creatures acting oddly through the whole swamp. The murlocs, yes, but before that the gilblins, and the makrura... I even saw some naga wander ashore the other day.\n\nSomething's calling them here, and working them into a frenzy to boot. Many of the creatures have been drawn to Stagalbog Cavern to the west. Something's down there, and if it gets any stronger we'll all start wandering in there too...\n\nYou should put a stop to whatever it is before that happens.", objectives = "Slay Hr'nglth the Lost.", completion = "Oh my. It sounds like you ran across quite a sinister being. I wonder what one of those was doing all the way out here..." }
WordHunterWoW_QuestEN[27758] = { title = "The Carpenter", description = "<Bzzzzzzzzzzzzt.>\n\nHello, can you hear me? Excellent!\n\nIt looks like Helix is in charge of building an enormous mast. You don't think they're trying to finish the Defias Juggernaut, do you?\n\nYou'd better go investigate {name}, and don't be afraid to get your hands dirty! You have clearance to use deadly force if necessary and, let's face it, it's probably going to be necessary.", objectives = "Defeat Helix Gearbreaker.", progress = "Yes?", completion = "<Bzzzzzzzzzzzzt.>\n\nHey, it's Horatio. That was intense! I'm watching your progress on the Stormwind Communicator's Spyatron X3 application.\n\nThey sure are using a lot of heavily fortified doors to hide their work. Keep pushing forward and see what you find next. I bet it'll be a huge clue!" }
WordHunterWoW_QuestEN[27760] = { title = "Artificial Intelligence", description = "<A feminine voice addresses you over the portable terminal.>\n\nEmergency code: 55-729.\n\nUpper cerebral cortex functions in expedition members have been compromised.\n\nPlease report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.", objectives = "Speak to the A.I.D.A. terminal at the Surveyor's Outpost  in Uldum.", progress = "<The terminal whirrs as its mechanisms become active.>", completion = "Scanning subject...\n\nCerebral cortex diagnostics indicate the absence of \"tomb curse\" phenomenon.\n\nDiagnostics did reveal frequent head trauma.  The user would do well to exercise more caution around blunt objects in the future." }
WordHunterWoW_QuestEN[27761] = { title = "A Disarming Distraction", description = "The curse has taken over the expedition members' higher brain functions, but my calculations reveal their suppressed adolescent subconscious can still be stimulated by realistic imagery.\n\nUtilize this holo-projector to distract them.\n\nThey are currently setting up explosives at the tomb to the east to attempt to gain access to secret passages in Uldum.\n\nThey seek dangerous re-origination technology beneath Uldum and must be stopped.", objectives = "Disarm the First, Second and Third Bomb Clusters and deactivate 4 Unstable Bomb Bots at the Tomb of the Sun King.", progress = "Greetings, user <name>.  I am happy to see you are still unaffected by the effects of the expedition curse.", completion = "Well done, <name>.  The expedition has already doomed itself.\n\nThere is no need for it to endanger the rest of the world as well." }
WordHunterWoW_QuestEN[27762] = { title = "Fuselight, Ho!", description = "Hey, {race}, listen up.  I got a job opportunity that you aren't gonna want to miss out on.\n\nWe been sent up here from Fuselight, a new goblin town way down in the Badlands.  Lots of money to be had down there, yes sir.  And not nearly so many zombies... or uptight Argent paladin-types.\n\nNope, it's an untamed wilderness down there, and we're looking for someone like you to help us tame it.  Whenever you're ready... we'll be waiting.", objectives = "Ride The Uncrashable to the Badlands, then report to Eddie Flofizzle.", completion = "Nice landing!" }
WordHunterWoW_QuestEN[27763] = { title = "To Fuselight Proper", description = "This, {race}, is paradise.  I've always wanted to live in a nice quiet town by the sea so I can focus on my explosions without any distractions.\n\nQuiet's not for everybody, though... 'specially the adventuring hero-type, like yourself.\n\nWe've installed a teleporter in the backside of town that'll take you up to the top of the cliffs.  From there, you can take the quick ride west into Fuselight proper, within the Badlands.\n\nThere should be more for you to do up there.  Tell 'em that Flo sent you.", objectives = "Use the Teleporter in the back of Fuselight-by-the-Sea to port up the mountain, then report to Dolph Blastus at Fuselight in the Badlands.", completion = "Welcome to Fuselight!" }
WordHunterWoW_QuestEN[27764] = { title = "A Strange Request", description = "On to other matters.  I have a package that I need delivered.\n\nA young lady came by our town not long ago, looking for compressed blasting powder, a tempered mithril bomb casing, and some safety goggles.  Naturally, we had plenty of blasting powder and bomb casings to sell her, but the safety goggles were a little harder to find.\n\nLong story short, I've got the goggles, but she's already returned to her studies down in Lethlor Ravine.  Will you bring these down to her?", objectives = "Bring Dolph's Package to Rhea at Lethlor Ravine in the Badlands.", progress = "Ahh... you've found me.  Good.", completion = "Thank you, <race>.  You may keep the goggles, as they have already served their purpose: they brought you to me." }
WordHunterWoW_QuestEN[27765] = { title = "First Sample: Wild Eggs", description = "I am experimenting with black dragons.  Specifically, I am interested in how they procreate.\n\nMy current experiments require plenty of black dragon eggs, which is why I am here in Lethlor Ravine.  I'd gather the eggs myself, but I think you'll benefit from helping me out.\n\nYou will find them along the edges of the ravine.  Beware the guardians that circle above - they do not appreciate stolen eggs.", objectives = "Obtain 6 Wild Black Dragon Eggs.", progress = "Have you brought the eggs?", completion = "Thank you for gathering these so quickly, <name>." }
WordHunterWoW_QuestEN[27766] = { title = "Second Sample: Whelps", description = "I need another favor from you.  I need you to obtain the bodies of the black dragon whelplings that fly nearby.  Slay them, and bring the corpses to me.", objectives = "Obtain 10 Scalding Whelp Corpses.", progress = "Have you done as I asked?", completion = "This grisly task was necessary, <name>.\n\nAll will be revealed to you soon.  For now, know this:\n\nI am no ordinary goblin.\n\nI serve a mistress of unimaginable power, and her motives here are not as dark as they might seem." }
WordHunterWoW_QuestEN[27767] = { title = "Back Under Cover", description = "The cultists seem assured of their victory, even as we detain more and more of them. We must find out more about the ritual mentioned by the cultist you questioned.\n\nThese rituals seem to be the core of the cult's plan to attack Stormwind. I'm going to give you one of the robes taken from the arrested cultists. Put it on and go back to the cultist outpost at Mirror Lake Orchard in Elwynn Forest and see if you can get the cultists there to let you in on the plan.", objectives = "Put on your Recruit's Robe, go to Mirror Lake Orchard and get the Book of Incantations from Overseer Sylandra. Read from the Book of Incantations near the Cultist Altar to practice the ritual.", progress = "It's good to see you again, <name>. We were worried that the tyrant Wrynn's guards had thrown you into the Stockade.", completion = "You need to familiarize yourself with the portal ritual quickly. We need to send as many teams into Stormwind as we can. They're discovering and arresting more of our brothers each day." }
WordHunterWoW_QuestEN[27768] = { title = "Step Two: The Bloodletter", description = "The trolls here perpetuate the fall of my brethren to the nightmare. They infect and corrupt green dragons with the blood of their foul god, and then harvest the evil that has grown within them. They are being farmed like livestock...\n\nThis disgusting savagery cannot continue. Return to where you left the Hall of Masks and take the other corridor toward the Butchery. Gomora the Bloodletter harvests corpses for these foul and evil rituals there. Take his undeserved life from him!", objectives = "Slay Gomora the Bloodletter in the Butchery." }
WordHunterWoW_QuestEN[27769] = { title = "Rhea Revealed", description = "As I hinted earlier, I am no ordinary goblin.  You may have already guessed my true identity.\n\nAllow me to show you my true form.  As you have proven yourself trustworthy, I will also share with you the details of my plan.", objectives = "Learn Rhea's true identity.", progress = "You are certainly impatient, <name>.", completion = "My true name is Rheastrasza, and I am an envoy of Alexstrasza herself, the Aspect of the red dragonflight.\n\nWith Deathwing currently occupied with other matters, we are going to find a way to redeem the black dragonflight.\n\nAnd you are going to help us." }
WordHunterWoW_QuestEN[27770] = { title = "Lifting the Veil", description = "The black dragonflight was once noble.  They were the earth warders, protecting the very land itself.  How ironic that they would become the worst menace the land has known.\n\nI believe that there remains a sliver of hope, however, and so does my mistress.  The black dragonflight will live beyond Deathwing's treachery, and will soar as the noble earth warders once again.\n\nI wish to show you something.  Close your eyes, and I will reveal to you the final part of my studies.", objectives = "Witness the final piece of Rhea's studies.", progress = "You are certainly impatient, <name>.", completion = "We will find a shred of good within these dragons, <name>.  Whether it is in the wild eggs you found, the bodies of the whelplings you slew, or the eggs that we have encouraged Nyxondra to lay... we will find an untainted black dragon." }
WordHunterWoW_QuestEN[27771] = { title = "Third Sample: Implanted Eggs", description = "Nyxondra is being held against her will.  She is hidden from her brood, right in the middle of their breeding grounds.  She lays eggs, but they will be taken away before she can see them hatch.\n\nCruel?  Perhaps... but not nearly as cruel as the treatment that their dragonflight showed my mistress.\n\nShow me that I can trust you, {name}.  Take Nyxondra's eggs, and bring them here.  You will need to beat Nyxondra into submission before you can take them.", objectives = "Obtain 3 of Nyxondra's Eggs.", progress = "Remember, <name>... this is for the good of the black dragonflight.  We are here to redeem them, not to hurt them.  This is but a step in their recovery.", completion = "You have done everything that I have asked you, without question.  Our job here in Lethlor Ravine is done.\n\nIt is now time that I revealed everything to you." }
WordHunterWoW_QuestEN[27772] = { title = "The Venerable Doctor Blam", description = "I made a calculated decision in revealing my identity to you, {name}.  I needed you to trust me, but I can no longer stay here in Lethlor Ravine, as my cover has quite clearly been blown.\n\nYou may be able to slip away unnoticed, however.  Here, take the results of our research, and bring them west.  At Agmond's End, you will find a gnome who knows what to do with these samples.\n\nHurry, {name}!  You mustn't loiter here any longer than necessary!", objectives = "Bring the Black Dragon Samples to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Dr. H. Blam, at your service.  How can I be of assistance to you today?", completion = "Ooh!  Science stuff!  Let's see what you've got here...\n\nWild eggs?  Blech.  Useless.  These are never any good.\n\nOoooh, what's this?  Some sort of... pre-engineered egg?  This looks promising, but I don't want to know what Rhea had to do to get it.\n\nHmm... yes, some very nice corpses.  Very nice indeed.\n\nAlright, I'll see what I can do." }
WordHunterWoW_QuestEN[27773] = { title = "Step Three: Prophet", description = "All that yet stands between me and the temple is Prophet Jammal'an himself. He is the leader of the Atal'ai trolls here, a foul manipulator.\n\nKnow that you do not face a mere crazed troll, {name}, but an instrument of forces beyond your darkest comprehension. Yet you do not fight alone--my strength and the will of the Green Dragonflight go with you.\n\nProceed to the Den of the Caller, left through the Hall of Ritual, and then down into the Hall of Bones. At the bottom, you will find Jammal'an.", objectives = "Defeat Jammal'an the Prophet.", completion = "He has escaped! I should have known it would not be so easy.\n\nThe path is clear, <name>. It is time to return." }
WordHunterWoW_QuestEN[27774] = { title = "Easily Swayed", description = "The most immediate threat to Fuselight is, without argument, the colony of ogres to the northwest.\n\nMost of our ogre neighbors used to be warrior-types, but it seems that more and more of them are practicing magic.  I won't have an army of ogre-magi at my doorstep.\n\nGo take out some of those Dustbelcher ogres.  Hopefully they'll get the picture and avoid messing with the might of Fuselight.", objectives = "Slay 9 Dustbelcher ogres at Camp Kosh.", progress = "I'll feel much better when those ogres are gone.", completion = "I wonder where all of these ogre-magi are coming from?  Curious times, indeed." }
WordHunterWoW_QuestEN[27775] = { title = "When the Going Gets Tough, Cheat", description = "I just can't get my invention to work!  Gah!\n\nThat's it, I've decided.  I'm going to cheat and use magic.\n\nWhat my invention really needs is a solid piston that's thin enough to fit through a narrow copper tube, but strong enough to withstand repeated impact without breaking.  The magical rods carried by those ogre magi to the north should work perfectly.\n\nFrom what I can tell, only the instructors carry the strong staves.", objectives = "Obtain an Instructor's Rod from an Ogre-Mage Instructor at Camp Kosh.", progress = "I don't like to stoop to using magic on my inventions, but this is somewhat of an emergency.", completion = "A perfect fit!  My goat puncher is finally finished!" }
WordHunterWoW_QuestEN[27776] = { title = "It's Goat Time, Baby", description = "We have a little bit of a goat problem here in Fuselight, in case you haven't noticed.  They'll eat anything, and they seem to have taken a liking to the piles of cogs and gears that we tend to leave sitting around.\n\nIt's getting really annoying!\n\nYou'll find most of the billy goats wandering around the edge of town, near the cliff's edge.  Use this device on them to give 'em a little \"nudge\".", objectives = "Use Garyanne's Goat Puncher on 12 Billy Goats in Fuselight.", completion = "Well done!  I have no doubt that those goats will be back, but they'll think twice before they nibble my cogs again!" }
WordHunterWoW_QuestEN[27777] = { title = "Core Access Codes", description = "The expedition's numbers are extremely large, user {name}.\n\nDealing with them by conventional means would take you an estimated 2,700,136.5 hours.\n\nWe can make use of a powerful source of energy held within expedition's crawler vehicle.\n\nWe will need the fusion core's access codes to accomplish this.\n\nMekgineer Twizzleflux has these codes and can be found at the Starwatch Tower to the southeast.\n\nI've uploaded jamming frequencies to a scrambler.  Use it to temporarily disable Twizzleflux's defenses.", objectives = "Obtain the Core Access Codes from Twizzleflux the Insane.", progress = "Did you succeed, <name>?  I estimated your chances of survival at 68.5%.", completion = "Excellent job, user <name>.  We must obtain access to the fusion core now." }
WordHunterWoW_QuestEN[27778] = { title = "Hacking the Wibson", description = "It is true.  New expedition crews have arrived by sea.\n\nMy scanners detect that they already have been afflicted by the curse phenomenon.\n\nYou must hurry and go aboard the M.A.C. Diver.  The access codes will give us control over the fusion core's functions, but there is still a layer of security we must bypass.\n\nUser {name}, I must ask you to hack a very sophisticated mainframe known as the \"Wibson.\"\n\nDo not worry I will provide you with further instructions.", objectives = "Hack the Wibson Mainframe on top of the M.A.C. Diver.", progress = "Greetings, user <name>.", completion = "I am in control, user <name>.  But I cannot keep the core temperature stable indefinitely." }
WordHunterWoW_QuestEN[27779] = { title = "Gnomebliteration", description = "I have downloaded my program to the fusion core and have complete control over it.\n\nI've created a small pocket of air inside to avoid vaporizing user {name}.\n\nI will yield control of all movement functions so I can dedicate my cycles to keeping the core stable.\n\nGo down the hill and neutralize as many of the expedition members as possible.\n\nMy analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers.\n\nUser {name}, you must be assured that expedition members are without hope.", objectives = "Obliterate 512 Crazed Gnomes.", completion = "It is done, user <name>.  I thank you for your assistance with this unfortunate task." }
WordHunterWoW_QuestEN[27780] = { title = "I Said the Words...", description = "Now that you're familiar with the ritual, it's time for you to perform it in the city. Dozens of our brethren have already infiltrated the city and made their way to the ritual sites.\n\nI want you to visit the portal ritual sites in Stormwind's Dwarven District, Park district, and Cathedral Square. The teams there will have made most of the preparations and all you need to is read the last part of the incantation from the book.\n\nVery soon, <name>, Stormwind will find itself awash in wind and water.", objectives = "Disrupt the cultist rituals in the Dwarven District, the Park, and the Cathedral District by reading the incorrect words from the Book of Incantations.", completion = "You've done an excellent job tracking down and combating the cultists, but I fear they are right about one thing. We will never know if we've gotten them all." }
WordHunterWoW_QuestEN[27781] = { title = "The Machination", description = "<Bzzzzzzzzzzzzt.>\n\n<Bzzzzzzzzzzzzt.>\n\nHe-hello? {name}, are you there? Are you still alive? Hello?\n\nOh good, you're still there! What in the name of Lordareon are they building? It's some sort of mechanized monstrosity! You have to stop them from completing that...that...thing! \n\nThrow out the rules, do whatever you have to do to thwart them!", objectives = "Destroy the Foe Reaper 5000.", completion = "<Bzzzzzzzzzzzzt.>\n\nYou're nearing the heart of their domain. There will likely be an extremely fortified door protecting the inner sanctum of the entire Defias operation. See if you can find anything that might pry it open!\n\nI suggest a stealthy method!" }
WordHunterWoW_QuestEN[27782] = { title = "Mathias Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Mathias says he needs you.\n\nHe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, buddy?", objectives = "Speak with Master Mathias Shaw at the Twilight Citadel in the Twilight Highlands.", completion = "Good, you're back. We know where Cho'gall's ultimate weapon is located!" }
WordHunterWoW_QuestEN[27783] = { title = "Garona Needs You", description = "We've had some good times. I'm really sorry to see you go. But, Garona says she needs you.\n\nShe said it's urgent!\n\nSo, you want to grab a drink or something after whatever, buddy?", objectives = "Speak with Garona Halforcen at the Twilight Citadel in the Twilight Highlands.", completion = "Good, you're back. It's about time. We know where Cho'gall's ultimate weapon is located!" }
WordHunterWoW_QuestEN[27784] = { title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\nMany SI:7 died to bring us this information.", objectives = "Get to the Hammer of Twilight.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected...." }
WordHunterWoW_QuestEN[27785] = { title = "The Admiral", description = "<Bzzzzzzzzzzzzt.>\n\nI can't believe it...they're almost done rebuilding it! We don't have much time, {name}.\n\nAdmiral Ripsnarl, Vanessa's right hand man, is bound to be on board. We'll never get to her if he's still alive to do anything about it. You're going to need to scale the unfinished Juggernaut, find Ripsnarl, and kill him so we can get to Vanessa's private quarters on the top deck.\n\nBe careful, the Admiral bears the worgen curse and would take much pleasure in digging his claws into you!", objectives = "Kill Admiral Ripsnarl.", completion = "<Bzzzzzzzzzzzzt.>\n\nYour exploits have gained quite the following in the intelligence community, <name>. Many top members of SI:7 have been earnestly watching you infiltrate the Deadmines through their own Stormwind Communicators.\n\nMathias Shaw himself wants to speak with you! I'll transfer you over momentarily." }
WordHunterWoW_QuestEN[27786] = { title = "The Hammer of Twilight", description = "While you were in the mine, I was able to figure out where the Hammer of Twilight is being kept. They created it at the Altar of Twilight to the south.\n\nMore important than that, the cultists have made a critical error: Cho'gall is personally overseeing its final construction.\n\n<Garona begins sharpening her blades.>\n\nMany Kor'kron died to bring us this information.", objectives = "Get to the Hammer of Twilight.", completion = "The Hammer of Twilight floats in the middle of the altar, unprotected...." }
WordHunterWoW_QuestEN[27787] = { title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", objectives = "Survive and then slay Skullcrusher the Mountain.", completion = "You did it, lad! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!" }
WordHunterWoW_QuestEN[27788] = { title = "Skullcrusher the Mountain", description = "It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off.\n\nSurvive and slay Skullcrusher the Mountain!", objectives = "Survive and then slay Skullcrusher the Mountain.", completion = "You did it, <name>! You beat that damned gronn and sent Cho'gall packing into the Twilight Bastion.\n\nDon't you worry. With your help and that of your friends, we'll get in there and we'll kill Cho'gall once and for all!" }
WordHunterWoW_QuestEN[27789] = { title = "Troggish Troubles", description = "I'll need some time to analyze these samples, as well as a break from this trogg-shooting duty.  Go man one of my turrets and take out as many troggs as you can.  I'll be here studying.\n\nThe turrets have two abilities: a regular shot, as well as an electrical overload, for when too many enemies get close!  Heh, heh.  Good luck.\n\nOh, and look out for the big, slow troggs.  You probably don't want to let them anywhere near you.", objectives = "Enter a Blam Turret, then survive four waves of trogg attacks.", progress = "Not quite done yet.  Need some more time.", completion = "The results are in.  I've identified traces of corruption in all three samples you brought me.  Rhea will be quite disappointed." }
WordHunterWoW_QuestEN[27790] = { title = "The Defias Kingpin", description = "Hello there, {name}. I've heard a great deal about you. Listen closely, you're only going to have one solid shot at this.\n\nThe new Defias Kingpin must be inside the hut orchestrating this entire operation. I want you to go inside and take her down, for the sake of the hundreds of innocent people the organization her father started has killed and terrorized.\n\nI'm shocked that she would let you get so close to her domain without fleeing and waiting until more favorable conditions, but it seems we're in luck.", objectives = "Kill the Defias Kingpin.", completion = "You very well may have saved all of Stormwind with your efforts here today, <name>. Vanessa may still be out there, but she is an insignificant threat now that the Juggernaut will be placed under our careful watch. Thank you." }
WordHunterWoW_QuestEN[27791] = { title = "Dustwind Dig", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Explorers' League has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to Lead Prospector Durdin at the camp to the north.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", objectives = "Speak with Lead Prospector Durdin at Dustwind Dig in the Badlands.", completion = "Titans?  You wanna know about titans?\n\nYou came to the right place, lad.  We're on the brink of somethin' big." }
WordHunterWoW_QuestEN[27792] = { title = "All's Fair in Love, War, and Archaeology", description = "First things first, though.  I'm not just going to sit here and tell you everything we've discovered down in those ruins.  We've got problems to take care of!\n\nMost pressing is those upstart Reliquary hooligans, just on the other side of the tomb.  They're makin' off with all of our loot!  Don't they know that diggin's dwarf work?\n\nHunt down a few of their \"excavators\" - more like bandits, if you ask me - and bring some of these precious artifacts back to me.\n\nTHEN we'll talk titans.", objectives = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", progress = "Your bags look heavy.  Heavy with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, <name>.\n\nAlright, fine.  Let's talk titans, shall we?" }
WordHunterWoW_QuestEN[27793] = { title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", objectives = "Investigate The Warden and The Sentinel." }
WordHunterWoW_QuestEN[27794] = { title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", objectives = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do." }
WordHunterWoW_QuestEN[27795] = { title = "Tides of Darkness", description = "The battle's proceeding just the way I wanted it. With their warriors nearly exhausted, I've sent in our cavalry.\n\nWhat I wasn't expecting was ogres. Our knights are well matched against the brutes, but they're going to need help.\n\nI need you back on the field right away, {name}. Few can bring down an ogre on foot, but I think I can count on you. Don't disappoint me.", objectives = "Slay 6 Stonard Ogres.", completion = "Going toe to toe with ogres is impressive, <name>. I'm glad I've got soldiers like you out here." }
WordHunterWoW_QuestEN[27796] = { title = "The Warden's Pawn", description = "Once those Reliquary honks got here, we panicked, and we all just started looting indiscriminately.\n\nA lot of bad archaeology happened that day.\n\nLuckily, Olga happened upon this small jade statue.  We thought it to be a key of some sort, but can't figure out what it opens.  Maybe you'll have some better luck with it.", objectives = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue clicks into place on the large stone slab.>" }
WordHunterWoW_QuestEN[27797] = { title = "The Sentinel's Pawn", description = "We very nearly had this statue stolen from us by one of Bloodwatcher's Reliquary stooges.  We managed to catch him in the act, and we've retrieved the statue, but it hasn't really paid off.\n\nIt appears to be a key of some sort, but I can't find the lock anywhere inside those ruins.  You feel like giving it a try?", objectives = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue slides into place on the cold marble slab.>" }
WordHunterWoW_QuestEN[27798] = { title = "Water of Life", description = "Take my Water of Life and pass it into the corpse of the drowned dwarf.\n\nHe was a worker of metals in life, and though his body now feeds my loch, the Water will allow him to tell you what you want to know.\n\nThen take your information and be gone from my demesne.", objectives = "Use the Water of Life to extract information from the Corpse of Forgemaster Finlay.", completion = "The Hammer of Twilight? And you say you got this information out of a drowned Wildhammer dwarf?\n\nYou're kidding, right?" }
WordHunterWoW_QuestEN[27799] = { title = "I Said the Words...", description = "Now that you're familiar with the ritual, it's time for you to perform it in the city. Dozens of our brethren have already made their way to the ritual sites.\n\nI want you to visit the portal ritual sites on the second level of the Drag, in the Valley of Honor near the Hall of the Brave, and near Orgrimmar's west gate. The teams there will have made most of the preparations and all you need to do is read the last part of the incantation from the book.\n\nVery soon the city will be consumed in flame.", objectives = "Disrupt the cultist rituals in the Drag, the Valley of Honor, and near the city's West Gate by reading the incorrect words from the Book of Incantations.", completion = "You've brought many of these traitors to justice, <name>, and yet their numbers keep growing. I fear we won't be able to stomp out all these rituals in time..." }
WordHunterWoW_QuestEN[27800] = { title = "Back Under Cover", description = "The cultists seem assured of their victory, although we have captured many of them. We must find out more about the ritual mentioned by the cultist you questioned.\n\nThese rituals must be the core of their plans to attack Orgrimmar.\n\nTake one of the robes from the arrested cultists; it's not like they're going to need them anymore. Put it on and go back to the cultist outpost at the Jaggedswine Farm in Durotar and see what you can learn about these rituals and their place in the cult's plans.", objectives = "Put on your Recruit's Robe, go to the Jaggedswine Farm and get the Book of Incantations from Overseer Jintak. Read from the Book of Incantations near the Cultist Altar to practice the ritual.", progress = "It's good to see you again, <name>. We thought the Warchief might have gotten his hands on you.", completion = "You need to familiarize yourself with the portal ritual quickly. We've sent dozens of brothers into the city, but only so many can evade capture. We're relying on you, <name>." }
WordHunterWoW_QuestEN[27801] = { title = "Show Me Your Papers", description = "My men recently discovered a group of cultists attempting to sneak into the city. The flow of traffic into Orgrimmar has come to a halt. The Warchief has decreed that all visitors must be searched before they can enter the gates. Take this copy of his proclamation and read it to the people assembled at the front gates, then assist the guards there in searching those who wish to enter.", objectives = "Go to the front gates of Orgrimmar, read the Warchief's Proclamation and search 5 Orgrimmar Citizens. Keep anything suspicious that you find.", completion = "So there were more cultists waiting to be admitted to the city? It's a good thing that you caught them, <name>. Reading over the note that you found, it seems they're planning something big." }
WordHunterWoW_QuestEN[27802] = { title = "Arrest the Infiltrators", description = "The note you found can only mean one thing. The warchief's proclamation was too late; they already have infiltrators at work in the city.\n\nThis note contains instructions and locations for cultists to meet, but it doesn't say what they're doing. Our enemies have grown smarter. It's going to be tough to track down all of them, but we have to get as many as we can. Use these cuffs to arrest the infiltrators and then deliver them to Warden Gartok Ragefist at the Ring of Valor in the Valley of Honor.", objectives = "Use the Heavy Manacles to arrest 5 Cultist Infiltrators and bring them to Warden Gartok Ragefist at the Ring of Valor in Orgrimmar's Valley of Honor. After you've returned with your prisoners, question the Detained Cultist.", completion = "So they're preparing some kind of ritual all over the city? Orgrimmar city is infested with cultists and their sympathizers and the warchief is at wit's end. We must do something!" }
WordHunterWoW_QuestEN[27803] = { title = "Welcome Relief", description = "I've got boys formin' defensive lines on all sides of the town, keepin' back the elementals streaming from the torn ground. They're good lads and they've been holdin' firm, but even the sturdiest dwarf tires eventually.\n\nThey're split into shifts: one hour of rest for every hour on the line. Best I can get'm with the men we have.\n\nIf you want to be helpin', pick a line and take up a shift. Give some of my boys a welcome breather. Report back in once you've killed several of the elementals.", objectives = "Kill 8 Subjugated Firestarters.", progress = "Don't be dallyin'. These men are pourin' every fiber of their bein' into holding this town, and I'll not see them insulted by the presence of anyone that won't hold their weight.", completion = "Good work, boy. Good to have another capable set of hands about." }
WordHunterWoW_QuestEN[27804] = { title = "The Only Homes We Have", description = "We've already been pushed back farther than I'd hoped, but I'm not about to give up our homes to these mongrels. They may burn them, pillage them, and spit on the rubbled remains, but we'll still fight to take them back.\n\nThat being said, I rather like them not burnt. I have the boys running buckets from the well to try to keep the fire down. If you'd join them, they can help out by tossing you buckets so you don't have to make the runs.", objectives = "Extinguish 50 fires at Firebeard's Patrol.", progress = "As long as we work together, we can overcome anything the Twilight's Hammer might throw at us.", completion = "Thanks for your help. Every little bit makes a difference.\n\nWe'll keep the water going until we can push the Twilight back." }
WordHunterWoW_QuestEN[27805] = { title = "Small Comforts", description = "You're the new face that's meant to be helping Keegan out I take it? Pleasure to meet you. Maybe you can lend a favor or two more to the troubled Wildhammer that have made refuge here.\n\nWe were all forced to retreat to this building quickly, and some of us left behind things of great value in our destroyed homes nearby. Would you mind bringing them back after you go out there? You would bring happiness to some very troubled souls.", objectives = "Find and return Meara's Dried Roses, Parlan's Ivory Hammer, and Aprika's Doll.", progress = "Were you able to find their valuables. I know it seems so minor, but little things make a big difference to some people in times like these.", completion = "You are very generous. Thank you.\n\nThere's a lot of darkness in our world these days. We appreciate the light that you've brought here." }
WordHunterWoW_QuestEN[27806] = { title = "Honorable Bearing", description = "Iain, my second in command, bore the body of one of our fallen heroes to the cathedral to the west. He's the man I've put in charge of reforming a wing of gryphon riders from whatever scattered forces he can find. I would like you to help him.\n\nI should impress upon you the urgency of this task. We will not be able to hold here forever; the Twilight's Hammer or the Dragonmaw orcs will eventually overwhelm us. Putting together an active gryphon wing may be our only hope for surviving these conflicts.", objectives = "Speak to Iain Firebeard at the Firebeard Cemetery.", completion = "Greetings, <race>. Sent by Keegan?" }
WordHunterWoW_QuestEN[27807] = { title = "Clan Mullan", description = "If we're going to pull a full gryphon wing back together, we're going to need to move fast to gather the survivors before they leave or get picked off. I've got a bead on a few groups of riders that stuck together. I'm leavin' to find the Thundermar riders and the Moore riders shortly.\n\nThe Mullans were heading up west to the Crucible of Carnage last I saw. Go see if you can convince Duglas Mullan to join up with Keegan - he should owe him a favor or three.", objectives = "Speak to Duglas Mullan at the Crucible of Carnage.", completion = "Iain sent ya?\n\nYou don't look like a Firebeard to me. Why exactly should I be listenin' to anything you say?" }
WordHunterWoW_QuestEN[27808] = { title = "Stubborn as a Doyle", description = "The Doyle riders were last spotted convergin' in the trees to the south, on the border of the Obsidian Forest. They're a stubborn bunch and are likely to take some convincin' if they're going to join up with us.\n\nYour best bet with Keeland Doyle is to tell'm Cailin Longfellow's taken up shelter with us back at the town. Keeland's got a good soft spot for her and she just might be enough to convince him to drag all his boys along.", objectives = "Speak to Keeland Doyle in the Highland Forest.", completion = "It seems the Doyles suffered the worst of the attacking Twilight drakes.\n\nIt's clear that they fought to the end: not a single rider's footprint more than a few yards from his gryphon. It's doubtful there were any survivors." }
WordHunterWoW_QuestEN[27809] = { title = "Firebeard Bellows", description = "I also need ya to seek out Mackay and his men on the other side of the Devouring Breach, at the Gorshak War Camp.\n\nThe Dragonmaw didn't survive the initial onslaught, and Mackay's lookin' to ransack what he can of their camp to supply our fight. There shouldn't be much convincin' necessary, but they'll likely want a hand wrappin' things up there before they make their way back to Keegan.\n\nGive'm a boot in the arse from ol' Iain if ya have to.", objectives = "Speak to Mackay Firebeard at the Gorshak War Camp.", completion = "Bout that time, eh? Help us wrap things up then." }
WordHunterWoW_QuestEN[27810] = { title = "The Fighting Spirit", description = "Keegan wants the Mullans to take wing with'm eh? If there's a dwarf I'd fly for, he'd be it. Still, I don't get why he'd be sendin' an outsider to be recruitin' me - not right polite by my standards.\n\nI'm guessin' ya don't last 20 seconds with any of my boys, at the bar or in the battlefield. Prove me wrong. Take one of'm down in a fight and then I'll think about flyin' with ol' Keegan.", objectives = "Challenge and defeat one of the Mullan Gryphon Riders.", progress = "Naw, I'll not be fightin' ya. Get in there and challenge one of my boys if you've got a gut on ya at all.", completion = "That's the stuff! Not half bad. You've got a bit of fight in ya after all." }
WordHunterWoW_QuestEN[27811] = { title = "The Scent of Battle", description = "Don't let Duglas fool you, the Mullans have been itchin' to take wing again, and if there's anyone we'd do it for, it's Firebeard.\n\nWe left our gryphons in the Highland Forest to the south to hunt and to get away from the sounds of battle for a bit. They deserved a rest.\n\nIf you want us back in the air soon, you'd do well to help us bring our gryphons back in.\n\nTake this piece of charred highland birch. We use it during training - as soon as they smell it, they'll come straight back to us.", objectives = "Find 8 Mullan Gryphons and dispatch them back to their gryphon riders.", progress = "We're not going to be much use to you without our birds.", completion = "Good on you. I always feel like a part of me is missing when my gryphon isn't nearby. I can't speak for Duglas or the rest of the clan, but I'll be ready to ride at Firebeard's call." }
WordHunterWoW_QuestEN[27812] = { title = "The Loyalty of Clan Mullan", description = "Your point's made. Keegan can count on us. We'll meet'm back at town as soon as all the boys are rallied up.\n\nYou're tough for not bein' a Wildhammer. Guess they breed'm good where you come from too.\n\nStill, haven't seen ya drink yet. That'll be the real test.", objectives = "Return the news on Clan Mullan to Iain Firebeard at the Firebeard Cemetery.", completion = "Ya got the Mullans. Good news! They're worth more than their weight in a fight, and they ain't exactly skinny." }
WordHunterWoW_QuestEN[27813] = { title = "Death Worthy of a Dragonmaw", description = "The Twilight sacked this town, killin' most of the Dragonmaw that lived in it. A few survived though, and they're not right keen on us takin' liberties with their supplies.\n\nNot that that matters much.\n\nWell, I'm not right keen on them attackin' my boys. Kill'm off, chase'm out - I don't care, just get'm gone.", objectives = "Defeat 6 Dragonmaw Stragglers.", completion = "That's more like it. Let's finish gatherin' up supplies and get back to Keegan." }
WordHunterWoW_QuestEN[27814] = { title = "Anything We Can Get", description = "Stay back and forge more weapons?  Pah!  A Forgehammer has ne'er been afraid of battle!  Who needs the safety of home to make weapons?  Besides - there is oodles of raw material out here.  Those Dragonmaw weapons are worthless, but they can be smelted down to make actual weapons.  Bring me 8 Dragonmaw weapons so me daughter and I can forge real weapons out of them.", objectives = "Bring 8 Dragonmaw weapons to Brom Forgehammer at Gorshak War Camp.", progress = "How many have you got so far?", completion = "Yer a good lad.  Have me thanks and a little gold for yer troubles." }
WordHunterWoW_QuestEN[27815] = { title = "Somethin' for the Boys", description = "Cleaned up the camp and ran errands for Forgehammer?  Not bad for a wee {class}.  Take these to Iain at Firebeard Cemetery, and he should reward you for a job well done.", objectives = "Bring Forgehammer's weapons to Iain Firebeard at the Firebeard Cemetery.", progress = "What have we here?", completion = "Hah! Looks like their raid went mighty well then. I'll have to buy ol' Forgehammer a round once we finish with this mess." }
WordHunterWoW_QuestEN[27816] = { title = "Personal Request", description = "Shame about the Doyles. It's a fair miracle that as many of us made it out as is though, so can't count it as much of a surprise.\n\nThose louts at Thundermar are cowards. Even after tellin' them it was Keegan askin', they won't set foot outside of their town. I did rope in the Moores though, so that's at least three clans' worth.\n\nKeegan wanted to hear from ya personally when you returned. Go find'm in town.", objectives = "Speak to Keegan Firebeard at Firebeard's Patrol.", completion = "It seems you had some luck bringin' riders back. Well timed too - we just pushed the elementals back, so we should have the arm room to lead an attack right away.\n\nThank you, <name>. You're a good <race>." }
WordHunterWoW_QuestEN[27817] = { title = "Dropping the Hammer", description = "Thanks to you and Iain, we've got enough riders together that we can take the fight back to the Twilight.\n\nWe're trained to fight while ridin', but a second rider to handle the Stormhammer tends to be more efficient. I thought you might enjoy the honor.\n\nPick your gryphon and join the fight. Best be quick about it though - we're aimin' to clear every last one of those Twilight off of those floatin' rocks before the hour's out.", objectives = "Kill 12 Twilight Stormbenders and Servias Windterror using one of the gryphons at Firebeard's Patrol.", progress = "Today is the day that the tables turn.", completion = "Now that's how it's done, lad!\n\nWith a real gryphon wing back together, we can take the fight to the rest of the Twilight. You're welcome to fly with us anytime." }
WordHunterWoW_QuestEN[27818] = { title = "Slithering Signs", description = "I settled here well before Bogpaddle was founded, to brew my potions and find some peace and quiet. I know this swamp like the back of my old, gnarly hand.\n\nThere's been a change in the wildlife recently. Those winged snakes you may have seen in the stagalbog are wind serpents, and they haven't been seen around here for ages.\n\nThey're also prime for ingredients if they're the kind I'm thinking of. Be a dear and gather me some of their hearts, will you?", objectives = "Collect 5 Intact Stagalbog Serpent Hearts.", progress = "Don't be squeamish now.", completion = "Let's have a look then...\n\nMmm, oh dear. That's what I thought these were. They might still be usable, but it's horrid to have such things in my backyard." }
WordHunterWoW_QuestEN[27819] = { title = "TEST - RVM", description = "", objectives = "" }
WordHunterWoW_QuestEN[27821] = { title = "Orcs and Humans", description = "With war raging across the entire world, the last thing we need is a Horde settlement right in our backyard. Redridge, Duskwood, even Elwynn itself are all a day's march from here.\n\nWe've made the first strike, and I don't plan to give the Horde a chance to catch their breath. So consider yourself deployed. Grab a weapon, join the rest of the troops out in the Bloodmire, and start killing orcs.\n\nReport back here after you've done some damage. I want you back alive...and that's an order. Dismissed!", objectives = "Slay 8 Stonard Warriors.", completion = "More black on you than red... that's what I like to see. Looks like you've got what it takes, <name>." }
WordHunterWoW_QuestEN[27822] = { title = "Lumbering Oafs", description = "I want victory to be totally assured here. Having more resources isn't enough; we need to make sure the enemy has nothing.\n\nStonard's forces depend on the lumber gathered from the surrounding woods. The orcish peons that chop the lumber may not be warriors, but they still know nothing but hate for humans.\n\nShow no mercy. I want those peons killed and the supply of lumber to Stonard cut off completely.", objectives = "Slay 5 Stonard Peons.", completion = "We've had strikes on our own lumber line while you've been gone. This should at least put us on equal footing for gathering rates.\n\nGood work, <name>." }
WordHunterWoW_QuestEN[27823] = { title = "A Dwarf's Got Needs", description = "I can appreciate a good diggin' as much as any other dwarf, don't get me wrong.  It's just that... well, we do so much diggin', and so little drinkin', that sometimes I wonder if I should just hang up me shovel and head back to Ironforge.\n\nBut not today.  I've got some diggin' in me yet.\n\nThose Dark Iron dwarves at Hammertoe's Digsite - just north of here - make some powerful fine beer, right here in the desert.  You think you could pick up a few for me?", objectives = "Obtain 15 mugs of Shadowstout.", progress = "<Sigrun licks his lips in anticipation.>", completion = "<Sigrun instantly downs a dusty mug of shadowstout.>\n\nWow, this stuff is strong!  I knew they had beer, but I never expected them to have shadowstout!  That's my favorite shadowbeer!" }
WordHunterWoW_QuestEN[27824] = { title = "The Good Stuff", description = "I've got a little proposition for you, if you're interested.\n\nThose Dark Irons were here before Durdin and his crew arrived.  That means that, once these titan ruins opened up, the dark irons were the first ones in there, lootin' all the good stuff.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nYou've more than proven your ability to wallop a dwarf.  Head on into that fortress and wallop your way to titan treasure.\n\nI'd go with, but I'm drunk.", objectives = "Search for treasure in the bottom floor of Angor Fortress.", progress = "Back so soon?", completion = "Now here's some treasure!  I was beginning to worry that these weren't titan ruins at all!\n\nI'll show these to Durdin.  Thanks again, <name>." }
WordHunterWoW_QuestEN[27825] = { title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on what would be our hunting grounds, we have no way to get food.\n\nThe ogres to our southwest, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", objectives = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles." }
WordHunterWoW_QuestEN[27826] = { title = "Into the Dragon's Mouth", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get this back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover pretty well when she transformed into her true form in front of all those whelps.  She's now in the west, staying at an Alliance camp called Dragon's Mouth.\n\nShe'll be waiting for you.  And for that egg.", objectives = "Bring the Purified Black Dragon Egg to Rhea at Dragon's Mouth in the Badlands.", progress = "That's some precious cargo you carry there, <name>.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way." }
WordHunterWoW_QuestEN[27827] = { title = "The Swift, the Fierce, and the Stout", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nTalk to Eric, over on the other side of camp.  He and his brothers will be joining you.", objectives = "Speak with Eric \"The Swift\" at Dragon's Mouth in the Badlands.", completion = "You're the <race> we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!" }
WordHunterWoW_QuestEN[27828] = { title = "Eric, the Utility Dwarf", description = "Before we get too crazy what with the dragon-killin', let me tell you a little bit about how I fight.\n\n\"The Swift\" is what they call me, and here's why: I'll dash straight into your enemies - helmet first, mind you - and stun 'em for a few seconds.  I also keep a few potions with me for tight spots.\n\nWhy don't we practice fightin' together?  Head out into the field, and try out my abilities.", objectives = "Use Eric's Charge and Eric's Pocket Potion.", progress = "We're not through yet, <name>.", completion = "I'm not what you'd call \"very strong\" or \"battle-hardened\", but I get the job done my own way.\n\nLookin' forward to fightin' with you.  I never fought with a fancy-lookin' <class> before." }
WordHunterWoW_QuestEN[27829] = { title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, northeast of Dragon's Mouth.  Hunt him down and defeat him.  You will likely need the help of your new dwarven allies.", objectives = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", completion = "One less dragon to worry about, one step closer to redemption.  Onward, my soldiers!" }
WordHunterWoW_QuestEN[27830] = { title = "Their Hunt Continues", description = "The black dragonflight means business.  It appears that they've taken over a large portion of New Kargath, the large Horde settlement northwest of Dragon's Mouth.  Their troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.\n\nWe dragons do not take part in the squabbles between Horde and Alliance, but I do understand the risk you take in entering New Kargath.  Please, heroes... be careful.", objectives = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", completion = "Two more dangerous black dragons have been removed from this egg hunt.  Your greatest task, however, still awaits." }
WordHunterWoW_QuestEN[27831] = { title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", objectives = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", completion = "Just think... Nyxondra may end up being the mother of the new black dragonflight.  In death, she has given a gift to the future generations of Azeroth." }
WordHunterWoW_QuestEN[27832] = { title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", objectives = "Speak with Rhea at The Hidden Clutch in the Badlands.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest." }
WordHunterWoW_QuestEN[27833] = { title = "Half-Ton Holdouts", description = "I'd say we have a dragon problem, but it seems like they're a little more interested in New Kargath than they are in our small encampment.  Nevertheless, I've got top men focused on keeping the dragons at bay.\n\nOne problem that has gone unchecked, however, is the ogre camp to our southwest.  A small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier.  Thin their ranks before they thin ours.", objectives = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", completion = "Thank you, <race>.  However, I'm afraid I don't have much to give you, other than this passionate round of applause.\n\n\n\nOh, I do have these.  Here, take your pick." }
WordHunterWoW_QuestEN[27834] = { title = "Baelog, the Glass Cannon", description = "Before I start droppin' arrows on those dragons, I'd better introduce myself.\n\nI'm Baelog, the muscle of this group.  My sword bites like a crocolisk, and my arrows sing like banshees.  I tend to wear down quickly, however, and can't take as much punishment as either of my two brothers.\n\nYou give the word, and I'll send an aimed shot right through your target's heart.  I can also cheer my brothers on, sending 'em into a battle-fueled frenzy.\n\nWhy don't we go try fighting together?", objectives = "Use Baelog's Valhalla Shot and Baelog's Warcry.", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, <name>.  You're getting the hang of this." }
WordHunterWoW_QuestEN[27835] = { title = "Olaf, the Big Fella'", description = "You may not have noticed, but I'm pretty big, as far as dwarves go.\n\nI make sure that my two brothers here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", objectives = "Use Olaf's Shield Wall and Olaf's Mighty Shout.", progress = "Don't worry, little <race>.  I'll protect you.", completion = "See?  No need to worry when Olaf is around.  Just let me know, and I'll protect you from the monsters." }
WordHunterWoW_QuestEN[27836] = { title = "Stopping the Spread", description = "Slaying the foul creatures that plague the river will not be enough, {name}.\n\nA new generation of these monstrosities already threatens to spawn within our holy waters.\n\nSeek their foul eggs and destroy them.", objectives = "Destroy 6 Slitherer Eggs.", completion = "I thank you, <name>.  This will make our prophetic visions that much clearer." }
WordHunterWoW_QuestEN[27837] = { title = "Trespassers in the Water", description = "Shortly after Uldum's protective barriers fell, the Vir'naal river became afflicted with a terrible corruption.\n\nWhether it was brought here maliciously or accidentally is not of great significance.\n\nThe result is the same.  As the river becomes clouded so does our ability to peer into what the future holds for us.\n\nLook outside, {class}.  These foul creatures were never meant to live in the pristine waters of our river.\n\nSlay them so that the river may grant us visions once again.", objectives = "Slay 8 Stillwater Slitherers.", completion = "Yes, <name>.  I can feel the disruption in the river fading.\n\nYet, I feel the source of this taint still lingers." }
WordHunterWoW_QuestEN[27838] = { title = "The Root of the Corruption", description = "You might have dealt with the symptoms of our problem, {name}.  But I've been studying these foul beasts and the eggs are not laid here by them.\n\nThe stream from the current carries their eggs to the dam, but whatever is laying them will be found upstream.\n\nGo northeast, to the river's main source, and deal with the root of the corruption.", objectives = "Go to the northeastern source of the Vir'naal River and slay Scalemother Hevna.", progress = "Is it done yet, <name>.", completion = "Yes.  The waters are clearing up.\n\nI am certain I will be visited by a vision before the High Council meets.\n\nBe warned, <race>.  My vote will only be swayed by what I see.\n\nYou might have helped us greatly here today, but if the vision sways me to make a case against war then that is the way my vote will be cast." }
WordHunterWoW_QuestEN[27839] = { title = "Ancient Weapons", description = "Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories.\n\nKing Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors.\n\nMy scouts report that the Neferset are about to move a major shipment of looted weapons south of here.\n\nI've instructed the laborers you recruited to assist you.  Call upon them with this horn when you find the smugglers and recover the weapons.", objectives = "Retrieve the Ancient Tol'vir Armaments.", progress = "You've returned, <name>.  How did the operation go?", completion = "This is quite timely.  I will distribute these armaments to my best men and to the laborers that you recruited.\n\nI've a feeling they'll show as much courage as my best trained captains." }
WordHunterWoW_QuestEN[27840] = { title = "Draenethyst Crystals", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the west, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", objectives = "Collect 5 Draenethyst Crystals from the Fallow Sanctuary.", progress = "Do you have the crystals?", completion = "Thank you, <name>.  We, are in your debt." }
WordHunterWoW_QuestEN[27841] = { title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Goblin Spirit in Orgrimmar's graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday." }
WordHunterWoW_QuestEN[27842] = { title = "Only the Beginning", description = "I miss the days when legions of powerful ogres marched by the Horde's side into battle, the pathetic Alliance cowering at their ferocity. Perhaps those days will return before I am gone to the ancestors.\n\nHowever, that is not the case now. An ogre magi, Glubtok, has joined forces with the despicable Defias Brotherhood and acts as Foreman over their mining operations. The pathetic fool! End his life for me, and for the spirit and glory of the Horde!", objectives = "Kill Glubtok.", completion = "Do not be alarmed, <name>. I am close to you, waiting in the shadows. You've done well.\n\nYou must continue the mission here - I am too valuable to risk my life against petty criminals like these." }
WordHunterWoW_QuestEN[27843] = { title = "Reinforcements Denied", description = "Just killing ogres won't be enough. The ogres themselves are being summoned onto the battlefield far too rapidly.\n\nI need you to go far behind the enemy line and seek out their summoners. The orcs are using warlocks to bring their reinforcements in.\n\nCut down the warlocks, and the portals should close. There aren't many of them; a quick, surgical strike should cripple the enemy.", objectives = "Slay 3 Stonard Warlocks.", completion = "Once again, well done. With a few more pushes the battle will be ours." }
WordHunterWoW_QuestEN[27844] = { title = "Traitors!!!", description = "The goblins you'll find working with the Defias are officially traitors to the Bilgewater Cartel, the Shattered Hand, and the Horde itself!\n\nI haven't yet been initiated into the Shattered Hand, so my loyalties lie strongly with my people. Helix Gearbreaker apparently has no time for such associations, and works on building a mast for the Defias Juggernaut. On behalf of Miss Mayhem and myself, would you kindly 'dispose' of Helix?", objectives = "Defeat Helix Gearbreaker.", progress = "Yes?", completion = "My employers do not take kindly to traitors.\n\nOn the flip side, they are renown for their kindness towards the loyal! You deserve to be rewarded!" }
WordHunterWoW_QuestEN[27845] = { title = "Marking the Fallen", description = "We've taken more than we've lost, but we've still lost too much. Too many brave have given their lives for the Alliance out there. I want to make sure they're given proper honors no matter how fierce this battle gets.\n\nTake these flags out with you and place one on any fallen soldier you see. The protective wards on them won't offer much protection against any defilement, but it's better than nothing. I'll be able to better judge how many we've lost from a distance, as well.", objectives = "Use the Banner of the Fallen to mark 7 Fallen Marshtide Footmen.", completion = "Thank you, <name>. Those soldiers deserve better than to be left face down in the mud." }
WordHunterWoW_QuestEN[27846] = { title = "The Grateful Dead", description = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me!\n\nMight I trouble you for some more of that delicious Bread of the Dead? I'd be most grateful...\n\nChapman there sells the recipe, I think.", objectives = "Acquire some Bread of the Dead and give it to the Cheerful Worgen Spirit in Darnassus' graveyard.\n\nUse an Orange Marigold to see the otherwise invisible spirit.", progress = "You don't have any Bread of the Dead, do you?", completion = "Ah, more delicious Bread of the Dead, thank you!\n\nPlease, take this in return... a little something fun for the holiday." }
WordHunterWoW_QuestEN[27847] = { title = "Not Quite There", description = "These prototypes are going to change the face of Horde warfare when I perfect them! The issue I've been having is that their power sources don't allow for complicated combat maneuvers or large frames, both highly desired traits when it comes to fighting Alliance.\n\nThe Defias, with some help from goblin traitors like Helix, have almost completed the Foe Reaper 5000, a massive golem that will actually work!\n\nWe can't have that going public, can we? I'll lose customers!", objectives = "Destroy the Foe Reaper 5000.", completion = "Brilliant! Now all I have to do is finish my work, and my Mayhem Reapers will cause...mayhem...on any Horde front!\n\nAnd there won't be any Defias knockoffs to steal my profits!" }
WordHunterWoW_QuestEN[27848] = { title = "Good Intentions...Poor Execution", description = "The Defias plan to finish their Juggernaut and use it to lay waste to Stormwind. It is a noble cause any true orc warrior would embrace without a single thought!\n\nVanessa's fault lies in her execution of their plan. The ship is poorly constructed, the crew practically untrained, and, worst of all, there's a worgen in their midst!\n\nHis name is Admiral Ripsnarl, and he must be mercilessly slain in the name of the Warchief. Lok'tar ogar!", objectives = "Kill Admiral Ripsnarl.", completion = "It's a shame that he was both a human and a worgen. Had he been a proud orc warrior I'd have liked to charge into battle alongside such a fierce combatant.\n\nWe can speak of ill-fated desires another day. It is time to take what is ours from the enemy." }
WordHunterWoW_QuestEN[27849] = { title = "Assault on Stonard", description = "This is it, {name}. We've made our final push into Stonard itself.\n\nI shouldn't have to remind anyone, but I'll say it anyway: We're not orcs, and we're not going to become them out of revenge or spite. Stonard will not be burned to the ground for us to dance on the ashes.\n\nNo, I want this done right. I want this surgical. Hold your head high and strike down any orc that picks up a weapon.", objectives = "Slay 6 Stonard Defenders.", completion = "You've followed orders well, <name>. On behalf of the crown, I'm rewarding you for your bravery on the battlefield." }
WordHunterWoW_QuestEN[27850] = { title = "The Defias Kingpin", description = "The Shattered Hand has laid mostly quiet for years now.\n\nNo more!\n\nYou will be the instrument of our rebirth, {name}. Slay the Defias Kingpin and commandeer her ship for the Horde! We will outfit it as a proper orc warship and use it to finally lay waste to Stormwind\n\nAny survivors will spread word of our unstoppable power across all of Azeroth, and all will tremble before our might!\n\nGo now, VanCleef's death will be your greatest triumph yet hero.", objectives = "Kill the Defias Kingpin.", completion = "COWARD!!! Vanessa VanCleef is a dirty human coward! How dare she flee from battle against the Horde and leave her unworthy subordinate to fight!\n\n<Kagtha composes herself.>\n\nNo matter. Her ship is reward enough. The citizens of Stormwind will bear first hand witness to our awe inspiring power using a ship made in part by the very architect of their city!" }
WordHunterWoW_QuestEN[27851] = { title = "Cutting Supply", description = "We may not be flattening Stonard into dust, but I don't want to have to go in there a second time.\n\nI want you to gather any supplies you see in the town while you're there. Without food, they won't have any fighters after more than a day.\n\nThere should be crates scattered all over town.", objectives = "Seize 5 crates of Stonard Supplies.", progress = "What's the situation?", completion = "Good work, <name>. With this, it's only a matter of time until the orcs are fleeing for the portal or begging for surrender." }
WordHunterWoW_QuestEN[27852] = { title = "Orcs and Humans", description = "War rages in the swamp, {name}. Vicious humans have settled north of the city and brought an army to our doorstep.\n\nThere is nothing in this swamp for them. Their sole reason for coming here is to attack us, unprovoked. We will not give them the pleasure of victory!\n\nWe are undermanned and I need every able orc to take to the battlefield. Go, and slay as many humans as you can.", objectives = "Slay 10 Marshtide Footmen.", progress = "I'm pretty sure you still have some slaying to do.", completion = "We will fight to the last orc, <name>. I hope you'll keep yourself alive long enough to properly destroy these trespassers." }
WordHunterWoW_QuestEN[27853] = { title = "Lumbering Oafs", description = "We are outnumbered by the Alliance. In their fear they send an army to crush a single settlement. But we will not give!\n\nWithout resources, their soldiers will be at a disadvantage. Human peasants busy themselves in the woods outside Marshtide Watch, gathering lumber to rebuild their crumbling walls.\n\nDeny them the wood, and their lives.", objectives = "Slay 5 Marshtide Peasants.", completion = "No true member of the Horde should find pleasure in killing such terrified weaklings... without challenge, victory has no true thrill.\n\nBut your dirty work has helped stave off the Alliance and protect our homes here. Be proud of your work for the Horde." }
WordHunterWoW_QuestEN[27854] = { title = "Tides of Darkness", description = "We have suffered many losses, {name}. Dreadmaul Hold has sent ogres from the Blasted Lands as reinforcements, but they can only send so many; the Alliance attacks them as well, even as we speak.\n\nThe Alliance has countered our ogres with mounted knights, a strategy that served them well in the Second War. We will need our strongest warriors to turn the tide of battle!\n\nReturn to the Bloodmire, {name}, and bring down those knights!", objectives = "Slay 6 Marshtide Knights.", completion = "You are a true champion, <name>, to take the lives of so many on the battlefield. I hope it will be enough to save Stonard." }
WordHunterWoW_QuestEN[27855] = { title = "Reinforcements Denied", description = "The Alliance has brought in their mages to summon more reinforcements directly to the battlefield from beyond their fortress. This must be stopped!\n\nTheir numbers are few, but a single portal can turn the tide of battle. Attack their mages and shut off those portals!", objectives = "Slay 3 Marshtide Mages.", completion = "With no link to the outside, the Alliance must rely on what they've brought to the swamp. We shall see if they can handle our home environment." }
WordHunterWoW_QuestEN[27856] = { title = "Marking the Fallen", description = "Many warriors have met death to bring us victory, {name}. The fate of a true orc.\n\nI have seen the way the Alliance loots the bodies of our fallen, clutching at our goods like packrats. They will not defile our fallen heroes on this field.\n\nTake these wards with you to the Bloodmire. Place them on the bodies of our fallen warriors. I will be watching, to see how many have fallen, and to honor their sacrifice. Let us hope the spirits give us aid for our respect.", objectives = "Use the Banner of the Fallen to mark 7 Fallen Stonard Warriors.", completion = "You honor both the dead and the living with your courage, <name>." }
WordHunterWoW_QuestEN[27857] = { title = "We're Under Attack!", description = "The Alliance are at our walls!\n\nYour actions delayed them and weakened their forces, {name}, but in the end we are outnumbered. This is our last stand. Victory or death...\n\nFight with honor, {name}. They are within the walls as we speak. Drive the human dogs from Stonard, for the Horde!", objectives = "Slay 12 Marshtide Invaders.", progress = "There is no time! Go! Fight!", completion = "The Alliance is driven out! Stonard will be safe, thanks to your ferocity. Lok'tar Ogar!" }
WordHunterWoW_QuestEN[27858] = { title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", objectives = "Wait as Rhea retrieves the egg from the Hidden Clutch." }
WordHunterWoW_QuestEN[27859] = { title = "The Egg Lives On", description = "", objectives = "Wait as Rhea retrieves the egg from the Hidden Clutch.", completion = "You were not the only mortal that Rheastrasza confided in.  I too earned the dragon's trust.\n\nI have already moved the real purified egg on to a safer location, away from the Badlands.  It will continue to grow, out of Deathwing's sight.\n\nThe red dragonflight is as benevolent as it is powerful.  It was Rheastrasza's final wish that I give this to you." }
WordHunterWoW_QuestEN[27860] = { title = "The Lost Ones", description = "When the Dark Portal closed many years ago, regret and fear seized many of us who had come to these lands. In their despair, they cursed the name of the Light, and sank into violence and hatred.\n\nThese fallen souls are now the Lost Ones, little more than mindless monsters, attacking all who approach. They grow more corrupt by the day, and as they die off, they have begun to kidnap from the Harborage..\n\nThey are beyond help, {name}. Their suffering must end. Will you put them from their misery?", objectives = "Slay 12 Lost Ones in the Fallow Sanctuary.", completion = "It still pains my heart to have asked you to do this, though I know there is no other way. You have saved those of us still holding on from a terrible menace." }
WordHunterWoW_QuestEN[27861] = { title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I was wondering when you'd show up, {name}! Having a past champion of the Ring of Blood here will be a huge draw! We're gonna be rich, buddy! RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!" }
WordHunterWoW_QuestEN[27862] = { title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "Well well, if it isn't the once champion of anguish, {name}! I'm seeing good money in the future now that you're here! We're gonna be rollin in the dough, buddy! Filthy RICH!\n\nAnyway, this is some old Dragonmaw fighting pit. Didn't take much modification to tune it up to our uses. I put out a few feelers, and got some heavy hitters from all around Azeroth to join in the carnage. Bout time to make some gold!\n\nYou know the drill, {name}. When you're ready, let me know and we'll get this show on the road!", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!" }
WordHunterWoW_QuestEN[27863] = { title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", objectives = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", completion = "Not bad, friend. You might make some gold out here - if you manage to stay alive." }
WordHunterWoW_QuestEN[27864] = { title = "The Crucible of Carnage: The Deadly Dragonmaw!", description = "You're going to love this one! The Dragonmaw heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on orc action! Let me know when you're ready to do this!", objectives = "Get in the arena at the Crucible of Carnage and defeat Torg Drakeflayer!", completion = "No love in your heart for orcs I see. You really made a mess of that guy." }
WordHunterWoW_QuestEN[27865] = { title = "The Crucible of Carnage: The Wayward Wildhammer!", description = "You're going to love this one! The Wildhammer heard you were entering the arena and they're determined to make sure you don't leave it.\n\nTime for some good ol' {race} on dwarf action! Let me know when you're ready to do this!", objectives = "Get in the arena at the Crucible of Carnage and defeat Sully Kneecapper!", completion = "No love in your heart for dwarves I see. You really made a mess of that guy." }
WordHunterWoW_QuestEN[27866] = { title = "The Crucible of Carnage: Calder's Creation!", description = "Grim and gory, this next match is sure to have the crowd groanin' one way or another. Calder Gray has been gathering the bodyparts of defeated challengers and building the perfect champion.\n\nThis thing is the ultimate cobbled collaboration of corpsified combatants. A magnificent mashup of mangled monstrosities. Are you ready to get messy?! Cause I am! Let me know when you're ready so we can get this thing started!", objectives = "Get in the arena at the Crucible of Carnage and defeat the Cadaver Collage!", progress = "No payout until the fight's over, man.", completion = "Wow! When I saw that... thing stumble into the arena, I thought you didn't stand a chance. But you proved me wrong. You tore it apart!\n\nGrizzly business." }
WordHunterWoW_QuestEN[27867] = { title = "The Crucible of Carnage: The Earl of Evisceration!", description = "You're going to have your hands full with this one, pal. We've got a seasoned gentleman warrior here! He hails from Gilneas, and he's out to prove that he's the best warrior this side of Azeroth.\n\nYou better pull up those boots and zip up those pants, because it's going to get downright feral up in here. Give me the word when you're down for some punishment.", objectives = "Get in the arena at the Crucible of Carnage and defeat Lord Geoffery Tulvan!", completion = "You really pulled that one out. I thought you were done for sure when he wolfed and started tearing up the arena. I guess I should know by now that you don't go down easy." }
WordHunterWoW_QuestEN[27868] = { title = "The Crucible of Carnage: The Twilight Terror!", description = "We've got someone you'll really love to hate this time around. I wasn't sure at first if I should let him into the pit, but a fight's a fight! And who am I to turn down some guaranteed cash?!\n\nThis guy hails from the Twilight Citadel itself, and comes toting a toasty punch. Better move fast and watch your back! Just give me the word when you're ready for some action.", objectives = "Get in the arena at the Crucible of Carnage and defeat Emberscar the Devourer!", completion = "Looks like this title is yours! You really pulled that one out of the fire. \n\nCongratulations. I hope the coin serves you well." }
WordHunterWoW_QuestEN[27869] = { title = "The Dragon and the Temple", description = "These serpents must be from the Temple of Atal'Hakkar. I already had a hint...\n\nNot a few days ago, I had a visitor stop by and ask me to keep an eye out for such things. An elf by the name of Itharius. I'm sure he didn't think I could see through his form... he was a green dragon in disguise, come here to help his fallen brothers no doubt.\n\nHe may very well be on to something. Itharius left for the temple itself. Perhaps you'd better go look for him there. Dark things are afoot.", objectives = "Speak with Lord Itharius atop the outer steps of the Temple of Atal'Hakkar.", completion = "The goblin sent you? She has a cunning eye, that one.\n\nShe speaks the truth. I am here to stem the tide of corruption seeping from this temple. If you would save your people from a wicked fate, <name>, I ask for your assistance." }
WordHunterWoW_QuestEN[27870] = { title = "To Marshtide Watch", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nNorth of the temple, humans of your mortal Alliance have built what they call Marshtide Watch. They war with the Horde across the swamp, a raging conflict that I foresee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", objectives = "Speak with Joanna Blueheart at Marshtide Watch.", completion = "Trouble within the temple... I wish we could spare forces to deal with it. The war with Stonard is already raging, and we need every man we can get." }
WordHunterWoW_QuestEN[27871] = { title = "To Stonard", description = "Regardless of whether you assist me within the temple, your people must be told of what is brewing here.\n\nSouthwest of the temple is the Horde town of Stonard. The orcs there wage war with the new human arrivals to the swamp, a raging conflict that I foresee only worsening.\n\nIt is not my role to interfere in mortal affairs, {name}. I simply ask you bring warning to your people of what lurks within the temple.", objectives = "Speak with Dispatch Commander Ruag at Stonard in Swamp of Sorrows.", completion = "We have no time to send orcs to the temple, <name>. The humans come, and they are many. Stonard must be defended!" }
WordHunterWoW_QuestEN[27872] = { title = "Tortolla Hub Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[27873] = { title = "Aviana Hub Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[27874] = { title = "Aviana's Legacy", description = "Your expertise is needed elsewhere, {name}.\n\nJust southwest of the World Tree you will find the Shrine of Aviana, home to the Druids of the Talon. Aviana, the matron of all winged creatures, gave her life for this world ten thousand years ago.\n\nI sense her shrine is being threatened, as are the druids who guard it. Seek out Choluna, one of the wisest of the winged druids, deep within the shrine. ", objectives = "Locate Choluna at the Shrine of Aviana in Mount Hyjal.", completion = "Ysera herself sent you to me? Oh! It's a honor to speak with a representative of the aspects.\n\nIt's true that our shrine is in jeopardy. The harpies we once sheltered in our boughs have suddenly turned against us.\n\nBut please, don't rejoin the fight until you are ready. Our shrine is no mere battleground. Use its peace and power to center yourself." }
WordHunterWoW_QuestEN[27875] = { title = "Prayerblossom", description = "I have worked for years to try to cure the affliction of the Broken. The foul energies that corrupted them did  more than twist their bodies; it took the comfort of the Light from them. They cannot feel its warmth.\n\nI cannot let Magtoor pass on in darkness, {name}. Before he worsened, I was studying prayerblossom, a flower that grows in the shifting mire. It grows hardy in even the darkest shade. I beg of you, gather these flowers for me, for Magtoor's sake.", objectives = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", progress = "Have you brought the prayerblossom?", completion = "Prayerblossom has been used by the Broken as a remedy since they settled in this swamp. If it soothes the physical form, it might be used for more powerful healing..." }
WordHunterWoW_QuestEN[27876] = { title = "Secrets of the Mire", description = "The Shifting Mire takes its name from a unique phenomenon. By some force, the extremely fine silt will collect, and move on its own accord, travelling as if alive.\n\nI originally worried this was some corruptive force, but my studies have shown the opposite; whatever energy invigorates this soil is positive in nature. Perhaps such vibrant life can be imparted onto the Broken to reawaken what they once were.\n\nThe silt may not take kindly to being collected, {name}. But please, help gather it.", objectives = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", progress = "Did you get those samples?", completion = "It will have to be purified, but this will be most helpful. Thank you." }
WordHunterWoW_QuestEN[27877] = { title = "The Morons' League", description = "I need your help in a little project I'm working on, {name}.  It falls into a realm I like to call \"defensive archaeology\".\n\nI like to bury non-magical items in conspicuous places to fool those Alliance idiots into thinking they've found something valuable.\n\nHmm... Dark Iron dwarves wander Hammertoe's Digsite and Angor Fortress, to the north.  Bring their heads back to me.  Yes, that's right, their heads.\n\nOnce the flesh is stripped, we can use those skulls to interfere with the dwarves' work.", objectives = "Obtain 15 Dark Iron Heads.", progress = "<Lidia waits expectantly.>", completion = "Excellent!  We'll bury these immediately.  Those Explorers' League dimwits will never suspect us!" }
WordHunterWoW_QuestEN[27878] = { title = "Forcible Acquisition", description = "I've got a little proposition for you, if you're interested.\n\nThe Dark Iron dwarves were here long before we arrived.  That means that, once these titan ruins opened up, the Dark Irons were the first ones in there, looting all the choice items.  I'll bet they've still got those treasures locked up inside Angor Fortress, northwest of here.\n\nI want you to find such a treasure... then steal it.", objectives = "Search for treasure in the bottom floor of Angor Fortress.", progress = "Back so soon?", completion = "I knew it!  The High Examiner will be pleased to see this.\n\nNice work, <race>." }
WordHunterWoW_QuestEN[27879] = { title = "Survival of the Fattest", description = "We're hard-up for supplies, stranger.  With the black dragons raining destruction on our hunting grounds, we have no way to get food.\n\nThe ogres to our south, however, have exactly what we need.  Within their grotto you should find plenty of meat and crafting supplies.\n\nThey may put up a fight.  Be on your guard.", objectives = "Obtain 6 pieces of Dustbelcher Meat and 10 sheets of Dustbelcher Silk.", progress = "Welcome back.", completion = "I imagine those ogres weren't too much trouble for you.  Here - some coin for your troubles." }
WordHunterWoW_QuestEN[27880] = { title = "Half-Ton Holdouts", description = "My grunts have got this dragon problem under control.  Besides, I can't have an upstart {class} like you barging in and ruining our battle plans.\n\nYou want work?  Fine, I'll give you work.  Investigate the ogre camp to our southwest.  From what I've heard, a small army of combatants seems to have appeared outside of their hovel.\n\nWe can't sit and wait for them to flank us, soldier... especially while we're already embroiled with black dragons.  Thin their ranks before they thin ours.", objectives = "Slay 12 Dustbelcher Combatants. You may kill Dustbelcher Maulers or Dustbelcher Shaman.", completion = "You've got the hint of a hero in you, <race>.\n\nNow get out of my battlefield." }
WordHunterWoW_QuestEN[27881] = { title = "Bloodwatcher Point", description = "I've got an idea, but it's a bit of a long shot.  Thankfully, long shots happen to be a specialty of mine.\n\nNorth of here, the Reliquary has uncovered a new set of titan ruins beneath the sands.  If there's anything older and wiser than dragons, it's titans.  Heck, I've heard rumors that the titans CREATED the dragons.\n\nTalk to High Examiner Tae'thelan Bloodwatcher at their camp to the northeast.  He'll have more information than I do about these titans.\n\nWhat did I tell you?  It's a long shot.", objectives = "Speak with High Examiner Tae'thelan Bloodwatcher at Bloodwatcher Point in the Badlands.", completion = "Titans?  You come to me, asking about titans?\n\nYou've come to the right place, as we're on the brink of discovering something big.  You will, however, need to earn your keep first." }
WordHunterWoW_QuestEN[27882] = { title = "It's Not About History, It's About Power", description = "The Explorers' League may have a yeoman's knowledge of the actual act of digging.  What they lack, however, is the good sense to USE the artifacts that they dig up.  They stow their treasures in stagnant museums instead of using these items of power for their true purpose.\n\nThe dwarves are fools.  Fortunately, they die easily.\n\nYou'll find them digging into canyon walls north of here.  Take whatever you can out of their stubby-fingered hands, then return it to me.", objectives = "Obtain a Broken Chalice, a Dusty Vase, an Earthen Hieroglyph, and a Trogg Tool.", progress = "You've returned with liberated artifacts, I presume?", completion = "Chalice... worthless.\n\nVase... counterfeit.\n\nHieroglyph... interesting, but rather common.\n\nWhat's this?  I've never seen trogg craftsmanship of this caliber!  You've stumbled upon something rare indeed, <name>.\n\nWe must not be so hasty as to overlook the troggs.  They may be simple, but they know things about the deep, hidden places of this world.\n\nYou've performed well enough.  Let's talk titans, shall we?" }
WordHunterWoW_QuestEN[27883] = { title = "The Warden's Pawn", description = "One of the few items of worth that we managed to loot from these ruins is this small jade statue.\n\nWe believe it to be a key of some sort, but we're unable to determine what it opens.  As such, it is useless to me.\n\nPerhaps you'll have some better luck with it.", objectives = "Find a use for the Warden's Pawn within the Tomb of the Watchers in the Badlands.\n\nProvided item:", completion = "<The statue clicks into place on the large stone slab.>" }
WordHunterWoW_QuestEN[27884] = { title = "The Sentinel's Pawn", description = "We found this small red statue on the corpse of one of those Explorers' League archaeologists.  Sadly, it wasn't us who killed him.  The local wildlife had already taken care of that.\n\nThe statue is well-crafted, but apparently bereft of magical power.  You may use it for whatever means you deem necessary.", objectives = "Find a use for the Sentinel's Pawn within the Tomb of the Watchers in the Badlands.", completion = "<The statue slides into place on the cold marble slab.>" }
WordHunterWoW_QuestEN[27885] = { title = "The Warden's Game", description = "You see the statue split into two, then four, then eight identical statues in a square formation.\n\nYou hear a voice, not through your ears, but in the back of your mind:\n\n   \"A true warden does not face OUTWARD, searching for signs of danger.\n  A true warden keeps his gaze INWARD, always focused on protecting his quarry.\"\n\nPerhaps this is a riddle of some sort?", objectives = "Complete the Warden's Game by teleporting the Warden's Pawns into inward-facing positions." }
WordHunterWoW_QuestEN[27886] = { title = "The Sentinel's Game", description = "As you place the statue in its place, several other stone statues appear in the room.  One more ruby-colored statue also appears, in a small enclosure on the far end of the room.  You hear a voice:\n\n  \"The Sentinel watches.\n  The Sentinel protects.\n   The Sentinel's vision never falters.\"\n\nThat red statue on the other side of the room looks important.  Perhaps you should try to connect the two red statues?", objectives = "Complete the Sentinel's Game by connecting the two red statues." }
WordHunterWoW_QuestEN[27887] = { title = "Ancient Protectors", description = "You heard a good amount of rumbling happen in the tomb's central chamber.  Those two large statues did look awfully suspicious.", objectives = "Investigate The Warden and The Sentinel." }
WordHunterWoW_QuestEN[27888] = { title = "Return to Blam", description = "Inside the chest, you find a small, circular device, resting upon a cushion.\n\nIf there are any titan artifacts to be found here in the tomb, this is it.  You resolve to bring it back to Dr. Blam.", objectives = "Bring the Eye of the Watchers to Dr. Hieronymus Blam at Agmond's End in the Badlands.", progress = "Well?  Has our long shot paid off?", completion = "Just one tiny little device?\n\nI never did understand those titans.\n\nVery well!  Let's see what this peeper can do." }
WordHunterWoW_QuestEN[27889] = { title = "New Kargath", description = "<Dr. Blam stares at the egg in awed silence, blinks a few times, then looks up at you.>\n\nD... did you see that?  Incredible!  My titan thing idea worked!  With your help, of course.\n\nWe'll want to get these back to Rhea.  She's not at Lethlor Ravine anymore; it sounds like she blew her cover when she transformed into her true form in front of all those whelps.  She's now in the west, staying at a large Horde establishment dubbed \"New Kargath\".\n\nShe'll be waiting for you.  And for that egg.", objectives = "Bring the Purified Black Dragon Egg to Rhea at New Kargath in the Badlands.", progress = "That's some precious cargo you carry there, <name>.", completion = "I'll take that egg out of your hands now.  We need to get this egg incubated... and hidden, quickly.  There are lots of angry dragons looking for this.\n\nIt's good to see you again, by the way." }
WordHunterWoW_QuestEN[27890] = { title = "The Bad Dogs", description = "In my haste to escape from Lethlor Ravine, I forgot to tie up one loose end: Nyxondra.  She's free, and she's sounded the alarm among the black dragonflight.  Half the flight is here in the western Badlands, combing for this egg.\n\nI'll take care of hiding the egg.  You're going to take care of some of the more troublesome dragons.  And you'll have help.\n\nI've paid off a couple of mercenaries to help you.  You'll find them inside this inn.", objectives = "Speak with Amakkar at New Kargath in the Badlands.", completion = "You're the <race> we've been waiting for?  It's about time you got here.  My legs could use a stretch.\n\nCome on boys!  Let's go kill us some black dragons!" }
WordHunterWoW_QuestEN[27891] = { title = "Amakkar, Jack of All Trades", description = "Before we get too crazy with the dragon-killing, let me tell you a little bit about how I fight.\n\nI'm not terribly strong or stalwart like these other two, but I've got a few tricks.  At your command I'll stun your enemies to keep 'em held still.  I also make sure to keep a few potions around for tight spots.\n\nWhy don't we practice fighting together?  Head out into the field, and you can see what it's like to fight with a real orc.", objectives = "Use Amakkar's Kidney Shot and Amakkar's Pocket Potion.", progress = "We're not through yet, <name>.", completion = "I'm looking forward to fighting with you." }
WordHunterWoW_QuestEN[27892] = { title = "Jurrix the Striker", description = "Oh, you want to talk?  Fine.\n\nI'm Jurrix, the only merc here with half a brain.  The only one with any bite to my attacks, too.  The only reason I keep these meat shields around is to keep myself from getting killed.\n\nListen, you're the boss of this operation.  You give the word, and I'll send a fireball right through your target's heart.  If things start getting hectic, I can even warp time a bit so you can fit in a few extra attacks.\n\nWhy don't we go try fighting together?", objectives = "Use Jurrix's Fiery Blast and Jurrix's Time Warp.", progress = "We're not quite ready yet.  A little more practice, then we'll get with the dragon-slaying.", completion = "I think you're ready, <name>.  You're getting the hang of this." }
WordHunterWoW_QuestEN[27893] = { title = "Gargal, the Behemoth", description = "You may not have noticed, but I'm pretty big, as far as orcs go.\n\nI make sure that my two pals here don't get into too much trouble.  They're small, and they don't have a big shield like me.  I'm big, and I can handle a few monsters hitting me!  Plus, if I'm careful, I can usually get them to hit my shield instead!\n\nI can protect you, too.  Come on, let's go practice for a bit.  I'll make sure the enemies attack me, and not you.", objectives = "Use Gargal's Shield Wall and Gargal's Mighty Shout.", progress = "Don't worry, little <race>.  I'll protect you.", completion = "See?  No need to worry when Gargal is around.  Just let me know, and I'll protect you from the monsters." }
WordHunterWoW_QuestEN[27894] = { title = "The Wrath of a Dragonflight", description = "Hello, {name}.  It looks like you four have had time to become well-acquainted.\n\nI have my first assignment for you.  Kalaran, an ancient black dragon of considerable power, has joined in the hunt for the egg we are protecting.  We need to stop him before he gets too close.\n\nYou will find him and his minions at the Dustbowl, east of New Kargath.  Hunt him down and defeat him.  You will likely need the help of your new mercenary allies.", objectives = "Slay Kalaran the Annihilator and 4 Darkflight Soldiers.", completion = "One less dragon to worry about, one step closer to redemption.  Onward, my soldiers!" }
WordHunterWoW_QuestEN[27895] = { title = "Their Hunt Continues", description = "The black dragonflight means business.  As you've probably already noticed, they've taken over a large portion of New Kargath.  These troops are under the command of General Jirakka and his champion, Moldarr.  They must be stopped.", objectives = "Defeat General Jirakka, Moldarr, and 6 Blackflight dragonspawn.", completion = "Two more dangerous black dragons have been removed from this egg hunt.  Your greatest task, however, still awaits." }
WordHunterWoW_QuestEN[27896] = { title = "The Sorrow and the Fury", description = "My greatest regret is the treatment that we - no, I - gave to Nyxondra.  I forced her to lay eggs, then I performed experiments on them.  Over, and over, and over again.\n\nEven as a mother myself, I can only imagine her sorrow.\n\nNo... I mustn't be weak.  Our work is, after all, for the benefit of future generations of black dragons.  Her sacrifice was necessary.\n\nShe circles the Ruins of Kargath, northwest of New Kargath, insane with fury.  Please, heroes... put her out of her misery.", objectives = "Slay Nyxondra and 12 of Nyxondra's Broodlings.", completion = "Just think... Nyxondra may end up being the mother of the new black dragonflight.  In death, she has given a gift to the future generations of Azeroth." }
WordHunterWoW_QuestEN[27897] = { title = "The Hidden Clutch", description = "With the major black dragons out of the Badlands, it is now safe to move the egg again.  You will find me on a small plateau, north of New Kargath.\n\nCome and find me.", objectives = "Speak with Rhea at The Hidden Clutch in the Badlands.", completion = "The egg must always be moving.  We are not safe anywhere.\n\nDeathwing, even in his madness, knows all the hidden places in this world.  The egg must not rest." }
WordHunterWoW_QuestEN[27898] = { title = "Rheastrasza's Gift", description = "Wait here.  I will retrieve the egg.", objectives = "Wait as Rhea retrieves the egg from the Hidden Clutch." }
WordHunterWoW_QuestEN[27899] = { title = "That Gleam in his Eye", description = "If you're looking for Harrison, you just missed him.\n\nHe was going on and on about his latest discovery, and how everything was beginning to make sense.\n\nWhatever... he certainly wasn't making sense to me.\n\nI tried to convince him to stay here and just enjoy a few desert sunsets with me, but there's no talking to him when he gets that gleam in his eye.\n\nPerhaps you'd be willing to check in on him?\n\nHe was headed to that big monolith, south of here.", objectives = "Speak to Harrison Jones at the Obelisk of the Sun.", completion = "It would seem that I'm not the only one interested in these obelisks..." }
WordHunterWoW_QuestEN[27900] = { title = "I've Got This Guy", description = "Good timing, {name}.\n\nSeems I'm not the only one interested in these obelisks, and these fellas aren't inclined to compare notes...\n\nI think I can handle this guy.\n\nMaybe you could take care of a few of his friends before they make their way over here?", objectives = "Kill 10 Schnottz Air Troopers.", progress = "This guy's tougher than he looks - and he looks tough!", completion = "That's a relief. Thanks, <name>.\n\nTurns out I've got my hands full here." }
WordHunterWoW_QuestEN[27901] = { title = "They Don't Know What They've Got Here", description = "Listen, {name}. I don't have a lot of time to talk here.\n\nThese guys are excavating relics from this site and taking pieces of ancient technology that we need!\n\nI need you to check their crates for pieces of an ancient activation device. The officers should have the codes you'll need to open them.\n\nHurry!\n\nWe can't let them load this stuff into their planes!", objectives = "Create the Titan Activation Device.", progress = "Have you got the titan activation device, <name>?", completion = "That's it!\n\nGood work, <name>!" }
WordHunterWoW_QuestEN[27902] = { title = "The Purespring", description = "Magtoor has told me of the shamanism that the Broken practice. The great Nobundo once said that the path of the elements may, in a way, be another way to the Light.\n\nI can only hope there is some truth in this. The elementals that gather near Purespring Cavern to the south are a source of truly pristine water. They can be chaotic and violent, but the pure water harvested from them will be the perfect conduit for the blessing of the Light.\n\nPlease, bring me this water, {name}.", objectives = "Collect 6 Purespring Motes from Purespring Elementals.", progress = "Have the elements given up their source?", completion = "Such clarity... let us hope this will aid poor Magtoor." }
WordHunterWoW_QuestEN[27903] = { title = "Ignition", description = "This guy just won't go down!\n\nYou're doin' great, kid. Only one thing left to do.\n\nAccording to my research, there should be a titan statue down below. Use the device to activate it, then break it down.\n\nIf my theory is correct, that statue holds the key to reactivating this obelisk.", objectives = "Recover the Lens of the Sun.", progress = "Time to see if this old mechanism still works...", completion = "According to Harrison's notes, placing the lens upon this dais should re-activate this obelisk.\n\nExactly what that means remains to be seen..." }
WordHunterWoW_QuestEN[27904] = { title = "Breath of Mist", description = "The Grell are forest spirits that wander the Misty Valley to the east. Though they resemble imps, I have found no demonic traces among the ones I've studied. They are, as far as I can tell, uncorrupted. \n\nThose that dwell in the valley move as one with the wind, summoning gusts of breeze at their whim. This pure air may be incorporated into my remedy for poor Magtoor.\n\nPlease, {name}, gather the smoky crystals found within the grells' bodies for me. I must exhaust every potential cure.", objectives = "Collect 5 Smoky Crystals from Misty Grell.", progress = "Do you have the crystals?", completion = "I can only hope this will lead to a cure, <name>. Thank you for bringing it to me." }
WordHunterWoW_QuestEN[27905] = { title = "Tailgunner!", description = "Okay, I've softened this guy up, how about you help me finish him off?\n\nI've got a plan for our escape, but it'll require a lot of guts and a little luck.\n\nYou up for it, {name}?\n\nJust follow my lead...", objectives = "Use the tailgun to defend the Schnottz Bomber.", completion = "Good work back there, <name>.\n\nLooks like we've lost them, for now at least." }
WordHunterWoW_QuestEN[27906] = { title = "Neeka Bloodscar", description = "There is much work to do in recovering from the assault and bracing ourselves for the next one. I will need coordination from all of our scouts.\n\nNeeka Bloodscar is our finest tracker, trained in the harsh Badlands. She has been sent west to Splinterspear Junction to watch for Alliance activity.\n\nGo to Neeka, {name}. Tell her of what has occured in Stonard. Assist her in any way she requires.", objectives = "Speak with Neeka Bloodscar at Splinterspear Junction.", completion = "I hope the sight of my sniveling amuses you, <name>. It will be the only joy here." }
WordHunterWoW_QuestEN[27907] = { title = "Prayerblossom", description = "I have been ruined, {class}. I placed my strength in Helgrum, and now it bleeds from his gaping wounds. Wounds too deep to heal, flesh that refuses to knit.\n\nHe murmurs in fear, consumed by fever and pain. I cannot leave his side. Not now. Please, I ask you in shame to gather herbs for me.\n\nThe prayerblossom that grows in the swamp is an old remedy for soothing. With enough of it, his pain might be stilled.", objectives = "Collect 10 sprigs of Prayerblossom from the Shifting Mire.", progress = "Have you brought the prayerblossom?", completion = "I will grind these and try to get him to eat. Thank you." }
WordHunterWoW_QuestEN[27908] = { title = "Secrets of the Mire", description = "Helgrum's wounds fester in the swamp air. They swell and ooze, filling his final moments with suffering. I must have something to coat them with.\n\nThe spirits move through this mire. They inhabit the mud itself, pushing it along in clumps of fine soil that take on lives of their own\n\nThe spirits of the cool, pure mud will offer him some comfort. Please, gather it for me, for I cannot abandon his side.", objectives = "Collect 10 samples of Invigorated Silt from Shifting Mireglobs.", progress = "Helgrum still breathes. Do you have the mud?", completion = "At least I can soothe him with my own hands while he still breathes. Thank you, <name>." }
